        {
            RaritySetRegistry.Load();
            BossSetDropController.Load();
        }

        private static void UpgradeFloatConfig(ConfigEntry<float> entry, float oldValue, float newValue)
        {
            if (entry == null)
            {
                return;
            }

            if (Mathf.Abs(entry.Value - oldValue) <= 0.001f)
            {
                entry.Value = newValue;
            }
        }

        private static void UpgradeIntConfig(ConfigEntry<int> entry, int oldValue, int newValue)
        {
            if (entry == null)
            {
                return;
            }

            if (entry.Value == oldValue)
            {
                entry.Value = newValue;
            }
        }

        private static void UpgradeShortcutConfig(ConfigEntry<KeyboardShortcut> entry, KeyCode oldKey, KeyCode newKey)
        {
            if (entry == null)
            {
                return;
            }

            KeyboardShortcut shortcut = entry.Value;
            if (shortcut.MainKey == oldKey && shortcut.Modifiers.Count() == 0)
            {
                entry.Value = new KeyboardShortcut(newKey);
            }
        }

        private static void UpgradeShortcutConfig(ConfigEntry<KeyboardShortcut> entry, KeyCode oldKey, KeyCode oldModifier, KeyCode newKey)
        {
            if (entry == null)
            {
                return;
            }

            KeyboardShortcut shortcut = entry.Value;
            if (shortcut.MainKey == oldKey && shortcut.Modifiers.Count() == 1 && shortcut.Modifiers.Contains(oldModifier))
            {
                entry.Value = new KeyboardShortcut(newKey);
            }
        }

        private static void UpgradeShortcutConfigToModified(ConfigEntry<KeyboardShortcut> entry, KeyCode oldKey, KeyCode newKey, params KeyCode[] newModifiers)
        {
            if (entry == null)
            {
                return;
            }

            KeyboardShortcut shortcut = entry.Value;
            if (shortcut.MainKey == oldKey && shortcut.Modifiers.Count() == 0)
            {
                entry.Value = new KeyboardShortcut(newKey, newModifiers ?? new KeyCode[0]);
            }
        }
    }

    internal static class GeneratedConfigSynchronizer
    {
        private const string ResourcePrefix = "Fran.EpicLootRaritySets.GeneratedConfig.";

        private static readonly ManagedConfigFile[] ManagedFiles =
        {
            new ManagedConfigFile(ResourcePrefix + "abilities.json", "EpicLoot", "baseconfig", "abilities.json"),
            new ManagedConfigFile(ResourcePrefix + "raritysets.json", "EpicLoot", "raritysets.json"),
            new ManagedConfigFile(ResourcePrefix + "legendaries.json", "EpicLoot", "baseconfig", "legendaries.json"),
            new ManagedConfigFile(ResourcePrefix + "loottables.json", "EpicLoot", "baseconfig", "loottables.json"),
            new ManagedConfigFile(ResourcePrefix + "iteminfo.json", "EpicLoot", "baseconfig", "iteminfo.json"),
            new ManagedConfigFile(ResourcePrefix + "magiceffects.json", "EpicLoot", "baseconfig", "magiceffects.json"),
            new ManagedConfigFile(ResourcePrefix + "adventuredata.json", "EpicLoot", "baseconfig", "adventuredata.json"),
            new ManagedConfigFile(ResourcePrefix + "bosssetdrops.json", "EpicLoot", "bosssetdrops.json"),
            new ManagedConfigFile(ResourcePrefix + "NorseDemigods.cfg", "NorseDemigods.cfg")
        };

        internal static void Sync()
        {
            int written = 0;
            foreach (ManagedConfigFile file in ManagedFiles)
            {
                try
                {
                    if (SyncFile(file))
                    {
                        written++;
                    }
                }
                catch (Exception ex)
                {
                    EpicLootRaritySetsPlugin.Log.LogError("Failed to sync managed config " + file.DisplayPath + ": " + ex);
                }
            }

            EpicLootRaritySetsPlugin.Log.LogInfo(string.Format("Managed config sync finished. Updated files: {0}.", written));
        }

        private static bool SyncFile(ManagedConfigFile file)
        {
            byte[] desired = ReadResourceBytes(file.ResourceName);
            if (desired == null || desired.Length == 0)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Managed config resource missing or empty: " + file.ResourceName);
                return false;
            }

            string targetPath = file.GetTargetPath();
            if (File.Exists(targetPath))
            {
                byte[] current = File.ReadAllBytes(targetPath);
                if (BytesEqual(current, desired))
                {
                    return false;
                }

                BackupExisting(targetPath);
            }

            string directory = Path.GetDirectoryName(targetPath);
            if (!string.IsNullOrEmpty(directory))
            {
                Directory.CreateDirectory(directory);
            }

            File.WriteAllBytes(targetPath, desired);
            EpicLootRaritySetsPlugin.Log.LogInfo("Wrote managed config: " + file.DisplayPath);
            return true;
        }

        private static byte[] ReadResourceBytes(string resourceName)
        {
            Assembly assembly = Assembly.GetExecutingAssembly();
            using (Stream stream = assembly.GetManifestResourceStream(resourceName))
            {
                if (stream == null)
                {
                    return null;
                }

                using (MemoryStream memory = new MemoryStream())
                {
                    stream.CopyTo(memory);
                    return memory.ToArray();
                }
            }
        }

        private static void BackupExisting(string targetPath)
        {
            string backupBase = targetPath + ".bak-fran-managed-" + DateTime.Now.ToString("yyyyMMdd-HHmmss");
            string backupPath = backupBase;
            int suffix = 1;
            while (File.Exists(backupPath))
            {
                backupPath = backupBase + "-" + suffix;
                suffix++;
            }

            File.Copy(targetPath, backupPath, false);
        }

        private static bool BytesEqual(byte[] left, byte[] right)
        {
            if (left == null || right == null || left.Length != right.Length)
            {
                return false;
            }

            for (int i = 0; i < left.Length; i++)
            {
                if (left[i] != right[i])
                {
                    return false;
                }
            }

            return true;
        }

        private sealed class ManagedConfigFile
        {
            private readonly string[] _relativePathParts;

            internal ManagedConfigFile(string resourceName, params string[] relativePathParts)
            {
                ResourceName = resourceName;
                _relativePathParts = relativePathParts;
                DisplayPath = string.Join("/", relativePathParts);
            }

            internal string ResourceName { get; private set; }
            internal string DisplayPath { get; private set; }

            internal string GetTargetPath()
            {
                string path = Paths.ConfigPath;
                foreach (string part in _relativePathParts)
                {
                    path = Path.Combine(path, part);
                }

                return path;
            }
        }
    }

    internal static class WolfPackCompatibilitySynchronizer
    {
        private const string WolfPackConfigFileName = "neobotics.valheim_mod.wolfpack.cfg";

        internal static void Sync()
        {
            if (EpicLootRaritySetsPlugin.ConfigureWolfPackCompatibility == null ||
                !EpicLootRaritySetsPlugin.ConfigureWolfPackCompatibility.Value)
            {
                return;
            }

            string configPath = Path.Combine(Paths.ConfigPath, WolfPackConfigFileName);
            if (!File.Exists(configPath) && !IsWolfPackInstalled())
            {
                return;
            }

            try
            {
                ConfigFile config = new ConfigFile(configPath, true);
                bool changed = false;

                ConfigEntry<string> trainableCreatures = config.Bind(
                    "General",
                    "TrainableCreatures",
                    "wolf",
                    "List of creatures that will be called to Follow or Stay.");
                changed |= SetValue(trainableCreatures, MergePatterns(trainableCreatures.Value, EpicLootRaritySetsPlugin.WolfPackTrainableCreatures.Value));

                ConfigEntry<int> detectionRange = config.Bind(
                    "General",
                    "DetectionRange",
                    50,
                    new ConfigDescription("Tame creatures beyond this distance will not be affected.", new AcceptableValueRange<int>(1, 150)));
                changed |= SetValue(detectionRange, Mathf.Clamp(Mathf.Max(detectionRange.Value, EpicLootRaritySetsPlugin.WolfPackDetectionRange.Value), 1, 150));

                ConfigEntry<int> attackRange = config.Bind(
                    "General",
                    "TamesAttackRange",
                    100,
                    new ConfigDescription("The maximum distance at which enemies can be targeted by hovering and tames will attack.", new AcceptableValueRange<int>(0, 150)));
                changed |= SetValue(attackRange, Mathf.Clamp(Mathf.Max(attackRange.Value, EpicLootRaritySetsPlugin.WolfPackAttackRange.Value), 0, 150));

                ConfigEntry<int> maxTames = config.Bind(
                    "General",
                    "MaxTames",
                    10,
                    new ConfigDescription("Maximum number of tame creatures that can be summoned at one time.", new AcceptableValueRange<int>(1, 50)));
                changed |= SetValue(maxTames, Mathf.Clamp(Mathf.Max(maxTames.Value, EpicLootRaritySetsPlugin.WolfPackMaxTames.Value), 1, 50));

                if (changed)
                {
                    config.Save();
                    EpicLootRaritySetsPlugin.Log.LogInfo("WolfPack compatibility config synchronized for Hraesvelgr summons.");
                }
            }
            catch (Exception ex)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not synchronize WolfPack compatibility config: " + ex.GetBaseException().Message);
            }
        }

        private static string MergePatterns(string current, string desired)
        {
            List<string> values = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            AddPatterns(values, seen, current);
            AddPatterns(values, seen, desired);
            return values.Count > 0 ? string.Join(",", values.ToArray()) : desired;
        }

        private static void AddPatterns(List<string> values, HashSet<string> seen, string raw)
        {
            if (string.IsNullOrWhiteSpace(raw))
            {
                return;
            }

            string[] parts = raw.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
            foreach (string part in parts)
            {
                string value = part.Trim();
                if (value.Length == 0 || !seen.Add(value))
                {
                    continue;
                }

                values.Add(value);
            }
        }

        private static bool SetValue<T>(ConfigEntry<T> entry, T value)
        {
            if (entry == null || EqualityComparer<T>.Default.Equals(entry.Value, value))
            {
                return false;
            }

            entry.Value = value;
            return true;
        }

        private static bool IsWolfPackInstalled()
        {
            try
            {
                return !string.IsNullOrEmpty(Paths.PluginPath) &&
                       Directory.Exists(Paths.PluginPath) &&
                       Directory.GetFiles(Paths.PluginPath, "WolfPack.dll", SearchOption.AllDirectories).Length > 0;
            }
            catch
            {
                return false;
            }
        }
    }

    internal static class WiresEnemyHudCompatibilitySynchronizer
    {
        private const string PluginGuid = "kajetan.valheim.enemyhudrework";
        private const string ConfigFileName = "kajetan.valheim.enemyhudrework.cfg";
        private const string DllName = "EnemyHudRework.dll";
        private const string PluginTypeName = "EnemyHudRework.EnemyHudReworkPlugin";
        private const string HealthDisplayValue = "Current HP/Max HP";

        internal static void Sync()
        {
            if (!IsEnabled() || !IsWiresEnemyHudInstalled())
            {
                return;
            }

            string configPath = Path.Combine(Paths.ConfigPath, ConfigFileName);
            try
            {
                ConfigFile config = new ConfigFile(configPath, true);
                bool changed = false;

                ConfigEntry<string> healthDisplay = config.Bind(
                    "Features",
                    "HealthDisplay",
                    "None",
                    new ConfigDescription(
                        "Enemy health text.",
                        new AcceptableValueList<string>("Current HP", HealthDisplayValue, "Percentage", "None")));
                changed |= SetValue(healthDisplay, HealthDisplayValue);

                if (changed)
                {
                    config.Save();
                    EpicLootRaritySetsPlugin.Log.LogInfo("Wires Enemy HUD compatibility config synchronized: HealthDisplay = " + HealthDisplayValue + ".");
                }
            }
            catch (Exception ex)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not synchronize Wires Enemy HUD compatibility config: " + ex.GetBaseException().Message);
            }
        }

        internal static void Patch(Harmony harmony)
        {
            if (harmony == null || !IsEnabled() || !IsWiresEnemyHudInstalled())
            {
                return;
            }

            try
            {
                Type pluginType = AccessTools.TypeByName(PluginTypeName);
                if (pluginType == null)
                {
                    return;
                }

                if (ApplyLoadedPluginConfig(pluginType))
                {
                    EpicLootRaritySetsPlugin.Log.LogInfo("Wires Enemy HUD loaded config patched: HealthDisplay = " + HealthDisplayValue + ".");
                }

                MethodInfo bindConfig = AccessTools.Method(pluginType, "BindConfig");
                MethodInfo postfix = AccessTools.Method(typeof(WiresEnemyHudCompatibilitySynchronizer), "BindConfigPostfix");
                if (bindConfig == null || postfix == null)
                {
                    return;
                }

                harmony.Patch(bindConfig, postfix: new HarmonyMethod(postfix));
            }
            catch (Exception ex)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not patch Wires Enemy HUD config at load: " + ex.GetBaseException().Message);
            }
        }

        private static void BindConfigPostfix(object __instance)
        {
            try
            {
                if (IsEnabled() && ApplyHealthDisplayEntry(__instance))
                {
                    EpicLootRaritySetsPlugin.Log.LogInfo("Wires Enemy HUD BindConfig patched: HealthDisplay = " + HealthDisplayValue + ".");
                }
            }
            catch (Exception ex)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not apply Wires Enemy HUD BindConfig patch: " + ex.GetBaseException().Message);
            }
        }

        private static bool ApplyLoadedPluginConfig(Type pluginType)
        {
            FieldInfo instanceField = AccessTools.Field(pluginType, "Instance");
            object instance = instanceField == null ? null : instanceField.GetValue(null);
            return ApplyHealthDisplayEntry(instance);
        }

        private static bool ApplyHealthDisplayEntry(object instance)
        {
            if (instance == null)
            {
                return false;
            }

            FieldInfo field = AccessTools.Field(instance.GetType(), "_healthDisplayMode");
            ConfigEntry<string> entry = field == null ? null : field.GetValue(instance) as ConfigEntry<string>;
            return SetValue(entry, HealthDisplayValue);
        }

        private static bool SetValue<T>(ConfigEntry<T> entry, T value)
        {
            if (entry == null || EqualityComparer<T>.Default.Equals(entry.Value, value))
            {
                return false;
            }

            entry.Value = value;
            return true;
        }

        private static bool IsEnabled()
        {
            return EpicLootRaritySetsPlugin.ConfigureWiresEnemyHudCompatibility != null &&
                   EpicLootRaritySetsPlugin.ConfigureWiresEnemyHudCompatibility.Value;
        }

        private static bool IsWiresEnemyHudInstalled()
        {
            try
            {
                if (BepInEx.Bootstrap.Chainloader.PluginInfos.ContainsKey(PluginGuid))
                {
                    return true;
                }

                return !string.IsNullOrEmpty(Paths.PluginPath) &&
                       Directory.Exists(Paths.PluginPath) &&
                       Directory.GetFiles(Paths.PluginPath, DllName, SearchOption.AllDirectories).Length > 0;
            }
            catch
            {
                return false;
            }
        }
    }

    internal static class BetterArcheryInventorySlotsCompatibility
    {
        private const string BetterArcheryTypeName = "BetterArchery.BetterArchery";
        private static bool _logged;
        private static bool _quiverRowIndexFieldResolved;
        private static FieldInfo _quiverRowIndexField;

        internal static void Patch(Harmony harmony)
        {
            if (harmony == null ||
                EpicLootRaritySetsPlugin.DisableBetterArcheryQuiverInventorySlots == null ||
                !EpicLootRaritySetsPlugin.DisableBetterArcheryQuiverInventorySlots.Value)
            {
                return;
            }

            Type betterArcheryType = AccessTools.TypeByName(BetterArcheryTypeName);
            if (betterArcheryType == null)
            {
                return;
            }

            try
            {
                PatchVoidSkip(harmony, "BetterArchery.Player_Awake_Patch", "Prefix");
                PatchBoolPassThrough(harmony, "BetterArchery.Player_SetInventorySize_Patch", "Prefix");
                PatchBoolPassThrough(harmony, "BetterArchery.Inventory_FindEmptySlot_Patch", "Prefix");
                PatchBoolPassThrough(harmony, "BetterArchery.Inventory_HaveEmptySlot_Patch", "Prefix");
                PatchBoolPassThrough(harmony, "BetterArchery.Player_CreateTombStone_Patch", "Prefix");
                PatchVoidSkip(harmony, "BetterArchery.InventoryGrid_UpdateGui_Patch", "Postfix");

                PatchBoolFalse(harmony, AccessTools.Method(betterArcheryType, "IsQuiverSlot", new[] { typeof(Vector2i) }));
                PatchBoolFalse(harmony, AccessTools.Method(betterArcheryType, "IsQuiverSlot", new[] { typeof(int), typeof(int) }));
                PatchVoidSkip(harmony, AccessTools.Method(betterArcheryType, "CheckQuiverUseInput", new[] { typeof(Player), typeof(int) }));

                Type quiverHudType = AccessTools.TypeByName("BetterArchery.QuiverHud");
                if (quiverHudType != null)
                {
                    PatchBoolFalse(harmony, AccessTools.Method(quiverHudType, "BuildSlots", new[] { typeof(Player) }));
                    PatchVoidSkip(harmony, AccessTools.Method(quiverHudType, "SetSlotsVisible", new[] { typeof(bool) }));
                    PatchVoidSkip(harmony, AccessTools.Method(quiverHudType, "UseQuiverSlot", new[] { typeof(int) }));
                }

                SetQuiverRowIndex(-1);
                EpicLootRaritySetsPlugin.Log.LogInfo("BetterArchery quiver inventory slots disabled; InventorySlots can use expanded cells for normal pickup.");
            }
            catch (Exception ex)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not patch BetterArchery quiver inventory slots: " + ex.GetBaseException().Message);
            }
        }

        private static void PatchBoolPassThrough(Harmony harmony, string typeName, string methodName)
        {
            Type type = AccessTools.TypeByName(typeName);
            PatchBoolPassThrough(harmony, type == null ? null : AccessTools.Method(type, methodName));
        }

        private static void PatchBoolPassThrough(Harmony harmony, MethodInfo target)
        {
            MethodInfo prefix = AccessTools.Method(typeof(BetterArcheryInventorySlotsCompatibility), "ReturnTrueAndSkip");
            Patch(harmony, target, prefix);
        }

        private static void PatchBoolFalse(Harmony harmony, MethodInfo target)
        {
            MethodInfo prefix = AccessTools.Method(typeof(BetterArcheryInventorySlotsCompatibility), "ReturnFalseAndSkip");
            Patch(harmony, target, prefix);
        }

        private static void PatchVoidSkip(Harmony harmony, string typeName, string methodName)
        {
            Type type = AccessTools.TypeByName(typeName);
            PatchVoidSkip(harmony, type == null ? null : AccessTools.Method(type, methodName));
        }

        private static void PatchVoidSkip(Harmony harmony, MethodInfo target)
        {
            MethodInfo prefix = AccessTools.Method(typeof(BetterArcheryInventorySlotsCompatibility), "SkipVoid");
            Patch(harmony, target, prefix);
        }

        private static void Patch(Harmony harmony, MethodInfo target, MethodInfo prefix)
        {
            if (harmony == null || target == null || prefix == null)
            {
                return;
            }

            harmony.Patch(target, prefix: new HarmonyMethod(prefix));
        }

        private static bool ReturnTrueAndSkip(ref bool __result)
        {
            __result = true;
            SetQuiverRowIndex(-1);
            LogOnce();
            return false;
        }

        private static bool ReturnFalseAndSkip(ref bool __result)
        {
            __result = false;
            SetQuiverRowIndex(-1);
            LogOnce();
            return false;
        }

        private static bool SkipVoid()
        {
            SetQuiverRowIndex(-1);
            LogOnce();
            return false;
        }

        private static void SetQuiverRowIndex(int rowIndex)
        {
            FieldInfo field = GetQuiverRowIndexField();
            if (field != null)
            {
                field.SetValue(null, rowIndex);
            }
        }

        private static FieldInfo GetQuiverRowIndexField()
        {
            if (_quiverRowIndexFieldResolved)
            {
                return _quiverRowIndexField;
            }

            _quiverRowIndexFieldResolved = true;
            Type betterArcheryType = AccessTools.TypeByName(BetterArcheryTypeName);
            _quiverRowIndexField = betterArcheryType == null ? null : AccessTools.Field(betterArcheryType, "QuiverRowIndex");
            return _quiverRowIndexField;
        }

        private static void LogOnce()
        {
            if (_logged || EpicLootRaritySetsPlugin.Log == null)
            {
                return;
            }

            _logged = true;
            EpicLootRaritySetsPlugin.Log.LogInfo("Suppressed BetterArchery quiver slot handling.");
        }
    }

    internal static class RaritySetRegistry
    {
        private static readonly ItemRarity[] SupportedRarities =
        {
            ItemRarity.Magic,
            ItemRarity.Rare,
            ItemRarity.Epic,
            ItemRarity.Legendary,
            ItemRarity.Mythic,
            ItemRarity.Ancient
        };

        private static readonly ItemRarity[] EpicLootSetCompendiumRarities =
        {
            ItemRarity.Magic,
            ItemRarity.Rare,
            ItemRarity.Epic,
            ItemRarity.Ancient
        };

        private static readonly Dictionary<ItemRarity, List<LegendaryInfo>> ItemsByRarity = new Dictionary<ItemRarity, List<LegendaryInfo>>();
        private static readonly Dictionary<string, LegendaryInfo> ItemById = new Dictionary<string, LegendaryInfo>();
        private static readonly Dictionary<string, ItemRarity> ItemRarityById = new Dictionary<string, ItemRarity>();
        private static readonly Dictionary<string, LegendarySetInfo> SetById = new Dictionary<string, LegendarySetInfo>();
        private static readonly Dictionary<string, ItemRarity> SetRarityById = new Dictionary<string, ItemRarity>();
        private static readonly Dictionary<string, string> SetIdByItemId = new Dictionary<string, string>();
        private static readonly Dictionary<string, string[]> AdventureBaseItemsByCustomId = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
        {
            { "EpicHellsyngWitchfinderArbalest", new[] { "CrossbowArbalest" } },
            { "EpicHellsyngWidebrim", new[] { "HelmetCarapace", "HelmetPadded", "HelmetDrake" } },
            { "EpicHellsyngLongcoat", new[] { "ArmorCarapaceChest", "ArmorPaddedCuirass", "ArmorIronChest" } },
            { "EpicHellsyngBoots", new[] { "ArmorCarapaceLegs", "ArmorPaddedGreaves", "ArmorIronLegs" } },

            { "EpicThorReturningAxe", new[] { "AxeJotunBane", "AxeBlackMetal", "AxeIron" } },
            { "EpicThorStormHelm", new[] { "HelmetCarapace", "HelmetPadded", "HelmetDrake" } },
            { "EpicThorThunderHarness", new[] { "ArmorCarapaceChest", "ArmorPaddedCuirass", "ArmorIronChest" } },
