    [HarmonyPatch(typeof(Skills), "CheatRaiseSkill")]
    internal static class ClassSkillCheatRaisePatch
    {
        private static bool Prefix(Skills __instance, string name, float value, bool showMessage)
        {
            return !ClassSkillManager.TryCheatRaiseSkill(__instance, name, value, showMessage);
        }

        private static void Postfix(Skills __instance, string name, float value)
        {
            if (string.Equals(name, "all", StringComparison.OrdinalIgnoreCase))
            {
                ClassSkillManager.CheatRaiseAll(__instance, value);
            }
        }
    }

    [HarmonyPatch(typeof(Skills), "CheatResetSkill")]
    internal static class ClassSkillCheatResetPatch
    {
        private static bool Prefix(Skills __instance, string name)
        {
            return !ClassSkillManager.TryCheatResetSkill(__instance, name);
        }

        private static void Postfix(Skills __instance, string name)
        {
            if (string.Equals(name, "all", StringComparison.OrdinalIgnoreCase))
            {
                ClassSkillManager.ResetAll(__instance);
            }
        }
    }

    [HarmonyPatch(typeof(Skills), "GetSkillFactor")]
    internal static class ClassSkillMagicEffectSkillFactorPatch
    {
        private static void Postfix(Skills __instance, Skills.SkillType skillType, ref float __result)
        {
            Player player = Player.m_localPlayer;
            if (__instance == null || player == null || player.GetSkills() != __instance)
            {
                return;
            }

            if (!ClassSkillManager.IsClassSkill(skillType))
            {
                return;
            }

            __result += ClassSkillManager.GetActiveMagicSkillBonus(player, skillType) / 100f;
        }
    }

    internal static class SetActivationBuffController
    {
        private const float UpdateInterval = 0.5f;
        private const float BuffTtl = 1.5f;
        private const string BuffNamePrefix = "FranSetActive_";
        private const string BuffCategory = "FranSetActivation";
        private const string ActiveHeaderColor = "#FFA626";
        private const string ActiveAccentColor = "#f5da53";
        private const string ActiveTextColor = "#c0c0c0ff";
        private const string ActiveGoodColor = "#70f56c";

        private static readonly Dictionary<string, StatusEffect> BuffsByBaseSet = new Dictionary<string, StatusEffect>(StringComparer.OrdinalIgnoreCase);
        private static readonly HashSet<string> ActiveBaseSets = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        private static readonly FieldInfo StatusEffectTimeField = AccessTools.Field(typeof(StatusEffect), "m_time");
        private static float _updateTimer;
        private static string _activeSignature = string.Empty;

        internal static bool HasActiveSet(string baseSetName)
        {
            return !string.IsNullOrEmpty(baseSetName) && ActiveBaseSets.Contains(baseSetName);
        }

        internal static string[] GetActiveBaseSetsSnapshot()
        {
            return ActiveBaseSets.ToArray();
        }

        internal static string[] GetActiveBaseSetsSnapshot(Player player)
        {
            HashSet<string> active = new HashSet<string>(ActiveBaseSets, StringComparer.OrdinalIgnoreCase);

            if (player != null)
            {
                foreach (string baseSetName in BuffsByBaseSet.Keys.ToArray())
                {
                    if (HasActiveBuff(player, baseSetName))
                    {
                        active.Add(baseSetName);
                    }
                }

                if (player == Player.m_localPlayer && active.Count == 0)
                {
                    foreach (string baseSetName in GetActiveBaseSets(player))
                    {
                        active.Add(baseSetName);
                    }
                }
            }

            return active.ToArray();
        }

        internal static bool HasActiveSet(Player player, string baseSetName)
        {
            if (player == null || string.IsNullOrEmpty(baseSetName))
            {
                return false;
            }

            if (HasActiveSet(baseSetName))
            {
                return true;
            }

            return HasActiveBuff(player, baseSetName);
        }

        private static bool HasActiveBuff(Player player, string baseSetName)
        {
            if (player == null || string.IsNullOrEmpty(baseSetName))
            {
                return false;
            }

            StatusEffect template = GetOrCreateBuff(baseSetName, null, false, player);
            return template != null && player.GetSEMan().HaveStatusEffect(template.NameHash());
        }

        internal static void Update(Player player, float dt)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            _updateTimer -= dt;
            if (_updateTimer > 0f)
            {
                return;
            }

            _updateTimer = UpdateInterval;

            if (EpicLootRaritySetsPlugin.EnableSetActivationBuffs != null && !EpicLootRaritySetsPlugin.EnableSetActivationBuffs.Value)
            {
                Clear(player);
                return;
            }

            HashSet<string> activeNow = GetActiveBaseSets(player);
            SEMan seMan = player.GetSEMan();

            string activeSignature = BuildActiveSignature(activeNow);
            if (string.Equals(_activeSignature, activeSignature, StringComparison.Ordinal))
            {
                foreach (string baseSetName in activeNow)
                {
                    RefreshActiveBuffLifetime(seMan, player, baseSetName);
                }

                return;
            }

            foreach (string oldBaseSet in ActiveBaseSets.ToArray())
            {
                if (activeNow.Contains(oldBaseSet))
                {
                    continue;
                }

                StatusEffect oldBuff = GetOrCreateBuff(oldBaseSet, null, false);
                if (oldBuff != null)
                {
                    seMan.RemoveStatusEffect(oldBuff.NameHash(), true);
                }
            }

            ActiveBaseSets.Clear();
            foreach (string baseSetName in activeNow)
            {
                ActiveBaseSets.Add(baseSetName);
                StatusEffect buff = GetOrCreateBuff(baseSetName, FindActiveSetIcon(player, baseSetName), true, player);
                if (buff != null)
                {
                    seMan.AddStatusEffect(buff, true, 0, 0f, 0);
                    ApplyActiveBuffFields(seMan.GetStatusEffect(buff.NameHash()), buff);
                }
            }

            _activeSignature = activeSignature;
        }

        internal static void Clear(Player player)
        {
            if (player != null)
            {
                SEMan seMan = player.GetSEMan();
                foreach (string baseSetName in ActiveBaseSets.ToArray())
                {
                    StatusEffect buff = GetOrCreateBuff(baseSetName, null, false);
                    if (buff != null)
                    {
                        seMan.RemoveStatusEffect(buff.NameHash(), true);
                    }
                }
            }

            ActiveBaseSets.Clear();
            _activeSignature = string.Empty;
            _updateTimer = 0f;
        }

        private static HashSet<string> GetActiveBaseSets(Player player)
        {
            Dictionary<string, HashSet<string>> piecesBySetId = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
            Inventory inventory = player.GetInventory();
            if (inventory == null)
            {
                return new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            }

            foreach (ItemDrop.ItemData item in inventory.GetEquippedItems())
            {
                if (item == null)
                {
                    continue;
                }

                MagicItem magicItem = ItemDataExtensions.GetMagicItem(item);
                if (magicItem == null || string.IsNullOrEmpty(magicItem.SetID))
                {
                    continue;
                }

                if (!piecesBySetId.ContainsKey(magicItem.SetID))
                {
                    piecesBySetId[magicItem.SetID] = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                }

                if (!string.IsNullOrEmpty(magicItem.LegendaryID))
                {
                    piecesBySetId[magicItem.SetID].Add(magicItem.LegendaryID);
                }
            }

            HashSet<string> activeBaseSets = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (KeyValuePair<string, HashSet<string>> entry in piecesBySetId)
            {
                if (!RaritySetRegistry.HasRequiredClassActivationPieces(entry.Key, entry.Value))
                {
                    continue;
                }

                string baseSetName = RaritySetRegistry.GetBaseSetName(entry.Key);
                if (!string.IsNullOrEmpty(baseSetName))
                {
                    activeBaseSets.Add(baseSetName);
                }
            }

            return activeBaseSets;
        }

        private static string BuildActiveSignature(HashSet<string> activeBaseSets)
        {
            if (activeBaseSets == null || activeBaseSets.Count == 0)
            {
                return string.Empty;
            }

            return string.Join("|", activeBaseSets.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToArray());
        }

        private static void RefreshActiveBuffLifetime(SEMan seMan, Player player, string baseSetName)
        {
            if (seMan == null || string.IsNullOrEmpty(baseSetName))
            {
                return;
            }

            StatusEffect template = GetOrCreateBuff(baseSetName, FindActiveSetIcon(player, baseSetName), true, player);
            if (template == null)
            {
                return;
            }

            StatusEffect active = seMan.GetStatusEffect(template.NameHash());
            if (active == null)
            {
                seMan.AddStatusEffect(template, true, 0, 0f, 0);
                ApplyActiveBuffFields(seMan.GetStatusEffect(template.NameHash()), template);

                return;
            }

            if (!(active is FixedIconTextStatusEffect))
            {
                seMan.RemoveStatusEffect(template.NameHash(), true);
                seMan.AddStatusEffect(template, true, 0, 0f, 0);
                ApplyActiveBuffFields(seMan.GetStatusEffect(template.NameHash()), template);
                return;
            }

            ApplyActiveBuffFields(active, template);
        }

        private static void ApplyActiveBuffFields(StatusEffect active, StatusEffect template)
        {
            if (active == null || template == null)
            {
                return;
            }

            active.m_name = template.m_name;
            active.m_tooltip = template.m_tooltip;
            active.m_ttl = template.m_ttl;
            active.m_icon = template.m_icon;
            active.m_flashIcon = template.m_flashIcon;
            active.m_cooldownIcon = template.m_cooldownIcon;
            active.m_hidden = template.m_hidden;
            active.m_category = template.m_category;

            FixedIconTextStatusEffect sourceText = template as FixedIconTextStatusEffect;
            FixedIconTextStatusEffect activeText = active as FixedIconTextStatusEffect;
            if (activeText != null)
            {
                activeText.IconText = sourceText != null ? sourceText.IconText : string.Empty;
            }

            ResetActiveBuffTime(active);
        }

        private static void ResetActiveBuffTime(StatusEffect active)
        {
            if (StatusEffectTimeField != null)
            {
                try
                {
                    StatusEffectTimeField.SetValue(active, 0f);
                }
                catch
                {
                }
            }
        }

        private static StatusEffect GetOrCreateBuff(string baseSetName, Sprite icon, bool refreshTooltip = true, Player player = null)
        {
            if (string.IsNullOrEmpty(baseSetName))
            {
                return null;
            }

            StatusEffect buff;
            if (!BuffsByBaseSet.TryGetValue(baseSetName, out buff) || buff == null || !(buff is FixedIconTextStatusEffect))
            {
                buff = ScriptableObject.CreateInstance<FixedIconTextStatusEffect>();
                buff.name = BuffNamePrefix + baseSetName;
                buff.m_name = GetDisplayName(baseSetName);
                buff.m_category = BuffCategory;
                buff.m_flashIcon = false;
                buff.m_cooldownIcon = false;
                buff.m_hidden = false;
                BuffsByBaseSet[baseSetName] = buff;
            }

            buff.m_ttl = BuffTtl;
            SetClassLevelIconText(buff, player, baseSetName);
            if (!refreshTooltip)
            {
                return buff;
            }

            buff.m_name = GetDisplayName(baseSetName);
            buff.m_tooltip = GetActiveEffectTooltip(baseSetName);
            if (icon != null)
            {
                buff.m_icon = icon;
            }

            return buff;
        }

        private static void SetClassLevelIconText(StatusEffect buff, Player player, string baseSetName)
        {
            FixedIconTextStatusEffect fixedText = buff as FixedIconTextStatusEffect;
            if (fixedText == null)
            {
                return;
            }

            fixedText.IconText = GetClassLevelIconText(player, baseSetName);
        }

        private static string GetClassLevelIconText(Player player, string baseSetName)
        {
            Player source = player ?? Player.m_localPlayer;
            float level = ClassSkillManager.GetSkillLevel(source, baseSetName);
            return Mathf.FloorToInt(Mathf.Max(0f, level)).ToString(CultureInfo.InvariantCulture);
        }

        private static string GetActiveEffectTooltip(string baseSetName)
        {
            string rawTooltip = GetBuffTooltip(baseSetName);
            string displayName = GetDisplayName(baseSetName);
            List<string> content = new List<string>
            {
                ActiveTitle(LocalizedText.Select(displayName + " activo", displayName + " active")),
                ActiveLabel(LocalizedText.Select("Estado", "Status")) + ActiveTextInline(LocalizedText.Select("Set completo equipado. Habilidades y pasivas de clase activas.", "Full set equipped. Class abilities and passives are active."))
            };

            if (!string.IsNullOrEmpty(rawTooltip))
            {
                content.AddRange(FormatActiveTooltip(rawTooltip, baseSetName));
            }

            return string.Join("\n\n", content.ToArray());
        }

        private static IEnumerable<string> FormatActiveTooltip(string tooltip, string baseSetName)
        {
            string normalized = tooltip.Replace("\r\n", "\n");
            string[] blocks = normalized.Split(new[] { "\n\n" }, StringSplitOptions.RemoveEmptyEntries);

            foreach (string block in blocks)
            {
                string trimmedBlock = block.Trim();
                if (trimmedBlock.Length == 0 ||
                    trimmedBlock.Equals(baseSetName + " set completo activo.", StringComparison.OrdinalIgnoreCase) ||
                    trimmedBlock.Equals(GetDisplayName(baseSetName) + " set completo activo.", StringComparison.OrdinalIgnoreCase) ||
                    trimmedBlock.Equals(baseSetName + " full set active.", StringComparison.OrdinalIgnoreCase) ||
                    trimmedBlock.Equals(GetDisplayName(baseSetName) + " full set active.", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string[] lines = trimmedBlock.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries)
                    .Select(x => x.Trim())
                    .Where(x => x.Length > 0)
                    .ToArray();

                if (lines.Length == 0)
                {
                    continue;
                }

                if (lines.Length == 1)
                {
                    yield return FormatActiveTooltipLine(lines[0]);
                    continue;
                }

                string first = lines[0];
                if (first.EndsWith(":", StringComparison.Ordinal))
                {
                    yield return ActiveSection(first.TrimEnd(':')) + "\n" + string.Join("\n", lines.Skip(1).Select(FormatActiveTooltipLine).ToArray());
                    continue;
                }

                yield return string.Join("\n", lines.Select(FormatActiveTooltipLine).ToArray());
            }
        }

        private static string FormatActiveTooltipLine(string line)
        {
            string trimmed = LocalizedText.LocalizeAbilityTerms(line.Trim());
            if (trimmed.Length == 0)
            {
                return string.Empty;
            }

            if (trimmed.EndsWith(":", StringComparison.Ordinal))
            {
                return ActiveSection(trimmed.TrimEnd(':'));
            }

            int colon = trimmed.IndexOf(':');
            if (colon > 0 && colon <= 34)
            {
                string key = trimmed.Substring(0, colon).Trim();
                string value = trimmed.Substring(colon + 1).Trim();
                return "\t" + ActiveInlineLabel(key) + (value.Length > 0 ? ActiveTextInline(value) : string.Empty);
            }

            return "\t" + ActiveTextInline("- " + trimmed);
        }

        private static string GetDisplayName(string baseSetName)
        {
            return string.Equals(baseSetName, "Hellsyng", StringComparison.OrdinalIgnoreCase) ? "Hellsyng" : baseSetName;
        }

        private static string ActiveTitle(string value)
        {
            return "<size=18><color=" + ActiveHeaderColor + "><b>" + value + "</b></color></size>";
        }

        private static string ActiveSection(string value)
        {
            return "<color=" + ActiveHeaderColor + "><b>" + value + "</b></color>";
        }

        private static string ActiveLabel(string value)
        {
            return "<color=" + ActiveAccentColor + "><b>" + value + ":</b></color> ";
        }

        private static string ActiveInlineLabel(string value)
        {
            return "<color=" + ActiveGoodColor + "><b>" + value + ":</b></color> ";
        }

        private static string ActiveTextInline(string value)
        {
            return "<color=" + ActiveTextColor + ">" + value + "</color>";
        }

        internal static string GetBuffTooltip(string baseSetName)
        {
            if (!LocalizedText.IsSpanish())
            {
                return GetBuffTooltipEnglish(baseSetName);
            }

            if (string.Equals(baseSetName, "Frostbrand", StringComparison.OrdinalIgnoreCase))
            {
                float elemental = ClassSkillManager.GetLocalSkillLevel("Frostbrand");
                float fireball = ScaleSkillValue(EpicLootRaritySetsPlugin.FrostbrandLightningStrikeBaseDamage.Value, EpicLootRaritySetsPlugin.FrostbrandLightningStrikeDamagePerElementalMagicLevel.Value, elemental);
                float slash = ScaleSkillValue(EpicLootRaritySetsPlugin.FrostbrandSlashBaseDamage.Value, EpicLootRaritySetsPlugin.FrostbrandSlashDamagePerElementalMagicLevel.Value, elemental);
                float lightningStrike = ScaleSkillValue(EpicLootRaritySetsPlugin.FrostbrandLightningChannelBaseDamagePerTick.Value, EpicLootRaritySetsPlugin.FrostbrandLightningChannelDamagePerElementalMagicLevel.Value, elemental);
                float shieldMitigation = ClampScaledFraction(EpicLootRaritySetsPlugin.FrostbrandElementalShieldBaseMitigation.Value, EpicLootRaritySetsPlugin.FrostbrandElementalShieldMitigationPerElementalMagicLevel.Value, elemental, EpicLootRaritySetsPlugin.FrostbrandElementalShieldMaxMitigation.Value) * 100f;
                float shieldBase = EpicLootRaritySetsPlugin.FrostbrandElementalShieldBaseMitigation.Value * 100f;
                float shieldPerLevel = EpicLootRaritySetsPlugin.FrostbrandElementalShieldMitigationPerElementalMagicLevel.Value * 100f;
                float shieldMax = EpicLootRaritySetsPlugin.FrostbrandElementalShieldMaxMitigation.Value * 100f;
                float dashSpeed = EpicLootRaritySetsPlugin.FrostbrandDashSpeedBonus.Value * 100f;
                float slashHeal = EpicLootRaritySetsPlugin.FrostbrandSlashHealFraction.Value * 100f;
                return "Frostbrand set completo activo.\n\nEscalado actual: Frostbrand " + elemental.ToString("0.#") + ".\n\nHabilidades:\n"
                    + LocalizedText.AbilityName("Dash") + ": tecla " + FormatShortcut(EpicLootRaritySetsPlugin.FrostbrandDashHotkey) + ". Coste " + EpicLootRaritySetsPlugin.FrostbrandDashEitrUse.Value.ToString("0") + " eitr. Tiene " + EpicLootRaritySetsPlugin.FrostbrandDashMaxCharges.Value + " cargas; recupera una carga cada " + EpicLootRaritySetsPlugin.FrostbrandDashRechargeSeconds.Value.ToString("0.#") + "s. Usa AbilityDash de NorseDemigods con tema Thor/rayo. Al usarlo: +" + dashSpeed.ToString("0.#") + "% velocidad durante " + EpicLootRaritySetsPlugin.FrostbrandDashSpeedDuration.Value.ToString("0.#") + "s.\n"
                    + "Slash de Surt: tecla ataque secundario. Coste " + EpicLootRaritySetsPlugin.FrostbrandSlashEitrUse.Value.ToString("0") + " eitr. CD " + EpicLootRaritySetsPlugin.FrostbrandSlashCooldown.Value.ToString("0") + "s. Escala con Frostbrand: " + EpicLootRaritySetsPlugin.FrostbrandSlashBaseDamage.Value.ToString("0.#") + "+" + EpicLootRaritySetsPlugin.FrostbrandSlashDamagePerElementalMagicLevel.Value.ToString("0.##") + "/nivel. Resultado actual: " + slash.ToString("0.#") + " fuego + " + slash.ToString("0.#") + " tajo. Cura " + slashHeal.ToString("0.#") + "% del dano real infligido. Tambien carga Fire Ball.\n"
                    + "Elemental Shield de Surt: tecla " + FormatBlockShortcut(EpicLootRaritySetsPlugin.FrostbrandElementalShieldHotkey) + ". Coste " + EpicLootRaritySetsPlugin.FrostbrandElementalShieldEitrUse.Value.ToString("0") + " eitr. CD " + EpicLootRaritySetsPlugin.FrostbrandElementalShieldCooldown.Value.ToString("0") + "s. Dura " + EpicLootRaritySetsPlugin.FrostbrandElementalShieldDuration.Value.ToString("0.#") + "s, anula fuego y mitiga dano actual " + shieldMitigation.ToString("0.#") + "%. Escalado: " + shieldBase.ToString("0.#") + "% base + " + shieldPerLevel.ToString("0.##") + "%/nivel, max " + shieldMax.ToString("0.#") + "%.\n"
                    + "Lightning Strike de Thor: tecla " + FormatShortcut(EpicLootRaritySetsPlugin.FrostbrandLightningChannelHotkey) + ". Reemplaza Crush. Coste " + EpicLootRaritySetsPlugin.FrostbrandLightningChannelEitrPerSecond.Value.ToString("0") + " eitr. CD " + EpicLootRaritySetsPlugin.FrostbrandLightningChannelCooldown.Value.ToString("0") + "s. Lanza 3 impactos seguidos cada " + EpicLootRaritySetsPlugin.FrostbrandLightningChannelTickInterval.Value.ToString("0.##") + "s. Rango " + EpicLootRaritySetsPlugin.FrostbrandLightningChannelRange.Value.ToString("0.#") + "m, radio " + EpicLootRaritySetsPlugin.FrostbrandLightningChannelRadius.Value.ToString("0.#") + "m. Rayo actual " + lightningStrike.ToString("0.#") + " por impacto antes de resistencias; inmoviliza " + EpicLootRaritySetsPlugin.FrostbrandLightningRootDuration.Value.ToString("0.#") + "s.\n\nPasivas:\n"
                    + "Fire Ball: cada " + EpicLootRaritySetsPlugin.FrostbrandLightningStrikeAttackCount.Value + " ataques con arma Frostbrand o usos de Slash muestra cargas y lanza Fire Ball a donde apuntas. Escala con Frostbrand: " + EpicLootRaritySetsPlugin.FrostbrandLightningStrikeBaseDamage.Value.ToString("0.#") + "+" + EpicLootRaritySetsPlugin.FrostbrandLightningStrikeDamagePerElementalMagicLevel.Value.ToString("0.##") + "/nivel. Resultado actual: " + fireball.ToString("0.#") + " fuego antes de modificadores EpicLoot.\nRecharge: ataques y habilidades solo suman cargas cuando golpean a un enemigo. Dura 15s, cada carga da +4% todo el dano, maximo 5. A 5/5, los ataques activan Chain Lightning garantizado hasta 3 saltos en 8m.";
            }

            if (string.Equals(baseSetName, "Moonvein", StringComparison.OrdinalIgnoreCase))
            {
                float elemental = ClassSkillManager.GetLocalSkillLevel("Moonvein");
                float acid = ScaleSkillValue(EpicLootRaritySetsPlugin.MoonveinAcidBoltBaseDamage.Value, EpicLootRaritySetsPlugin.MoonveinAcidBoltDamagePerElementalMagicLevel.Value, elemental);
                float lightning = ScaleSkillValue(EpicLootRaritySetsPlugin.MoonveinLightningBoltBaseDamage.Value, EpicLootRaritySetsPlugin.MoonveinLightningBoltDamagePerElementalMagicLevel.Value, elemental);
                float fireball = ScaleSkillValue(EpicLootRaritySetsPlugin.MoonveinFireballBaseDamage.Value, EpicLootRaritySetsPlugin.MoonveinFireballDamagePerElementalMagicLevel.Value, elemental);
                float meteor = ScaleSkillValue(EpicLootRaritySetsPlugin.MoonveinMeteorBaseDamage.Value, EpicLootRaritySetsPlugin.MoonveinMeteorDamagePerElementalMagicLevel.Value, elemental);
                float tornado = ScaleSkillValue(EpicLootRaritySetsPlugin.MoonveinTornadoBaseDamage.Value, EpicLootRaritySetsPlugin.MoonveinTornadoDamagePerElementalMagicLevel.Value, elemental);
                float arcaneLightning = ScaleSkillValue(EpicLootRaritySetsPlugin.MoonveinShotLightningBaseDamage.Value, EpicLootRaritySetsPlugin.MoonveinShotLightningDamagePerMoonveinLevel.Value, elemental);
                float arcaneSpirit = ScaleSkillValue(EpicLootRaritySetsPlugin.MoonveinShotSpiritBaseDamage.Value, EpicLootRaritySetsPlugin.MoonveinShotSpiritDamagePerMoonveinLevel.Value, elemental);
                return string.Format(
                    "Moonvein set completo activo.\n\nEscalado actual: Moonvein {21:0.#}.\n\nPasivas:\nDisparos arcanos: cada disparo normal con arco Moonvein anade {27:0.#}+{28:0.##}/nivel = {29:0.#} rayo y {30:0.#}+{31:0.##}/nivel = {32:0.#} espiritu.\nDisparos cargados: al llenar 2 cargas, el siguiente disparo consecutivo lanza un hechizo aleatorio desde el arco y reinicia el contador.\nRecarga: ataques y habilidades Moonvein suman cargas al golpear. Dura 15s, cada carga da +4% todo el dano, maximo 5. A 5/5, los golpes activan Chain Lightning garantizado hasta 3 saltos en 8m.\n\nDisparos cargados:\nProbabilidades: Proyectil acido 40%, Proyectil de rayo 40%, Bola de fuego 20%.\nProyectil acido: {6:0.#}+{7:0.##}/nivel = {22:0.#} veneno.\nProyectil de rayo: {8:0.#}+{9:0.##}/nivel = {23:0.#} rayo.\nBola de fuego: {10:0.#}+{11:0.##}/nivel = {24:0.#} fuego.\n\nHabilidades:\nMeteoro: tecla {0}. Coste {1:0} eitr. CD {2:0}s. Escala con Moonvein: {12:0.#}+{13:0.##}/nivel = {25:0.#} fuego + {25:0.#} contundente. Lanza 1 meteorito; 2 desde nivel 60 y 3 desde nivel 90. Si lanza mas de uno, caen con 1.5s entre meteoritos; los extra caen a 1m a izquierda/derecha del principal.\nDisparo tornado: tecla {3}. Coste {4:0} eitr. CD {5:0}s. Arma la siguiente flecha; al impactar invoca el tornado de Njord donde caiga durante {17:0.#}s. Ralentizacion {19:0.#}% durante {20:0.#}s por golpe. Alternativa: rayo {14:0.#}+{15:0.##}/nivel = {26:0.#} cada {16:0.##}s en {18:0.#}m.\nLobo espiritual: tecla {33}. Coste {34:0} eitr. Invoca wolf_spiritcaller con vida, dano y reduccion recibida escalados por Moonvein. Obedece comandos de mascota. Si muere, CD {35:0}s.\nLos hechizos de dano propios pasan por modificadores de EpicLoot como ModifyDamage y ModifyElementalDamage.",
                    FormatShortcut(EpicLootRaritySetsPlugin.MoonveinMeteorHotkey),
                    EpicLootRaritySetsPlugin.MoonveinMeteorEitrUse.Value,
                    EpicLootRaritySetsPlugin.MoonveinMeteorCooldown.Value,
                    FormatShortcut(EpicLootRaritySetsPlugin.MoonveinTornadoHotkey),
                    EpicLootRaritySetsPlugin.MoonveinTornadoEitrUse.Value,
                    EpicLootRaritySetsPlugin.MoonveinTornadoCooldown.Value,
