                float stoneReduction = ScaleSkillValue(EpicLootRaritySetsPlugin.HeimdallStoneShieldBaseReduction.Value, EpicLootRaritySetsPlugin.HeimdallStoneShieldReductionPerBlockingLevel.Value, blocking);
