    internal static class SetAbilityInput
    {
        internal static bool IsSecondaryAttackDown()
        {
            if (PetCommandController.IsInputConsumedThisFrame())
            {
                return false;
            }

            return GetButtonDown("AltAttack") ||
                   GetButtonDown("SecondaryAttack") ||
                   GetButtonDown("SpecialAttack") ||
                   GetButtonDown("AttackSecondary") ||
                   Input.GetMouseButtonDown(2);
        }

        internal static bool IsAttackDown()
        {
            if (PetCommandController.IsInputConsumedThisFrame())
            {
                return false;
            }

            return GetButtonDown("Attack") ||
                   GetButtonDown("JoyAttack") ||
                   Input.GetMouseButtonDown(0);
        }

        internal static bool IsBlockHeld()
        {
            return GetButton("Block") ||
                   GetButton("JoyBlock") ||
                   Input.GetMouseButton(1);
        }

        internal static bool IsShortcutDown(ConfigEntry<KeyboardShortcut> shortcutEntry)
        {
            if (PetCommandController.IsInputConsumedThisFrame())
            {
                return false;
            }

            if (shortcutEntry == null)
            {
                return false;
            }

            KeyboardShortcut shortcut = shortcutEntry.Value;
            if (shortcut.IsDown())
            {
                return true;
            }

            KeyCode mainKey = shortcut.MainKey;
            if (mainKey == KeyCode.None || !Input.GetKeyDown(mainKey))
            {
                return false;
            }

            foreach (KeyCode modifier in shortcut.Modifiers)
            {
                if (!Input.GetKey(modifier))
                {
                    return false;
                }
            }

            return true;
        }

        internal static bool IsShortcutHeld(ConfigEntry<KeyboardShortcut> shortcutEntry)
        {
            if (shortcutEntry == null)
            {
                return false;
            }

            KeyboardShortcut shortcut = shortcutEntry.Value;
            KeyCode mainKey = shortcut.MainKey;
            if (mainKey == KeyCode.None || !Input.GetKey(mainKey))
            {
                return false;
            }

            foreach (KeyCode modifier in shortcut.Modifiers)
            {
                if (!Input.GetKey(modifier))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool GetButtonDown(string name)
        {
            try
            {
                return ZInput.GetButtonDown(name);
            }
            catch
            {
                return false;
            }
        }

        private static bool GetButton(string name)
        {
            try
            {
                return ZInput.GetButton(name);
            }
            catch
            {
                return false;
            }
        }
    }

    internal static class PetCommandController
    {
        internal enum CommandMode
        {
            Default,
            ForceFollow,
            ForceAttack
        }

        private const float DirectAimRange = 10000f;
        private const float AimAssistRange = 120f;
        private const float AimAssistRadius = 2.25f;

        private static readonly FieldInfo BaseAITargetCreatureField = AccessTools.Field(typeof(BaseAI), "m_targetCreature");
        private static readonly FieldInfo BaseAITargetStaticField = AccessTools.Field(typeof(BaseAI), "m_targetStatic");
        private static readonly FieldInfo BaseAIAlertedField = AccessTools.Field(typeof(BaseAI), "m_alerted");
        private static readonly MethodInfo BaseAISetTargetMethod = AccessTools.Method(typeof(BaseAI), "SetTarget", new[] { typeof(Character) });
        private static readonly MethodInfo MonsterAISetTargetMethod = AccessTools.Method(typeof(MonsterAI), "SetTarget", new[] { typeof(Character) });

        private static CommandMode _mode;
        private static Character _forcedTarget;
        private static int _inputConsumedFrame = -1;

        internal static bool HasActiveOverride
        {
            get { return _mode != CommandMode.Default; }
        }

        internal static CommandMode CurrentMode
        {
            get { return _mode; }
        }

        internal static bool HasActivePets
        {
            get { return GetActivePetCount() > 0; }
        }

        internal static bool IsInputConsumedThisFrame()
        {
            return _inputConsumedFrame == Time.frameCount;
        }

        internal static void Update(Player player, float dt)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            if (_mode == CommandMode.ForceAttack && !IsValidManualTarget(player, _forcedTarget))
            {
                _forcedTarget = null;
                _mode = CommandMode.ForceFollow;
                ShowMessage(player, "Mascotas: objetivo eliminado, seguidme.");
            }

            if (!CanReadInput(player) || !IsControlHeld())
            {
                return;
            }

            if (Input.GetKeyDown(KeyCode.Mouse4))
            {
                MarkInputConsumed();
                TryCommandAttack(player);
                return;
            }

            if (Input.GetKeyDown(KeyCode.Mouse3))
            {
                MarkInputConsumed();
                CommandFollow(player);
                return;
            }

            if (IsSecondaryAttackDownRaw())
            {
                MarkInputConsumed();
                CommandDefault(player);
            }
        }

        internal static bool ApplyToPet(Player owner, GameObject pet, Func<Character, bool> isValidTargetForPet)
        {
            Character petCharacter;
            if (owner == null || !TryGetLivingPetCharacter(pet, out petCharacter))
            {
                return false;
            }

            if (_mode == CommandMode.ForceFollow)
            {
                ForceFollow(owner, pet);
                return true;
            }

            if (_mode == CommandMode.ForceAttack)
            {
                if (IsValidManualTarget(owner, _forcedTarget) &&
                    (isValidTargetForPet == null || isValidTargetForPet(_forcedTarget)))
                {
                    ForceAttack(pet, _forcedTarget);
                    return true;
                }

                _forcedTarget = null;
                _mode = CommandMode.ForceFollow;
                ForceFollow(owner, pet);
                return true;
            }

            return false;
        }

        internal static void ReleasePetFollow(GameObject pet)
        {
            if (pet == null)
            {
                return;
            }

            SetFollowTarget(pet, null);
            BaseAI baseAI = pet.GetComponent<BaseAI>() ?? pet.GetComponentInChildren<BaseAI>();
            ClearAITarget(baseAI);
        }

        internal static bool ShouldCommandedPetsTreatAsEnemy(Character first, Character second)
        {
            Player owner = Player.m_localPlayer;
            if (owner == null || _mode != CommandMode.ForceAttack || !IsValidManualTarget(owner, _forcedTarget))
            {
                return false;
            }

            return (IsCommandedPet(first) && second == _forcedTarget) ||
                   (IsCommandedPet(second) && first == _forcedTarget);
        }

        internal static bool ShouldPassivePetIgnoreEnemy(Character first, Character second)
        {
            Player owner = Player.m_localPlayer;
            return owner != null &&
                   _mode == CommandMode.ForceFollow &&
                   IsCommandedPet(first) &&
                   IsValidManualTarget(owner, second);
        }

        internal static void ModifyCommandedPetOutgoingDamage(HitData hit)
        {
            if (_mode != CommandMode.ForceFollow || hit == null)
            {
                return;
            }

            Character attacker = GetAttacker(hit);
            if (IsCommandedPet(attacker))
            {
                hit.m_damage.Modify(0f);
            }
        }

        private static void TryCommandAttack(Player player)
        {
            if (GetActivePetCount() <= 0)
            {
                ShowMessage(player, "Mascotas: no hay mascotas activas.");
                return;
            }

            Character target;
            if (!TryFindAimedEnemy(player, out target))
            {
                ShowMessage(player, "Mascotas: no hay enemigo apuntado.");
                return;
            }

            _forcedTarget = target;
            _mode = CommandMode.ForceAttack;
            ShowMessage(player, "Mascotas: atacad " + GetTargetName(target) + ".");
        }

        private static void CommandFollow(Player player)
        {
            if (GetActivePetCount() <= 0)
            {
                ShowMessage(player, "Mascotas: no hay mascotas activas.");
                return;
            }

            _forcedTarget = null;
            _mode = CommandMode.ForceFollow;
            ShowMessage(player, "Mascotas: seguidme.");
        }

        private static void CommandDefault(Player player)
        {
            if (GetActivePetCount() <= 0)
            {
                ShowMessage(player, "Mascotas: no hay mascotas activas.");
                return;
            }

            _forcedTarget = null;
            _mode = CommandMode.Default;
            HraesvelgrAbilityController.ReleasePetFollow(player);
            MoonveinAbilityController.ReleasePetFollow(player);
            HelveigAbilityController.ReleasePetFollow(player);
            SeidrAbilityController.ReleasePetFollow(player);
            ShowMessage(player, "Mascotas: modo libre.");
        }

        private static int GetActivePetCount()
        {
            return HraesvelgrAbilityController.GetActivePetCount() +
                   MoonveinAbilityController.GetActivePetCount() +
                   HelveigAbilityController.GetActivePetCount() +
                   SeidrAbilityController.GetActivePetCount();
        }

        private static void ForceFollow(Player owner, GameObject pet)
        {
            SetFollowTarget(pet, owner);
            BaseAI baseAI = pet.GetComponent<BaseAI>() ?? pet.GetComponentInChildren<BaseAI>();
            ClearAITarget(baseAI);
        }

        private static void ForceAttack(GameObject pet, Character target)
        {
            SetFollowTarget(pet, null);
            BaseAI baseAI = pet.GetComponent<BaseAI>() ?? pet.GetComponentInChildren<BaseAI>();
            AssignAITarget(baseAI, target);
        }

        private static void SetFollowTarget(GameObject pet, Player owner)
        {
            MonsterAI monsterAI = pet != null ? pet.GetComponent<MonsterAI>() ?? pet.GetComponentInChildren<MonsterAI>() : null;
            if (monsterAI == null)
            {
                return;
            }

            monsterAI.MakeTame();
            monsterAI.SetFollowTarget(owner != null ? owner.gameObject : null);
        }

        private static void AssignAITarget(BaseAI baseAI, Character target)
        {
            if (baseAI == null || target == null)
            {
                return;
            }

            bool assigned = TryInvokeSetTarget(baseAI, target);
            if (!assigned)
            {
                SetTargetCreatureField(baseAI, target);
            }

            if (BaseAITargetStaticField != null)
            {
                try
                {
                    BaseAITargetStaticField.SetValue(baseAI, null);
                }
                catch
                {
                }
            }

            SetAIAlerted(baseAI, true);
        }

        private static void ClearAITarget(BaseAI baseAI)
        {
            if (baseAI == null)
            {
                return;
            }

            TryInvokeSetTarget(baseAI, null);
            SetTargetCreatureField(baseAI, null);
            if (BaseAITargetStaticField != null)
            {
                try
                {
                    BaseAITargetStaticField.SetValue(baseAI, null);
                }
                catch
                {
                }
            }

            SetAIAlerted(baseAI, false);
        }

        private static bool TryInvokeSetTarget(BaseAI baseAI, Character target)
        {
            foreach (MethodInfo method in new[] { MonsterAISetTargetMethod, BaseAISetTargetMethod })
            {
                if (method == null || baseAI == null || !method.DeclaringType.IsInstanceOfType(baseAI))
                {
                    continue;
                }

                try
                {
                    method.Invoke(baseAI, new object[] { target });
                    return true;
                }
                catch
                {
                }
            }

            return false;
        }

        private static void SetTargetCreatureField(BaseAI baseAI, Character target)
        {
            if (baseAI == null || BaseAITargetCreatureField == null)
            {
                return;
            }

            try
            {
                Type fieldType = BaseAITargetCreatureField.FieldType;
                if (typeof(Character).IsAssignableFrom(fieldType))
                {
                    BaseAITargetCreatureField.SetValue(baseAI, target);
                }
                else if (typeof(GameObject).IsAssignableFrom(fieldType))
                {
                    BaseAITargetCreatureField.SetValue(baseAI, target != null ? target.gameObject : null);
                }
            }
            catch
            {
            }
        }

        private static void SetAIAlerted(BaseAI baseAI, bool alerted)
        {
            if (baseAI == null || BaseAIAlertedField == null)
            {
                return;
            }

            try
            {
                BaseAIAlertedField.SetValue(baseAI, alerted);
            }
            catch
            {
            }
        }

        private static bool TryFindAimedEnemy(Player player, out Character target)
        {
            target = null;
            Transform originTransform = GameCamera.instance != null ? GameCamera.instance.transform : player.transform;
            Vector3 origin = originTransform.position;
            Vector3 direction = originTransform.forward;

            RaycastHit[] hits = Physics.RaycastAll(origin, direction, DirectAimRange, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            Array.Sort(hits, (left, right) => left.distance.CompareTo(right.distance));
            foreach (RaycastHit hit in hits)
            {
                Character candidate = hit.collider != null ? hit.collider.GetComponentInParent<Character>() : null;
                if (candidate == player || IsCommandedPet(candidate))
                {
                    continue;
                }

                if (IsValidManualTarget(player, candidate))
                {
                    target = candidate;
                    return true;
                }

                return false;
            }

            float bestScore = float.MaxValue;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (!IsValidManualTarget(player, character))
                {
                    continue;
                }

                Vector3 toTarget = character.GetCenterPoint() - origin;
                float alongRay = Vector3.Dot(toTarget, direction);
                if (alongRay < 0f || alongRay > AimAssistRange)
                {
                    continue;
                }

                Vector3 closest = origin + direction * alongRay;
                float distanceFromRay = (character.GetCenterPoint() - closest).magnitude;
                if (distanceFromRay > AimAssistRadius)
                {
                    continue;
                }

                float score = alongRay + distanceFromRay * 8f;
                if (score >= bestScore)
                {
                    continue;
                }

                bestScore = score;
                target = character;
            }

            return target != null;
        }

        private static bool IsValidManualTarget(Player player, Character target)
        {
            return player != null &&
                   target != null &&
                   target != player &&
                   !CharacterTargeting.ShouldExcludeNonHostilePlayer(player, target) &&
                   !target.IsDead() &&
                   !target.IsTamed() &&
                   !IsCommandedPet(target);
        }

        private static bool IsCommandedPet(Character character)
        {
            return HraesvelgrAbilityController.IsSummonedBeast(character) ||
                   MoonveinAbilityController.IsSpiritWolfForPetCommand(character) ||
                   HelveigAbilityController.IsControlledUndeadForPetCommand(character) ||
                   SeidrAbilityController.IsStoneGolemForPetCommand(character);
        }

        private static Character GetAttacker(HitData hit)
        {
            if (hit == null)
            {
                return null;
            }

            try
            {
                return hit.GetAttacker();
            }
            catch
            {
                return null;
            }
        }

        private static bool TryGetLivingPetCharacter(GameObject pet, out Character character)
        {
            character = pet != null ? pet.GetComponent<Character>() ?? pet.GetComponentInChildren<Character>() : null;
            return character != null && !character.IsDead();
        }

        private static bool IsControlHeld()
        {
            return Input.GetKey(KeyCode.LeftControl) || Input.GetKey(KeyCode.RightControl);
        }

        private static bool IsSecondaryAttackDownRaw()
        {
            return GetButtonDown("AltAttack") ||
                   GetButtonDown("SecondaryAttack") ||
                   GetButtonDown("SpecialAttack") ||
                   GetButtonDown("AttackSecondary") ||
                   Input.GetMouseButtonDown(2);
        }

        private static bool GetButtonDown(string name)
        {
            try
            {
                return ZInput.GetButtonDown(name);
            }
            catch
            {
                return false;
            }
        }

        private static bool CanReadInput(Player player)
        {
            return player != null &&
                   !player.IsDead() &&
                   !player.IsTeleporting() &&
                   !IsAnyMenuOpen();
        }

        private static bool IsAnyMenuOpen()
        {
            return (InventoryGui.instance != null && InventoryGui.IsVisible()) ||
                   (Menu.instance != null && Menu.IsVisible()) ||
                   (TextInput.instance != null && TextInput.IsVisible()) ||
                   (Chat.instance != null && Chat.instance.HasFocus()) ||
                   (Minimap.instance != null && Minimap.IsOpen());
        }

        private static string GetTargetName(Character target)
        {
            if (target == null)
            {
                return "objetivo";
            }

            try
            {
                string hoverName = target.GetHoverName();
                if (!string.IsNullOrEmpty(hoverName))
                {
                    return Localization.instance != null ? Localization.instance.Localize(hoverName) : hoverName;
                }
            }
            catch
            {
            }

            string name = !string.IsNullOrEmpty(target.m_name) ? target.m_name : target.gameObject.name;
            return Localization.instance != null ? Localization.instance.Localize(name) : name;
        }

        private static void MarkInputConsumed()
        {
            _inputConsumedFrame = Time.frameCount;
        }

        private static void ShowMessage(Player player, string message)
        {
            if (player != null)
            {
                player.Message(MessageHud.MessageType.Center, message, 0, null, false);
            }
        }
    }

    internal static class CharacterTargeting
    {
        internal static bool IsPlayerPvPEnemy(Player owner, Character target)
        {
            Player targetPlayer = target as Player;
            if (owner == null || targetPlayer == null || targetPlayer == owner || targetPlayer.IsDead())
            {
                return false;
            }

            return IsPvpEnabled(owner) && IsPvpEnabled(targetPlayer);
        }

        internal static bool ShouldExcludeNonHostilePlayer(Player owner, Character target)
        {
            return target is Player && !IsPlayerPvPEnemy(owner, target);
        }

        private static bool IsPvpEnabled(Player player)
        {
            if (player == null)
            {
                return false;
            }

            try
            {
                return player.IsPVPEnabled();
            }
            catch
            {
                return false;
            }
        }

    }

    internal static class CharacterControlEffects
    {
        private static readonly MethodInfo CharacterStaggerMethod = AccessTools.GetDeclaredMethods(typeof(Character))
            .FirstOrDefault(method =>
            {
                if (method == null || !string.Equals(method.Name, "Stagger", StringComparison.Ordinal))
                {
                    return false;
                }

                ParameterInfo[] parameters = method.GetParameters();
                return parameters.Length > 0 && parameters[0].ParameterType == typeof(Vector3);
            });

        internal static void TryStagger(Character target, Vector3 direction)
        {
            if (target == null || target.IsDead() || CharacterStaggerMethod == null)
            {
                return;
            }

            if (direction.sqrMagnitude <= 0.001f)
            {
                direction = target.transform.forward;
            }

            ParameterInfo[] parameters = CharacterStaggerMethod.GetParameters();
            object[] args = new object[parameters.Length];
            args[0] = direction.normalized;
            for (int i = 1; i < args.Length; i++)
            {
                Type parameterType = parameters[i].ParameterType;
                if (parameterType == typeof(float))
                {
                    args[i] = 1f;
                }
                else if (parameterType == typeof(bool))
                {
                    args[i] = true;
                }
                else
                {
                    args[i] = parameterType.IsValueType ? Activator.CreateInstance(parameterType) : null;
                }
            }

            try
            {
                CharacterStaggerMethod.Invoke(target, args);
            }
            catch
            {
            }
        }
    }

    internal static class ZNetSceneSafety
    {
        private static readonly FieldInfo ZNetSceneInstancesField = AccessTools.Field(typeof(ZNetScene), "m_instances");
        private static bool _loggedInstanceCleanup;
        private static bool _loggedRemoveObjectsRecovery;

        internal static void Destroy(GameObject gameObject)
        {
            if (gameObject == null)
            {
                return;
            }

            if (ZNetScene.instance != null && HasLiveZNetView(gameObject))
            {
                ZNetScene.instance.Destroy(gameObject);
                return;
            }

            UnityEngine.Object.Destroy(gameObject);
        }

        internal static void Destroy(GameObject gameObject, float delay)
        {
            if (gameObject == null)
            {
                return;
            }

            if (delay <= 0f)
            {
                Destroy(gameObject);
                return;
            }

            if (HasLiveZNetView(gameObject))
            {
                DisableUnsafeTimedDestruction(gameObject);
                ZNetSceneSafeTimedDestroy timedDestroy = gameObject.GetComponent<ZNetSceneSafeTimedDestroy>();
                if (timedDestroy == null)
                {
                    timedDestroy = gameObject.AddComponent<ZNetSceneSafeTimedDestroy>();
                }

                timedDestroy.ResetTimer(delay);
                return;
            }

            UnityEngine.Object.Destroy(gameObject, delay);
        }

        private static void DisableUnsafeTimedDestruction(GameObject gameObject)
        {
            if (gameObject == null)
            {
                return;
            }

            foreach (MonoBehaviour behaviour in gameObject.GetComponentsInChildren<MonoBehaviour>(true))
            {
                if (behaviour == null)
                {
                    continue;
                }

                string typeName = behaviour.GetType().Name;
                if (typeName.IndexOf("TimedDestruction", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    typeName.IndexOf("TimedDestroy", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    behaviour.enabled = false;
                }
            }
        }

        internal static void PrepareRemoveObjects(ZNetScene scene, List<ZDO> currentNearObjects, List<ZDO> currentDistantObjects)
        {
            int removed = RemoveNullZdos(currentNearObjects) + RemoveNullZdos(currentDistantObjects) + CleanupInvalidInstances(scene);
            if (removed > 0 && !_loggedInstanceCleanup)
            {
                _loggedInstanceCleanup = true;
                EpicLootRaritySetsPlugin.Log.LogWarning("Cleaned invalid ZNetScene entries before object removal. This prevents a Valheim ZNetScene.RemoveObjects null reference caused by stale networked objects.");
            }
        }

        internal static Exception RecoverRemoveObjects(ZNetScene scene, Exception exception)
        {
            if (exception == null)
            {
                return null;
            }

            if (!(exception is NullReferenceException))
            {
                return exception;
            }

            int removed = CleanupInvalidInstances(scene);
            if (!_loggedRemoveObjectsRecovery)
            {
                _loggedRemoveObjectsRecovery = true;
                EpicLootRaritySetsPlugin.Log.LogWarning("Recovered from a Valheim ZNetScene.RemoveObjects null reference by pruning invalid networked object entries. Removed entries: " + removed + ".");
            }

            return null;
        }

        internal static void UnregisterDestroyedView(ZNetView view)
        {
            if (view == null || ZNetScene.instance == null || ZNetSceneInstancesField == null)
            {
                return;
            }

            ZDO zdo = null;
            try
            {
                zdo = view.GetZDO();
            }
            catch
            {
            }

            if (zdo == null)
            {
                return;
            }

            Dictionary<ZDO, ZNetView> instances = null;
            try
            {
                instances = ZNetSceneInstancesField.GetValue(ZNetScene.instance) as Dictionary<ZDO, ZNetView>;
            }
            catch
            {
            }

            if (instances == null)
            {
                return;
            }

            ZNetView registeredView;
            if (!instances.TryGetValue(zdo, out registeredView) || registeredView != view)
            {
                return;
            }

            instances.Remove(zdo);
            DestroyOwnedZdo(zdo);
        }

        private static bool HasLiveZNetView(GameObject gameObject)
        {
            if (gameObject == null)
            {
                return false;
            }

            try
            {
                ZNetView view = gameObject.GetComponent<ZNetView>() ?? gameObject.GetComponentInChildren<ZNetView>(true);
                return view != null && view.GetZDO() != null;
            }
            catch
            {
                return false;
            }
        }

        private static int RemoveNullZdos(List<ZDO> zdos)
        {
            if (zdos == null)
            {
                return 0;
            }

            return zdos.RemoveAll(zdo => zdo == null);
        }

        private static int CleanupInvalidInstances(ZNetScene scene)
        {
            if (scene == null || ZNetSceneInstancesField == null)
            {
                return 0;
            }

            Dictionary<ZDO, ZNetView> instances = null;
            try
            {
                instances = ZNetSceneInstancesField.GetValue(scene) as Dictionary<ZDO, ZNetView>;
            }
            catch
            {
            }

            if (instances == null || instances.Count == 0)
            {
                return 0;
            }

            List<ZDO> invalidKeys = null;
            foreach (KeyValuePair<ZDO, ZNetView> pair in instances)
            {
                if (!IsInvalidInstance(pair.Key, pair.Value))
                {
                    continue;
                }

                if (invalidKeys == null)
                {
                    invalidKeys = new List<ZDO>();
                }

                invalidKeys.Add(pair.Key);
            }

            if (invalidKeys == null)
            {
                return 0;
            }

            foreach (ZDO key in invalidKeys)
            {
                DestroyOwnedZdo(key);
                instances.Remove(key);
            }

            return invalidKeys.Count;
        }

        private static void DestroyOwnedZdo(ZDO zdo)
        {
            if (zdo == null || ZDOMan.instance == null)
            {
                return;
            }

            try
            {
                if (zdo.IsOwner())
                {
                    ZDOMan.instance.DestroyZDO(zdo);
                }
            }
            catch
            {
            }
        }

        private static bool IsInvalidInstance(ZDO key, ZNetView view)
        {
            if (key == null || view == null)
            {
                return true;
            }

            try
            {
                return view.GetZDO() == null;
            }
            catch
            {
                return true;
            }
        }
    }

    internal sealed class ZNetSceneSafeTimedDestroy : MonoBehaviour
    {
        private float _remaining;

        internal void ResetTimer(float delay)
        {
            _remaining = Mathf.Max(0.01f, delay);
            enabled = true;
        }

        private void Update()
        {
            _remaining -= Time.deltaTime;
            if (_remaining > 0f)
            {
                return;
            }

            enabled = false;
            ZNetSceneSafety.Destroy(gameObject);
        }
    }

    internal static class ClassPetScalingController
    {
        private sealed class PetScaling
        {
            internal readonly float DamageMultiplier;
            internal readonly float DamageTakenReduction;

            internal PetScaling(float damageMultiplier, float damageTakenReduction)
            {
                DamageMultiplier = Mathf.Max(0.01f, damageMultiplier);
                DamageTakenReduction = Mathf.Clamp(damageTakenReduction, 0f, 0.95f);
            }
        }

        private static readonly FieldInfo CharacterBaseHpField = AccessTools.Field(typeof(Character), "m_baseHP");
        private static readonly FieldInfo CharacterHealthField = AccessTools.Field(typeof(Character), "m_health");
        private static readonly MethodInfo CharacterSetMaxHealthMethod = AccessTools.Method(typeof(Character), "SetMaxHealth", new[] { typeof(float) });
        private static readonly MethodInfo CharacterSetHealthMethod = AccessTools.Method(typeof(Character), "SetHealth", new[] { typeof(float) });
        private static readonly Dictionary<Character, PetScaling> ScalingByCharacter = new Dictionary<Character, PetScaling>();

        internal static void Register(GameObject pet, float maxHealth, float damageMultiplier, float damageTakenReduction)
        {
            Character character = pet != null ? pet.GetComponent<Character>() ?? pet.GetComponentInChildren<Character>() : null;
            if (character == null)
            {
                return;
            }

            SetCharacterHealth(character, Mathf.Max(1f, maxHealth));
            ScalingByCharacter[character] = new PetScaling(damageMultiplier, damageTakenReduction);
        }

        internal static void Unregister(GameObject pet)
        {
            Character character = pet != null ? pet.GetComponent<Character>() ?? pet.GetComponentInChildren<Character>() : null;
            if (character != null)
            {
                ScalingByCharacter.Remove(character);
            }
        }

        internal static bool TryGetDamageMultiplier(Character character, out float multiplier)
        {
            multiplier = 1f;
            PetScaling scaling;
            if (!TryGetScaling(character, out scaling))
            {
                return false;
            }

            multiplier = scaling.DamageMultiplier;
            return true;
        }

        internal static void ModifyOutgoingDamage(HitData hit)
        {
            if (hit == null)
            {
                return;
            }

            float multiplier;
            if (TryGetDamageMultiplier(GetAttacker(hit), out multiplier))
            {
                ScaleAllDamage(ref hit.m_damage, multiplier);
            }
        }

        internal static void ModifyIncomingDamage(Character target, HitData hit)
        {
            if (target == null || hit == null)
            {
                return;
            }

            PetScaling scaling;
            if (!TryGetScaling(target, out scaling) || scaling.DamageTakenReduction <= 0f)
            {
                return;
            }

            ScaleAllDamage(ref hit.m_damage, Mathf.Clamp01(1f - scaling.DamageTakenReduction));
        }

        private static bool TryGetScaling(Character character, out PetScaling scaling)
        {
            scaling = null;
            if (character == null)
            {
                return false;
            }

            if (!ScalingByCharacter.TryGetValue(character, out scaling))
            {
                return false;
            }

            if (character.IsDead())
            {
                ScalingByCharacter.Remove(character);
                scaling = null;
                return false;
            }

            return true;
        }

        private static Character GetAttacker(HitData hit)
        {
            try
            {
                return hit != null ? hit.GetAttacker() : null;
            }
            catch
            {
                return null;
            }
        }

        private static void SetCharacterHealth(Character character, float maxHealth)
        {
            TrySetFloatField(character, CharacterBaseHpField, maxHealth);
            TryInvoke(CharacterSetMaxHealthMethod, character, new object[] { maxHealth });
            TryInvoke(CharacterSetHealthMethod, character, new object[] { maxHealth });
            TrySetFloatField(character, CharacterHealthField, maxHealth);
        }

        private static void ScaleAllDamage(ref HitData.DamageTypes damages, float multiplier)
        {
            damages.m_blunt *= multiplier;
            damages.m_slash *= multiplier;
            damages.m_pierce *= multiplier;
            damages.m_chop *= multiplier;
            damages.m_pickaxe *= multiplier;
            damages.m_fire *= multiplier;
            damages.m_frost *= multiplier;
            damages.m_lightning *= multiplier;
            damages.m_poison *= multiplier;
            damages.m_spirit *= multiplier;
        }

        private static bool TrySetFloatField(object instance, FieldInfo field, float value)
        {
            if (instance == null || field == null)
            {
                return false;
            }

            try
            {
                field.SetValue(instance, value);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryInvoke(MethodInfo method, object target, object[] args)
        {
            if (method == null || target == null)
            {
                return false;
            }

            try
            {
                method.Invoke(target, args);
                return true;
            }
            catch
            {
                return false;
            }
        }
    }

    internal static class StatusEffectIconHelper
    {
        private static Sprite _fallbackIcon;

        internal static void Apply(StatusEffect effect, Player player, string baseSetName)
        {
            if (effect == null)
            {
                return;
            }

            Sprite panelIcon = AbilityPanelIconCatalog.GetStatusEffectIcon(effect, baseSetName);
            if (panelIcon != null)
            {
                effect.m_icon = panelIcon;
                return;
            }

            Sprite icon = GetIcon(player, baseSetName);
            if (icon != null)
            {
                effect.m_icon = icon;
            }
        }

        internal static void Apply(StatusEffect effect, string baseSetName, Sprite fallbackIcon)
        {
            if (effect == null)
            {
                return;
            }

            Sprite panelIcon = AbilityPanelIconCatalog.GetStatusEffectIcon(effect, baseSetName);
            if (panelIcon != null)
            {
                effect.m_icon = panelIcon;
                return;
            }

            if (fallbackIcon != null)
            {
                effect.m_icon = fallbackIcon;
            }
        }

        internal static Sprite GetIcon(Player player, string baseSetName)
        {
            Sprite classIcon = ClassSkillManager.GetIcon(baseSetName);
            if (classIcon != null)
            {
                return classIcon;
            }

            ItemDrop.ItemData current = player != null ? player.GetCurrentWeapon() : null;
            Sprite currentIcon = GetItemIcon(current);
            if (currentIcon != null)
            {
                return currentIcon;
            }

            Inventory inventory = player != null ? player.GetInventory() : null;
            if (inventory != null)
            {
                foreach (ItemDrop.ItemData item in inventory.GetEquippedItems())
                {
                    Sprite icon = GetItemIcon(item);
                    if (icon != null)
                    {
                        return icon;
                    }
                }
            }

            return GetFallbackIcon();
        }

        private static Sprite GetItemIcon(ItemDrop.ItemData item)
        {
            if (item == null || item.m_shared == null || item.m_shared.m_icons == null || item.m_shared.m_icons.Length == 0)
            {
                return null;
            }

            return item.m_shared.m_icons[0];
        }

        private static Sprite GetFallbackIcon()
        {
            if (_fallbackIcon != null)
            {
                return _fallbackIcon;
            }

            Texture2D texture = new Texture2D(16, 16, TextureFormat.RGBA32, false);
            Color32[] pixels = new Color32[16 * 16];
            for (int i = 0; i < pixels.Length; i++)
            {
                pixels[i] = new Color32(190, 220, 255, 235);
            }

            texture.SetPixels32(pixels);
            texture.Apply();
            texture.name = "FranStatusEffectFallbackIcon";
            _fallbackIcon = Sprite.Create(texture, new Rect(0f, 0f, 16f, 16f), new Vector2(0.5f, 0.5f));
            return _fallbackIcon;
        }
    }

    internal static class NorseDashBridge
    {
        private const string NorseAssemblyName = "NorseDemigods";

        private static bool _initialized;
        private static bool _available;
        private static bool _loggedFailure;
        private static Type _abilityDashType;
        private static Type _abilityPropertyType;
        private static Type _abilityThemeType;
        private static Type _abilityParametersType;
        private static Type _abilityTypeType;
        private static Type _demigodType;
        private static ConstructorInfo _abilityConstructor;
        private static FieldInfo _propertyThemeField;
        private static FieldInfo _parametersAbilityTypeField;
        private static FieldInfo _parametersSkillTypesField;
        private static FieldInfo _parametersPropertiesField;
        private static FieldInfo _teleportPositionField;
        private static FieldInfo _teleportingToLookDirectionField;
        private static FieldInfo _layerMaskEnvNoTerrainField;
        private static MethodInfo _getTeleportRangeMethod;
        private static MethodInfo _damageEnemiesOnTheWayMethod;
        private static MethodInfo _dashMethod;
        private static MethodInfo _getSpawnPointMethod;
        private static object _dashTheme;
        private static object _slotOneAbilityType;

        internal static bool TryDash(Player player, out string reason, bool damageEnemiesOnTheWay = true)
        {
            reason = null;
            if (player == null)
            {
                reason = "Norse dash unavailable.";
                return false;
            }

            if (!EnsureInitialized(out reason))
            {
                return false;
            }

            try
            {
                object ability = CreateAbility(player);
                Vector3 target;
                bool teleportingToLookDirection;
                if (!TryFindDashTarget(player, ability, out target, out teleportingToLookDirection))
                {
                    reason = "No Norse dash target.";
                    return false;
                }

                _teleportPositionField.SetValue(ability, target);
                _teleportingToLookDirectionField.SetValue(ability, teleportingToLookDirection);
                if (damageEnemiesOnTheWay)
                {
                    _damageEnemiesOnTheWayMethod.Invoke(ability, null);
                }

                _dashMethod.Invoke(ability, null);
                return true;
            }
            catch (Exception ex)
            {
                reason = "Norse dash failed.";
                LogFailure(reason, ex);
                return false;
            }
        }

        private static bool EnsureInitialized(out string reason)
        {
            reason = null;
            if (_initialized)
            {
                if (!_available)
                {
                    reason = "NorseDemigods dash unavailable.";
                }

                return _available;
            }

            _initialized = true;
            try
            {
                _abilityDashType = FindType("NorseDemigods.Abilities.AbilityDash");
                _abilityPropertyType = FindType("NorseDemigods.Abilities.AbilityDash+AbilityProperty");
                _abilityThemeType = FindType("NorseDemigods.Abilities.AbilityDash+AbilityTheme");
                _abilityParametersType = FindType("NorseDemigods.DemigodAbility+AbilityParametersStruct");
                _abilityTypeType = FindType("NorseDemigods.DemigodAbility+AbilityType");
                _demigodType = FindType("NorseDemigods.Demigod");
                Type helperType = FindType("NorseDemigods.Helper");
                Type cacheType = FindType("NorseDemigods.Cache");

                if (_abilityDashType == null || _abilityPropertyType == null || _abilityThemeType == null ||
                    _abilityParametersType == null || _abilityTypeType == null || _demigodType == null ||
                    helperType == null || cacheType == null)
                {
                    reason = "NorseDemigods dash unavailable.";
                    return false;
                }

                _abilityConstructor = _abilityDashType.GetConstructor(new[] { typeof(Player), _demigodType, _abilityParametersType });
                _propertyThemeField = _abilityPropertyType.GetField("AbilityTheme", BindingFlags.Public | BindingFlags.Instance);
                _parametersAbilityTypeField = _abilityParametersType.GetField("AbilityType", BindingFlags.Public | BindingFlags.Instance);
                _parametersSkillTypesField = _abilityParametersType.GetField("SkillTypes", BindingFlags.Public | BindingFlags.Instance);
                _parametersPropertiesField = _abilityParametersType.GetField("Properties", BindingFlags.Public | BindingFlags.Instance);
                _teleportPositionField = _abilityDashType.GetField("teleportPosition", BindingFlags.NonPublic | BindingFlags.Instance);
                _teleportingToLookDirectionField = _abilityDashType.GetField("teleportingToLookDirection", BindingFlags.NonPublic | BindingFlags.Instance);
                _getTeleportRangeMethod = _abilityDashType.GetMethod("GetTeleportRange", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
                _damageEnemiesOnTheWayMethod = _abilityDashType.GetMethod("DamageEnemiesOnTheWay", BindingFlags.NonPublic | BindingFlags.Instance);
                _dashMethod = _abilityDashType.GetMethod("Dash", BindingFlags.NonPublic | BindingFlags.Instance);
                _getSpawnPointMethod = helperType.GetMethod(
                    "GetSpawnPoint",
                    BindingFlags.Public | BindingFlags.Static,
                    null,
                    new[] { typeof(Vector3), typeof(Vector3), typeof(float), typeof(float), typeof(float), typeof(Vector3).MakeByRefType(), typeof(bool) },
                    null);
                _layerMaskEnvNoTerrainField = cacheType.GetField("LayerMaskEnvNoTerrain", BindingFlags.Public | BindingFlags.Static);
                _dashTheme = ResolveThorDashTheme(_abilityThemeType);
                _slotOneAbilityType = Enum.Parse(_abilityTypeType, "SLOT_1");

                _available = _abilityConstructor != null && _propertyThemeField != null && _dashTheme != null &&
                             _parametersAbilityTypeField != null && _parametersSkillTypesField != null &&
                             _parametersPropertiesField != null && _teleportPositionField != null &&
                             _teleportingToLookDirectionField != null && _getTeleportRangeMethod != null &&
                             _damageEnemiesOnTheWayMethod != null && _dashMethod != null &&
                             _getSpawnPointMethod != null && _layerMaskEnvNoTerrainField != null;

                if (!_available)
                {
                    reason = "NorseDemigods dash unavailable.";
                }

                return _available;
            }
            catch (Exception ex)
            {
                reason = "NorseDemigods dash unavailable.";
                LogFailure(reason, ex);
                return false;
            }
        }

        private static Type FindType(string fullName)
        {
            Type type = Type.GetType(fullName + ", " + NorseAssemblyName);
            if (type != null)
            {
                return type;
            }

            foreach (Assembly assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                if (!string.Equals(assembly.GetName().Name, NorseAssemblyName, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                type = assembly.GetType(fullName);
                if (type != null)
                {
                    return type;
                }
            }

            return null;
        }

        private static object CreateAbility(Player player)
        {
            object properties = Activator.CreateInstance(_abilityPropertyType);
            _propertyThemeField.SetValue(properties, _dashTheme);

            object parameters = Activator.CreateInstance(_abilityParametersType);
            _parametersAbilityTypeField.SetValue(parameters, _slotOneAbilityType);
            _parametersSkillTypesField.SetValue(parameters, Array.CreateInstance(typeof(Skills.SkillType), 0));
            _parametersPropertiesField.SetValue(parameters, properties);

            return _abilityConstructor.Invoke(new[] { player, null, parameters });
        }

        private static object ResolveThorDashTheme(Type enumType)
        {
            if (enumType == null || !enumType.IsEnum)
            {
                return null;
            }

            string[] names = Enum.GetNames(enumType);
            object exact = TryResolveEnumName(enumType, names, "THOR", "LIGHTNING", "THUNDER", "STORM", "ELECTRIC", "SHOCK");
            if (exact != null)
            {
                return exact;
            }

            object partial = TryResolveEnumNameContains(enumType, names, "THOR", "LIGHTNING", "THUNDER", "STORM", "ELECTRIC", "SHOCK");
            if (partial != null)
            {
                return partial;
            }

            object fallback = TryResolveEnumName(enumType, names, "NATURE");
            if (fallback != null)
            {
                return fallback;
            }

            Array values = Enum.GetValues(enumType);
            return values.Length > 0 ? values.GetValue(0) : null;
        }

        private static object TryResolveEnumName(Type enumType, string[] names, params string[] preferred)
        {
            foreach (string candidate in preferred)
            {
                foreach (string name in names)
                {
                    if (string.Equals(name, candidate, StringComparison.OrdinalIgnoreCase))
                    {
                        return Enum.Parse(enumType, name);
                    }
                }
            }

            return null;
        }

        private static object TryResolveEnumNameContains(Type enumType, string[] names, params string[] preferred)
        {
            foreach (string candidate in preferred)
            {
                foreach (string name in names)
                {
                    if (name.IndexOf(candidate, StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        return Enum.Parse(enumType, name);
                    }
                }
            }

            return null;
        }

        private static bool TryFindDashTarget(Player player, object ability, out Vector3 target, out bool teleportingToLookDirection)
        {
            target = Vector3.zero;
            teleportingToLookDirection = false;

            float range = Convert.ToSingle(_getTeleportRangeMethod.Invoke(ability, null));
            if (range <= 0f || float.IsNaN(range) || float.IsInfinity(range))
            {
                return false;
            }

            Vector3 direction = player.GetLookYaw() * Vector3.forward;
            Vector3 heightOffset = new Vector3(0f, player.GetHeight(), 0f);
            Vector3 playerPosition = player.transform.position;
            List<Vector3> candidates = new List<Vector3>();
            Vector3 spawnPoint;

            if (TryGetNorseSpawnPoint(playerPosition + new Vector3(0f, 3.5f, 0f), direction, range, player.GetRadius(), 10f, out spawnPoint) &&
                !Physics.Linecast(playerPosition + heightOffset, spawnPoint + heightOffset, GetEnvNoTerrainLayerMask()))
            {
                candidates.Add(spawnPoint);
            }

            if (TryGetNorseSpawnPoint(playerPosition + heightOffset, direction, range, player.GetRadius(), 10f, out spawnPoint) &&
                !Physics.Linecast(playerPosition + heightOffset, spawnPoint + heightOffset, GetEnvNoTerrainLayerMask()))
            {
                candidates.Add(spawnPoint);
            }

            if (candidates.Count == 0)
            {
                return false;
            }

            target = candidates
                .OrderByDescending(candidate => Vector3.Distance(playerPosition, candidate))
                .First();
            return true;
        }

        private static bool TryGetNorseSpawnPoint(Vector3 referencePosition, Vector3 direction, float range, float radius, float maxHeightDifference, out Vector3 spawnPoint)
        {
            object[] args =
            {
                referencePosition,
                direction,
                range,
                radius,
                maxHeightDifference,
                Vector3.zero,
                false
            };

            bool result = (bool)_getSpawnPointMethod.Invoke(null, args);
            spawnPoint = (Vector3)args[5];
            return result;
        }

        private static int GetEnvNoTerrainLayerMask()
        {
            object layerMask = _layerMaskEnvNoTerrainField.GetValue(null);
            if (layerMask is LayerMask)
            {
                LayerMask unityLayerMask = (LayerMask)layerMask;
                return unityLayerMask.value;
            }

            if (layerMask is int)
            {
                return (int)layerMask;
            }

            return Physics.DefaultRaycastLayers;
        }

        private static void LogFailure(string reason, Exception ex)
        {
            if (_loggedFailure)
            {
                return;
            }

            _loggedFailure = true;
            EpicLootRaritySetsPlugin.Log.LogWarning(reason + " " + ex.GetBaseException().Message);
        }
    }

    internal static class NorseDemigodsSuppression
    {
        private const string NorseAssemblyName = "NorseDemigods";
        private static readonly string[] ManagedSets =
        {
            "Frostbrand",
            "Hraesvelgr",
            "Hellsyng",
            "Moonvein",
            "Nott",
            "Helveig",
            "Heimdall",
            "Seidr"
        };

        private static bool _removeMetersFailed;
        private static MethodInfo _removeMetersMethod;

        internal static bool ShouldSuppressLocal()
        {
            return Player.m_localPlayer != null &&
                   ManagedSets.Any(SetActivationBuffController.HasActiveSet);
        }

        internal static void RemoveMeters()
        {
            if (_removeMetersFailed)
            {
                return;
            }

            try
            {
                if (_removeMetersMethod == null)
                {
                    Type customUiType = FindNorseType("NorseDemigods.CustomUI");
                    _removeMetersMethod = customUiType != null
                        ? customUiType.GetMethod("RemoveMeters", BindingFlags.Public | BindingFlags.Static)
                        : null;
                }

                if (_removeMetersMethod != null)
                {
                    _removeMetersMethod.Invoke(null, null);
                }
            }
            catch (Exception ex)
            {
                _removeMetersFailed = true;
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not hide NorseDemigods meters while Frostbrand is active. " + ex.GetBaseException().Message);
            }
        }

        internal static Type FindNorseType(string fullName)
        {
            Type type = Type.GetType(fullName + ", " + NorseAssemblyName);
            if (type != null)
            {
                return type;
            }

            foreach (Assembly assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                if (!string.Equals(assembly.GetName().Name, NorseAssemblyName, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                type = assembly.GetType(fullName);
                if (type != null)
                {
                    return type;
                }
            }

            return null;
        }
    }

    internal static class NorseEirAbilityBridge
    {
        private static bool _initialized;
        private static bool _available;
        private static bool _loggedFailure;
        private static int _bridgeExecutionDepth;
        private static int _bridgeUpdateDepth;
        private static Type _abilityHolyStrikeType;
        private static Type _abilityHolySunType;
        private static Type _abilityParametersType;
        private static Type _abilityTypeType;
        private static Type _demigodType;
        private static Type _hitInfoType;
        private static ConstructorInfo _holyStrikeConstructor;
        private static ConstructorInfo _holySunConstructor;
        private static FieldInfo _parametersAbilityTypeField;
        private static FieldInfo _parametersSkillTypesField;
        private static FieldInfo _parametersPropertiesField;
        private static FieldInfo _holyStrikeTargetCharacterField;
        private static FieldInfo _holyStrikeRangeField;
        private static FieldInfo _holySunLifeTimerField;
        private static FieldInfo _energyRequiredField;
        private static FieldInfo _energyCostField;
        private static FieldInfo _eitrCostField;
        private static FieldInfo _cooldownField;
        private static MethodInfo _holyStrikeExecuteMethod;
        private static MethodInfo _holySunExecuteMethod;
        private static MethodInfo _holySunUpdateMethod;
        private static MethodInfo _findCrosshairTargetMethod;
        private static MethodInfo _areCharactersEnemiesMethod;
        private static PropertyInfo _hitInfoColliderProperty;
        private static object _slotTwoAbilityType;
        private static object _slotThreeAbilityType;
        private static readonly List<object> ActiveHolySuns = new List<object>();

        internal static bool IsBridgeExecuting
        {
            get { return _bridgeExecutionDepth > 0; }
        }

        internal static bool IsBridgeUpdating
        {
            get { return _bridgeUpdateDepth > 0; }
        }

        internal static void Update(float dt)
        {
            if (ActiveHolySuns.Count == 0)
            {
                return;
            }

            string failureReason;
            if (!EnsureInitialized(out failureReason))
            {
                ActiveHolySuns.Clear();
                return;
            }

            for (int i = ActiveHolySuns.Count - 1; i >= 0; i--)
            {
                object ability = ActiveHolySuns[i];
                try
                {
                    _bridgeUpdateDepth++;
                    try
                    {
                        _holySunUpdateMethod.Invoke(ability, new object[] { dt });
                    }
                    finally
                    {
                        _bridgeUpdateDepth--;
                    }

                    if (GetHolySunLifeTimer(ability) < 0f)
                    {
                        ActiveHolySuns.RemoveAt(i);
                    }
                }
                catch (Exception ex)
                {
                    ActiveHolySuns.RemoveAt(i);
                    LogFailure("Norse Holy Sun update failed.", ex);
                }
            }
        }

        internal static bool TryHolyStrike(Player player, out string reason)
        {
            reason = null;
            if (player == null)
            {
                reason = "Norse Holy Strike unavailable.";
                return false;
            }

            if (!EnsureInitialized(out reason))
            {
                return false;
            }

            Character target;
            if (!TryFindHolyStrikeTarget(player, out target))
            {
                reason = "No holy strike target.";
                return false;
            }

            try
            {
                object ability = CreateAbility(_holyStrikeConstructor, player, _slotTwoAbilityType);
                NeutralizeNorseCosts(ability);
                _holyStrikeTargetCharacterField.SetValue(ability, target);
                InvokeBridgeExecute(_holyStrikeExecuteMethod, ability);
                return true;
            }
            catch (Exception ex)
            {
                reason = "Norse Holy Strike failed.";
                LogFailure(reason, ex);
                return false;
            }
        }

        internal static bool TryHolySun(Player player, out string reason)
        {
            reason = null;
            if (player == null)
            {
                reason = "Norse Holy Sun unavailable.";
                return false;
            }

            if (!EnsureInitialized(out reason))
            {
                return false;
            }

            try
            {
                object ability = CreateAbility(_holySunConstructor, player, _slotThreeAbilityType);
                NeutralizeNorseCosts(ability);
                InvokeBridgeExecute(_holySunExecuteMethod, ability);
                if (GetHolySunLifeTimer(ability) < 0f)
                {
                    reason = "No holy sun target.";
                    return false;
                }

                ActiveHolySuns.Add(ability);
                return true;
            }
            catch (Exception ex)
            {
                reason = "Norse Holy Sun failed.";
                LogFailure(reason, ex);
                return false;
            }
        }

        private static bool EnsureInitialized(out string reason)
        {
            reason = null;
            if (_initialized)
            {
                if (!_available)
                {
                    reason = "Norse Eir abilities unavailable.";
                }

                return _available;
            }

            _initialized = true;
            try
            {
                _abilityHolyStrikeType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.Abilities.AbilityHolyStrike");
                _abilityHolySunType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.Abilities.AbilityHolySun");
                _abilityParametersType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.DemigodAbility+AbilityParametersStruct");
                _abilityTypeType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.DemigodAbility+AbilityType");
                _demigodType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.Demigod");
                _hitInfoType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.Helper+HitInfo");
                Type helperType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.Helper");
                Type demigodAbilityType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.DemigodAbility");

                if (_abilityHolyStrikeType == null || _abilityHolySunType == null ||
                    _abilityParametersType == null || _abilityTypeType == null ||
                    _demigodType == null || _hitInfoType == null ||
                    helperType == null || demigodAbilityType == null)
                {
                    reason = "Norse Eir abilities unavailable.";
                    return false;
                }

                Type[] constructorTypes = { typeof(Player), _demigodType, _abilityParametersType };
                _holyStrikeConstructor = _abilityHolyStrikeType.GetConstructor(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance, null, constructorTypes, null);
                _holySunConstructor = _abilityHolySunType.GetConstructor(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance, null, constructorTypes, null);
                _parametersAbilityTypeField = _abilityParametersType.GetField("AbilityType", BindingFlags.Public | BindingFlags.Instance);
                _parametersSkillTypesField = _abilityParametersType.GetField("SkillTypes", BindingFlags.Public | BindingFlags.Instance);
                _parametersPropertiesField = _abilityParametersType.GetField("Properties", BindingFlags.Public | BindingFlags.Instance);
                _holyStrikeTargetCharacterField = _abilityHolyStrikeType.GetField("targetCharacter", BindingFlags.NonPublic | BindingFlags.Instance);
                _holyStrikeRangeField = _abilityHolyStrikeType.GetField("AbilityRange", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static);
                _holySunLifeTimerField = _abilityHolySunType.GetField("lifeTimer", BindingFlags.NonPublic | BindingFlags.Instance);
                _energyRequiredField = demigodAbilityType.GetField("<EnergyRequired>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _energyCostField = demigodAbilityType.GetField("<EnergyCost>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _eitrCostField = demigodAbilityType.GetField("<EitrCost>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _cooldownField = demigodAbilityType.GetField("<Cooldown>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _holyStrikeExecuteMethod = _abilityHolyStrikeType.GetMethod("Execute", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
                _holySunExecuteMethod = _abilityHolySunType.GetMethod("Execute", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
                _holySunUpdateMethod = _abilityHolySunType.GetMethod("Update", BindingFlags.Public | BindingFlags.Instance, null, new[] { typeof(float) }, null);
                _findCrosshairTargetMethod = helperType.GetMethod(
                    "FindCrosshairTarget",
                    BindingFlags.Public | BindingFlags.Static,
                    null,
                    new[] { typeof(Player), typeof(float), _hitInfoType.MakeByRefType(), typeof(float), typeof(float) },
                    null);
                _areCharactersEnemiesMethod = helperType.GetMethod(
                    "AreCharactersEnemies",
                    BindingFlags.Public | BindingFlags.Static,
                    null,
                    new[] { typeof(Character), typeof(Character) },
                    null);
                _hitInfoColliderProperty = _hitInfoType.GetProperty("Collider", BindingFlags.Public | BindingFlags.Instance);
                _slotTwoAbilityType = Enum.Parse(_abilityTypeType, "SLOT_2");
                _slotThreeAbilityType = Enum.Parse(_abilityTypeType, "SLOT_3");

                _available = _holyStrikeConstructor != null && _holySunConstructor != null &&
                             _parametersAbilityTypeField != null && _parametersSkillTypesField != null &&
                             _parametersPropertiesField != null && _holyStrikeTargetCharacterField != null &&
                             _holyStrikeRangeField != null && _holySunLifeTimerField != null &&
                             _energyRequiredField != null && _energyCostField != null &&
                             _eitrCostField != null && _cooldownField != null &&
                             _holyStrikeExecuteMethod != null && _holySunExecuteMethod != null &&
                             _holySunUpdateMethod != null && _findCrosshairTargetMethod != null &&
                             _areCharactersEnemiesMethod != null && _hitInfoColliderProperty != null;

                if (!_available)
                {
                    reason = "Norse Eir abilities unavailable.";
                }

                return _available;
            }
            catch (Exception ex)
            {
                reason = "Norse Eir abilities unavailable.";
                LogFailure(reason, ex);
                return false;
            }
        }

        private static object CreateAbility(ConstructorInfo constructor, Player player, object abilityType)
        {
            object parameters = Activator.CreateInstance(_abilityParametersType);
            _parametersAbilityTypeField.SetValue(parameters, abilityType);
            _parametersSkillTypesField.SetValue(parameters, Array.CreateInstance(typeof(Skills.SkillType), 0));
            _parametersPropertiesField.SetValue(parameters, null);

            return constructor.Invoke(new[] { player, null, parameters });
        }

        private static void NeutralizeNorseCosts(object ability)
        {
            _energyRequiredField.SetValue(ability, 0);
            _energyCostField.SetValue(ability, 0);
            _eitrCostField.SetValue(ability, 0);
            _cooldownField.SetValue(ability, 0f);
        }

        private static void InvokeBridgeExecute(MethodInfo executeMethod, object ability)
        {
            _bridgeExecutionDepth++;
            try
            {
                executeMethod.Invoke(ability, null);
            }
            finally
            {
                _bridgeExecutionDepth--;
            }
        }

        private static bool TryFindHolyStrikeTarget(Player player, out Character target)
        {
            target = null;
            object hitInfo = Activator.CreateInstance(_hitInfoType);
            object[] args =
            {
                player,
                GetHolyStrikeRange(),
                hitInfo,
                0.2f,
                0.5f
            };

            if (!(bool)_findCrosshairTargetMethod.Invoke(null, args))
            {
                return false;
            }

            Collider collider = _hitInfoColliderProperty.GetValue(args[2], null) as Collider;
            if (collider == null)
            {
                return false;
            }

            GameObject hitObject = Projectile.FindHitObject(collider);
            if (hitObject == null)
            {
                return false;
            }

            target = hitObject.GetComponent<Character>();
            return target != null && (bool)_areCharactersEnemiesMethod.Invoke(null, new object[] { player, target });
        }

        private static float GetHolyStrikeRange()
        {
            object configEntry = _holyStrikeRangeField.GetValue(null);
            PropertyInfo valueProperty = configEntry != null ? configEntry.GetType().GetProperty("Value") : null;
            if (valueProperty == null)
            {
                return EpicLootRaritySetsPlugin.FrostbrandHolyStrikeRange.Value;
            }

            return Convert.ToSingle(valueProperty.GetValue(configEntry, null));
        }

        private static float GetHolySunLifeTimer(object ability)
        {
            return Convert.ToSingle(_holySunLifeTimerField.GetValue(ability));
        }

        private static void LogFailure(string reason, Exception ex)
        {
            if (_loggedFailure)
            {
                return;
            }

            _loggedFailure = true;
            EpicLootRaritySetsPlugin.Log.LogWarning(reason + " " + ex.GetBaseException().Message);
        }
    }

    internal static class NorseWaterSphereBridge
    {
        private const string WaterSphereRootBuffName = "FranWaterSphereRoot";
        private const string WaterSphereRootBuffCategory = "FranWaterSphereRoot";
        private const float WaterSphereRootRefreshSeconds = 0.55f;
        private const float WaterSpherePullTickSeconds = 0.1f;
        private const float WaterSphereHoldDistance = 1.15f;

        private static readonly List<ActiveWaterSphere> ActiveWaterSpheres = new List<ActiveWaterSphere>();
        private static readonly FieldInfo SpeedModifierField = AccessTools.Field(typeof(SE_Stats), "m_speedModifier");
        private static readonly FieldInfo StatusEffectTimeField = AccessTools.Field(typeof(StatusEffect), "m_time");
        private static bool _initialized;
        private static bool _available;
        private static bool _loggedFailure;
        private static int _bridgeExecutionDepth;
        private static int _bridgeUpdateDepth;
        private static Type _abilityWaterSphereType;
        private static Type _abilityParametersType;
        private static Type _abilityTypeType;
        private static Type _demigodType;
        private static ConstructorInfo _constructorWithPlayer;
        private static ConstructorInfo _constructorSimple;
        private static FieldInfo _parametersAbilityTypeField;
        private static FieldInfo _parametersSkillTypesField;
        private static FieldInfo _parametersPropertiesField;
        private static FieldInfo _energyRequiredField;
        private static FieldInfo _energyCostField;
        private static FieldInfo _eitrCostField;
        private static FieldInfo _cooldownField;
        private static FieldInfo _waterSphereListField;
        private static FieldInfo _sphereFxField;
        private static FieldInfo _sphereTargetCharacterField;
        private static FieldInfo _sphereTargetPointField;
        private static MethodInfo _setupConfigsMethod;
        private static MethodInfo _executeMethod;
        private static MethodInfo _updateMethod;
        private static MethodInfo _stopMethod;
        private static MethodInfo _baseAIIsEnemyMethod;
        private static object _slotTwoAbilityType;
        private static ConfigFile _norseConfig;
        private static StatusEffect _waterSphereRootBuff;

        internal static bool IsBridgeExecuting
        {
            get { return _bridgeExecutionDepth > 0; }
        }

        internal static bool IsBridgeUpdating
        {
            get { return _bridgeUpdateDepth > 0; }
        }

        internal static void Update(float dt)
        {
            if (ActiveWaterSpheres.Count == 0)
            {
                return;
            }

            string reason;
            if (!EnsureInitialized(out reason))
            {
                ActiveWaterSpheres.Clear();
                return;
            }

            for (int i = ActiveWaterSpheres.Count - 1; i >= 0; i--)
            {
                ActiveWaterSphere active = ActiveWaterSpheres[i];
                if (active == null || active.Owner == null || active.Ability == null)
                {
                    ActiveWaterSpheres.RemoveAt(i);
                    continue;
                }

                active.Elapsed += dt;
                try
                {
                    _bridgeUpdateDepth++;
                    try
                    {
                        _updateMethod.Invoke(active.Ability, new object[] { dt });
                    }
                    finally
                    {
                        _bridgeUpdateDepth--;
                    }

                    List<Vector3> livePositions = GetSpherePositions(active.Ability).ToList();
                    if (livePositions.Count > 0)
                    {
                        active.SetPositions(livePositions);
                        active.MissingPositionTime = 0f;
                    }
                    else
                    {
                        active.MissingPositionTime += dt;
                    }

                    active.PullTickAccumulator += dt;
                    if (active.PullTickAccumulator >= WaterSpherePullTickSeconds)
                    {
                        float pullDt = active.PullTickAccumulator;
                        active.PullTickAccumulator = 0f;
                        if (active.HasPositions && active.MissingPositionTime <= WaterSpherePullTickSeconds * 2f)
                        {
                            ApplyGravityPull(active.Owner, active.LastPositions, active.PullRadius, active.PullForce, active.IconSet, pullDt);
                        }
                    }

                    if (active.Elapsed >= Mathf.Max(1f, active.MaxDuration) ||
                        active.MissingPositionTime > 0.75f ||
                        (!active.HasPositions && active.Elapsed > 0.75f))
                    {
                        Stop(active.Ability);
                        ActiveWaterSpheres.RemoveAt(i);
                    }
                }
                catch (Exception ex)
                {
                    Stop(active.Ability);
                    ActiveWaterSpheres.RemoveAt(i);
                    LogFailure("Norse Water Sphere update failed.", ex);
                }
            }
        }

        internal static bool TryWaterSphere(Player player, Skills.SkillType skillType, string skillName, string iconSet, float maxDuration, float pullRadius, float pullForce, out string reason)
        {
            reason = null;
            if (player == null)
            {
                reason = "Norse Water Sphere unavailable.";
                return false;
            }

            if (!EnsureInitialized(out reason))
            {
                return false;
            }

            try
            {
                Character targetCharacter;
                Vector3 targetPoint = GetAimedTargetPoint(player, Mathf.Max(1f, GetConfiguredTargetMaxRange()), out targetCharacter);
                object ability = CreateAbility(player, skillType);
                SetupConfigs(ability);
                NeutralizeNorseCosts(ability);
                ActiveWaterSphere active = new ActiveWaterSphere(player, ability, skillType, skillName, iconSet, maxDuration, pullRadius, pullForce);
                ActiveWaterSpheres.Add(active);
                try
                {
                    InvokeBridgeExecute(ability);
                    ApplyAimedTarget(ability, player, targetPoint, targetCharacter);
                    active.SetPositions(GetSpherePositions(ability).ToList());
                }
                catch
                {
                    ActiveWaterSpheres.Remove(active);
                    throw;
                }

                return true;
            }
            catch (Exception ex)
            {
                reason = "Norse Water Sphere failed.";
                LogFailure(reason, ex);
                return false;
            }
        }

        private static bool EnsureInitialized(out string reason)
        {
            reason = null;
            if (_initialized)
            {
                if (!_available)
                {
                    reason = "Norse Water Sphere unavailable.";
                }

                return _available;
            }

            _initialized = true;
            try
            {
                _abilityWaterSphereType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.Abilities.AbilityWaterSphere");
                _abilityParametersType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.DemigodAbility+AbilityParametersStruct");
                _abilityTypeType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.DemigodAbility+AbilityType");
                _demigodType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.Demigod");
                Type demigodAbilityType = NorseDemigodsSuppression.FindNorseType("NorseDemigods.DemigodAbility");

                if (_abilityWaterSphereType == null || _abilityParametersType == null ||
                    _abilityTypeType == null || demigodAbilityType == null)
                {
                    reason = "Norse Water Sphere unavailable.";
                    return false;
                }

                Type[] constructorTypes = { typeof(Player), _demigodType, _abilityParametersType };
                _constructorWithPlayer = _demigodType != null
                    ? _abilityWaterSphereType.GetConstructor(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance, null, constructorTypes, null)
                    : null;
                _constructorSimple = _abilityWaterSphereType.GetConstructor(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance, null, new[] { _abilityParametersType }, null);
                _parametersAbilityTypeField = _abilityParametersType.GetField("AbilityType", BindingFlags.Public | BindingFlags.Instance);
                _parametersSkillTypesField = _abilityParametersType.GetField("SkillTypes", BindingFlags.Public | BindingFlags.Instance);
                _parametersPropertiesField = _abilityParametersType.GetField("Properties", BindingFlags.Public | BindingFlags.Instance);
                _energyRequiredField = demigodAbilityType.GetField("<EnergyRequired>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _energyCostField = demigodAbilityType.GetField("<EnergyCost>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _eitrCostField = demigodAbilityType.GetField("<EitrCost>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _cooldownField = demigodAbilityType.GetField("<Cooldown>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                _waterSphereListField = _abilityWaterSphereType.GetField("WaterSphereList", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                Type waterSphereType = _abilityWaterSphereType.GetNestedType("WaterSphere", BindingFlags.Public | BindingFlags.NonPublic);
                _sphereFxField = waterSphereType != null ? waterSphereType.GetField("fxWaterSphere", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance) : null;
                _sphereTargetCharacterField = waterSphereType != null ? waterSphereType.GetField("TargetCharacter", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance) : null;
                _sphereTargetPointField = waterSphereType != null ? waterSphereType.GetField("targetPoint", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance) : null;
                _setupConfigsMethod = _abilityWaterSphereType.GetMethod("SetupConfigs", BindingFlags.Public | BindingFlags.Instance, null, new[] { typeof(ConfigFile), typeof(string) }, null);
                _executeMethod = _abilityWaterSphereType.GetMethod("Execute", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
                _updateMethod = _abilityWaterSphereType.GetMethod("Update", BindingFlags.Public | BindingFlags.Instance, null, new[] { typeof(float) }, null);
                _stopMethod = demigodAbilityType.GetMethod("Stop", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance, null, new[] { typeof(bool) }, null);
                _baseAIIsEnemyMethod = AccessTools.Method(typeof(BaseAI), "IsEnemy", new[] { typeof(Character), typeof(Character) });
                _slotTwoAbilityType = Enum.Parse(_abilityTypeType, "SLOT_2");

                _available = (_constructorWithPlayer != null || _constructorSimple != null) &&
                             _parametersAbilityTypeField != null && _parametersSkillTypesField != null &&
                             _parametersPropertiesField != null && _waterSphereListField != null &&
                             _sphereFxField != null && _sphereTargetCharacterField != null &&
                             _sphereTargetPointField != null && _executeMethod != null && _updateMethod != null;

                if (!_available)
                {
                    reason = "Norse Water Sphere unavailable.";
                }

                return _available;
            }
            catch (Exception ex)
            {
                reason = "Norse Water Sphere unavailable.";
                LogFailure(reason, ex);
                return false;
            }
        }

        private static object CreateAbility(Player player, Skills.SkillType skillType)
        {
            object parameters = Activator.CreateInstance(_abilityParametersType);
            Array skillTypes = Array.CreateInstance(typeof(Skills.SkillType), 1);
            skillTypes.SetValue(skillType, 0);
            _parametersAbilityTypeField.SetValue(parameters, _slotTwoAbilityType);
            _parametersSkillTypesField.SetValue(parameters, skillTypes);
            _parametersPropertiesField.SetValue(parameters, null);

            if (_constructorWithPlayer != null)
            {
                object demigod = _demigodType != null ? player.GetComponent(_demigodType) : null;
                return _constructorWithPlayer.Invoke(new[] { player, demigod, parameters });
            }

            return _constructorSimple.Invoke(new[] { parameters });
        }

        private static void SetupConfigs(object ability)
        {
            if (_setupConfigsMethod == null || ability == null)
            {
                return;
            }

            ConfigFile config = GetNorseConfig();
            if (config != null)
            {
                _setupConfigsMethod.Invoke(ability, new object[] { config, "Ability Water Sphere" });
            }
        }

        private static ConfigFile GetNorseConfig()
        {
            if (_norseConfig != null)
            {
                return _norseConfig;
            }

            try
            {
                string configPath = Path.Combine(Paths.ConfigPath, "NorseDemigods.cfg");
                if (File.Exists(configPath))
                {
                    _norseConfig = new ConfigFile(configPath, true);
                    return _norseConfig;
                }
            }
            catch
            {
            }

            return EpicLootRaritySetsPlugin.PluginConfig;
        }

        internal static float GetConfiguredBaseDamage()
        {
            return GetNorseConfigFloat("Base Damage", 5f);
        }

        internal static float GetConfiguredDamagePerLevel()
        {
            return GetNorseConfigFloat("Damage Per Level", 0.7f);
        }

        internal static float GetConfiguredAoeDamageRadius()
        {
            return GetNorseConfigFloat("Aoe Damage Radius", 3f);
        }

        internal static float GetConfiguredTargetMaxRange()
        {
            return GetNorseConfigFloat("Target Max Range", 15f);
        }

        internal static bool TryGetManagedScaledDamage(object ability, out float damage)
        {
            damage = 0f;
            if (ability == null)
            {
                return false;
            }

            for (int i = ActiveWaterSpheres.Count - 1; i >= 0; i--)
            {
                ActiveWaterSphere active = ActiveWaterSpheres[i];
                if (active == null || !ReferenceEquals(active.Ability, ability) || active.Owner == null)
                {
                    continue;
                }

                float skillLevel = ClassSkillManager.GetSkillLevel(active.Owner, active.SkillName);
                damage = Mathf.Max(0f, GetConfiguredBaseDamage() + skillLevel * GetConfiguredDamagePerLevel());
                return true;
            }

            return false;
        }

        private static float GetNorseConfigFloat(string key, float fallback)
        {
            if (string.IsNullOrEmpty(key))
            {
                return fallback;
            }

            try
            {
                string configPath = Path.Combine(Paths.ConfigPath, "NorseDemigods.cfg");
                if (!File.Exists(configPath))
                {
                    return fallback;
                }

                bool inSection = false;
                foreach (string rawLine in File.ReadLines(configPath))
                {
                    string line = (rawLine ?? string.Empty).Trim();
                    if (line.Length == 0 || line.StartsWith("#", StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (line.StartsWith("[", StringComparison.Ordinal) && line.EndsWith("]", StringComparison.Ordinal))
                    {
                        inSection = string.Equals(line, "[Ability Water Sphere]", StringComparison.OrdinalIgnoreCase);
                        continue;
                    }

                    if (!inSection || !line.StartsWith(key, StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    int separator = line.IndexOf('=');
                    if (separator < 0)
                    {
                        continue;
                    }

                    string valueText = line.Substring(separator + 1).Trim();
                    float value;
                    if (float.TryParse(valueText, NumberStyles.Float, CultureInfo.InvariantCulture, out value) ||
                        float.TryParse(valueText, NumberStyles.Float, CultureInfo.CurrentCulture, out value))
                    {
                        return value;
                    }
                }
            }
            catch
            {
            }

            return fallback;
        }

        private static Vector3 GetAimedTargetPoint(Player player, float range, out Character targetCharacter)
        {
            targetCharacter = null;
            if (player == null)
            {
                return Vector3.zero;
            }

            Transform originTransform = GameCamera.instance != null ? GameCamera.instance.transform : player.transform;
            Vector3 origin = originTransform.position;
            Vector3 direction = originTransform.forward;
            if (direction.sqrMagnitude <= 0.001f)
            {
                direction = player.transform.forward;
            }

            direction = direction.sqrMagnitude > 0.001f ? direction.normalized : Vector3.forward;
            float maxRange = Mathf.Max(1f, range);
            RaycastHit[] hits = Physics.RaycastAll(origin, direction, maxRange, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            if (hits != null && hits.Length > 0)
            {
                Array.Sort(hits, (left, right) => left.distance.CompareTo(right.distance));
                foreach (RaycastHit hit in hits)
                {
                    if (hit.collider == null)
                    {
                        continue;
                    }

                    Character hitCharacter = GetCharacterFromCollider(hit.collider);
                    if (hitCharacter == player)
                    {
                        continue;
                    }

                    Vector3 hitPoint = ClampTargetPoint(player, hit.point, maxRange);
                    if (IsEnemyTarget(player, hitCharacter) && !hitCharacter.IsDead())
                    {
                        targetCharacter = hitCharacter;
                        return ClampTargetPoint(player, hitCharacter.GetCenterPoint(), maxRange);
                    }

                    targetCharacter = FindEnemyNearPoint(player, hitPoint, Mathf.Max(2f, GetConfiguredAoeDamageRadius()));
                    return hitPoint;
                }
            }

            Vector3 fallback = ClampTargetPoint(player, origin + direction * maxRange, maxRange);
            targetCharacter = FindEnemyNearPoint(player, fallback, Mathf.Max(2f, GetConfiguredAoeDamageRadius()));
            return fallback;
        }

        private static Vector3 ClampTargetPoint(Player player, Vector3 targetPoint, float range)
        {
            if (player == null)
            {
                return targetPoint;
            }

            Vector3 center = player.GetCenterPoint();
            Vector3 delta = targetPoint - center;
            float maxRange = Mathf.Max(1f, range);
            if (delta.sqrMagnitude > maxRange * maxRange)
            {
                targetPoint = center + delta.normalized * maxRange;
            }

            return targetPoint;
        }

        private static Character FindEnemyNearPoint(Player player, Vector3 point, float radius)
        {
            Character best = null;
            float bestDistance = Mathf.Max(0.1f, radius);
            bestDistance *= bestDistance;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character == player || character.IsDead() || !IsEnemyTarget(player, character))
                {
                    continue;
                }

                float distance = (character.GetCenterPoint() - point).sqrMagnitude;
                if (distance < bestDistance)
                {
                    bestDistance = distance;
                    best = character;
                }
            }

            return best;
        }

        private static Character GetCharacterFromCollider(Collider collider)
        {
            if (collider == null)
            {
                return null;
            }

            Character character = collider.GetComponentInParent<Character>();
            if (character != null)
            {
                return character;
            }

            GameObject hitObject = null;
            try
            {
                hitObject = Projectile.FindHitObject(collider);
            }
            catch
            {
            }

            return hitObject != null ? hitObject.GetComponentInParent<Character>() : null;
        }

        private static void ApplyAimedTarget(object ability, Player player, Vector3 targetPoint, Character targetCharacter)
        {
            IEnumerable spheres = _waterSphereListField != null ? _waterSphereListField.GetValue(ability) as IEnumerable : null;
            if (spheres == null)
            {
                return;
            }

            Character anchor = targetCharacter != null ? targetCharacter : player;
            object nullableTargetPoint = CreateNullableVector3(targetPoint);
            foreach (object sphere in spheres)
            {
                if (sphere == null)
                {
                    continue;
                }

                _sphereTargetCharacterField.SetValue(sphere, anchor);
                _sphereTargetPointField.SetValue(sphere, nullableTargetPoint);
            }
        }

        private static object CreateNullableVector3(Vector3 value)
        {
            if (_sphereTargetPointField == null)
            {
                return value;
            }

            try
            {
                return Activator.CreateInstance(_sphereTargetPointField.FieldType, value);
            }
            catch
            {
                return value;
            }
        }

        private static void NeutralizeNorseCosts(object ability)
        {
            if (_energyRequiredField != null)
            {
                _energyRequiredField.SetValue(ability, 0);
            }

            if (_energyCostField != null)
            {
                _energyCostField.SetValue(ability, 0);
            }

            if (_eitrCostField != null)
            {
                _eitrCostField.SetValue(ability, 0);
            }

            if (_cooldownField != null)
            {
                _cooldownField.SetValue(ability, 0f);
            }
        }

        private static void InvokeBridgeExecute(object ability)
        {
            _bridgeExecutionDepth++;
            try
            {
                _executeMethod.Invoke(ability, null);
            }
            finally
            {
                _bridgeExecutionDepth--;
            }
        }

        private static IEnumerable<Vector3> GetSpherePositions(object ability)
        {
            IEnumerable spheres = _waterSphereListField != null ? _waterSphereListField.GetValue(ability) as IEnumerable : null;
            if (spheres == null)
            {
                yield break;
            }

            foreach (object sphere in spheres)
            {
                if (sphere == null)
                {
                    continue;
                }

                GameObject fx = _sphereFxField.GetValue(sphere) as GameObject;
                if (fx != null)
                {
                    yield return fx.transform.position;
                }
            }
        }

        private static void ApplyGravityPull(Player owner, IEnumerable<Vector3> spherePositions, float radius, float force, string iconSet, float dt)
        {
            if (owner == null || spherePositions == null)
            {
                return;
            }

            radius = Mathf.Max(0.1f, radius);
            force = Mathf.Max(0f, force);
            if (force <= 0f)
            {
                return;
            }

            List<Vector3> positions = spherePositions.ToList();
            if (positions.Count == 0)
            {
                return;
            }

            float radiusSqr = radius * radius;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character == owner || character.IsDead() || !IsEnemyTarget(owner, character))
                {
                    continue;
                }

                Vector3 characterPosition = character.transform.position;
                Vector3 closestSphere = Vector3.zero;
                float closestDistanceSqr = radiusSqr;
                bool hasSphere = false;
                foreach (Vector3 spherePosition in positions)
                {
                    Vector3 delta = spherePosition - characterPosition;
                    float sqrDistance = delta.sqrMagnitude;
                    if (sqrDistance > closestDistanceSqr)
                    {
                        continue;
                    }

                    closestSphere = spherePosition;
                    closestDistanceSqr = sqrDistance;
                    hasSphere = true;
                }

                if (!hasSphere)
                {
                    continue;
                }

                ApplyWaterSphereRoot(character, iconSet);
                PullAndHoldWaterSphereTarget(character, closestSphere, Mathf.Sqrt(closestDistanceSqr), radius, force, dt);
            }
        }

        private static void PullAndHoldWaterSphereTarget(Character character, Vector3 spherePosition, float distance, float radius, float force, float dt)
        {
            if (character == null || distance <= 0.001f)
            {
                return;
            }

            Vector3 position = character.transform.position;
            Vector3 delta = spherePosition - position;
            Vector3 direction = delta.normalized;
            Rigidbody body = character.GetComponent<Rigidbody>();
            float holdDistance = Mathf.Max(0.35f, WaterSphereHoldDistance);
            Vector3 holdPosition = spherePosition - direction * holdDistance;
            if (distance <= holdDistance * 1.6f)
            {
                float snap = Mathf.Clamp01(dt * 12f);
                character.transform.position = Vector3.Lerp(position, holdPosition, snap);
                if (body != null)
                {
                    body.linearVelocity = Vector3.Lerp(body.linearVelocity, Vector3.zero, Mathf.Clamp01(dt * 18f));
                }

                return;
            }

            float distance01 = Mathf.Clamp01(distance / Mathf.Max(0.1f, radius));
            float pullStrength = force * Mathf.Lerp(3.4f, 0.75f, distance01);
            Vector3 pullVelocity = direction * pullStrength;
            if (body != null)
            {
                body.linearVelocity = Vector3.Lerp(body.linearVelocity, pullVelocity, Mathf.Clamp01(dt * 7f));
            }
            else
            {
                float step = Mathf.Min(distance - holdDistance, pullStrength * dt);
                character.transform.position += direction * Mathf.Max(0f, step);
            }

            if (distance <= holdDistance * 4f)
            {
                character.transform.position = Vector3.Lerp(character.transform.position, holdPosition, Mathf.Clamp01(dt * 4f));
                if (body != null)
                {
                    body.linearVelocity = Vector3.Lerp(body.linearVelocity, Vector3.zero, Mathf.Clamp01(dt * 4f));
                }
            }
        }

        private static void ApplyWaterSphereRoot(Character target, string iconSet)
        {
            if (target == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateWaterSphereRootBuff(iconSet);
            SEMan seMan = target.GetSEMan();
            StatusEffect active = seMan.GetStatusEffect(buff.NameHash());
            if (active == null)
            {
                seMan.AddStatusEffect(buff, true, 0, 0f, 0);
                return;
            }

            active.m_name = buff.m_name;
            active.m_tooltip = buff.m_tooltip;
            active.m_ttl = buff.m_ttl;
            active.m_icon = buff.m_icon;
            active.m_flashIcon = buff.m_flashIcon;
            active.m_cooldownIcon = buff.m_cooldownIcon;
            active.m_hidden = buff.m_hidden;
            active.m_category = buff.m_category;
            if (StatusEffectTimeField != null)
            {
                try
                {
                    StatusEffectTimeField.SetValue(active, 0f);
                }
                catch
                {
                }
            }
        }

        private static StatusEffect GetOrCreateWaterSphereRootBuff(string iconSet)
        {
            if (_waterSphereRootBuff == null)
            {
                _waterSphereRootBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _waterSphereRootBuff.name = WaterSphereRootBuffName;
                _waterSphereRootBuff.m_name = LocalizedText.AbilityName("Water Sphere");
                _waterSphereRootBuff.m_category = WaterSphereRootBuffCategory;
                _waterSphereRootBuff.m_flashIcon = false;
                _waterSphereRootBuff.m_cooldownIcon = true;
                _waterSphereRootBuff.m_hidden = false;
                _waterSphereRootBuff.m_tooltip = LocalizedText.Select(
                    "Inmovilizado por la esfera de agua.",
                    "Immobilized by Water Sphere.");
                if (SpeedModifierField != null)
                {
                    SpeedModifierField.SetValue(_waterSphereRootBuff, -1f);
                }
            }

            StatusEffectIconHelper.Apply(_waterSphereRootBuff, Player.m_localPlayer, string.IsNullOrEmpty(iconSet) ? "Heimdall" : iconSet);
            _waterSphereRootBuff.m_ttl = WaterSphereRootRefreshSeconds;
            return _waterSphereRootBuff;
        }

        private static bool IsEnemyTarget(Player owner, Character target)
        {
            if (owner == null || target == null || target == owner)
            {
                return false;
            }

            if (CharacterTargeting.IsPlayerPvPEnemy(owner, target))
            {
                return true;
            }

            if (target is Player)
            {
                return false;
            }

            if (_baseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = _baseAIIsEnemyMethod.Invoke(null, new object[] { owner, target });
                    if (value is bool)
                    {
                        return (bool)value;
                    }
                }
                catch
                {
                }
            }

            return true;
        }

        private static void Stop(object ability)
        {
            if (ability == null || _stopMethod == null)
            {
                return;
            }

            try
            {
                _stopMethod.Invoke(ability, new object[] { false });
            }
            catch
            {
            }
        }

        private static void LogFailure(string reason, Exception ex)
        {
            if (_loggedFailure)
            {
                return;
            }

            _loggedFailure = true;
            EpicLootRaritySetsPlugin.Log.LogWarning(reason + " " + ex.GetBaseException().Message);
        }

        private sealed class ActiveWaterSphere
        {
            internal readonly Player Owner;
            internal readonly object Ability;
            internal readonly Skills.SkillType SkillType;
            internal readonly string SkillName;
            internal readonly string IconSet;
            internal readonly float MaxDuration;
            internal readonly float PullRadius;
            internal readonly float PullForce;
            internal readonly List<Vector3> LastPositions = new List<Vector3>();
            internal float Elapsed;
            internal float PullTickAccumulator;
            internal float MissingPositionTime;

            internal ActiveWaterSphere(Player owner, object ability, Skills.SkillType skillType, string skillName, string iconSet, float maxDuration, float pullRadius, float pullForce)
            {
                Owner = owner;
                Ability = ability;
                SkillType = skillType;
                SkillName = string.IsNullOrEmpty(skillName) ? "Heimdall" : skillName;
                IconSet = iconSet;
                MaxDuration = Mathf.Max(1f, maxDuration);
                PullRadius = Mathf.Max(0.1f, pullRadius);
                PullForce = Mathf.Max(0f, pullForce);
                Elapsed = 0f;
                PullTickAccumulator = 0f;
                MissingPositionTime = 0f;
            }

            internal bool HasPositions
            {
                get { return LastPositions.Count > 0; }
            }

            internal void SetPositions(List<Vector3> positions)
            {
                LastPositions.Clear();
                if (positions != null)
                {
                    LastPositions.AddRange(positions);
                }
            }
        }
    }

