        private static Vector3 _pendingCrushLastPosition;

        internal static void Update(Player player, float dt)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            NorseSurtAbilityBridge.Update(dt);
            UpdateBurningGrounds(player, dt);
            UpdatePendingCrush(player, dt);
            UpdateTripleLightningStrike(player, dt);

            UpdateDashSpeedBuff(player, dt);
            _slashLifestealWindow = Mathf.Max(0f, _slashLifestealWindow - dt);
            _slashCooldown = Mathf.Max(0f, _slashCooldown - dt);
            _crushCooldown = Mathf.Max(0f, _crushCooldown - dt);
            _elementalShieldCooldown = Mathf.Max(0f, _elementalShieldCooldown - dt);
            _lightningChannelCooldown = Mathf.Max(0f, _lightningChannelCooldown - dt);
            UpdateElementalShield(player, dt);

            if (EpicLootRaritySetsPlugin.EnableFrostbrandAbilities != null && !EpicLootRaritySetsPlugin.EnableFrostbrandAbilities.Value)
            {
                CancelTripleLightningStrike(player);
                RemoveElementalShield(player);
                RemoveRechargeBuff(player);
                RemoveDashChargeBuff(player);
                RemoveDashSpeedBuff(player);
                return;
            }

            if (!SetActivationBuffController.HasActiveSet(RequiredSet))
            {
                CancelTripleLightningStrike(player);
                RemoveElementalShield(player);
                RemoveLightningStackBuff(player);
                RemoveRechargeBuff(player);
                RemoveDashChargeBuff(player);
                RemoveDashSpeedBuff(player);
                _dashChargesInitialized = false;
                return;
            }

            UpdateDashCharges(player, dt);
            UpdateLightningStackBuff(player, dt);
            UpdateRechargeBuff(player, dt);
            if (!CanReadAbilityInput(player))
            {
                return;
            }

            if (SetAbilityInput.IsShortcutDown(EpicLootRaritySetsPlugin.FrostbrandDashHotkey))
            {
                TryDash(player);
                return;
            }

            if ((SetAbilityInput.IsSecondaryAttackDown() && _secondarySlashConsumedFrame != Time.frameCount) ||
                SetAbilityInput.IsShortcutDown(EpicLootRaritySetsPlugin.FrostbrandSlashHotkey))
            {
                TrySlash(player);
                return;
            }

            if (SetAbilityInput.IsShortcutDown(EpicLootRaritySetsPlugin.FrostbrandElementalShieldHotkey) &&
                SetAbilityInput.IsBlockHeld())
            {
                TryElementalShield(player);
                return;
            }

            if (SetAbilityInput.IsShortcutDown(EpicLootRaritySetsPlugin.FrostbrandLightningChannelHotkey) &&
                !SetAbilityInput.IsBlockHeld())
            {
                TryStartTripleLightningStrike(player);
                return;
            }
        }

        internal static void Clear(Player player)
        {
            CancelTripleLightningStrike(player);
            RemoveElementalShield(player);
            RemoveLightningStackBuff(player);
            RemoveRechargeBuff(player);
            RemoveDashChargeBuff(player);
            RemoveDashSpeedBuff(player);
            DestroyVisual(ref _elementalShieldVisual);
            BurningGrounds.Clear();
            _dashCharges = 0;
            _dashRechargeTimer = 0f;
            _dashChargeRefreshTimer = 0f;
            _dashSpeedRemaining = 0f;
            _slashLifestealWindow = 0f;
            _dashChargesInitialized = false;
            _slashCooldown = 0f;
            _crushCooldown = 0f;
            _elementalShieldCooldown = 0f;
            _lightningChannelCooldown = 0f;
            _elementalShieldRemaining = 0f;
            _lightningStrikeSequenceTimer = 0f;
            _lightningStrikeSequenceRemaining = 0;
            _lightningStrikeSequenceActive = false;
            _lightningStrikeSequenceWeapon = null;
            RestoreLightningChannelWeaponPose();
            _lightningStackRefreshTimer = 0f;
            _rechargeChainDepth = 0;
            _secondarySlashConsumedFrame = -1;
            _slashAnimationDepth = 0;
            _pendingCrushActive = false;
            _pendingCrushLeftGround = false;
            _pendingCrushWasDescending = false;
            _pendingCrushAirTimer = 0f;
        }

        internal static bool TryGetFireBallStacks(out int stacks, out int maxStacks)
        {
            maxStacks = Mathf.Max(1, EpicLootRaritySetsPlugin.FrostbrandLightningStrikeAttackCount != null ? EpicLootRaritySetsPlugin.FrostbrandLightningStrikeAttackCount.Value : 3);
            stacks = Mathf.Clamp(_lightningStrikeHits, 0, maxStacks);
            return IsFrostbrandEnabledAndActive();
        }

        internal static bool TryGetDashPanelState(out int charges, out int maxCharges, out float secondsUntilNextCharge, out bool speedActive)
        {
            bool available = IsFrostbrandEnabledAndActive();
            if (available && Player.m_localPlayer != null)
            {
                EnsureDashChargesInitialized(Player.m_localPlayer);
            }

            maxCharges = GetDashMaxCharges();
            charges = Mathf.Clamp(_dashCharges, 0, maxCharges);
            secondsUntilNextCharge = GetDashSecondsUntilNextCharge();
            speedActive = _dashSpeedRemaining > 0f;
            return available;
        }

        internal static void OnPlayerHit(Character target, HitData hit, float beforeHealth, float afterHealth)
        {
            if (target == null || hit == null || !IsFrostbrandEnabledAndActive())
            {
                return;
            }

            Character attacker = null;
            try
            {
                attacker = hit.GetAttacker();
            }
            catch
            {
            }

            Player player = attacker as Player;
            if (player == null || player != Player.m_localPlayer || target == player || !IsEnemyTarget(player, target))
            {
                return;
            }

            TryHealFromSlash(player, hit, beforeHealth, afterHealth);

            bool rechargeChainHit = _rechargeChainDepth > 0;
            if (!rechargeChainHit)
            {
                AddRechargeStack(player);
            }

            if (_lightningStrikeExecuting || _abilityDamageDepth > 0 || _slashAnimationDepth > 0 || hit.m_skill == ClassSkillManager.Frostbrand)
            {
                return;
            }

            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            TryTriggerRechargeChainLightning(player, target, hit);
        }

        internal static void OnWeaponAttackStarted(Player player, ItemDrop.ItemData weapon)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            if (!IsFrostbrandEnabledAndActive())
            {
                return;
            }

            if (_lightningStrikeExecuting || _abilityDamageDepth > 0 ||
                _lightningStrikeSequenceActive ||
                _slashAnimationDepth > 0 ||
                NorseSurtAbilityBridge.IsBridgeExecuting || NorseSurtAbilityBridge.IsBridgeUpdating)
            {
                return;
            }

            AddFireBallStack(player, weapon);
        }

        internal static bool TryConsumeSecondarySlash(Player player)
        {
            if (player == null || player != Player.m_localPlayer ||
                _slashAnimationDepth > 0 ||
                NorseSurtAbilityBridge.IsBridgeExecuting || NorseSurtAbilityBridge.IsBridgeUpdating ||
                !IsFrostbrandEnabledAndActive())
            {
                return false;
            }

            _secondarySlashConsumedFrame = Time.frameCount;
            TrySlash(player);
            return true;
        }

        private static bool CanReadAbilityInput(Player player)
        {
            return !player.IsDead() &&
                   !player.IsTeleporting() &&
                   !IsAnyMenuOpen();
        }

        private static bool IsShortcutDown(ConfigEntry<KeyboardShortcut> shortcutEntry)
        {
            if (shortcutEntry == null)
            {
                return false;
            }

            KeyboardShortcut shortcut = shortcutEntry.Value;
            if (shortcut.IsDown())
            {
                return true;
            }

            KeyCode mainKey = shortcut.MainKey;
            if (mainKey == KeyCode.None || !Input.GetKeyDown(mainKey))
            {
                return false;
            }

            foreach (KeyCode modifier in shortcut.Modifiers)
            {
                if (!Input.GetKey(modifier))
                {
                    return false;
                }
            }

            return true;
        }

        private static string FormatShortcut(ConfigEntry<KeyboardShortcut> shortcut)
        {
            if (shortcut == null)
            {
                return LocalizedText.Select("Sin tecla", "Unbound");
            }

            string value = shortcut.Value.ToString();
            return string.IsNullOrEmpty(value) ? LocalizedText.Select("Sin tecla", "Unbound") : value;
        }

        private static string FormatSeconds(float seconds)
        {
            return Mathf.CeilToInt(Mathf.Max(0f, seconds)).ToString(CultureInfo.InvariantCulture) + "s";
        }

        private static bool IsAnyMenuOpen()
        {
            if (InventoryGui.instance != null && InventoryGui.IsVisible())
            {
                return true;
            }

            if (Menu.instance != null && Menu.IsVisible())
            {
                return true;
            }

            if (TextInput.instance != null && TextInput.IsVisible())
            {
                return true;
            }

            if (Chat.instance != null && Chat.instance.HasFocus())
            {
                return true;
            }

            return Minimap.instance != null && Minimap.IsOpen();
        }

        private static void TryDash(Player player)
        {
            EnsureDashChargesInitialized(player);
            if (_dashCharges <= 0)
            {
                ShowMessage(player, string.Format(LocalizedText.Select("Dash: sin cargas. Siguiente carga en {0:0}s.", "Dash: no charges. Next charge in {0:0}s."), GetDashSecondsUntilNextCharge()));
                RefreshDashChargeBuff(player);
                return;
            }

            if (!TrySpendEitrAndCooldown(player, "Dash", EpicLootRaritySetsPlugin.FrostbrandDashEitrUse.Value, 0f))
            {
                return;
            }

            string failureReason;
            if (!NorseDashBridge.TryDash(player, out failureReason))
            {
                ShowMessage(player, failureReason);
                return;
            }

            player.UseEitr(EpicLootRaritySetsPlugin.FrostbrandDashEitrUse.Value);
            ConsumeDashCharge(player);
            ApplyDashSpeedBuff(player);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            RefreshDashChargeBuff(player);
        }

        private static void UpdateDashCharges(Player player, float dt)
        {
            EnsureDashChargesInitialized(player);
            int maxCharges = GetDashMaxCharges();
            bool changed = false;
            if (_dashCharges > maxCharges)
            {
                _dashCharges = maxCharges;
                changed = true;
            }

            if (_dashCharges < maxCharges)
            {
                float rechargeSeconds = GetDashRechargeSeconds();
                _dashRechargeTimer += Mathf.Max(0f, dt);
                while (_dashCharges < maxCharges && _dashRechargeTimer >= rechargeSeconds)
                {
                    _dashRechargeTimer -= rechargeSeconds;
                    _dashCharges++;
                    changed = true;
                }
            }
            else
            {
                _dashRechargeTimer = 0f;
            }

            _dashChargeRefreshTimer -= dt;
            if (changed || _dashChargeRefreshTimer <= 0f)
            {
                _dashChargeRefreshTimer = 0.25f;
                RefreshDashChargeBuff(player);
            }
        }

        private static void EnsureDashChargesInitialized(Player player)
        {
            if (_dashChargesInitialized)
            {
                return;
            }

            _dashChargesInitialized = true;
            _dashCharges = GetDashMaxCharges();
            _dashRechargeTimer = 0f;
            RefreshDashChargeBuff(player);
        }

        private static void ConsumeDashCharge(Player player)
        {
            EnsureDashChargesInitialized(player);
            int maxCharges = GetDashMaxCharges();
            _dashCharges = Mathf.Clamp(_dashCharges - 1, 0, maxCharges);
            if (_dashCharges >= maxCharges)
            {
                _dashRechargeTimer = 0f;
            }

            RefreshDashChargeBuff(player);
        }

        private static int GetDashMaxCharges()
        {
            return Mathf.Max(1, EpicLootRaritySetsPlugin.FrostbrandDashMaxCharges != null ? EpicLootRaritySetsPlugin.FrostbrandDashMaxCharges.Value : 3);
        }

        private static float GetDashRechargeSeconds()
        {
            return Mathf.Max(0.1f, EpicLootRaritySetsPlugin.FrostbrandDashRechargeSeconds != null ? EpicLootRaritySetsPlugin.FrostbrandDashRechargeSeconds.Value : 15f);
        }

        private static float GetDashSecondsUntilNextCharge()
        {
            if (_dashCharges >= GetDashMaxCharges())
            {
                return 0f;
            }

            return Mathf.Max(0f, GetDashRechargeSeconds() - _dashRechargeTimer);
        }

        private static void RefreshDashChargeBuff(Player player)
        {
            if (player == null)
            {
                return;
            }

            Sprite icon = AbilityPanelIconCatalog.GetIcon("Abilities", "frostbrand_dash.png") ??
                          GetWeaponIcon(player.GetCurrentWeapon()) ??
                          StatusEffectIconHelper.GetIcon(player, RequiredSet);
            StatusEffect buff = GetOrCreateDashChargeBuff(icon);
            buff.m_ttl = 0f;
            SEMan seMan = player.GetSEMan();
            StatusEffect active = seMan.GetStatusEffect(buff.NameHash());
            if (active == null)
            {
                seMan.AddStatusEffect(buff, true, 0, 0f, 0);
                return;
            }

            ApplyStatusEffectFields(active, buff);
        }

        private static StatusEffect GetOrCreateDashChargeBuff(Sprite icon)
        {
            if (_dashChargeBuff == null)
            {
                _dashChargeBuff = ScriptableObject.CreateInstance<FixedIconTextStatusEffect>();
                _dashChargeBuff.name = DashChargeBuffName;
                _dashChargeBuff.m_category = DashChargeBuffCategory;
                _dashChargeBuff.m_flashIcon = false;
                _dashChargeBuff.m_cooldownIcon = false;
                _dashChargeBuff.m_hidden = false;
            }

            int maxCharges = GetDashMaxCharges();
            _dashChargeBuff.m_name = string.Format("{0} {1}/{2}", LocalizedText.AbilityName("Dash"), Mathf.Clamp(_dashCharges, 0, maxCharges), maxCharges);
            _dashChargeBuff.m_tooltip = string.Format(
                LocalizedText.Select(
                    "Cargas de Dash de Frostbrand.\n\nCargas: {0}/{1}.\nRecarga: una carga cada {2:0.#}s.\nSiguiente carga en: {3:0.#}s.\nTecla: {4}.",
                    "Frostbrand Dash charges.\n\nCharges: {0}/{1}.\nRecharge: one charge every {2:0.#}s.\nNext charge in: {3:0.#}s.\nKey: {4}."),
                Mathf.Clamp(_dashCharges, 0, maxCharges),
                maxCharges,
                GetDashRechargeSeconds(),
                GetDashSecondsUntilNextCharge(),
                FormatShortcut(EpicLootRaritySetsPlugin.FrostbrandDashHotkey));
            FixedIconTextStatusEffect fixedText = _dashChargeBuff as FixedIconTextStatusEffect;
            if (fixedText != null)
            {
                fixedText.IconText = _dashCharges >= maxCharges ? string.Empty : FormatSeconds(GetDashSecondsUntilNextCharge());
            }

            StatusEffectIconHelper.Apply(_dashChargeBuff, RequiredSet, icon);
            return _dashChargeBuff;
        }

        private static void RemoveDashChargeBuff(Player player)
        {
            if (player != null && _dashChargeBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_dashChargeBuff.NameHash(), true);
            }
        }

        private static void ApplyDashSpeedBuff(Player player)
        {
            if (player == null)
            {
                return;
            }

            _dashSpeedRemaining = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.FrostbrandDashSpeedDuration != null ? EpicLootRaritySetsPlugin.FrostbrandDashSpeedDuration.Value : 3f);
            StatusEffect buff = GetOrCreateDashSpeedBuff(AbilityPanelIconCatalog.GetIcon("Buffs", "frostbrand_dash_speed.png") ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            buff.m_ttl = _dashSpeedRemaining + 0.1f;
            buff.m_tooltip = string.Format(
                LocalizedText.Select(
                    "Impulso de Dash.\n\nVelocidad de movimiento: +{0:0.#}%.\nDuracion: {1:0.#}s.",
                    "Dash momentum.\n\nMovement speed: +{0:0.#}%.\nDuration: {1:0.#}s."),
                GetDashSpeedBonus() * 100f,
                _dashSpeedRemaining);
            ApplyOrRefreshStatusEffect(player, buff, 0);
        }

        private static void UpdateDashSpeedBuff(Player player, float dt)
        {
            if (_dashSpeedRemaining <= 0f)
            {
                return;
            }

            _dashSpeedRemaining -= Mathf.Max(0f, dt);
            if (_dashSpeedRemaining <= 0f)
            {
                RemoveDashSpeedBuff(player);
            }
        }

        private static StatusEffect GetOrCreateDashSpeedBuff(Sprite icon)
        {
            if (_dashSpeedBuff == null)
            {
                _dashSpeedBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _dashSpeedBuff.name = DashSpeedBuffName;
                _dashSpeedBuff.m_category = DashSpeedBuffCategory;
                _dashSpeedBuff.m_flashIcon = false;
                _dashSpeedBuff.m_cooldownIcon = true;
                _dashSpeedBuff.m_hidden = false;
            }

            _dashSpeedBuff.m_name = LocalizedText.Select("Impulso de Dash", "Dash Momentum");
            _dashSpeedBuff.m_category = DashSpeedBuffCategory;
            _dashSpeedBuff.m_flashIcon = false;
            _dashSpeedBuff.m_cooldownIcon = true;
            _dashSpeedBuff.m_hidden = false;
            StatusEffectIconHelper.Apply(_dashSpeedBuff, RequiredSet, icon);
            SetFloatField(_dashSpeedBuff, SpeedModifierField, GetDashSpeedBonus());
            return _dashSpeedBuff;
        }

        private static float GetDashSpeedBonus()
        {
            return Mathf.Max(0f, EpicLootRaritySetsPlugin.FrostbrandDashSpeedBonus != null ? EpicLootRaritySetsPlugin.FrostbrandDashSpeedBonus.Value : 0.5f);
        }

        private static void RemoveDashSpeedBuff(Player player)
        {
            _dashSpeedRemaining = 0f;
            if (player != null && _dashSpeedBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_dashSpeedBuff.NameHash(), true);
            }
        }

        private static void TrySlash(Player player)
        {
            if (!TrySpendEitrAndCooldown(player, "Slash", EpicLootRaritySetsPlugin.FrostbrandSlashEitrUse.Value, _slashCooldown))
            {
                return;
            }

            ItemDrop.ItemData weapon = player.GetCurrentWeapon();
            player.UseEitr(EpicLootRaritySetsPlugin.FrostbrandSlashEitrUse.Value);
            _slashLifestealWindow = 0.8f;
            TriggerSlashAnimation(player);
            string failureReason;
            if (!NorseSurtAbilityBridge.TrySlash(player, out failureReason))
            {
                NorseVisualEffectBridge.SpawnAtPlayer(player, "FxFireSlash", "FireSlash", "Slash", "Surt", "FxFire", "Fire");
                WithAbilityDamage(() => DamageCone(player, weapon, EpicLootRaritySetsPlugin.FrostbrandSlashRange.Value, EpicLootRaritySetsPlugin.FrostbrandSlashRadius.Value, CreateSlashDamage(player, weapon), EpicLootRaritySetsPlugin.FrostbrandSlashBaseDamage.Value));
            }

            _slashCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.FrostbrandSlashCooldown.Value);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            AddFireBallStack(player, weapon);
            AbilityCooldownBuffController.Start(player, "FrostbrandSlash", "Slash", _slashCooldown, null);
            ShowMessage(player, "Slash.");
        }

        private static void TryHealFromSlash(Player player, HitData hit, float beforeHealth, float afterHealth)
        {
            if (player == null || hit == null || _slashLifestealWindow <= 0f)
            {
                return;
            }

            if (_rechargeChainDepth > 0 || _lightningStrikeExecuting || _lightningStrikeSequenceActive)
            {
                return;
            }

            bool frostbrandAbilityHit = hit.m_skill == ClassSkillManager.Frostbrand ||
                                        _abilityDamageDepth > 0 ||
                                        NorseSurtAbilityBridge.IsBridgeExecuting ||
                                        NorseSurtAbilityBridge.IsBridgeUpdating;
            if (!frostbrandAbilityHit)
            {
                return;
            }

            float dealt = beforeHealth >= 0f
                ? Mathf.Max(0f, beforeHealth - Mathf.Max(0f, afterHealth))
                : GetTotalDamage(hit.m_damage);
            if (dealt <= 0.01f)
            {
                return;
            }

            float heal = dealt * Mathf.Max(0f, EpicLootRaritySetsPlugin.FrostbrandSlashHealFraction != null ? EpicLootRaritySetsPlugin.FrostbrandSlashHealFraction.Value : 0.5f);
            if (heal > 0.01f)
            {
                player.Heal(heal, true);
            }
        }

        private static void AddFireBallStack(Player player, ItemDrop.ItemData weapon)
        {
            if (player == null || player != Player.m_localPlayer || !IsFrostbrandEnabledAndActive())
            {
                return;
            }

            int requiredHits = Mathf.Max(1, EpicLootRaritySetsPlugin.FrostbrandLightningStrikeAttackCount.Value);
            _lightningStrikeHits = Mathf.Clamp(_lightningStrikeHits + 1, 0, requiredHits);
            if (_lightningStrikeHits < requiredHits)
            {
                RefreshLightningStackBuff(player);
                return;
            }

            _lightningStrikeHits = 0;
            Vector3 strikePoint;
            Vector3 strikeDirection;
            if (!TryFindProjectileAim(player, Mathf.Max(12f, EpicLootRaritySetsPlugin.FrostbrandLightningStrikeRadius.Value + 20f), out strikePoint, out strikeDirection))
            {
                strikePoint = player.GetCenterPoint() + player.transform.forward * 5f;
                strikeDirection = player.GetAimDir(player.GetCenterPoint());
            }

            CastFrostbrandFireBall(player, weapon, strikePoint, strikeDirection);
            RefreshLightningStackBuff(player);
        }

        private static void TriggerSlashAnimation(Player player)
        {
            _slashAnimationDepth++;
            try
            {
                TriggerSecondaryAttackIfNeeded(player, "knife_stab0", 0.5f, 0f);
            }
            finally
            {
                _slashAnimationDepth--;
            }
        }

        private static void TriggerCrushAnimation(Player player)
        {
            _slashAnimationDepth++;
            try
            {
                TriggerSecondaryAttackIfNeeded(player, "knife_secondary", null, 0f);
            }
            finally
            {
                _slashAnimationDepth--;
            }
        }

        private static void TryCrush(Player player)
        {
            if (!TrySpendEitrAndCooldown(player, "Crush", EpicLootRaritySetsPlugin.FrostbrandCrushEitrUse.Value, _crushCooldown))
            {
                return;
            }

            Vector3 targetPoint;
            if (!TryFindAimPoint(player, EpicLootRaritySetsPlugin.FrostbrandCrushRange.Value, out targetPoint))
            {
                ShowMessage(player, "Crush: sin punto.");
                return;
            }

            ItemDrop.ItemData weapon = player.GetCurrentWeapon();
            player.UseEitr(EpicLootRaritySetsPlugin.FrostbrandCrushEitrUse.Value);
            TriggerCrushAnimation(player);
            LaunchPlayerToward(player, targetPoint);

            _pendingCrushActive = true;
            _pendingCrushPoint = targetPoint;
            _pendingCrushStartPoint = player.transform.position;
            _pendingCrushWeapon = weapon;
            _pendingCrushTimer = 1.15f;
            _pendingCrushAirTimer = 0f;
            _pendingCrushLeftGround = false;
            _pendingCrushWasDescending = false;
            _pendingCrushLastPosition = player.transform.position;
            _crushCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.FrostbrandCrushCooldown.Value);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            AbilityCooldownBuffController.Start(player, "FrostbrandCrush", "Crush", _crushCooldown, null);
            ShowMessage(player, "Crush.");
        }

        private static void TryElementalShield(Player player)
        {
            if (_elementalShieldRemaining > 0f)
            {
                ShowMessage(player, "Elemental Shield: activo.");
                return;
            }

            if (!TrySpendEitrAndCooldown(player, "Elemental Shield", EpicLootRaritySetsPlugin.FrostbrandElementalShieldEitrUse.Value, _elementalShieldCooldown))
            {
                return;
            }

            player.UseEitr(EpicLootRaritySetsPlugin.FrostbrandElementalShieldEitrUse.Value);
            _elementalShieldRemaining = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.FrostbrandElementalShieldDuration.Value);
            _elementalShieldCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.FrostbrandElementalShieldCooldown.Value);
            EnsureElementalShieldVisual(player);
            RefreshElementalShieldBuff(player);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            AbilityCooldownBuffController.Start(player, "FrostbrandElementalShield", "Elemental Shield", _elementalShieldCooldown, null);
            ShowMessage(player, "Elemental Shield.");
        }

        private static void TryStartTripleLightningStrike(Player player)
        {
            if (_lightningStrikeSequenceActive)
            {
                return;
            }

            if (_lightningChannelCooldown > 0f)
            {
                ShowMessage(player, string.Format("Lightning Strike: {0:0}s cooldown.", _lightningChannelCooldown));
                return;
            }

            if (_pendingCrushActive)
            {
                ShowMessage(player, "Lightning Strike: espera a caer.");
                return;
            }

            ItemDrop.ItemData weapon = player.GetCurrentWeapon();

            float eitrUse = GetTripleLightningStrikeEitrUse();
            if (eitrUse > 0f && !player.HaveEitr(eitrUse))
            {
                if (Hud.instance != null)
                {
                    Hud.instance.EitrBarEmptyFlash();
                }

                ShowMessage(player, "Lightning Strike: no tienes eitr suficiente.");
                return;
            }

            Vector3 targetPoint;
            if (!TryFindAimPoint(player, EpicLootRaritySetsPlugin.FrostbrandLightningChannelRange.Value, out targetPoint))
            {
                ShowMessage(player, "Lightning Strike: sin punto.");
                return;
            }

            if (eitrUse > 0f)
            {
                player.UseEitr(eitrUse);
            }

            _lightningChannelPoint = targetPoint;
            _lightningStrikeSequenceWeapon = weapon;
            _lightningStrikeSequenceRemaining = TripleLightningStrikeCount;
            _lightningStrikeSequenceTimer = 0f;
            _lightningStrikeSequenceActive = true;
            _lightningChannelCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.FrostbrandLightningChannelCooldown.Value);
            AbilityCooldownBuffController.Start(player, "FrostbrandLightningStrike", "Lightning Strike", _lightningChannelCooldown, GetWeaponIcon(weapon));
            ShowMessage(player, "Lightning Strike.");
            UpdateTripleLightningStrike(player, 0f);
        }

        private static void UpdateTripleLightningStrike(Player player, float dt)
        {
            if (!_lightningStrikeSequenceActive || player == null)
            {
                return;
            }

            if (player.IsDead() || player.IsTeleporting() || !IsFrostbrandEnabledAndActive())
            {
                CancelTripleLightningStrike(player);
                return;
            }

            _lightningStrikeSequenceTimer -= Mathf.Max(0f, dt);
            if (_lightningStrikeSequenceTimer > 0f)
            {
                return;
            }

            CastTripleLightningStrikeImpact(player, _lightningStrikeSequenceWeapon ?? player.GetCurrentWeapon());
            _lightningStrikeSequenceRemaining--;
            if (_lightningStrikeSequenceRemaining <= 0)
            {
                CancelTripleLightningStrike(player);
                return;
            }

            _lightningStrikeSequenceTimer = Mathf.Max(0.05f, EpicLootRaritySetsPlugin.FrostbrandLightningChannelTickInterval.Value);
        }

        private static void CancelTripleLightningStrike(Player player)
        {
            _lightningStrikeSequenceActive = false;
            _lightningStrikeSequenceRemaining = 0;
            _lightningStrikeSequenceTimer = 0f;
            _lightningStrikeSequenceWeapon = null;
            _lightningChannelPoint = Vector3.zero;
            RestoreLightningChannelWeaponPose();
        }

        private static void CastTripleLightningStrikeImpact(Player player, ItemDrop.ItemData weapon)
        {
            string failureReason;
            bool nativeVisual = NorseThorAbilityBridge.TryLightningStrike(player, out failureReason);

            Vector3 point = _lightningChannelPoint;
            if (!nativeVisual)
            {
                NorseVisualEffectBridge.Spawn(
                    point + Vector3.up * 0.15f,
                    Quaternion.identity,
                    1.15f,
                    "FxLightningExpansion",
                    "FxLightningExplosion2",
                    "FxLightningWithSoundOnline",
                    "FxLightningWithoutSoundOnline",
                    "LightningStrike",
                    "Lightning",
                    "Thunder",
                    "Thor");
            }

            WithAbilityDamage(() => DamageArea(
                player,
                weapon,
                point,
                EpicLootRaritySetsPlugin.FrostbrandLightningChannelRadius.Value,
                CreateTripleLightningStrikeDamage(player, weapon),
                18f,
                ApplyLightningRoot));
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
        }

        private static void RestoreLightningChannelWeaponPose()
        {
            if (_lightningChannelWeaponPoseSaved && _lightningChannelWeaponVisual != null)
            {
                try
                {
                    _lightningChannelWeaponVisual.transform.localRotation = _lightningChannelWeaponLocalRotation;
                }
                catch
                {
                }
            }

            _lightningChannelWeaponVisual = null;
            _lightningChannelWeaponLocalRotation = Quaternion.identity;
            _lightningChannelWeaponPoseSaved = false;
        }

        private static HitData.DamageTypes CreateTripleLightningStrikeDamage(Player player, ItemDrop.ItemData weapon)
        {
            HitData.DamageTypes damages = new HitData.DamageTypes
            {
                m_lightning = GetTripleLightningStrikeDamage(player)
            };

            ApplyEpicLootDamageModifiers(player, weapon, ref damages);
            return damages;
        }

        private static float GetTripleLightningStrikeDamage(Player player)
        {
            return GetElementalScaled(
                player,
                EpicLootRaritySetsPlugin.FrostbrandLightningChannelBaseDamagePerTick.Value,
                EpicLootRaritySetsPlugin.FrostbrandLightningChannelDamagePerElementalMagicLevel.Value);
        }

        private static float GetTripleLightningStrikeEitrUse()
        {
            return Mathf.Max(0f, EpicLootRaritySetsPlugin.FrostbrandLightningChannelEitrPerSecond.Value);
        }

        internal static void ModifyIncomingDamage(Player player, HitData hit)
        {
            if (player == null || hit == null || player != Player.m_localPlayer || _elementalShieldRemaining <= 0f || !IsFrostbrandEnabledAndActive())
            {
                return;
            }

            float mitigation = GetElementalShieldMitigation(player);
            hit.m_damage.m_fire = 0f;
            ScaleNonFireDamage(ref hit.m_damage, Mathf.Clamp01(1f - mitigation));
        }

        internal static void ModifyOutgoingDamage(HitData hit)
        {
            if (hit == null || _rechargeStacks <= 0 || !IsFrostbrandEnabledAndActive())
            {
                return;
            }

            Character attacker = null;
            try
            {
                attacker = hit.GetAttacker();
            }
            catch
            {
            }

            Player player = attacker as Player;
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            float multiplier = 1f + Mathf.Clamp(_rechargeStacks, 0, RechargeMaxStacks) * RechargeDamagePerStack;
            ScaleAllDamage(ref hit.m_damage, multiplier);
        }

        private static void CastFrostbrandFireBall(Player player, ItemDrop.ItemData weapon, Vector3 center, Vector3 aimDirection)
        {
            float radius = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.FrostbrandLightningStrikeRadius.Value);
            HitData.DamageTypes damages = CreateFrostbrandFireBallDamage(player, weapon);

            _lightningStrikeExecuting = true;
            try
            {
                if (TryLaunchFrostbrandFireBallProjectile(player, weapon, center, aimDirection, damages))
                {
                    ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
                    return;
                }

                foreach (Character character in Character.GetAllCharacters())
                {
                    if (character == null || character.IsDead() || !IsEnemyTarget(player, character))
                    {
                        continue;
                    }

                    if ((character.GetCenterPoint() - center).sqrMagnitude > radius * radius)
                    {
                        continue;
                    }

                    HitData strikeHit = new HitData
                    {
                        m_damage = damages,
                        m_skill = ClassSkillManager.Frostbrand,
                        m_skillLevel = ClassSkillManager.GetSkillLevel(player, "Frostbrand"),
                        m_ranged = true,
                        m_dodgeable = true,
                        m_blockable = true,
                        m_backstabBonus = 1f,
                        m_staggerMultiplier = 1f,
                        m_pushForce = EpicLootRaritySetsPlugin.FrostbrandLightningStrikeImpactForce.Value,
                        m_point = character.GetCenterPoint(),
                        m_dir = character.GetCenterPoint() - center
                    };

                    if (player != null)
                    {
                        strikeHit.SetAttacker(player);
                    }

                    character.Damage(strikeHit);
                }
            }
            finally
            {
                _lightningStrikeExecuting = false;
            }

            if (player != null)
            {
                NorseVisualEffectBridge.Spawn(center, Quaternion.identity, "FxFireExplosion2", "FxFireExplosion", "FxFireExpansion", "FxFire");
                ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
                ShowMessage(player, "Fire Ball.");
            }
        }

        private static bool TryLaunchFrostbrandFireBallProjectile(Player player, ItemDrop.ItemData weapon, Vector3 targetPoint, Vector3 aimDirection, HitData.DamageTypes damages)
        {
            if (player == null)
            {
                return false;
            }

            GameObject projectilePrefab = GetFrostbrandFireBallProjectilePrefab();
            if (projectilePrefab == null)
            {
                return false;
            }

            Vector3 spawnPoint = player.GetCenterPoint() + player.transform.forward * 0.8f + Vector3.up * 0.15f;
            Vector3 direction = aimDirection;
            if (direction.sqrMagnitude <= 0.001f)
            {
                direction = targetPoint - spawnPoint;
            }

            if (direction.sqrMagnitude <= 0.001f)
            {
                direction = player.GetAimDir(spawnPoint);
            }

            if (direction.sqrMagnitude <= 0.001f)
            {
                direction = player.transform.forward;
            }

            direction.Normalize();
            GameObject projectileObject = UnityEngine.Object.Instantiate(projectilePrefab, spawnPoint, Quaternion.LookRotation(direction));
            IProjectile projectile = projectileObject.GetComponent<IProjectile>();
            if (projectile == null)
            {
                projectile = projectileObject.GetComponentInChildren<IProjectile>();
            }

            if (projectile == null)
            {
                ZNetSceneSafety.Destroy(projectileObject);
                return false;
            }

            HitData hit = CreateProjectileHit(player, weapon, damages, targetPoint, direction);
            float velocity = Mathf.Max(10f, EpicLootRaritySetsPlugin.FrostbrandLightningStrikeImpactForce.Value);
            projectile.Setup(player, direction * velocity, 0f, hit, weapon, null);
            ShowMessage(player, "Fire Ball.");
            return true;
        }

        private static GameObject GetFrostbrandFireBallProjectilePrefab()
        {
            GameObject fireball = GetAttackProjectileFromItem("StaffFireball");
            return fireball != null ? fireball : GetPrefab("fireball_projectile", "StaffFireball_projectile", "projectile_fireball");
        }

        private static GameObject GetAttackProjectileFromItem(string itemPrefabName)
        {
            GameObject itemPrefab = null;
            if (ObjectDB.instance != null)
            {
                itemPrefab = ObjectDB.instance.GetItemPrefab(itemPrefabName);
            }

            if (itemPrefab == null)
            {
                itemPrefab = GetPrefab(itemPrefabName);
            }

            ItemDrop itemDrop = itemPrefab != null ? itemPrefab.GetComponent<ItemDrop>() : null;
            if (itemDrop == null || itemDrop.m_itemData == null || itemDrop.m_itemData.m_shared == null || itemDrop.m_itemData.m_shared.m_attack == null)
            {
                return null;
            }

            return itemDrop.m_itemData.m_shared.m_attack.m_attackProjectile;
        }

        private static GameObject GetPrefab(params string[] names)
        {
            if (names == null || ZNetScene.instance == null)
            {
                return null;
            }

            foreach (string name in names)
            {
                if (string.IsNullOrEmpty(name))
                {
                    continue;
                }

                GameObject prefab = ZNetScene.instance.GetPrefab(name);
                if (prefab != null)
                {
                    return prefab;
                }
            }

            return null;
        }

        private static HitData CreateProjectileHit(Player player, ItemDrop.ItemData weapon, HitData.DamageTypes damages, Vector3 point, Vector3 direction)
        {
            HitData hit = new HitData
            {
                m_damage = damages,
                m_skill = ClassSkillManager.Frostbrand,
                m_skillLevel = ClassSkillManager.GetSkillLevel(player, "Frostbrand"),
                m_ranged = true,
                m_dodgeable = true,
                m_blockable = true,
                m_backstabBonus = 1f,
                m_staggerMultiplier = 1f,
                m_pushForce = EpicLootRaritySetsPlugin.FrostbrandLightningStrikeImpactForce.Value,
                m_point = point,
                m_dir = direction.sqrMagnitude > 0.001f ? direction.normalized : Vector3.forward
            };

            if (player != null)
            {
                hit.SetAttacker(player);
            }

            return hit;
        }

