        private static void UpdatePassiveSneaky(Player player, float dt)
        {
            if (!IsSneaking(player))
            {
                RemoveSneakyBuff(player);
                RestoreSneakyVisual();
                _sneakyActive = false;
                _sneakyRefreshTimer = 0f;
                _aggroSuppressTimer = 0f;
                return;
            }

            _sneakyActive = true;
            ApplySneakyVisual(player);
            _aggroSuppressTimer -= dt;
            if (_aggroSuppressTimer <= 0f)
            {
                _aggroSuppressTimer = AggroSuppressInterval;
                SuppressNearbyAggro(player);
            }

            _sneakyRefreshTimer -= dt;
            if (_sneakyRefreshTimer > 0f)
            {
                return;
            }

            _sneakyRefreshTimer = SneakyRefreshInterval;
            StatusEffect buff = GetOrCreateSneakyBuff(FindHraesvelgrIcon(player) ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            if (buff == null)
            {
                return;
            }

            SEMan seMan = player.GetSEMan();
            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, 1, 0f, 0);
        }

        private static void UpdateRapidVolley(Player player, float dt)
        {
            if (_volleyRemaining <= 0f)
            {
                return;
            }

            player.StopMovement();
            if (_volleyShotsFired >= GetRapidVolleyMaxShots())
            {
                FinishRapidVolley(player);
                return;
            }

            _volleyRemaining -= dt;
            UpdateRapidVolleyAutoFire(player, dt);
            RefreshRapidVolleyBuff(player);
            if (_volleyRemaining > 0f && _volleyShotsFired < GetRapidVolleyMaxShots())
            {
                return;
            }

            FinishRapidVolley(player);
        }

        private static void FinishRapidVolley(Player player)
        {
            _volleyRemaining = 0f;
            _volleyShotTimer = 0f;
            RemoveVolleyBuff(player);
            RestoreFullStamina(player);
            if (_volleyCooldown > 0f)
            {
                AbilityCooldownBuffController.Start(player, "HraesvelgrRapidVolley", "Rapid Volley", _volleyCooldown, GetWeaponIcon(player.GetCurrentWeapon()));
            }
            ShowMessage(player, "Rapid Volley: vigor recuperado.");
        }

        private static void UpdateTrapDamageBuff(Player player, float dt)
        {
            if (!_trapDamageArmed)
            {
                return;
            }

            _trapDamageRemaining -= dt;
            if (_trapDamageRemaining > 0f && IsHraesvelgrEnabledAndActive())
            {
                RefreshTrapDamageBuff(player);
                return;
            }

            _trapDamageArmed = false;
            _trapDamageRemaining = 0f;
            RemoveTrapDamageBuff(player);
        }

        private static void UpdateTrapCharges(Player player, float dt)
        {
            int maxCharges = GetTrapMaxCharges();
            if (!_trapChargesInitialized)
            {
                _trapChargesInitialized = true;
                _trapCharges = maxCharges;
                _trapRechargeTimer = 0f;
                RefreshTrapChargeBuff(player);
                return;
            }

            if (_trapCharges > maxCharges)
            {
                _trapCharges = maxCharges;
            }

            bool changed = false;
            if (_trapCharges < maxCharges)
            {
                float rechargeSeconds = GetTrapRechargeSeconds();
                _trapRechargeTimer += Mathf.Max(0f, dt);
                while (_trapCharges < maxCharges && _trapRechargeTimer >= rechargeSeconds)
                {
                    _trapRechargeTimer -= rechargeSeconds;
                    _trapCharges++;
                    changed = true;
                }
            }
            else
            {
                _trapRechargeTimer = 0f;
            }

            _trapChargeRefreshTimer -= dt;
            if (changed || _trapChargeRefreshTimer <= 0f)
            {
                _trapChargeRefreshTimer = 1f;
                RefreshTrapChargeBuff(player);
            }
        }

        private static void RefreshRapidVolleyBuff(Player player)
        {
            if (player == null || _volleyBuff == null || _volleyRemaining <= 0f)
            {
                return;
            }

            StatusEffect buff = GetOrCreateVolleyBuff(GetWeaponIcon(player.GetCurrentWeapon()) ?? FindHraesvelgrIcon(player) ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            ApplyOrUpdateStatusEffect(player, buff);
        }

        private static void UpdateHeadshotBuff(Player player, float dt)
        {
            _headshotBuffRefreshTimer -= dt;
            if (_headshotBuffRefreshTimer > 0f)
            {
                return;
            }

            _headshotBuffRefreshTimer = 0.5f;
            RefreshHeadshotBuff(player, player != null ? player.GetCurrentWeapon() : null);
        }

        private static void UpdateRapidVolleyAutoFire(Player player, float dt)
        {
            ItemDrop.ItemData weapon = player != null ? player.GetCurrentWeapon() : null;
            if (!IsUsableHraesvelgrBow(player, weapon) || !IsAttackHeld())
            {
                _volleyShotTimer = 0f;
                return;
            }

            float shotsPerSecond = Mathf.Max(1f, EpicLootRaritySetsPlugin.HraesvelgrVolleyShotsPerSecond.Value);
            float interval = 1f / shotsPerSecond;
            _volleyShotTimer -= dt;
            int maxShots = GetRapidVolleyMaxShots();
            while (_volleyShotTimer <= 0f && _volleyRemaining > 0f && _volleyShotsFired < maxShots)
            {
                if (!FireRapidVolleyArrow(player, weapon))
                {
                    FinishRapidVolley(player);
                    return;
                }

                _volleyShotsFired++;
                _volleyShotTimer += interval;
            }
        }

        private static int GetRapidVolleyMaxShots()
        {
            return RapidVolleyShotCap;
        }

        private static bool IsAttackHeld()
        {
            return Input.GetMouseButton(0) ||
                   Input.GetKey(KeyCode.JoystickButton5) ||
                   Input.GetKey(KeyCode.JoystickButton7);
        }

        private static void TryRapidVolley(Player player)
        {
            if (_volleyRemaining > 0f)
            {
                ShowMessage(player, string.Format("Rapid Volley: {0:0}s activo.", _volleyRemaining));
                return;
            }

            if (_volleyCooldown > 0f)
            {
                ShowMessage(player, string.Format("Rapid Volley: {0:0}s cooldown.", _volleyCooldown));
                return;
            }

            ItemDrop.ItemData weapon = player.GetCurrentWeapon();
            if (!IsUsableHraesvelgrBow(player, weapon))
            {
                ShowMessage(player, "Rapid Volley: equipa un arco.");
                return;
            }

            _volleyRemaining = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HraesvelgrVolleyDuration.Value);
            _volleyCooldown = EpicLootRaritySetsPlugin.HraesvelgrVolleyCooldown.Value;
            _volleyShotTimer = 0f;
            _volleyShotsFired = 0;
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);

            StatusEffect buff = GetOrCreateVolleyBuff(GetWeaponIcon(weapon));
            if (buff != null)
            {
                SEMan seMan = player.GetSEMan();
                seMan.RemoveStatusEffect(buff.NameHash(), true);
                seMan.AddStatusEffect(buff, true, 1, 0f, 0);
            }
        }

        private static void TryDash(Player player)
        {
            if (_dashCooldown > 0f)
            {
                ShowMessage(player, string.Format("Dash: {0:0}s cooldown.", _dashCooldown));
                return;
            }

            float staminaUse = Mathf.Max(0f, EpicLootRaritySetsPlugin.HraesvelgrDashEitrUse.Value);
            if (!HasStamina(player, staminaUse))
            {
                ShowMessage(player, "Dash: no tienes vigor suficiente.");
                return;
            }

            Vector3 dashStart = player.transform.position;
            string failureReason;
            if (!NorseDashBridge.TryDash(player, out failureReason, false))
            {
                ShowMessage(player, failureReason);
                return;
            }

            Vector3 dashEnd = player.transform.position;
            ApplyDashTrailDamage(player, dashStart, dashEnd);
            TrySpendStamina(player, staminaUse);
            _dashCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HraesvelgrDashCooldown.Value);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            AbilityCooldownBuffController.Start(player, "HraesvelgrDash", "Dash", _dashCooldown, FindHraesvelgrIcon(player));
        }

        private static void ApplyDashTrailDamage(Player owner, Vector3 start, Vector3 end)
        {
            if (owner == null)
            {
                return;
            }

            float skillLevel = ClassSkillManager.GetSkillLevel(owner, RequiredSet);
            float damage = Mathf.Max(0f, EpicLootRaritySetsPlugin.HraesvelgrDashBaseDamage.Value + skillLevel * EpicLootRaritySetsPlugin.HraesvelgrDashDamagePerHraesvelgrLevel.Value);
            if (damage <= 0.01f)
            {
                return;
            }

            Vector3 travel = end - start;
            if (travel.sqrMagnitude <= 0.25f)
            {
                travel = owner.transform.forward * DashFallbackDistance;
                end = start + travel;
            }

            float radius = Mathf.Max(DashHitRadius, owner.GetRadius() + 1.1f);
            float radiusSqr = radius * radius;
            foreach (Character target in Character.GetAllCharacters())
            {
                if (target == null || target == owner || target.IsDead() || target.IsTamed() || IsSummonedBeast(target) || !IsEnemyTarget(owner, target))
                {
                    continue;
                }

                Vector3 targetPoint = target.GetCenterPoint();
                if (DistancePointToSegmentSquared(targetPoint, start, end) > radiusSqr)
                {
                    continue;
                }

                DamageDashTarget(owner, target, damage, skillLevel, targetPoint, travel.normalized);
            }
        }

        private static void DamageDashTarget(Player owner, Character target, float damage, float skillLevel, Vector3 point, Vector3 travelDirection)
        {
            if (owner == null || target == null)
            {
                return;
            }

            HitData.DamageTypes damages = new HitData.DamageTypes { m_pierce = damage };
            ApplyEpicLootDamageModifiers(owner, owner.GetCurrentWeapon(), ref damages);

            Vector3 direction = point - owner.GetCenterPoint();
            if (direction.sqrMagnitude <= 0.001f)
            {
                direction = travelDirection.sqrMagnitude > 0.001f ? travelDirection : owner.transform.forward;
            }

            HitData hit = new HitData
            {
                m_damage = damages,
                m_skill = ClassSkillManager.Hraesvelgr,
                m_skillLevel = skillLevel,
                m_ranged = false,
                m_dodgeable = false,
                m_blockable = true,
                m_backstabBonus = 1f,
                m_staggerMultiplier = DashStaggerMultiplier,
                m_pushForce = 18f,
                m_point = point,
                m_dir = direction.normalized
            };

            hit.SetAttacker(owner);
            target.Damage(hit);
            CharacterControlEffects.TryStagger(target, hit.m_dir);
        }

        private static float DistancePointToSegmentSquared(Vector3 point, Vector3 segmentStart, Vector3 segmentEnd)
        {
            Vector3 segment = segmentEnd - segmentStart;
            float lengthSqr = segment.sqrMagnitude;
            if (lengthSqr <= 0.0001f)
            {
                return (point - segmentStart).sqrMagnitude;
            }

            float t = Mathf.Clamp01(Vector3.Dot(point - segmentStart, segment) / lengthSqr);
            Vector3 closest = segmentStart + segment * t;
            return (point - closest).sqrMagnitude;
        }

        private static void TryPlaceTrap(Player player)
        {
            EnsureTrapChargesInitialized(player);
            if (_trapCharges <= 0)
            {
                ShowMessage(player, string.Format("Trampa: sin cargas. Siguiente carga en {0:0}s.", GetTrapSecondsUntilNextCharge()));
                RefreshTrapChargeBuff(player);
                return;
            }

            float staminaUse = Mathf.Max(0f, EpicLootRaritySetsPlugin.HraesvelgrTrapStaminaUse.Value);
            if (!TrySpendStamina(player, staminaUse))
            {
                ShowMessage(player, "Trampa: no tienes vigor suficiente.");
                return;
            }

            Vector3 spawn = player.transform.position + player.transform.forward * 1.8f;
            TryProjectGround(spawn, out spawn);
            GameObject prefab = GetAnyPrefab("piece_trap_troll", "piece_trap_wood", "piece_trap", "piece_trap_ashlands", "goblin_trap");
            GameObject trap = prefab != null
                ? UnityEngine.Object.Instantiate(prefab, spawn, Quaternion.LookRotation(player.transform.forward))
                : new GameObject("HraesvelgrArmedTrap");
            if (prefab == null)
            {
                trap.transform.position = spawn;
                trap.transform.rotation = Quaternion.LookRotation(player.transform.forward);
            }

            ForceTrapArmed(trap);

            ZNetView zNetView = trap.GetComponent<ZNetView>();
            if (zNetView != null && zNetView.GetZDO() != null)
            {
                zNetView.GetZDO().Persistent = false;
            }

            HraesvelgrTrapMarker marker = trap.GetComponent<HraesvelgrTrapMarker>();
            if (marker == null)
            {
                marker = trap.AddComponent<HraesvelgrTrapMarker>();
            }

            marker.Setup(player);
            ConsumeTrapCharge(player);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            NorseVisualEffectBridge.Spawn(spawn, Quaternion.identity, 2f, "FxRoots", "Trap", "Root", "Snare");
            ShowMessage(player, string.Format("Trampa armada. Cargas: {0}/{1}.", _trapCharges, GetTrapMaxCharges()));
        }

        internal static void ForceTrapArmed(GameObject trapObject)
        {
            if (trapObject == null)
            {
                return;
            }

            Trap trap = trapObject.GetComponent<Trap>();
            if (trap == null)
            {
                return;
            }

            try
            {
                trap.m_startsArmed = true;
                trap.m_triggeredByEnemies = true;
                SetBoolField(trap, TrapTriggeredByPlayersField, false);
                SetBoolField(trap, TrapTriggeredByTamedField, false);
                SetBoolField(trap, TrapTriggeredByTamesField, false);
                if (trap.m_trigger != null)
                {
                    trap.m_trigger.enabled = true;
                }

                if (trap.m_visualArmed != null)
                {
                    trap.m_visualArmed.SetActive(true);
                }

                if (trap.m_visualUnarmed != null)
                {
                    trap.m_visualUnarmed.SetActive(false);
                }
            }
            catch
            {
            }

            try
            {
                ZNetView zNetView = trap.GetComponent<ZNetView>();
                ZDO zdo = zNetView != null ? zNetView.GetZDO() : null;
                object stateKeyObject = ZdoVarsStateField != null ? ZdoVarsStateField.GetValue(null) : null;
                if (zdo != null && stateKeyObject is int)
                {
                    zdo.Set((int)stateKeyObject, 1, false);
                }
            }
            catch
            {
            }

            try
            {
                if (TrapStateType != null && TrapRequestStateChangeMethod != null)
                {
                    object armedState = Enum.ToObject(TrapStateType, 1);
                    TryInvoke(TrapRequestStateChangeMethod, trap, new[] { armedState });
                }

                TryInvoke(TrapUpdateStateMethod, trap, null);
            }
            catch
            {
            }
        }

        private static void TrySummonBeasts(Player player)
        {
            if (_summonToggleCooldown > 0f)
            {
                ShowMessage(player, string.Format("Summon Beasts: {0:0}s cooldown.", _summonToggleCooldown));
                return;
            }

            if (HasActiveSummons())
            {
                DestroySummonedBeasts(true);
                RemoveSummonBuff(player);
                StartSummonToggleCooldown(player);
                ShowMessage(player, "Summon Beasts: mascotas guardadas.");
                return;
            }

            if (_summonDeathCooldown > 0f)
            {
                ShowMessage(player, string.Format("Summon Beasts: {0:0}s cooldown por mascota muerta.", _summonDeathCooldown));
                return;
            }

            ItemDrop.ItemData weapon = player.GetCurrentWeapon();

            List<SummonSpawnPlan> spawnPlans = BuildSummonSpawnPlans();
            if (spawnPlans.Count == 0)
            {
                ShowMessage(player, "Summon Beasts: prefab de mascota no disponible.");
                return;
            }

            float staminaUse = Mathf.Max(0f, EpicLootRaritySetsPlugin.HraesvelgrSummonStaminaUse.Value);
            if (!TrySpendStamina(player, staminaUse))
            {
                ShowMessage(player, "Summon Beasts: no tienes vigor suficiente.");
                return;
            }

            DestroySummonedBeasts(false);

            int spawned = 0;
            for (int i = 0; i < spawnPlans.Count; i++)
            {
                SummonSpawnPlan plan = spawnPlans[i];
                if (SpawnSummonedBeast(player, plan.Prefab, plan.Definition.Kind, GetSummonOffset(player, i, spawnPlans.Count)) != null)
                {
                    spawned++;
                }
            }

            if (spawned <= 0)
            {
                ShowMessage(player, "Summon Beasts: no se pudo invocar la mascota.");
                return;
            }

            AddSummonBuff(player, GetWeaponIcon(weapon) ?? FindHraesvelgrIcon(player) ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            StartSummonToggleCooldown(player);
            ShowMessage(player, string.Format("Summon Beasts: {0} invocada.", GetCurrentSummonedBeastDefinition().DisplayName));
        }

        private static void StartSummonToggleCooldown(Player player)
        {
            _summonToggleCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HraesvelgrSummonCooldown.Value);
            if (player != null && _summonToggleCooldown > 0f)
            {
                AbilityCooldownBuffController.Start(player, "HraesvelgrSummonBeastsToggle", "Summon Beasts", _summonToggleCooldown, FindHraesvelgrIcon(player));
            }
        }

        private static void TryTameBeast(Player player)
        {
            Character target = FindTameBeastTarget(player, TameBeastRange);
            if (target == null)
            {
                ShowMessage(player, "Domar bestia: apunta a una bestia valida a 10m.");
                return;
            }

            SummonedBeastDefinition definition;
            if (!TryCreateTameDefinition(target, out definition))
            {
                ShowMessage(player, "Domar bestia: esa criatura no es una bestia valida.");
                return;
            }

            GameObject prefab = GetPrefab(definition.PrefabNames);
            if (prefab == null)
            {
                ShowMessage(player, string.Format("Domar bestia: prefab no disponible ({0}).", definition.PrimaryPrefabName));
                return;
            }

            Vector3 spawnPoint = target.transform.position;
            Quaternion rotation = target.transform.rotation;
            string petName = GetCreatureDisplayName(target, definition.PrimaryPrefabName, definition.Kind);
            bool hasSaddle = HasSaddle(target.gameObject);

            DestroySummonedBeasts(false);
            StoredSummonNames.Clear();
            StoredSummonSaddles.Clear();
            StoredSummonNames[definition.Kind] = petName;
            StoredSummonSaddles[definition.Kind] = hasSaddle;
            SaveTamedBeast(definition, hasSaddle);
            DestroyWildBeast(target.gameObject);

            GameObject beast = SpawnSummonedBeastAt(player, prefab, definition.Kind, spawnPoint, rotation);
            if (beast == null)
            {
                ShowMessage(player, "Domar bestia: no se pudo crear la mascota.");
                return;
            }

            SetTameableName(beast, petName);
            AddSummonBuff(player, FindHraesvelgrIcon(player) ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, string.Format("Domar bestia: {0} ahora es tu mascota.", petName));
        }

        private static List<SummonSpawnPlan> BuildSummonSpawnPlans()
        {
            List<SummonSpawnPlan> result = new List<SummonSpawnPlan>();
            List<SummonedBeastDefinition> roster = GetSummonRoster();
            foreach (SummonedBeastDefinition definition in roster)
            {
                GameObject prefab = GetPrefab(definition.PrefabNames);
                if (prefab != null)
                {
                    result.Add(new SummonSpawnPlan(definition, prefab));
                }
            }

            return result;
        }

        private static List<SummonedBeastDefinition> GetSummonRoster()
        {
            return new List<SummonedBeastDefinition> { GetCurrentSummonedBeastDefinition() };
        }

        private static SummonedBeastDefinition GetCurrentSummonedBeastDefinition()
        {
            SummonedBeastDefinition definition;
            if (EpicLootRaritySetsPlugin.HraesvelgrTamedPetPrefab != null &&
                TryCreateTameDefinition(EpicLootRaritySetsPlugin.HraesvelgrTamedPetPrefab.Value, out definition))
            {
                return definition;
            }

            return CreateDefaultSummonDefinition();
        }

        private static SummonedBeastDefinition CreateDefaultSummonDefinition()
        {
            return new SummonedBeastDefinition("Bear", "Bjorn", "Bjorn", BuildPrefabNameList("Bjorn", "bjorn"));
        }

        private static Vector3 GetSummonOffset(Player player, int index, int count)
        {
            if (player == null)
            {
                return Vector3.forward * 2f;
            }

            if (count <= 1)
            {
                return player.transform.forward * 2f + player.transform.right * 1.1f;
            }

            float angle = -35f + 70f * (float)index / Mathf.Max(1, count - 1);
            return Quaternion.AngleAxis(angle, Vector3.up) * player.transform.forward * 2.25f;
        }

        private static void AddSummonBuff(Player player, Sprite icon)
        {
            if (player == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateSummonBuff(icon ?? FindHraesvelgrIcon(player) ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            if (buff == null)
            {
                return;
            }

            SEMan seMan = player.GetSEMan();
            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, 1, 0f, 0);
        }

        private static void SaveTamedBeast(SummonedBeastDefinition definition, bool hasSaddle = false)
        {
            if (definition == null || EpicLootRaritySetsPlugin.HraesvelgrTamedPetPrefab == null)
            {
                return;
            }

            EpicLootRaritySetsPlugin.HraesvelgrTamedPetPrefab.Value = definition.PrimaryPrefabName;
            SaveTamedBeastSaddleState(hasSaddle, false);
            SavePluginConfig();
        }

        private static void SaveTamedBeastSaddleState(bool hasSaddle, bool saveNow = true)
        {
            if (EpicLootRaritySetsPlugin.HraesvelgrTamedPetHasSaddle == null)
            {
                return;
            }

            EpicLootRaritySetsPlugin.HraesvelgrTamedPetHasSaddle.Value = hasSaddle;
            if (saveNow)
            {
                SavePluginConfig();
            }
        }

        private static void SavePluginConfig()
        {
            try
            {
                EpicLootRaritySetsPlugin.PluginConfig.Save();
            }
            catch
            {
            }
        }

        private static Character FindTameBeastTarget(Player player, float range)
        {
            if (player == null)
            {
                return null;
            }

            range = Mathf.Max(1f, range);
            float maxDistanceSqr = range * range;
            Transform originTransform = GameCamera.instance != null ? GameCamera.instance.transform : player.transform;
            RaycastHit[] hits = Physics.SphereCastAll(originTransform.position, 0.8f, originTransform.forward, range + 2f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            if (hits != null)
            {
                foreach (RaycastHit hit in hits.OrderBy(hit => hit.distance))
                {
                    Character character = GetCharacterFromCollider(hit.collider);
                    if (IsValidTameTarget(player, character, maxDistanceSqr))
                    {
                        return character;
                    }
                }
            }

            Collider[] colliders = Physics.OverlapSphere(player.GetCenterPoint(), range, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            Character best = null;
            float bestScore = float.MinValue;
            HashSet<Character> seen = new HashSet<Character>();
            foreach (Collider collider in colliders)
            {
                Character character = GetCharacterFromCollider(collider);
                if (character == null || !seen.Add(character) || !IsValidTameTarget(player, character, maxDistanceSqr))
                {
                    continue;
                }

                Vector3 toTarget = character.GetCenterPoint() - originTransform.position;
                float distance = Mathf.Max(0.1f, toTarget.magnitude);
                float facing = Vector3.Dot(originTransform.forward, toTarget.normalized);
                if (facing < 0.58f)
                {
                    continue;
                }

                float score = facing * 10f - distance;
                if (score > bestScore)
                {
                    bestScore = score;
                    best = character;
                }
            }

            return best;
        }

        private static bool IsValidTameTarget(Player player, Character target, float maxDistanceSqr)
        {
            if (player == null || target == null || target == player || target is Player || target.IsDead() || target.IsTamed() || IsSummonedBeast(target))
            {
                return false;
            }

            if ((target.transform.position - player.transform.position).sqrMagnitude > maxDistanceSqr)
            {
                return false;
            }

            SummonedBeastDefinition definition;
            return TryCreateTameDefinition(target, out definition);
        }

        private static Character GetCharacterFromCollider(Collider collider)
        {
            return collider != null ? collider.GetComponentInParent<Character>() : null;
        }

        private static bool TryCreateTameDefinition(Character target, out SummonedBeastDefinition definition)
        {
            definition = null;
            if (target == null)
            {
                return false;
            }

            string prefabName = GetPrefabishName(target.gameObject);
            string search = prefabName + " " + (target.m_name ?? string.Empty) + " " + GetTameableName(target.gameObject);
            string token;
            if (!TryGetTameableBeastToken(search, out token))
            {
                return false;
            }

            definition = new SummonedBeastDefinition(
                GetBeastKind(token),
                prefabName,
                GetCreatureDisplayName(target, prefabName, token),
                BuildPrefabNameList(prefabName, token));
            return true;
        }

        private static bool TryCreateTameDefinition(string prefabName, out SummonedBeastDefinition definition)
        {
            definition = null;
            if (string.IsNullOrEmpty(prefabName))
            {
                return false;
            }

            string token;
            if (!TryGetTameableBeastToken(prefabName, out token))
            {
                return false;
            }

            definition = new SummonedBeastDefinition(
                GetBeastKind(token),
                prefabName,
                HumanizeCreatureName(prefabName),
                BuildPrefabNameList(prefabName, token));
            return true;
        }

        private static bool TryGetTameableBeastToken(string value, out string token)
        {
            token = null;
            string normalized = NormalizeBeastName(value);
            if (string.IsNullOrEmpty(normalized))
            {
                return false;
            }

            foreach (string candidate in TameableBeastTokens)
            {
                if (normalized.Contains(NormalizeBeastName(candidate)))
                {
                    token = candidate;
                    return true;
                }
            }

            if (normalized.Contains("bear") || normalized.Contains("blackbear") || normalized.Contains("grizzly"))
            {
                token = "bjorn";
                return true;
            }

            if (normalized.Contains("vulture"))
            {
                token = "volture";
                return true;
            }

            return false;
        }

        private static string GetBeastKind(string token)
        {
            if (string.Equals(token, "bjorn", StringComparison.OrdinalIgnoreCase))
            {
                return "Bear";
            }

            if (string.Equals(token, "volture", StringComparison.OrdinalIgnoreCase))
            {
                return "Volture";
            }

            return token;
        }

        private static string[] BuildPrefabNameList(string primaryPrefabName, string token)
        {
            List<string> names = new List<string>();
            AddUniqueName(names, primaryPrefabName);
            AddUniqueName(names, token);

            string[] fallbackNames;
            if (!string.IsNullOrEmpty(token) && TameableBeastPrefabFallbacks.TryGetValue(token, out fallbackNames))
            {
                foreach (string fallback in fallbackNames)
                {
                    AddUniqueName(names, fallback);
                }
            }

            return names.ToArray();
        }

        private static void AddUniqueName(List<string> names, string name)
        {
            if (names == null || string.IsNullOrEmpty(name))
            {
                return;
            }

            foreach (string existing in names)
            {
                if (string.Equals(existing, name, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }
            }

            names.Add(name);
        }

        private static string GetCreatureDisplayName(Character target, string prefabName, string token)
        {
            string name = target != null ? GetTameableName(target.gameObject) : null;
            if (!string.IsNullOrEmpty(name) && !name.StartsWith("$", StringComparison.Ordinal))
            {
                return name;
            }

            return HumanizeCreatureName(!string.IsNullOrEmpty(prefabName) ? prefabName : token);
        }

        private static string HumanizeCreatureName(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return "Bestia";
            }

            string cleaned = value.Replace("(Clone)", string.Empty).Replace("_", " ").Replace("-", " ").Trim();
            if (cleaned.StartsWith("$", StringComparison.Ordinal) && cleaned.LastIndexOf('_') >= 0)
            {
                cleaned = cleaned.Substring(cleaned.LastIndexOf('_') + 1);
            }

            if (string.IsNullOrEmpty(cleaned))
            {
                return "Bestia";
            }

            return CultureInfo.InvariantCulture.TextInfo.ToTitleCase(cleaned.ToLowerInvariant());
        }

        private static string NormalizeBeastName(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return string.Empty;
            }

            StringBuilder builder = new StringBuilder(value.Length);
            foreach (char c in value)
            {
                if (char.IsLetterOrDigit(c))
                {
                    builder.Append(char.ToLowerInvariant(c));
                }
            }

            return builder.ToString();
        }

        private static void DestroyWildBeast(GameObject beast)
        {
            if (beast == null)
            {
                return;
            }

            if (ZNetScene.instance != null)
            {
                ZNetScene.instance.Destroy(beast);
            }
            else
            {
                UnityEngine.Object.Destroy(beast);
            }
        }

