                EpicLootRaritySetsPlugin.HraesvelgrVolleyDamageMultiplier.Value,
                GetRapidVolleyMaxShots(),
                Mathf.Clamp(_volleyShotsFired, 0, GetRapidVolleyMaxShots()));
