            StatusEffectIconHelper.Apply(_trapRootBuff, Player.m_localPlayer, RequiredSet);
            SetFloatField(_trapRootBuff, SpeedModifierField, -1f);
            return _trapRootBuff;
        }

        private static GameObject SpawnSummonedBeast(Player player, GameObject prefab, string kind, Vector3 offset)
        {
            if (player == null || prefab == null)
            {
                return null;
            }

            Vector3 spawnPoint = player.transform.position + offset;
            Quaternion rotation = Quaternion.LookRotation(player.transform.forward);
            return SpawnSummonedBeastAt(player, prefab, kind, spawnPoint, rotation);
        }

        private static GameObject SpawnSummonedBeastAt(Player player, GameObject prefab, string kind, Vector3 spawnPoint, Quaternion rotation)
        {
            if (player == null || prefab == null)
            {
                return null;
            }

            GameObject beast = UnityEngine.Object.Instantiate(prefab, spawnPoint, rotation);
            if (beast == null)
            {
                return null;
            }

            SetupSummonedBeast(player, beast);
            ApplySummonedBeastScaling(player, beast, kind);
            ApplyStoredSummonName(kind, beast);
            ApplyStoredSummonSaddle(kind, beast);
            SummonedBeasts.Add(beast);
            SummonedBeastKinds[beast.GetInstanceID()] = kind;
            return beast;
        }

        private static void ApplySummonedBeastScaling(Player player, GameObject beast, string kind)
        {
            float skill = ClassSkillManager.GetSkillLevel(player, RequiredSet);
            ClassPetScalingController.Register(
                beast,
                GetSummonedBeastMaxHealth(kind, skill),
                GetSummonedBeastDamageMultiplier(kind, skill),
                GetSummonedBeastDamageTakenReduction(kind, skill));
        }

        private static float GetSummonedBeastMaxHealth(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            return 110f + skill * 1.6f;
        }

        private static float GetSummonedBeastDamageMultiplier(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            return 0.45f + skill * 0.004f;
        }

        private static float GetSummonedBeastDamageTakenReduction(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            return Mathf.Min(0.20f, skill * 0.0015f);
        }

        private static void MatchSummonedBeastHealth(GameObject target, GameObject source)
        {
            float sourceHealth = GetCharacterMaxHealth(source);
            if (sourceHealth <= 0f)
            {
                return;
            }

            SetCharacterMaxHealth(target, sourceHealth);
        }

        private static float GetCharacterMaxHealth(GameObject gameObject)
        {
            Character character = gameObject != null ? gameObject.GetComponent<Character>() ?? gameObject.GetComponentInChildren<Character>() : null;
            if (character == null)
            {
                return 0f;
            }

            try
            {
                float health = character.GetMaxHealth();
                if (health > 0f)
                {
                    return health;
                }
            }
            catch
            {
            }

            foreach (FieldInfo field in new[] { CharacterBaseHpField, CharacterHealthField })
            {
                if (field == null)
                {
                    continue;
                }

                try
                {
                    object value = field.GetValue(character);
                    if (value is float && (float)value > 0f)
                    {
                        return (float)value;
                    }
                }
                catch
                {
                }
            }

            return 0f;
        }

        private static void SetCharacterMaxHealth(GameObject gameObject, float health)
        {
            Character character = gameObject != null ? gameObject.GetComponent<Character>() ?? gameObject.GetComponentInChildren<Character>() : null;
            if (character == null || health <= 0f)
            {
                return;
            }

            SetFloatField(character, CharacterBaseHpField, health);
            TryInvoke(CharacterSetMaxHealthMethod, character, new object[] { health });
            TryInvoke(CharacterSetHealthMethod, character, new object[] { health });
            SetFloatField(character, CharacterHealthField, health);
        }

        private static void SetupSummonedBeast(Player player, GameObject beast)
        {
            Character character = beast != null ? beast.GetComponent<Character>() : null;
            if (character != null)
            {
                character.SetTamed(true);
            }

            Tameable tameable = GetTameable(beast);
            if (tameable == null)
            {
                tameable = beast.AddComponent<Tameable>();
            }

            if (tameable != null)
            {
                tameable.m_commandable = true;
                tameable.m_startsTamed = true;
                tameable.m_fedDuration = Mathf.Max(tameable.m_fedDuration, 3600f);
                tameable.m_unsummonDistance = Mathf.Max(tameable.m_unsummonDistance, 65f);
                tameable.m_unsummonOnOwnerLogoutSeconds = Mathf.Max(tameable.m_unsummonOnOwnerLogoutSeconds, 5f);
                if (TameMethod != null)
                {
                    TryInvoke(TameMethod, tameable, null);
                }
            }

            MonsterAI monsterAI = beast.GetComponent<MonsterAI>();
            if (monsterAI != null)
            {
                monsterAI.MakeTame();
                monsterAI.SetFollowTarget(player.gameObject);
            }

            ZNetView zNetView = beast.GetComponent<ZNetView>();
            ZDO zdo = zNetView != null ? zNetView.GetZDO() : null;
            if (zdo != null)
            {
                zdo.Persistent = false;
            }
        }

        private static void UpdateSummonedBeasts(float dt)
        {
            if (SummonedBeasts.Count == 0)
            {
                RemoveSummonBuff(Player.m_localPlayer);
                return;
            }

            Player owner = Player.m_localPlayer;
            for (int i = SummonedBeasts.Count - 1; i >= 0; i--)
            {
                GameObject beast = SummonedBeasts[i];
                if (beast == null)
                {
                    SummonedBeasts.RemoveAt(i);
                    continue;
                }

                Character character = beast.GetComponent<Character>();
                if (character != null && character.IsDead())
                {
                    ClassPetScalingController.Unregister(beast);
                    ForgetSummonName(beast);
                    SummonedBeastKinds.Remove(beast.GetInstanceID());
                    SummonedBeasts.RemoveAt(i);
                    StartSummonDeathCooldown(owner);
                    continue;
                }

                if (owner != null)
                {
                    if (PetCommandController.ApplyToPet(owner, beast, target => IsEnemyTarget(owner, target)))
                    {
                        continue;
                    }

                    RefreshSummonedBeastCombat(owner, beast);
                }
            }

            if (SummonedBeasts.Count == 0)
            {
                RemoveSummonBuff(Player.m_localPlayer);
            }
        }

        private static void RefreshSummonedBeastFollow(Player owner, GameObject beast)
        {
            if (owner == null || beast == null)
            {
                return;
            }

            MonsterAI monsterAI = beast.GetComponent<MonsterAI>();
            if (monsterAI != null)
            {
                monsterAI.MakeTame();
                monsterAI.SetFollowTarget(owner.gameObject);
            }
        }

        private static void RefreshSummonedBeastCombat(Player owner, GameObject beast)
        {
            if (owner == null || beast == null)
            {
                return;
            }

            Character target = FindSummonDefenseTarget(owner);
            if (target == null)
            {
                return;
            }

            BaseAI baseAI = beast.GetComponent<BaseAI>() ?? beast.GetComponentInChildren<BaseAI>();
            if (baseAI != null)
            {
                AssignAITarget(baseAI, target);
            }
        }

        private static Character FindSummonDefenseTarget(Player owner)
        {
            if (owner == null)
            {
                return null;
            }

            float radius = Mathf.Max(5f, EpicLootRaritySetsPlugin.HraesvelgrSummonGuardRadius.Value);
            float bestScore = radius * radius;
            Character best = null;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character == owner || character.IsDead() || !IsEnemyTarget(owner, character))
                {
                    continue;
                }

                float distanceToOwner = (character.transform.position - owner.transform.position).sqrMagnitude;
                if (distanceToOwner > radius * radius)
                {
                    continue;
                }

                float distanceToBeasts = GetClosestSummonDistanceSqr(character.transform.position);
                float score = Mathf.Min(distanceToOwner, distanceToBeasts);
                if (score >= bestScore)
                {
                    continue;
                }

                bestScore = score;
                best = character;
            }

            return best;
        }

        private static float GetClosestSummonDistanceSqr(Vector3 point)
        {
            float best = float.MaxValue;
            foreach (GameObject beast in SummonedBeasts)
            {
                if (beast == null)
                {
                    continue;
                }

                float distance = (beast.transform.position - point).sqrMagnitude;
                if (distance < best)
                {
                    best = distance;
                }
            }

            return best;
        }

        private static bool IsEnemyTarget(Player player, Character target)
        {
            if (player == null || target == null || target == player)
            {
                return false;
            }

            if (CharacterTargeting.IsPlayerPvPEnemy(player, target))
            {
                return true;
            }

            if (target is Player)
            {
                return false;
            }

            if (BaseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = BaseAIIsEnemyMethod.Invoke(null, new object[] { player, target });
                    if (value is bool && (bool)value)
                    {
                        return true;
                    }
                }
                catch
                {
                }
            }

            return IsValidSummonEnemy(target);
        }

        internal static bool IsSummonedBeast(Character character)
        {
            if (character == null)
            {
                return false;
            }

            foreach (GameObject beast in SummonedBeasts)
            {
                if (beast == null)
                {
                    continue;
                }

                Character beastCharacter = beast.GetComponent<Character>();
                if (beastCharacter == character)
                {
                    return true;
                }
            }

            return false;
        }

        internal static int GetActivePetCount()
        {
            int count = 0;
            for (int i = SummonedBeasts.Count - 1; i >= 0; i--)
            {
                GameObject beast = SummonedBeasts[i];
                if (beast == null)
                {
                    SummonedBeasts.RemoveAt(i);
                    continue;
                }

                Character character = beast.GetComponent<Character>() ?? beast.GetComponentInChildren<Character>();
                if (character == null || character.IsDead())
                {
                    continue;
                }

                count++;
            }

            return count;
        }

        internal static void ReleasePetFollow(Player owner)
        {
            foreach (GameObject beast in SummonedBeasts)
            {
                PetCommandController.ReleasePetFollow(beast);
            }
        }

        private static bool IsWildSameKindAsSummon(Character target)
        {
            if (target == null || target is Player || target.IsTamed())
            {
                return false;
            }

            string prefabName = GetPrefabishName(target.gameObject);
            foreach (string kind in SummonedBeastKinds.Values)
            {
                if (IsSameBeastKind(prefabName, kind))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsValidSummonEnemy(Character target)
        {
            return target != null &&
                   !(target is Player) &&
                   !target.IsDead() &&
                   !target.IsTamed() &&
                   !IsSummonedBeast(target);
        }

        private static bool IsSameBeastKind(string prefabName, string kind)
        {
            if (string.IsNullOrEmpty(prefabName) || string.IsNullOrEmpty(kind))
            {
                return false;
            }

            if (string.Equals(kind, "Volture", StringComparison.OrdinalIgnoreCase))
            {
                return prefabName.IndexOf("Volture", StringComparison.OrdinalIgnoreCase) >= 0 ||
                       prefabName.IndexOf("Vulture", StringComparison.OrdinalIgnoreCase) >= 0;
            }

            if (string.Equals(kind, "Bear", StringComparison.OrdinalIgnoreCase))
            {
                return prefabName.IndexOf("Bjorn", StringComparison.OrdinalIgnoreCase) >= 0 ||
                       prefabName.IndexOf("Bear", StringComparison.OrdinalIgnoreCase) >= 0;
            }

            string normalizedPrefab = NormalizeBeastName(prefabName);
            string normalizedKind = NormalizeBeastName(kind);
            return !string.IsNullOrEmpty(normalizedPrefab) &&
                   !string.IsNullOrEmpty(normalizedKind) &&
                   (normalizedPrefab.Contains(normalizedKind) || normalizedKind.Contains(normalizedPrefab));
        }

        private static string GetPrefabishName(GameObject gameObject)
        {
            if (gameObject == null)
            {
                return string.Empty;
            }

            string name = gameObject.name ?? string.Empty;
            return name.Replace("(Clone)", string.Empty).Trim();
        }

        private static void AssignAITarget(BaseAI baseAI, Character target)
        {
            if (baseAI == null || target == null)
            {
                return;
            }

            bool assigned = TryInvokeSetTarget(baseAI, target);
            if (!assigned)
            {
                SetTargetCreatureField(baseAI, target);
            }

            if (BaseAITargetStaticField != null)
            {
                try
                {
                    BaseAITargetStaticField.SetValue(baseAI, null);
                }
                catch
                {
                }
            }

            SetAIAlerted(baseAI, true);
        }

        private static bool TryInvokeSetTarget(BaseAI baseAI, Character target)
        {
            foreach (MethodInfo method in new[] { MonsterAISetTargetMethod, BaseAISetTargetMethod })
            {
                if (method == null || !method.DeclaringType.IsInstanceOfType(baseAI))
                {
                    continue;
                }

                try
                {
                    method.Invoke(baseAI, new object[] { target });
                    return true;
                }
                catch
                {
                }
            }

            return false;
        }

