        internal static void Update(Player player, float dt)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            RegisterRpcs();
            _holyHealCooldown = Mathf.Max(0f, _holyHealCooldown - dt);
            _holyStrikeCooldown = Mathf.Max(0f, _holyStrikeCooldown - dt);
            _bloodRiteCooldown = Mathf.Max(0f, _bloodRiteCooldown - dt);
            _undeadSummonCooldown = Mathf.Max(0f, _undeadSummonCooldown - dt);
            _bodyguardRespawnCooldown = Mathf.Max(0f, _bodyguardRespawnCooldown - dt);
            _bodyguardCombatRefreshTimer = Mathf.Max(0f, _bodyguardCombatRefreshTimer - dt);

            if (!IsHelveigEnabledAndActive())
            {
                UpdateHealingShields(dt);
                if (_wasActive || _bloodRiteActive || _undeadSummonActive || _undeadSummon != null || Bodyguards.Count > 0 || _healingPowerStacks > 0)
                {
                    Clear(player, false);
                }
                return;
            }

            _wasActive = true;
            UpdateBloodRite(player, dt);
            UpdateUndeadSummon(player, dt);
            UpdateBodyguards(player, dt);
            UpdateHealingShields(dt);
            UpdateHealingPower(player, dt);

            if (!CanReadAbilityInput(player))
            {
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.HelveigBloodRiteHotkey))
            {
                TryBloodRite(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.HelveigSummonUndeadHotkey) &&
                SetAbilityInput.IsBlockHeld())
            {
                TrySummonUndead(player);
                return;
            }

            if (SetAbilityInput.IsSecondaryAttackDown() ||
                IsShortcutDown(EpicLootRaritySetsPlugin.HelveigHolyStrikeHotkey))
            {
                TryHolyStrike(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.HelveigHolyHealHotkey))
            {
                TryHolyHeal(player);
            }
        }

        internal static void Clear(Player player)
        {
            Clear(player, true);
        }

        private static void Clear(Player player, bool clearHealingShields)
        {
            _bloodRiteActive = false;
            _bloodRiteDuration = 0f;
            _bloodRiteRemaining = 0f;
            _bloodRiteTickTimer = 0f;
            _bloodRiteVisualPulseTimer = 0f;
            RemoveBloodRiteBuff(player);
            DestroyBloodRiteChannelVisual();
            DestroyBloodRiteChannelBar();
            DestroyUndeadSummon(player);
            DestroyBodyguards(player, true);
            if (clearHealingShields)
            {
                ClearHealingShields();
            }
            _healingPowerStacks = 0;
            _healingPowerRemaining = 0f;
            RemoveHealingPowerBuff(player);
            _bodyguardRespawnCooldown = 0f;
            _bodyguardCombatRefreshTimer = 0f;
            _wasActive = false;
        }

        private static void TryHolyHeal(Player player)
        {
            if (!TrySpendEitrAndCooldown(player, "Holy Heal", EpicLootRaritySetsPlugin.HelveigHolyHealEitrUse.Value, _holyHealCooldown))
            {
                return;
            }

            float healing = GetScaledHealing(player, EpicLootRaritySetsPlugin.HelveigHolyHealBaseHealing.Value, EpicLootRaritySetsPlugin.HelveigHolyHealHealingPerBloodMagicLevel.Value);
            Character target;
            if (!TryFindHolyHealTarget(player, EpicLootRaritySetsPlugin.HelveigHolyStrikeRange.Value, out target))
            {
                target = player;
            }

            player.UseEitr(EpicLootRaritySetsPlugin.HelveigHolyHealEitrUse.Value);
            float actualHealing = HealAndApplyPassives(player, target, healing);
            SpawnHolyHealVisual(target);
            _holyHealCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigHolyHealCooldown.Value);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            AbilityCooldownBuffController.Start(player, "HelveigHolyHeal", "Holy Heal", _holyHealCooldown, null);
            ShowMessage(player, target == player
                ? string.Format("Holy Heal: +{0:0} vida.", actualHealing)
                : string.Format("Holy Heal: aliado +{0:0} vida.", actualHealing));
        }

        private static void TryHolyStrike(Player player)
        {
            if (!TrySpendEitrAndCooldown(player, "Holy Strike", EpicLootRaritySetsPlugin.HelveigHolyStrikeEitrUse.Value, _holyStrikeCooldown))
            {
                return;
            }

            Character target;
            if (!TryFindHolyStrikeTarget(player, EpicLootRaritySetsPlugin.HelveigHolyStrikeRange.Value, out target))
            {
                ShowMessage(player, "Holy Strike: no hay objetivo.");
                return;
            }

            player.UseEitr(EpicLootRaritySetsPlugin.HelveigHolyStrikeEitrUse.Value);
            HitData hit = CreateHolyStrikeHit(player, player.GetCurrentWeapon(), target);
            target.Damage(hit);
            RestoreHolyStrikeEitr(player);
            SpawnHolyStrikeVisual(player, target);
            _holyStrikeCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigHolyStrikeCooldown.Value);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            AbilityCooldownBuffController.Start(player, "HelveigHolyStrike", "Holy Strike", _holyStrikeCooldown, null);
            ShowMessage(player, "Holy Strike.");
        }

        private static void TryBloodRite(Player player)
        {
            if (_bloodRiteActive)
            {
                ShowMessage(player, "Blood Rite: canalizando.");
                return;
            }

            if (!TrySpendEitrAndCooldown(player, "Blood Rite", EpicLootRaritySetsPlugin.HelveigBloodRiteEitrUse.Value, _bloodRiteCooldown))
            {
                return;
            }

            player.UseEitr(EpicLootRaritySetsPlugin.HelveigBloodRiteEitrUse.Value);
            _bloodRiteDuration = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HelveigBloodRiteDuration.Value);
            _bloodRiteRemaining = _bloodRiteDuration;
            _bloodRiteTickTimer = 0f;
            _bloodRiteVisualPulseTimer = 0f;
            _bloodRiteOrigin = player.transform.position;
            _bloodRiteActive = true;
            EnsureBloodRiteChannelVisual(player);
            UpdateBloodRiteChannelBar(player);
            RefreshBloodRiteBuff(player);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, "Blood Rite: canalizando curacion.");
        }

        private static void UpdateBloodRite(Player player, float dt)
        {
            if (!_bloodRiteActive)
            {
                return;
            }

            if (player.IsDead())
            {
                CancelBloodRite(player, false);
                return;
            }

            float cancelDistance = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigBloodRiteCancelMoveDistance.Value);
            if (cancelDistance > 0f && (player.transform.position - _bloodRiteOrigin).sqrMagnitude > cancelDistance * cancelDistance)
            {
                CancelBloodRite(player, true);
                return;
            }

            player.StopMovement();
            _bloodRiteRemaining -= dt;
            UpdateBloodRiteChannelEffects(player, dt);
            _bloodRiteTickTimer -= dt;
            if (_bloodRiteTickTimer <= 0f)
            {
                _bloodRiteTickTimer = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HelveigBloodRiteTickInterval.Value);
                HealAlliesInBloodRite(player);
                RefreshBloodRiteBuff(player);
            }

            if (_bloodRiteRemaining <= 0f)
            {
                _bloodRiteActive = false;
                StartBloodRiteCooldown(player);
                RemoveBloodRiteBuff(player);
                DestroyBloodRiteChannelVisual();
                DestroyBloodRiteChannelBar();
                ShowMessage(player, "Blood Rite: completado.");
            }
        }

        private static void CancelBloodRite(Player player, bool showMessage)
        {
            _bloodRiteActive = false;
            _bloodRiteDuration = 0f;
            _bloodRiteRemaining = 0f;
            _bloodRiteTickTimer = 0f;
            _bloodRiteVisualPulseTimer = 0f;
            StartBloodRiteCooldown(player);
            RemoveBloodRiteBuff(player);
            DestroyBloodRiteChannelVisual();
            DestroyBloodRiteChannelBar();
            if (showMessage)
            {
                ShowMessage(player, "Blood Rite: cancelado al moverte.");
            }
        }

        private static void StartBloodRiteCooldown(Player player)
        {
            _bloodRiteCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigBloodRiteCooldown.Value);
            AbilityCooldownBuffController.Start(player, "HelveigBloodRite", "Blood Rite", _bloodRiteCooldown, null);
        }

        private static void TrySummonUndead(Player player)
        {
            if (_undeadSummonActive && !HasLivingUndeadSummon())
            {
                StartUndeadSummonCooldown(player);
                DestroyUndeadSummon(player);
            }

            if (HasLivingUndeadSummon())
            {
                ShowMessage(player, "Summon Monster: ya tienes una invocacion activa.");
                return;
            }

            if (!TrySpendEitrAndCooldown(player, "Summon Monster", EpicLootRaritySetsPlugin.HelveigSummonUndeadEitrUse.Value, _undeadSummonCooldown))
            {
                return;
            }

            float skillLevel = ClassSkillManager.GetSkillLevel(player, "Helveig");
            GameObject prefab = GetUndeadSummonPrefab(skillLevel, out _undeadSummonKind, out _undeadSummonDisplayName);
            if (prefab == null)
            {
                ShowMessage(player, "Summon Monster: prefab no disponible.");
                EpicLootRaritySetsPlugin.Log.LogWarning("Helveig Summon Monster could not resolve a prefab for Helveig level " + skillLevel.ToString("0.#") + ".");
                return;
            }

            Vector3 forward = Vector3.ProjectOnPlane(player.transform.forward, Vector3.up);
            if (forward.sqrMagnitude <= 0.001f)
            {
                forward = Vector3.forward;
            }

            forward.Normalize();
            Vector3 spawn = player.transform.position + forward * 2.2f + player.transform.right * 0.6f;
            TryProjectGround(spawn, out spawn);
            DestroyUndeadSummon(player);
            _undeadSummon = UnityEngine.Object.Instantiate(prefab, spawn, Quaternion.LookRotation(forward));
            if (_undeadSummon == null)
            {
                ShowMessage(player, "Summon Monster: fallo al invocar.");
                return;
            }

            SetupUndeadSummon(player, _undeadSummon);
            ApplyActiveSummonScaling(player, _undeadSummon, _undeadSummonKind);
            player.UseEitr(EpicLootRaritySetsPlugin.HelveigSummonUndeadEitrUse.Value);
            _undeadSummonRemaining = Mathf.Max(1f, EpicLootRaritySetsPlugin.HelveigSummonUndeadDuration.Value);
            _undeadSummonActive = true;
            RefreshUndeadSummonBuff(player);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            NorseVisualEffectBridge.Spawn(spawn, Quaternion.identity, "fx_DvergerMage_Support", "sfx_seekerqueen_callout", "vfx_StaffSkeleton", "Spirit");
            ShowMessage(player, "Summon Monster: " + _undeadSummonDisplayName + ".");
        }

        private static void UpdateUndeadSummon(Player player, float dt)
        {
            if (_undeadSummon == null)
            {
                StartUndeadSummonCooldown(player);
                _undeadSummonActive = false;
                RemoveUndeadSummonBuff(player);
                _undeadSummonRemaining = 0f;
                _undeadSummonKind = SummonEntKind;
                _undeadSummonDisplayName = "Ent";
                return;
            }

            Character character = _undeadSummon.GetComponent<Character>() ?? _undeadSummon.GetComponentInChildren<Character>();
            if (character == null || character.IsDead())
            {
                StartUndeadSummonCooldown(player);
                ClassPetScalingController.Unregister(_undeadSummon);
                _undeadSummon = null;
                _undeadSummonActive = false;
                _undeadSummonRemaining = 0f;
                _undeadSummonKind = SummonEntKind;
                _undeadSummonDisplayName = "Ent";
                RemoveUndeadSummonBuff(player);
                return;
            }

            _undeadSummonRemaining -= dt;
            if (_undeadSummonRemaining <= 0f)
            {
                StartUndeadSummonCooldown(player);
                DestroyUndeadSummon(player);
                return;
            }

            MonsterAI monsterAI = _undeadSummon.GetComponent<MonsterAI>();
            if (monsterAI != null)
            {
                monsterAI.MakeTame();
            }

            if (PetCommandController.ApplyToPet(player, _undeadSummon, target => IsEnemyTarget(player, target)))
            {
                RefreshUndeadSummonBuff(player);
                return;
            }

            RefreshUndeadSummonCombat(player);

            RefreshUndeadSummonBuff(player);
        }

        private static bool HasLivingUndeadSummon()
        {
            if (_undeadSummon == null)
            {
                return false;
            }

            Character character = _undeadSummon.GetComponent<Character>() ?? _undeadSummon.GetComponentInChildren<Character>();
            return character != null && !character.IsDead();
        }

        private static void StartUndeadSummonCooldown(Player player)
        {
            if (!_undeadSummonActive)
            {
                return;
            }

            _undeadSummonCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigSummonUndeadCooldown.Value);
            AbilityCooldownBuffController.Start(player, "HelveigSummonUndead", "Summon Monster", _undeadSummonCooldown, null);
        }

        private static GameObject GetUndeadSummonPrefab(float skillLevel, out string kind, out string displayName)
        {
            string[] fallbackOrder = GetActiveSummonFallbackOrder(skillLevel);
            foreach (string candidateKind in fallbackOrder)
            {
                GameObject prefab = GetActiveSummonPrefab(candidateKind);
                if (prefab == null)
                {
                    continue;
                }

                kind = candidateKind;
                displayName = GetActiveSummonDisplayName(candidateKind);
                return prefab;
            }

            kind = GetActiveSummonKindForSkill(skillLevel);
            displayName = GetActiveSummonDisplayName(kind);
            return null;
        }

        private static string[] GetActiveSummonFallbackOrder(float skillLevel)
        {
            if (skillLevel >= 75f)
            {
                return new[] { SummonFallenValkyrieKind, SummonElakingMoleKind, SummonAbominationKind, SummonEntKind };
            }

            if (skillLevel >= 50f)
            {
                return new[] { SummonElakingMoleKind, SummonAbominationKind, SummonEntKind, SummonFallenValkyrieKind };
            }

            if (skillLevel >= 25f)
            {
                return new[] { SummonAbominationKind, SummonEntKind, SummonElakingMoleKind, SummonFallenValkyrieKind };
            }

            return new[] { SummonEntKind, SummonAbominationKind, SummonElakingMoleKind, SummonFallenValkyrieKind };
        }

        private static string GetActiveSummonKindForSkill(float skillLevel)
        {
            if (skillLevel >= 75f)
            {
                return SummonFallenValkyrieKind;
            }

            if (skillLevel >= 50f)
            {
                return SummonElakingMoleKind;
            }

            if (skillLevel >= 25f)
            {
                return SummonAbominationKind;
            }

            return SummonEntKind;
        }

        private static GameObject GetActiveSummonPrefab(string kind)
        {
            if (string.Equals(kind, SummonEntKind, StringComparison.OrdinalIgnoreCase))
            {
                return GetPrefab("RDB_Ent", "Ent", "RRRM_Ent", "ForestEnt");
            }

            if (string.Equals(kind, SummonAbominationKind, StringComparison.OrdinalIgnoreCase))
            {
                return GetPrefab("Abomination", "abomination");
            }

            if (string.Equals(kind, SummonElakingMoleKind, StringComparison.OrdinalIgnoreCase))
            {
                return GetPrefab("ElakingMole", "Elakingmole", "ElaKingMole", "Elaking_Mole");
            }

            if (string.Equals(kind, SummonFallenValkyrieKind, StringComparison.OrdinalIgnoreCase))
            {
                return GetPrefab("FallenValkyrie", "Fallen_Valkyrie", "fallenvalkyrie");
            }

            return null;
        }

        private static string GetActiveSummonDisplayName(string kind)
        {
            if (string.Equals(kind, SummonEntKind, StringComparison.OrdinalIgnoreCase))
            {
                return "Ent";
            }

            if (string.Equals(kind, SummonAbominationKind, StringComparison.OrdinalIgnoreCase))
            {
                return "Abomination";
            }

            if (string.Equals(kind, SummonElakingMoleKind, StringComparison.OrdinalIgnoreCase))
            {
                return "ElakingMole";
            }

            if (string.Equals(kind, SummonFallenValkyrieKind, StringComparison.OrdinalIgnoreCase))
            {
                return "Fallen Valkyrie";
            }

            return "Invocacion";
        }

        private static void SetupUndeadSummon(Player player, GameObject summon)
        {
            if (player == null || summon == null)
            {
                return;
            }

            Character character = summon.GetComponent<Character>() ?? summon.GetComponentInChildren<Character>();
            if (character != null)
            {
                character.SetTamed(true);
            }

            Tameable tameable = summon.GetComponent<Tameable>();
            if (tameable == null)
            {
                tameable = summon.AddComponent<Tameable>();
            }

            if (tameable != null)
            {
                tameable.m_commandable = true;
                tameable.m_startsTamed = true;
                tameable.m_fedDuration = Mathf.Max(tameable.m_fedDuration, 3600f);
                tameable.m_unsummonDistance = Mathf.Max(tameable.m_unsummonDistance, 65f);
                tameable.m_unsummonOnOwnerLogoutSeconds = Mathf.Max(tameable.m_unsummonOnOwnerLogoutSeconds, 5f);
                if (TameMethod != null)
                {
                    try
                    {
                        TameMethod.Invoke(tameable, null);
                    }
                    catch
                    {
                    }
                }
            }

            MonsterAI monsterAI = summon.GetComponent<MonsterAI>();
            if (monsterAI != null)
            {
                monsterAI.MakeTame();
                monsterAI.SetFollowTarget(player.gameObject);
            }

            ZNetView view = summon.GetComponent<ZNetView>();
            if (view != null && view.GetZDO() != null)
            {
                view.GetZDO().Persistent = false;
            }
        }

        private static void DestroyUndeadSummon(Player player)
        {
            if (_undeadSummon != null)
            {
                SpawnBodyguardEffect(_undeadSummon.transform.position);
                ClassPetScalingController.Unregister(_undeadSummon);
                if (ZNetScene.instance != null)
                {
                    ZNetScene.instance.Destroy(_undeadSummon);
                }
                else
                {
                    UnityEngine.Object.Destroy(_undeadSummon);
                }
            }

            _undeadSummon = null;
            _undeadSummonActive = false;
            _undeadSummonRemaining = 0f;
            _undeadSummonKind = SummonEntKind;
            _undeadSummonDisplayName = "Ent";
            RemoveUndeadSummonBuff(player);
        }

        private static void UpdateBodyguards(Player player, float dt)
        {
            bool lostBodyguard = false;
            for (int i = Bodyguards.Count - 1; i >= 0; i--)
            {
                GameObject bodyguard = Bodyguards[i];
                if (bodyguard == null)
                {
                    Bodyguards.RemoveAt(i);
                    lostBodyguard = true;
                    continue;
                }

                Character character = bodyguard.GetComponent<Character>() ?? bodyguard.GetComponentInChildren<Character>();
                if (character == null || character.IsDead())
                {
                    ClassPetScalingController.Unregister(bodyguard);
                    BodyguardKinds.Remove(bodyguard.GetInstanceID());
                    Bodyguards.RemoveAt(i);
                    lostBodyguard = true;
                    continue;
                }

                PetCommandController.ApplyToPet(player, bodyguard, target => IsEnemyTarget(player, target));
            }

            if (lostBodyguard)
            {
                StartBodyguardRespawnCooldown(player);
            }

            if (_bodyguardCombatRefreshTimer <= 0f)
            {
                _bodyguardCombatRefreshTimer = 0.5f;
                if (!PetCommandController.HasActiveOverride)
                {
                    RefreshBodyguardCombat(player);
                }
            }

            if (_bodyguardRespawnCooldown <= 0f)
            {
                SpawnMissingBodyguards(player);
            }

            RefreshBodyguardBuff(player);
        }

        private static void SpawnMissingBodyguards(Player player)
        {
            if (player == null)
            {
                return;
            }

            bool spawned = false;
            if (!HasLivingBodyguardKind(BodyguardDyrnwynKind))
            {
                GameObject prefab = GetBodyguardPrefab(BodyguardDyrnwynKind);
                if (prefab != null)
                {
                    spawned |= SpawnBodyguard(player, prefab, BodyguardDyrnwynKind, player.transform.forward * 2.2f - player.transform.right * 1.0f) != null;
                }
                else if (!_loggedDyrnwynBodyguardMissing)
                {
                    _loggedDyrnwynBodyguardMissing = true;
                    EpicLootRaritySetsPlugin.Log.LogWarning("Helveig bodyguard prefab not found: Charred_Melee_Dyrnwyn.");
                }
            }

            if (spawned)
            {
                ClassSkillManager.RaiseSkill(player, RequiredSet, 0.25f);
            }
        }

        private static GameObject SpawnBodyguard(Player player, GameObject prefab, string kind, Vector3 offset)
        {
            if (player == null || prefab == null)
            {
                return null;
            }

            Vector3 forward = Vector3.ProjectOnPlane(player.transform.forward, Vector3.up);
            if (forward.sqrMagnitude <= 0.001f)
            {
                forward = Vector3.forward;
            }

            forward.Normalize();
            Vector3 spawn = player.transform.position + offset;
            TryProjectGround(spawn, out spawn);
            Quaternion rotation = Quaternion.LookRotation(forward);
            GameObject bodyguard = UnityEngine.Object.Instantiate(prefab, spawn, rotation);
            if (bodyguard == null)
            {
                return null;
            }

            SetupUndeadSummon(player, bodyguard);
            ApplyBodyguardScaling(player, bodyguard, kind);
            Bodyguards.Add(bodyguard);
            BodyguardKinds[bodyguard.GetInstanceID()] = kind;
            SpawnBodyguardEffect(spawn);
            return bodyguard;
        }

        private static GameObject GetBodyguardPrefab(string kind)
        {
            if (string.Equals(kind, BodyguardDyrnwynKind, StringComparison.OrdinalIgnoreCase))
            {
                return GetPrefab("Charred_Melee_Dyrnwyn", "CHARRED_MELEE_DYRNWYN", "Charred_Melee");
            }

            return null;
        }

        private static void ApplyBodyguardScaling(Player player, GameObject bodyguard, string kind)
        {
            Character character = bodyguard != null ? bodyguard.GetComponent<Character>() ?? bodyguard.GetComponentInChildren<Character>() : null;
            if (character == null)
            {
                return;
            }

            float skill = ClassSkillManager.GetSkillLevel(player, RequiredSet);
            ClassPetScalingController.Register(
                bodyguard,
                GetBodyguardMaxHealth(kind, skill),
                GetBodyguardDamageMultiplier(kind, skill),
                GetBodyguardDamageTakenReduction(kind, skill));
        }

        private static void ApplyActiveSummonScaling(Player player, GameObject summon, string kind)
        {
            Character character = summon != null ? summon.GetComponent<Character>() ?? summon.GetComponentInChildren<Character>() : null;
            if (character == null)
            {
                return;
            }

            float skill = ClassSkillManager.GetSkillLevel(player, RequiredSet);
            ClassPetScalingController.Register(
                summon,
                GetActiveSummonMaxHealth(kind, skill),
                GetActiveSummonDamageMultiplier(kind, skill),
                GetBodyguardDamageTakenReduction(kind, skill));
        }

        private static float GetBodyguardMaxHealth(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            if (string.Equals(kind, BodyguardDyrnwynKind, StringComparison.OrdinalIgnoreCase))
            {
                return 140f + skill * 1.8f;
            }

            return 110f + skill * 1.4f;
        }

        private static float GetActiveSummonMaxHealth(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            if (string.Equals(kind, SummonEntKind, StringComparison.OrdinalIgnoreCase))
            {
                return 180f + skill * 1.4f;
            }

            if (string.Equals(kind, SummonAbominationKind, StringComparison.OrdinalIgnoreCase))
            {
                return 260f + skill * 2.0f;
            }

            if (string.Equals(kind, SummonElakingMoleKind, StringComparison.OrdinalIgnoreCase))
            {
                return 320f + skill * 2.3f;
            }

            if (string.Equals(kind, SummonFallenValkyrieKind, StringComparison.OrdinalIgnoreCase))
            {
                return 300f + skill * 2.1f;
            }

            return 180f + skill * 1.4f;
        }

        private static float GetBodyguardDamageMultiplier(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            if (string.Equals(kind, BodyguardDyrnwynKind, StringComparison.OrdinalIgnoreCase))
            {
                return 0.55f + skill * 0.004f;
            }

            if (IsActiveSummonKind(kind))
            {
                return GetActiveSummonDamageMultiplier(kind, skill);
            }

            return 0.50f + skill * 0.0035f;
        }

        private static float GetActiveSummonDamageMultiplier(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            if (string.Equals(kind, SummonEntKind, StringComparison.OrdinalIgnoreCase))
            {
                return 0.45f + skill * 0.0035f;
            }

            if (string.Equals(kind, SummonAbominationKind, StringComparison.OrdinalIgnoreCase))
            {
                return 0.40f + skill * 0.0035f;
            }

            if (string.Equals(kind, SummonElakingMoleKind, StringComparison.OrdinalIgnoreCase))
            {
                return 0.45f + skill * 0.0035f;
            }

            if (string.Equals(kind, SummonFallenValkyrieKind, StringComparison.OrdinalIgnoreCase))
            {
                return 0.45f + skill * 0.004f;
            }

            return 0.45f + skill * 0.0035f;
        }

        private static float GetBodyguardDamageTakenReduction(string kind, float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            return Mathf.Min(0.20f, skill * 0.0015f);
        }

        private static bool IsActiveSummonKind(string kind)
        {
            return string.Equals(kind, SummonEntKind, StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, SummonAbominationKind, StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, SummonElakingMoleKind, StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, SummonFallenValkyrieKind, StringComparison.OrdinalIgnoreCase);
        }

        private static void SetCharacterHealth(Character character, float maxHealth)
        {
            if (character == null || maxHealth <= 0f)
            {
                return;
            }

            TrySetFloatField(CharacterBaseHpField, character, maxHealth);
            TryInvoke(CharacterSetMaxHealthMethod, character, new object[] { maxHealth });
            TryInvoke(CharacterSetHealthMethod, character, new object[] { maxHealth });
            TrySetFloatField(CharacterHealthField, character, maxHealth);
        }

        internal static void ModifyBodyguardOutgoingDamage(HitData hit)
        {
            Character attacker = GetAttacker(hit);
            string kind;
            if (attacker == null || !TryGetControlledUndeadKind(attacker, out kind))
            {
                return;
            }

            ScaleAllDamage(ref hit.m_damage, GetHealingPowerSummonDamageMultiplier());
        }

        private static void RefreshBodyguardFollow(Player owner, GameObject bodyguard)
        {
            if (owner == null || bodyguard == null)
            {
                return;
            }

            MonsterAI monsterAI = bodyguard.GetComponent<MonsterAI>();
            if (monsterAI != null)
            {
                monsterAI.MakeTame();
                monsterAI.SetFollowTarget(owner.gameObject);
            }
        }

        private static void RefreshBodyguardCombat(Player owner)
        {
            Character target = FindBodyguardDefenseTarget(owner);
            if (target == null)
            {
                return;
            }

            foreach (GameObject bodyguard in Bodyguards)
            {
                if (bodyguard == null)
                {
                    continue;
                }

                BaseAI baseAI = bodyguard.GetComponent<BaseAI>() ?? bodyguard.GetComponentInChildren<BaseAI>();
                if (baseAI != null)
                {
                    AssignAITarget(baseAI, target);
                }
            }
        }

        private static void RefreshUndeadSummonCombat(Player owner)
        {
            if (owner == null || _undeadSummon == null)
            {
                return;
            }

            Character target = FindBodyguardDefenseTarget(owner);
            if (target == null)
            {
                return;
            }

            BaseAI baseAI = _undeadSummon.GetComponent<BaseAI>() ?? _undeadSummon.GetComponentInChildren<BaseAI>();
            if (baseAI != null)
            {
                AssignAITarget(baseAI, target);
            }
        }

        private static Character FindBodyguardDefenseTarget(Player owner)
        {
            if (owner == null)
            {
                return null;
            }

            float radius = Mathf.Max(5f, EpicLootRaritySetsPlugin.HelveigBodyguardGuardRadius.Value);
            float bestScore = radius * radius;
            Character best = null;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character == owner || character.IsDead() || !IsEnemyTarget(owner, character))
                {
                    continue;
                }

                float distanceToOwner = (character.transform.position - owner.transform.position).sqrMagnitude;
                if (distanceToOwner > radius * radius)
                {
                    continue;
                }

                float score = Mathf.Min(distanceToOwner, GetClosestBodyguardDistanceSqr(character.transform.position));
                if (score >= bestScore)
                {
                    continue;
                }

                bestScore = score;
                best = character;
            }

            return best;
        }

        private static bool IsEnemyTarget(Player player, Character target)
        {
            if (player == null || target == null || target == player)
            {
                return false;
            }

            if (CharacterTargeting.IsPlayerPvPEnemy(player, target))
            {
                return true;
            }

            if (target is Player || target.IsTamed())
            {
                return false;
            }

            if (BaseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = BaseAIIsEnemyMethod.Invoke(null, new object[] { player, target });
                    if (value is bool && (bool)value)
                    {
                        return true;
                    }
                }
                catch
                {
                }
            }

            return IsValidControlledUndeadEnemy(target);
        }

        internal static bool ShouldSummonTreatAsEnemy(Character first, Character second)
        {
            return IsHelveigEnabledAndActive() &&
                   ((IsControlledUndead(first) && IsValidControlledUndeadEnemy(second)) ||
                    (IsControlledUndead(second) && IsValidControlledUndeadEnemy(first)));
        }

        private static bool IsControlledUndead(Character character)
        {
            string kind;
            return TryGetControlledUndeadKind(character, out kind);
        }

        internal static bool IsControlledUndeadForPetCommand(Character character)
        {
            return IsControlledUndead(character);
        }

        internal static int GetActivePetCount()
        {
            int count = 0;
            foreach (GameObject bodyguard in Bodyguards)
            {
                Character character = bodyguard != null ? bodyguard.GetComponent<Character>() ?? bodyguard.GetComponentInChildren<Character>() : null;
                if (character != null && !character.IsDead())
                {
                    count++;
                }
            }

            Character summonCharacter = _undeadSummon != null ? _undeadSummon.GetComponent<Character>() ?? _undeadSummon.GetComponentInChildren<Character>() : null;
            if (summonCharacter != null && !summonCharacter.IsDead())
            {
                count++;
            }

            return count;
        }

        internal static void ReleasePetFollow(Player owner)
        {
            foreach (GameObject bodyguard in Bodyguards)
            {
                PetCommandController.ReleasePetFollow(bodyguard);
            }

            PetCommandController.ReleasePetFollow(_undeadSummon);
        }

        private static bool IsValidControlledUndeadEnemy(Character target)
        {
            return target != null &&
                   !(target is Player) &&
                   !target.IsDead() &&
                   !target.IsTamed() &&
                   !IsControlledUndead(target);
        }

        private static float GetClosestBodyguardDistanceSqr(Vector3 point)
        {
            float best = float.MaxValue;
            foreach (GameObject bodyguard in Bodyguards)
            {
                if (bodyguard == null)
                {
                    continue;
                }

                float distance = (bodyguard.transform.position - point).sqrMagnitude;
                if (distance < best)
                {
                    best = distance;
                }
            }

            return best;
        }

        private static void AssignAITarget(BaseAI baseAI, Character target)
        {
            if (baseAI == null || target == null)
            {
                return;
            }

            bool assigned = TryInvokeSetTarget(baseAI, target);
            if (!assigned)
            {
                SetTargetCreatureField(baseAI, target);
            }

            if (BaseAITargetStaticField != null)
            {
                try
                {
                    BaseAITargetStaticField.SetValue(baseAI, null);
                }
                catch
                {
                }
            }

            if (BaseAIAlertedField != null)
            {
                try
                {
                    BaseAIAlertedField.SetValue(baseAI, true);
                }
                catch
                {
                }
            }
        }

        private static bool TryInvokeSetTarget(BaseAI baseAI, Character target)
        {
            foreach (MethodInfo method in new[] { MonsterAISetTargetMethod, BaseAISetTargetMethod })
            {
                if (method == null || !method.DeclaringType.IsInstanceOfType(baseAI))
                {
                    continue;
                }

                try
                {
                    method.Invoke(baseAI, new object[] { target });
                    return true;
                }
                catch
                {
                }
            }

            return false;
        }

        private static void SetTargetCreatureField(BaseAI baseAI, Character target)
        {
            if (BaseAITargetCreatureField == null)
            {
                return;
            }

            try
            {
                Type fieldType = BaseAITargetCreatureField.FieldType;
                if (typeof(Character).IsAssignableFrom(fieldType))
                {
                    BaseAITargetCreatureField.SetValue(baseAI, target);
                }
                else if (typeof(GameObject).IsAssignableFrom(fieldType))
                {
                    BaseAITargetCreatureField.SetValue(baseAI, target.gameObject);
                }
            }
            catch
            {
            }
        }

        private static void StartBodyguardRespawnCooldown(Player owner)
        {
            _bodyguardRespawnCooldown = Mathf.Max(_bodyguardRespawnCooldown, Mathf.Max(1f, EpicLootRaritySetsPlugin.HelveigBodyguardRespawnCooldown.Value));
            if (owner != null)
            {
                AbilityCooldownBuffController.Start(owner, "HelveigBodyguardsDeath", "Undead Bodyguards", _bodyguardRespawnCooldown, FindHelveigIcon(owner));
            }
        }

        private static void DestroyBodyguards(Player player, bool playVisual)
        {
            for (int i = Bodyguards.Count - 1; i >= 0; i--)
            {
                GameObject bodyguard = Bodyguards[i];
                if (bodyguard == null)
                {
                    continue;
                }

                if (playVisual)
                {
                    SpawnBodyguardEffect(bodyguard.transform.position);
                }

                ClassPetScalingController.Unregister(bodyguard);
                if (ZNetScene.instance != null)
                {
                    ZNetScene.instance.Destroy(bodyguard);
                }
                else
                {
                    UnityEngine.Object.Destroy(bodyguard);
                }
            }

            Bodyguards.Clear();
            BodyguardKinds.Clear();
            RemoveBodyguardBuff(player);
        }

        private static void SpawnBodyguardEffect(Vector3 position)
        {
            NorseVisualEffectBridge.Spawn(position, Quaternion.identity, 2f, "Smoke", "Dark", "Spirit", "vfx_StaffSkeleton", "fx_DvergerMage_Support");
        }

        private static bool HasLivingBodyguardKind(string kind)
        {
            Character character;
            return TryFindBodyguard(kind, out character);
        }

        private static bool TryFindBodyguard(string kind, out Character character)
        {
            character = null;
            for (int i = Bodyguards.Count - 1; i >= 0; i--)
            {
                GameObject bodyguard = Bodyguards[i];
                if (bodyguard == null)
                {
                    Bodyguards.RemoveAt(i);
                    continue;
                }

                string existingKind;
                if (!BodyguardKinds.TryGetValue(bodyguard.GetInstanceID(), out existingKind) ||
                    !string.Equals(existingKind, kind, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                Character candidate = bodyguard.GetComponent<Character>() ?? bodyguard.GetComponentInChildren<Character>();
                if (candidate != null && !candidate.IsDead())
                {
                    character = candidate;
                    return true;
                }
            }

            return false;
        }

        private static bool TryGetBodyguardKind(Character character, out string kind)
        {
            kind = null;
            if (character == null)
            {
                return false;
            }

            foreach (GameObject bodyguard in Bodyguards)
            {
                if (bodyguard == null)
                {
                    continue;
                }

                Character bodyguardCharacter = bodyguard.GetComponent<Character>() ?? bodyguard.GetComponentInChildren<Character>();
                if (bodyguardCharacter != character && !character.transform.IsChildOf(bodyguard.transform))
                {
                    continue;
                }

                if (BodyguardKinds.TryGetValue(bodyguard.GetInstanceID(), out kind) && !string.IsNullOrEmpty(kind))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool TryGetControlledUndeadKind(Character character, out string kind)
        {
            if (TryGetBodyguardKind(character, out kind))
            {
                return true;
            }

            kind = null;
            if (character == null || _undeadSummon == null)
            {
                return false;
            }

            Character summonCharacter = _undeadSummon.GetComponent<Character>() ?? _undeadSummon.GetComponentInChildren<Character>();
            if (summonCharacter == character || character.transform.IsChildOf(_undeadSummon.transform))
            {
                kind = _undeadSummonKind;
                return true;
            }

            return false;
        }

        private static Character GetAttacker(HitData hit)
        {
            if (hit == null)
            {
                return null;
            }

            try
            {
                return hit.GetAttacker();
            }
            catch
            {
                return null;
            }
        }

        private static void ScaleAllDamage(ref HitData.DamageTypes damages, float multiplier)
        {
            damages.m_blunt *= multiplier;
            damages.m_slash *= multiplier;
            damages.m_pierce *= multiplier;
            damages.m_chop *= multiplier;
            damages.m_pickaxe *= multiplier;
            damages.m_fire *= multiplier;
            damages.m_frost *= multiplier;
            damages.m_lightning *= multiplier;
            damages.m_poison *= multiplier;
            damages.m_spirit *= multiplier;
        }

        private static bool TryInvoke(MethodInfo method, object target, object[] args)
        {
            if (method == null)
            {
                return false;
            }

            try
            {
                method.Invoke(target, args);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static void TrySetFloatField(FieldInfo field, object target, float value)
        {
            if (field == null || target == null)
            {
                return;
            }

            try
            {
                field.SetValue(target, value);
            }
            catch
            {
            }
        }

        private sealed class HealingShieldState
        {
            internal float Amount;
            internal float Remaining;
            internal GameObject Visual;
        }

        private static bool IsHelveigId(string id)
        {
            return !string.IsNullOrEmpty(id) && id.IndexOf("Helveig", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static Sprite FindHelveigIcon(Player player)
        {
            Inventory inventory = player != null ? player.GetInventory() : null;
            if (inventory == null)
            {
                return null;
            }

            foreach (ItemDrop.ItemData item in inventory.GetEquippedItems())
            {
                if (item == null || item.m_shared == null || item.m_shared.m_icons == null || item.m_shared.m_icons.Length == 0)
                {
                    continue;
                }

                MagicItem magicItem = ItemDataExtensions.GetMagicItem(item);
                if (magicItem != null && (IsHelveigId(magicItem.SetID) || IsHelveigId(magicItem.LegendaryID)))
                {
                    return item.m_shared.m_icons[0];
                }
            }

            return null;
        }

        private static void RefreshBodyguardBuff(Player player)
        {
            if (player == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateBodyguardBuff(FindHelveigIcon(player) ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            AddOrUpdateHelveigBuff(player, buff, 0, true);
        }

        private static StatusEffect GetOrCreateBodyguardBuff(Sprite icon)
        {
            if (_bodyguardBuff == null)
            {
                _bodyguardBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _bodyguardBuff.name = BodyguardBuffName;
                _bodyguardBuff.m_name = LocalizedText.AbilityName("Undead Bodyguards");
                _bodyguardBuff.m_category = BodyguardBuffCategory;
                _bodyguardBuff.m_flashIcon = false;
                _bodyguardBuff.m_cooldownIcon = false;
                _bodyguardBuff.m_hidden = false;
            }

            int living = CountLivingBodyguards();
            float skill = Player.m_localPlayer != null ? ClassSkillManager.GetSkillLevel(Player.m_localPlayer, RequiredSet) : 0f;
            string respawn = _bodyguardRespawnCooldown > 0f
                ? string.Format("\nReaparicion: {0:0.#}s.", _bodyguardRespawnCooldown)
                : string.Empty;
            _bodyguardBuff.m_ttl = 0f;
            _bodyguardBuff.m_tooltip = string.Format(
                "Guardaespaldas no muerto de Helveig.\n\nVivos: {0}/1.\nCharred Dyrnwyn: {1:0} vida, x{2:0.##} dano, {3:0.#}% reduccion recibida.{4}",
                living,
                GetBodyguardMaxHealth(BodyguardDyrnwynKind, skill),
                GetBodyguardDamageMultiplier(BodyguardDyrnwynKind, skill),
                GetBodyguardDamageTakenReduction(BodyguardDyrnwynKind, skill) * 100f,
                respawn);
            StatusEffectIconHelper.Apply(_bodyguardBuff, RequiredSet, icon);

            return _bodyguardBuff;
        }

        private static void RemoveBodyguardBuff(Player player)
        {
            if (player != null && _bodyguardBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_bodyguardBuff.NameHash(), true);
            }
        }

        private static int CountLivingBodyguards()
        {
            int count = 0;
            foreach (GameObject bodyguard in Bodyguards)
            {
                Character character = bodyguard != null ? bodyguard.GetComponent<Character>() ?? bodyguard.GetComponentInChildren<Character>() : null;
                if (character != null && !character.IsDead())
                {
                    count++;
                }
            }

            return count;
        }

        private static void UpdateBloodRiteChannelEffects(Player player, float dt)
        {
            CleanupBloodRitePulseVisuals();
            EnsureBloodRiteChannelVisual(player);
            UpdateBloodRiteChannelBar(player);
            if (_bloodRiteRemaining <= 0f)
            {
                return;
            }

            _bloodRiteVisualPulseTimer -= Mathf.Max(0f, dt);
            if (_bloodRiteVisualPulseTimer > 0f)
            {
                return;
            }

            SpawnBloodRitePulse(player);
            _bloodRiteVisualPulseTimer = Mathf.Clamp(EpicLootRaritySetsPlugin.HelveigBloodRiteTickInterval.Value * 0.5f, 0.45f, 1.25f);
        }

        private static void EnsureBloodRiteChannelVisual(Player player)
        {
            if (player == null || !_bloodRiteActive || _bloodRiteRemaining <= 0f || _bloodRiteChannelVisual != null)
            {
                return;
            }

            _bloodRiteChannelVisual = NorseVisualEffectBridge.SpawnAttached(
                player,
                Vector3.up * 1.0f,
                Quaternion.identity,
                Mathf.Max(0.25f, _bloodRiteRemaining + 0.25f),
                "BloodRite",
                "Blood",
                "fx_DvergerMage_Support",
                "vfx_StaffShield",
                "vfx_Potion_health_medium",
                "Spirit");
        }

        private static void SpawnBloodRitePulse(Player player)
        {
            if (player == null)
            {
                return;
            }

            GameObject pulse = NorseVisualEffectBridge.Spawn(
                player.GetCenterPoint(),
                Quaternion.identity,
                1.25f,
                "BloodRite",
                "Blood",
                "Heal",
                "fx_DvergerMage_Support",
                "vfx_Potion_health_medium",
                "vfx_StaffSkeleton",
                "Spirit");
            if (pulse != null)
            {
                BloodRitePulseVisuals.Add(pulse);
            }
        }

        private static void SpawnHolyHealVisual(Character target)
        {
            if (target == null)
            {
                return;
            }

            NorseVisualEffectBridge.SpawnAttached(
                target.gameObject,
                Vector3.up * 1.0f,
                Quaternion.identity,
                1.8f,
                "HolyHeal",
                "Heal",
                "Holy",
                "fx_DvergerMage_Support",
                "vfx_Potion_health_medium",
                "vfx_Potion_health_minor",
                "Spirit");
        }

        private static void SpawnHolyStrikeVisual(Player player, Character target)
        {
            if (target == null)
            {
                return;
            }

            Vector3 impact = target.GetCenterPoint();
            Vector3 direction = player != null ? impact - player.GetCenterPoint() : target.transform.forward;
            if (direction.sqrMagnitude <= 0.001f)
            {
                direction = target.transform.forward;
            }

            NorseVisualEffectBridge.Spawn(
                impact,
                Quaternion.LookRotation(direction.normalized, Vector3.up),
                1.5f,
                "HolyStrike",
                "Holy",
                "Spirit",
                "fx_fireball_staff_explosion",
                "vfx_HitSparks",
                "vfx_Potion_health_medium",
                "Lightning");
        }

        private static void UpdateBloodRiteChannelBar(Player player)
        {
            if (player == null || !_bloodRiteActive)
            {
                DestroyBloodRiteChannelBar();
                return;
            }

            EnsureBloodRiteChannelBar();
            if (_bloodRiteBarRoot == null || _bloodRiteBarFillTransform == null)
            {
                return;
            }

            float progress = Mathf.Clamp01(_bloodRiteRemaining / Mathf.Max(0.1f, _bloodRiteDuration));
            _bloodRiteBarFillTransform.sizeDelta = new Vector2(BloodRiteBarWidth * progress, 0f);
            _bloodRiteBarRoot.SetActive(progress > 0f);
        }

        private static void EnsureBloodRiteChannelBar()
        {
            if (_bloodRiteBarRoot != null || Hud.instance == null)
            {
                return;
            }

            _bloodRiteBarRoot = new GameObject(BloodRiteChannelBarName, typeof(RectTransform));
            _bloodRiteBarRoot.transform.SetParent(Hud.instance.transform, false);
            _bloodRiteBarRoot.transform.SetAsLastSibling();

            RectTransform root = _bloodRiteBarRoot.GetComponent<RectTransform>();
            root.anchorMin = new Vector2(0.5f, 0.5f);
            root.anchorMax = new Vector2(0.5f, 0.5f);
            root.pivot = new Vector2(0.5f, 0.5f);
            root.anchoredPosition = new Vector2(0f, -175f);
            root.sizeDelta = new Vector2(BloodRiteBarWidth + 8f, BloodRiteBarHeight + 8f);

            GameObject frame = CreateBloodRiteBarImage("Frame", _bloodRiteBarRoot.transform, new Color(0.58f, 0.03f, 0.035f, 0.92f));
            RectTransform frameRect = frame.GetComponent<RectTransform>();
            frameRect.anchorMin = Vector2.zero;
            frameRect.anchorMax = Vector2.one;
            frameRect.offsetMin = Vector2.zero;
            frameRect.offsetMax = Vector2.zero;

            GameObject background = CreateBloodRiteBarImage("Background", _bloodRiteBarRoot.transform, new Color(0.025f, 0.005f, 0.008f, 0.86f));
            RectTransform backgroundRect = background.GetComponent<RectTransform>();
            backgroundRect.anchorMin = new Vector2(0.5f, 0.5f);
            backgroundRect.anchorMax = new Vector2(0.5f, 0.5f);
            backgroundRect.pivot = new Vector2(0.5f, 0.5f);
            backgroundRect.anchoredPosition = Vector2.zero;
            backgroundRect.sizeDelta = new Vector2(BloodRiteBarWidth, BloodRiteBarHeight);

            GameObject fill = CreateBloodRiteBarImage("Fill", background.transform, new Color(0.9f, 0.05f, 0.08f, 0.95f));
            _bloodRiteBarFillTransform = fill.GetComponent<RectTransform>();
            _bloodRiteBarFillTransform.anchorMin = new Vector2(0f, 0f);
            _bloodRiteBarFillTransform.anchorMax = new Vector2(0f, 1f);
            _bloodRiteBarFillTransform.pivot = new Vector2(0f, 0.5f);
            _bloodRiteBarFillTransform.anchoredPosition = Vector2.zero;
            _bloodRiteBarFillTransform.sizeDelta = new Vector2(BloodRiteBarWidth, 0f);
        }

        private static GameObject CreateBloodRiteBarImage(string name, Transform parent, Color color)
        {
            GameObject gameObject = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            gameObject.transform.SetParent(parent, false);

            Image image = gameObject.GetComponent<Image>();
            image.sprite = GetBloodRiteBarSprite();
            image.type = Image.Type.Simple;
            image.color = color;
            image.raycastTarget = false;
            return gameObject;
        }

        private static Sprite GetBloodRiteBarSprite()
        {
            if (_bloodRiteBarSprite != null)
            {
                return _bloodRiteBarSprite;
            }

            Texture2D texture = new Texture2D(8, 8, TextureFormat.RGBA32, false);
            texture.wrapMode = TextureWrapMode.Clamp;
            Color[] pixels = Enumerable.Repeat(Color.white, 8 * 8).ToArray();
            texture.SetPixels(pixels);
            texture.Apply();
            _bloodRiteBarSprite = Sprite.Create(texture, new Rect(0f, 0f, 8f, 8f), new Vector2(0.5f, 0.5f));
            return _bloodRiteBarSprite;
        }

        private static void DestroyBloodRiteChannelVisual()
        {
            _bloodRiteVisualPulseTimer = 0f;
            DestroyVisual(ref _bloodRiteChannelVisual);
            DestroyBloodRitePulseVisuals();
        }

        private static void CleanupBloodRitePulseVisuals()
        {
            for (int i = BloodRitePulseVisuals.Count - 1; i >= 0; i--)
            {
                if (BloodRitePulseVisuals[i] == null)
                {
                    BloodRitePulseVisuals.RemoveAt(i);
                }
            }
        }

        private static void DestroyBloodRitePulseVisuals()
        {
            for (int i = BloodRitePulseVisuals.Count - 1; i >= 0; i--)
            {
                GameObject visual = BloodRitePulseVisuals[i];
                if (visual != null)
                {
                    UnityEngine.Object.Destroy(visual);
                }
            }

            BloodRitePulseVisuals.Clear();
        }

        private static void DestroyBloodRiteChannelBar()
        {
            if (_bloodRiteBarRoot != null)
            {
                UnityEngine.Object.Destroy(_bloodRiteBarRoot);
            }

            _bloodRiteBarRoot = null;
            _bloodRiteBarFillTransform = null;
        }

        private static void DestroyVisual(ref GameObject visual)
        {
            if (visual != null)
            {
                UnityEngine.Object.Destroy(visual);
                visual = null;
            }
        }

        private static void HealAlliesInBloodRite(Player player)
        {
            float radius = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HelveigBloodRiteRadius.Value);
            float healing = GetScaledHealing(player, EpicLootRaritySetsPlugin.HelveigBloodRiteBaseHealing.Value, EpicLootRaritySetsPlugin.HelveigBloodRiteHealingPerBloodMagicLevel.Value);
            bool healedAny = false;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character.IsDead())
                {
                    continue;
                }

                if ((character.transform.position - player.transform.position).sqrMagnitude > radius * radius || !IsAlly(player, character))
                {
                    continue;
                }

                if (HealAndApplyPassives(player, character, healing) > 0.01f || healing > 0.01f)
                {
                    healedAny = true;
                }
            }

            if (healedAny)
            {
                ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            }
        }

        private static float HealAndApplyPassives(Player caster, Character target, float healing)
        {
            if (caster == null || target == null || healing <= 0f || target.IsDead())
            {
                return 0f;
            }

            float potentialHealing = Mathf.Max(0f, healing);
            float before = GetHealthSafe(target);
            target.Heal(potentialHealing, true);
            float actualHealing = Mathf.Max(0f, GetHealthSafe(target) - before);
            ApplyHealingShield(caster, target, potentialHealing);
            AddHealingPowerStack(caster);
            return actualHealing;
        }

        internal static void RegisterRpcs()
        {
            if (_rpcsRegistered || ZRoutedRpc.instance == null)
            {
                return;
            }

            try
            {
                ZRoutedRpc.instance.Register<ZDOID, float, float>(ApplyHealingShieldRpc, RPC_ApplyHealingShield);
                _rpcsRegistered = true;
            }
            catch
            {
            }
        }

        private static void RPC_ApplyHealingShield(long sender, ZDOID targetId, float shieldAmount, float remaining)
        {
            Character target = FindCharacterByZdoId(targetId);
            if (target == null)
            {
                return;
            }

            Player targetPlayer = target as Player;
            if (targetPlayer != null && targetPlayer != Player.m_localPlayer)
            {
                return;
            }

            ApplyHealingShieldAmount(null, target, shieldAmount, Mathf.Max(0.1f, remaining), false);
        }

        private static float GetHealthSafe(Character target)
        {
            if (target == null)
            {
                return 0f;
            }

            try
            {
                return target.GetHealth();
            }
            catch
            {
                return 0f;
            }
        }

        private static void ApplyHealingShield(Player caster, Character target, float actualHealing)
        {
            if (target == null || actualHealing <= 0f)
            {
                return;
            }

            float shieldAmount = Mathf.Max(0f, actualHealing * HealingShieldFraction);
            ApplyHealingShieldAmount(caster, target, shieldAmount, HealingShieldDuration, true);
        }

        private static void ApplyHealingShieldAmount(Player caster, Character target, float shieldAmount, float duration, bool sendRemotePlayerRpc)
        {
            if (target == null)
            {
                return;
            }

            if (shieldAmount <= 0.01f)
            {
                return;
            }

            HealingShieldState state;
            if (!HealingShields.TryGetValue(target, out state) || state == null)
            {
                state = new HealingShieldState();
                HealingShields[target] = state;
            }

            state.Amount = Mathf.Max(state.Amount, shieldAmount);
            state.Remaining = Mathf.Max(0.1f, duration);
            EnsureHealingShieldVisual(target, state);
            RefreshHealingShieldBuff(caster, target, state);
            if (sendRemotePlayerRpc)
            {
                TrySendHealingShieldRpc(target, shieldAmount, state.Remaining);
            }
        }

        private static void AddHealingPowerStack(Player player)
        {
            if (player == null || player != Player.m_localPlayer || !IsHelveigEnabledAndActive())
            {
                return;
            }

            _healingPowerStacks = Mathf.Clamp(_healingPowerStacks + 1, 0, HealingPowerMaxStacks);
            _healingPowerRemaining = HealingPowerDuration;
            RefreshHealingPowerBuff(player);
        }

        private static void UpdateHealingPower(Player player, float dt)
        {
            if (_healingPowerStacks <= 0)
            {
                return;
            }

            _healingPowerRemaining -= Mathf.Max(0f, dt);
            if (_healingPowerRemaining > 0f && IsHelveigEnabledAndActive())
            {
                return;
            }

            _healingPowerStacks = 0;
            _healingPowerRemaining = 0f;
            RemoveHealingPowerBuff(player);
        }

        private static void UpdateHealingShields(float dt)
        {
            if (HealingShields.Count == 0)
            {
                return;
            }

            HealingShieldsToRemove.Clear();
            foreach (KeyValuePair<Character, HealingShieldState> pair in HealingShields)
            {
                Character target = pair.Key;
                HealingShieldState state = pair.Value;
                if (target == null || state == null || target.IsDead())
                {
                    HealingShieldsToRemove.Add(target);
                    continue;
                }

                state.Remaining -= dt;
                if (state.Remaining <= 0f || state.Amount <= 0.01f)
                {
                    HealingShieldsToRemove.Add(target);
                    continue;
                }

                EnsureHealingShieldVisual(target, state);
            }

            foreach (Character target in HealingShieldsToRemove)
            {
                RemoveHealingShield(target);
            }

            HealingShieldsToRemove.Clear();
        }

        private static void ClearHealingShields()
        {
            foreach (Character target in HealingShields.Keys.ToList())
            {
                RemoveHealingShield(target);
            }

            HealingShields.Clear();
        }

        internal static void ModifyIncomingDamage(Character target, HitData hit)
        {
            if (target == null || hit == null)
            {
                return;
            }

            HealingShieldState state;
            if (!HealingShields.TryGetValue(target, out state) || state == null || state.Remaining <= 0f || state.Amount <= 0.01f)
            {
                return;
            }

            float before = TotalDamage(hit.m_damage);
            if (before <= 0.01f)
            {
                return;
            }

            ReduceFlatDamage(ref hit.m_damage, state.Amount);
            float absorbed = Mathf.Max(0f, before - TotalDamage(hit.m_damage));
            state.Amount = Mathf.Max(0f, state.Amount - absorbed);
            if (state.Amount <= 0.01f)
            {
                RemoveHealingShield(target);
            }
        }

        private static void EnsureHealingShieldVisual(Character target, HealingShieldState state)
        {
            if (target == null || state == null || state.Remaining <= 0f || state.Visual != null)
            {
                return;
            }

            state.Visual = NorseVisualEffectBridge.SpawnSeidrElementalShield(target.gameObject, Mathf.Max(0.2f, state.Remaining + 0.25f));
        }

        private static void RefreshHealingShieldBuff(Player caster, Character target, HealingShieldState state)
        {
            if (target == null || state == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateHealingShieldBuff(AbilityPanelIconCatalog.GetIcon("Buffs", "helveig_blood_aegis.png") ?? FindHelveigIcon(caster) ?? StatusEffectIconHelper.GetIcon(caster, RequiredSet));
            buff.m_ttl = Mathf.Max(0.1f, state.Remaining);
            buff.m_tooltip = LocalizedText.Select(
                string.Format(
                    "Egida de sangre de Helveig.\n\nAbsorbe {0:0.#} de dano.\nTiempo restante: {1:0.#}s.",
                    Mathf.Max(0f, state.Amount),
                    Mathf.Max(0f, state.Remaining)),
                string.Format(
                    "Helveig Blood Aegis.\n\nAbsorbs {0:0.#} damage.\nTime remaining: {1:0.#}s.",
                    Mathf.Max(0f, state.Amount),
                    Mathf.Max(0f, state.Remaining)));

            SEMan seMan = target.GetSEMan();
            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, 0, 0f, 0);
        }

        private static StatusEffect GetOrCreateHealingShieldBuff(Sprite icon)
        {
            if (_healingShieldBuff == null)
            {
                _healingShieldBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _healingShieldBuff.name = HealingShieldBuffName;
                _healingShieldBuff.m_name = LocalizedText.AbilityName("Blood Aegis");
                _healingShieldBuff.m_category = HealingShieldBuffCategory;
                _healingShieldBuff.m_flashIcon = false;
                _healingShieldBuff.m_cooldownIcon = true;
                _healingShieldBuff.m_hidden = false;
            }

            StatusEffectIconHelper.Apply(_healingShieldBuff, RequiredSet, icon);
            return _healingShieldBuff;
        }

        private static void RemoveHealingShield(Character target)
        {
            HealingShieldState state;
            if (target != null && HealingShields.TryGetValue(target, out state) && state != null && state.Visual != null)
            {
                UnityEngine.Object.Destroy(state.Visual);
                state.Visual = null;
            }

            HealingShields.Remove(target);
            if (target != null && _healingShieldBuff != null)
            {
                target.GetSEMan().RemoveStatusEffect(_healingShieldBuff.NameHash(), true);
            }
        }

        private static void TrySendHealingShieldRpc(Character target, float shieldAmount, float remaining)
        {
            Player targetPlayer = target as Player;
            if (targetPlayer == null || targetPlayer == Player.m_localPlayer)
            {
                return;
            }

            RegisterRpcs();
            if (!_rpcsRegistered || ZRoutedRpc.instance == null)
            {
                return;
            }

            ZDOID targetId;
            long owner;
            if (!TryGetCharacterNetworkIdentity(target, out targetId, out owner) || owner == 0L)
            {
                return;
            }

            try
            {
                ZRoutedRpc.instance.InvokeRoutedRPC(owner, ApplyHealingShieldRpc, targetId, shieldAmount, Mathf.Max(0.1f, remaining));
            }
            catch
            {
            }
        }

        private static Character FindCharacterByZdoId(ZDOID targetId)
        {
            foreach (Character character in Character.GetAllCharacters())
            {
                ZDOID characterId;
                long owner;
                if (character != null &&
                    TryGetCharacterNetworkIdentity(character, out characterId, out owner) &&
                    characterId.Equals(targetId))
                {
                    return character;
                }
            }

            return null;
        }

        private static bool TryGetCharacterNetworkIdentity(Character target, out ZDOID id, out long owner)
        {
            id = default(ZDOID);
            owner = 0L;
            if (target == null)
            {
                return false;
            }

            ZNetView view = target.GetComponent<ZNetView>();
            ZDO zdo = view != null ? view.GetZDO() : null;
            if (zdo == null)
            {
                return false;
            }

            id = zdo.m_uid;
            owner = zdo.GetOwner();
            return true;
        }

        private static void RefreshHealingPowerBuff(Player player)
        {
            if (player == null || _healingPowerStacks <= 0)
            {
                return;
            }

            StatusEffect buff = GetOrCreateHealingPowerBuff(AbilityPanelIconCatalog.GetIcon("Buffs", "helveig_sanguine_devotion.png") ?? FindHelveigIcon(player) ?? StatusEffectIconHelper.GetIcon(player, RequiredSet));
            buff.m_name = string.Format("{0} {1}/{2}", LocalizedText.AbilityName("Sanguine Devotion"), _healingPowerStacks, HealingPowerMaxStacks);
            buff.m_ttl = Mathf.Max(0.1f, _healingPowerRemaining + 0.1f);
            buff.m_tooltip = LocalizedText.Select(
                string.Format(
                    "Devocion sanguinea de Helveig.\n\nCargas: {0}/{1}.\nDano de invocaciones: +{2:0.#}%.\nDano de Golpe sagrado: +{3:0.#}%.\nTiempo restante: {4:0.#}s.",
                    _healingPowerStacks,
                    HealingPowerMaxStacks,
                    (_healingPowerStacks * HealingPowerSummonDamagePerStack) * 100f,
                    (_healingPowerStacks * HealingPowerHolyStrikeDamagePerStack) * 100f,
                    Mathf.Max(0f, _healingPowerRemaining)),
                string.Format(
                    "Helveig Sanguine Devotion.\n\nStacks: {0}/{1}.\nSummon damage: +{2:0.#}%.\nHoly Strike damage: +{3:0.#}%.\nTime remaining: {4:0.#}s.",
                    _healingPowerStacks,
                    HealingPowerMaxStacks,
                    (_healingPowerStacks * HealingPowerSummonDamagePerStack) * 100f,
                    (_healingPowerStacks * HealingPowerHolyStrikeDamagePerStack) * 100f,
                    Mathf.Max(0f, _healingPowerRemaining)));

            SEMan seMan = player.GetSEMan();
            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, Mathf.Max(1, _healingPowerStacks), 0f, 0);
        }

        private static StatusEffect GetOrCreateHealingPowerBuff(Sprite icon)
        {
            if (_healingPowerBuff == null)
            {
                _healingPowerBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _healingPowerBuff.name = HealingPowerBuffName;
                _healingPowerBuff.m_category = HealingPowerBuffCategory;
                _healingPowerBuff.m_flashIcon = false;
                _healingPowerBuff.m_cooldownIcon = true;
                _healingPowerBuff.m_hidden = false;
            }

            StatusEffectIconHelper.Apply(_healingPowerBuff, RequiredSet, icon);
            return _healingPowerBuff;
        }

        private static void RemoveHealingPowerBuff(Player player)
        {
            if (player != null && _healingPowerBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_healingPowerBuff.NameHash(), true);
            }
        }

        private static float GetHealingPowerSummonDamageMultiplier()
        {
            if (_healingPowerRemaining <= 0f)
            {
                return 1f;
            }

            return 1f + Mathf.Clamp(_healingPowerStacks, 0, HealingPowerMaxStacks) * HealingPowerSummonDamagePerStack;
        }

        private static float GetHealingPowerHolyStrikeDamageMultiplier()
        {
            if (_healingPowerRemaining <= 0f)
            {
                return 1f;
            }

            return 1f + Mathf.Clamp(_healingPowerStacks, 0, HealingPowerMaxStacks) * HealingPowerHolyStrikeDamagePerStack;
        }

        private static void ReduceFlatDamage(ref HitData.DamageTypes damages, float reduction)
        {
            float total = TotalDamage(damages);
            if (total <= 0.01f || reduction <= 0f)
            {
                return;
            }

            ScaleAllDamage(ref damages, Mathf.Clamp01((total - Mathf.Max(0f, reduction)) / total));
        }

        private static float TotalDamage(HitData.DamageTypes damages)
        {
            return damages.m_blunt + damages.m_slash + damages.m_pierce + damages.m_chop + damages.m_pickaxe +
                   damages.m_fire + damages.m_frost + damages.m_lightning + damages.m_poison + damages.m_spirit;
        }

        private static bool IsAlly(Player player, Character target)
        {
            if (player == null || target == null)
            {
                return false;
            }

            if (target == player)
            {
                return true;
            }

            if (CharacterTargeting.IsPlayerPvPEnemy(player, target))
            {
                return false;
            }

            if (target is Player || target.IsTamed())
            {
                return true;
            }

            if (BaseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = BaseAIIsEnemyMethod.Invoke(null, new object[] { player, target });
                    if (value is bool)
                    {
                        return !(bool)value;
                    }
                }
                catch
                {
                }
            }

            return false;
        }

        private static float GetScaledHealing(Player player, float baseHealing, float healingPerBloodMagicLevel)
        {
            float skillLevel = ClassSkillManager.GetSkillLevel(player, "Helveig");
            return Mathf.Max(0f, baseHealing + skillLevel * healingPerBloodMagicLevel);
        }

        private static HitData CreateHolyStrikeHit(Player player, ItemDrop.ItemData weapon, Character target)
        {
            float skillLevel = ClassSkillManager.GetSkillLevel(player, "Helveig");
            HitData.DamageTypes damages = new HitData.DamageTypes
            {
                m_fire = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigHolyStrikeBaseFireDamage.Value + skillLevel * EpicLootRaritySetsPlugin.HelveigHolyStrikeFireDamagePerBloodMagicLevel.Value),
                m_spirit = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigHolyStrikeBaseSpiritDamage.Value + skillLevel * EpicLootRaritySetsPlugin.HelveigHolyStrikeSpiritDamagePerBloodMagicLevel.Value)
            };

            ApplyEpicLootDamageModifiers(player, weapon, ref damages);
            ScaleAllDamage(ref damages, GetHealingPowerHolyStrikeDamageMultiplier());

            HitData hit = new HitData
            {
                m_damage = damages,
                m_skill = ClassSkillManager.Helveig,
                m_skillLevel = skillLevel,
                m_ranged = true,
                m_dodgeable = true,
                m_blockable = true,
                m_backstabBonus = 1f,
                m_staggerMultiplier = 1f,
                m_point = target != null ? target.GetCenterPoint() : Vector3.zero,
                m_dir = target != null && player != null ? (target.GetCenterPoint() - player.GetCenterPoint()).normalized : Vector3.forward
            };

            if (player != null)
            {
                hit.SetAttacker(player);
            }

            return hit;
        }

        private static void RestoreHolyStrikeEitr(Player player)
        {
            if (player == null)
            {
                return;
            }

            float refund = Mathf.Max(0f, EpicLootRaritySetsPlugin.HelveigHolyStrikeEitrRefund.Value);
            if (refund <= 0f)
            {
                return;
            }

            player.AddEitr(refund);
        }

        private static void ApplyEpicLootDamageModifiers(Player player, ItemDrop.ItemData weapon, ref HitData.DamageTypes damages)
        {
            if (player == null || weapon == null || ApplyMagicDamageModifiersMethod == null)
            {
                return;
            }

            try
            {
                object[] args = { player, weapon, damages };
                ApplyMagicDamageModifiersMethod.Invoke(null, args);
                damages = (HitData.DamageTypes)args[2];
            }
            catch (Exception ex)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not apply EpicLoot damage modifiers to Helveig Holy Strike. " + ex.GetBaseException().Message);
            }
        }

        private static bool TryFindHolyHealTarget(Player player, float range, out Character target)
        {
            target = null;
            if (player == null)
            {
                return false;
            }

            range = Mathf.Max(1f, range);
            Transform originTransform = GameCamera.instance != null ? GameCamera.instance.transform : player.transform;
            RaycastHit[] hits = Physics.SphereCastAll(originTransform.position, 0.75f, originTransform.forward, range, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            if (hits != null)
            {
                foreach (RaycastHit hit in hits.OrderBy(hit => hit.distance))
                {
                    Character character = hit.collider != null ? hit.collider.GetComponentInParent<Character>() : null;
                    if (character == null || character == player || character.IsDead() || !IsAlly(player, character))
                    {
                        continue;
                    }

                    target = character;
                    return true;
                }
            }

            return false;
        }

        private static bool TryFindHolyStrikeTarget(Player player, float range, out Character target)
        {
            target = null;
            if (player == null)
            {
                return false;
            }

            range = Mathf.Max(1f, range);
            Transform originTransform = GameCamera.instance != null ? GameCamera.instance.transform : player.transform;
            RaycastHit[] hits = Physics.SphereCastAll(originTransform.position, 0.75f, originTransform.forward, range, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            if (hits != null)
            {
                foreach (RaycastHit hit in hits.OrderBy(hit => hit.distance))
                {
                    Character character = hit.collider != null ? hit.collider.GetComponentInParent<Character>() : null;
                    if (character == null || character == player || character.IsDead() || !IsEnemy(player, character))
                    {
                        continue;
                    }

                    target = character;
                    return true;
                }
            }

            float bestDistance = range * range;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character == player || character.IsDead() || !IsEnemy(player, character))
                {
                    continue;
                }

                float sqrDistance = (character.transform.position - player.transform.position).sqrMagnitude;
                if (sqrDistance > bestDistance)
                {
                    continue;
                }

                bestDistance = sqrDistance;
                target = character;
            }

            return target != null;
        }

        private static bool IsEnemy(Player player, Character target)
        {
            if (player == null || target == null || target == player)
            {
                return false;
            }

            if (CharacterTargeting.IsPlayerPvPEnemy(player, target))
            {
                return true;
            }

            if (target is Player)
            {
                return false;
            }

            if (BaseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = BaseAIIsEnemyMethod.Invoke(null, new object[] { player, target });
                    if (value is bool)
                    {
                        return (bool)value;
                    }
                }
                catch
                {
                }
            }

            return true;
        }

        private static bool IsHelveigEnabledAndActive()
        {
            return EpicLootRaritySetsPlugin.EnableHelveigAbilities != null &&
                   EpicLootRaritySetsPlugin.EnableHelveigAbilities.Value &&
                   SetActivationBuffController.HasActiveSet(RequiredSet);
        }

        private static bool CanReadAbilityInput(Player player)
        {
            return !player.IsDead() &&
                   !player.IsTeleporting() &&
                   !IsAnyMenuOpen();
        }

        private static bool IsShortcutDown(ConfigEntry<KeyboardShortcut> shortcutEntry)
        {
            if (shortcutEntry == null)
            {
                return false;
            }

            KeyboardShortcut shortcut = shortcutEntry.Value;
            if (shortcut.IsDown())
            {
                return true;
            }

            KeyCode mainKey = shortcut.MainKey;
            if (mainKey == KeyCode.None || !Input.GetKeyDown(mainKey))
            {
                return false;
            }

            foreach (KeyCode modifier in shortcut.Modifiers)
            {
                if (!Input.GetKey(modifier))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool IsAnyMenuOpen()
        {
            if (InventoryGui.instance != null && InventoryGui.IsVisible())
            {
                return true;
            }

            if (Menu.instance != null && Menu.IsVisible())
            {
                return true;
            }

            if (TextInput.instance != null && TextInput.IsVisible())
            {
                return true;
            }

            if (Chat.instance != null && Chat.instance.HasFocus())
            {
                return true;
            }

            return Minimap.instance != null && Minimap.IsOpen();
        }

        private static bool TrySpendEitrAndCooldown(Player player, string abilityName, float eitrUse, float cooldown)
        {
            if (cooldown > 0f)
            {
                ShowMessage(player, string.Format("{0}: {1:0}s cooldown.", abilityName, cooldown));
                return false;
            }

            if (eitrUse > 0f && !player.HaveEitr(eitrUse))
            {
                if (Hud.instance != null)
                {
                    Hud.instance.EitrBarEmptyFlash();
                }

                ShowMessage(player, string.Format("{0}: no tienes eitr suficiente.", abilityName));
                return false;
            }

            return true;
        }

        private static StatusEffect GetOrCreateBloodRiteBuff()
        {
            if (_bloodRiteBuff == null)
            {
                _bloodRiteBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _bloodRiteBuff.name = BloodRiteBuffName;
                _bloodRiteBuff.m_name = LocalizedText.AbilityName("Blood Rite");
                _bloodRiteBuff.m_category = BloodRiteBuffCategory;
                _bloodRiteBuff.m_flashIcon = false;
                _bloodRiteBuff.m_cooldownIcon = true;
                _bloodRiteBuff.m_hidden = false;
            }

            _bloodRiteBuff.m_ttl = Mathf.Max(0.2f, _bloodRiteRemaining + 0.1f);
            _bloodRiteBuff.m_tooltip = string.Format(
                "Canalizando curacion de sangre.\n\nRadio: {0:0.#}m.\nPulso: cada {1:0.#}s.\nCuracion por pulso: {2:0.#} + {3:0.##} por nivel de Helveig.\nTiempo restante: {4:0.#}s.\nMoverte cancela la canalizacion.",
                EpicLootRaritySetsPlugin.HelveigBloodRiteRadius.Value,
                EpicLootRaritySetsPlugin.HelveigBloodRiteTickInterval.Value,
                EpicLootRaritySetsPlugin.HelveigBloodRiteBaseHealing.Value,
                EpicLootRaritySetsPlugin.HelveigBloodRiteHealingPerBloodMagicLevel.Value,
                Mathf.Max(0f, _bloodRiteRemaining));
            return _bloodRiteBuff;
        }

        private static void RefreshBloodRiteBuff(Player player)
        {
            if (player == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateBloodRiteBuff();
            StatusEffectIconHelper.Apply(buff, player, RequiredSet);
            SEMan seMan = player.GetSEMan();
            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, 1, 0f, 0);
        }

        private static void RemoveBloodRiteBuff(Player player)
        {
            if (player != null && _bloodRiteBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_bloodRiteBuff.NameHash(), true);
            }
        }

        private static StatusEffect GetOrCreateUndeadSummonBuff()
        {
            if (_undeadSummonBuff == null)
            {
                _undeadSummonBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _undeadSummonBuff.name = UndeadSummonBuffName;
                _undeadSummonBuff.m_name = LocalizedText.AbilityName("Summon Monster");
                _undeadSummonBuff.m_category = UndeadSummonBuffCategory;
                _undeadSummonBuff.m_flashIcon = false;
                _undeadSummonBuff.m_cooldownIcon = true;
                _undeadSummonBuff.m_hidden = false;
            }

            _undeadSummonBuff.m_ttl = Mathf.Max(0.2f, _undeadSummonRemaining + 0.1f);
            _undeadSummonBuff.m_tooltip = string.Format(
                "Bestia invocada por Helveig activa.\n\nInvocacion: {0}.\nTiempo restante: {1:0.#}s.\nVida y dano escalan con Helveig.",
                _undeadSummonDisplayName,
                Mathf.Max(0f, _undeadSummonRemaining));
            return _undeadSummonBuff;
        }

        private static void RefreshUndeadSummonBuff(Player player)
        {
            if (player == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateUndeadSummonBuff();
            StatusEffectIconHelper.Apply(buff, player, RequiredSet);
            AddOrUpdateHelveigBuff(player, buff, 0, false);
        }

        private static void AddOrUpdateHelveigBuff(Player player, StatusEffect buff, int itemLevel, bool refreshTtl)
        {
            if (player == null || buff == null)
            {
                return;
            }

            SEMan seMan = player.GetSEMan();
            StatusEffect active = seMan.GetStatusEffect(buff.NameHash());
            if (active == null)
            {
                seMan.AddStatusEffect(buff, true, itemLevel, 0f, 0);
                return;
            }

            active.m_name = buff.m_name;
            active.m_tooltip = buff.m_tooltip;
            active.m_icon = buff.m_icon;
            active.m_flashIcon = false;
            active.m_cooldownIcon = buff.m_cooldownIcon;
            active.m_hidden = buff.m_hidden;
            active.m_category = buff.m_category;

            if (refreshTtl)
            {
                active.m_ttl = buff.m_ttl;
            }
        }

        private static void RemoveUndeadSummonBuff(Player player)
        {
            if (player != null && _undeadSummonBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_undeadSummonBuff.NameHash(), true);
            }
        }

        private static GameObject GetPrefab(params string[] names)
        {
            if (names == null || ZNetScene.instance == null)
            {
                return null;
            }

            foreach (string name in names)
            {
                if (string.IsNullOrEmpty(name))
                {
                    continue;
                }

                GameObject prefab = ZNetScene.instance.GetPrefab(name);
                if (prefab != null && (prefab.GetComponent<Character>() != null || prefab.GetComponentInChildren<Character>() != null))
                {
                    return prefab;
                }
            }

            return null;
        }

        private static bool TryProjectGround(Vector3 probe, out Vector3 point)
        {
            RaycastHit[] hits = Physics.RaycastAll(probe + Vector3.up * 8f, Vector3.down, 20f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            Array.Sort(hits, (left, right) => left.distance.CompareTo(right.distance));
            foreach (RaycastHit hit in hits)
            {
                if (hit.collider == null || hit.collider.GetComponentInParent<Character>() != null)
                {
                    continue;
                }

                point = hit.point + Vector3.up * 0.05f;
                return true;
            }

            point = probe;
            return false;
        }

        private static void ShowMessage(Player player, string message)
        {
            if (player != null)
            {
                player.Message(MessageHud.MessageType.Center, message, 0, null, false);
            }
        }
    }

    internal static class RagnarAbilityController
    {
        private const string RequiredSet = "Ragnar";
        private const string DecayBuffName = "FranRagnarDecayAura";
        private const string DecayBuffCategory = "FranRagnarDecayAura";
        private const string FuryBuffName = "FranRagnarFury";
        private const string FuryBuffCategory = "FranRagnarFury";
        private const string BloodFrenzyBuffName = "FranRagnarBloodFrenzy";
        private const string BloodFrenzyBuffCategory = "FranRagnarBloodFrenzy";

        private static readonly MethodInfo BaseAIIsEnemyMethod = AccessTools.Method(typeof(BaseAI), "IsEnemy", new[] { typeof(Character), typeof(Character) });
        private static readonly MethodInfo GetStaminaMethod = AccessTools.Method(typeof(Player), "GetStamina", Type.EmptyTypes) ?? AccessTools.Method(typeof(Character), "GetStamina", Type.EmptyTypes);
        private static readonly MethodInfo GetMaxStaminaMethod = AccessTools.Method(typeof(Player), "GetMaxStamina", Type.EmptyTypes) ?? AccessTools.Method(typeof(Character), "GetMaxStamina", Type.EmptyTypes);
        private static readonly MethodInfo UseStaminaMethod = AccessTools.Method(typeof(Player), "UseStamina", new[] { typeof(float) }) ?? AccessTools.Method(typeof(Character), "UseStamina", new[] { typeof(float) });
        private static readonly MethodInfo PlayerIsOnGroundMethod = AccessTools.Method(typeof(Character), "IsOnGround", Type.EmptyTypes) ?? AccessTools.Method(typeof(Player), "IsOnGround", Type.EmptyTypes);
        private static readonly MethodInfo PlayerStartAttackMethod = AccessTools
            .GetDeclaredMethods(typeof(Player))
            .Concat(AccessTools.GetDeclaredMethods(typeof(Humanoid)))
            .FirstOrDefault(method => method.Name == "StartAttack" && method.GetParameters().Any(parameter => parameter.ParameterType == typeof(bool)));
        private static readonly MethodInfo PlayerInAttackMethod =
            AccessTools.Method(typeof(Player), "InAttack", Type.EmptyTypes) ??
            AccessTools.Method(typeof(Humanoid), "InAttack", Type.EmptyTypes) ??
            AccessTools.Method(typeof(Character), "InAttack", Type.EmptyTypes);
        private static readonly FieldInfo AttackCharacterField = AccessTools.Field(typeof(Attack), "m_character");
        private static readonly FieldInfo SpeedModifierField = AccessTools.Field(typeof(SE_Stats), "m_speedModifier");
        private static readonly FieldInfo MaxAirAltitudeField = AccessTools.Field(typeof(Character), "m_maxAirAltitude");

        private static StatusEffect _decayBuff;
        private static StatusEffect _furyBuff;
        private static StatusEffect _bloodFrenzyBuff;
        private static GameObject _decayAuraVisual;
        private static GameObject _crushFlameVisual;
        private static bool _decayAuraActive;
        private static bool _crushArmed;
        private static bool _crushLeftGround;
        private static bool _crushForcesLoaded;
        private static bool _wasActive;
        private static float _decayTickTimer;
        private static float _bloodFrenzyRemaining;
        private static float _bloodFrenzyCooldown;
        private static float _crushCooldown;
        private static float _crushAirTimer;
        private static float _crushTimer;
        private static float _crushQueuedTimer;
        private static float _crushForceForward = 5f;
        private static float _crushForceUpwards = 7f;
        private static string _crushQueuedFailureReason;
        private static float _furyTimer;
        private static int _furyStacks;
        private static int _furyHitCounter;

        internal static void Update(Player player, float dt)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            if (!IsEnabledAndActive())
            {
                if (_wasActive || _decayAuraActive || _bloodFrenzyRemaining > 0f || _furyStacks > 0 || _crushArmed || _crushTimer > 0f || _crushQueuedTimer > 0f)
                {
                    Clear(player);
                }
                return;
            }

            _wasActive = true;
            UpdateDecayAura(player, dt);
            UpdateFuryBuff(player, dt);
            UpdateBloodFrenzy(player, dt);
            UpdateCrush(player, dt);
            UpdateCooldowns(dt);

            if (!CanReadInput(player))
            {
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.RagnarDecayAuraHotkey))
            {
                ToggleDecayAura(player);
            }

            bool crushPressed = IsShortcutDown(EpicLootRaritySetsPlugin.RagnarCrushHotkey);
            if (crushPressed && HasJumpedForCrush(player))
            {
                TryStartCrush(player, true);
                return;
            }

            if (crushPressed && ShouldQueueCrush(player))
            {
                QueueCrush(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.RagnarBloodFrenzyHotkey))
            {
                TryActivateBloodFrenzy(player);
            }
        }

        internal static void Clear(Player player)
        {
            _decayAuraActive = false;
            _crushArmed = false;
            _crushLeftGround = false;
            _decayTickTimer = 0f;
            _bloodFrenzyRemaining = 0f;
            _bloodFrenzyCooldown = 0f;
            _crushCooldown = 0f;
            _crushAirTimer = 0f;
            _crushTimer = 0f;
            _crushQueuedTimer = 0f;
            _crushQueuedFailureReason = null;
            _furyTimer = 0f;
            _furyStacks = 0;
            _furyHitCounter = 0;
            RemoveDecayBuff(player);
            RemoveFuryBuff(player);
            RemoveBloodFrenzyBuff(player);
            DestroyVisual(ref _decayAuraVisual);
            DestroyVisual(ref _crushFlameVisual);
            _wasActive = false;
        }

        internal static bool TryGetBloodSurgeStacks(out int stacks, out int maxStacks)
        {
            maxStacks = Mathf.Max(1, EpicLootRaritySetsPlugin.RagnarFuryHealEveryAttacks != null ? EpicLootRaritySetsPlugin.RagnarFuryHealEveryAttacks.Value : 3);
            stacks = Mathf.Clamp(_furyHitCounter, 0, maxStacks);
            return IsEnabledAndActive();
        }

        internal static float GetAttackSpeedMultiplier(Attack attack)
        {
            if (!IsEnabledAndActive())
            {
                return 1f;
            }

            Player player = GetAttackPlayer(attack);
            if (player == null || player != Player.m_localPlayer)
            {
                return 1f;
            }

            float multiplier = 1f;
            if (_furyStacks > 0)
            {
                multiplier *= 1f + Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarFuryAttackSpeedPerStack.Value) * _furyStacks;
            }

            if (_bloodFrenzyRemaining > 0f)
            {
                multiplier *= 1f + Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarBloodFrenzyAttackSpeedBonus.Value);
            }

            return multiplier;
        }

        internal static void ModifyIncomingDamage(Player player, HitData hit)
        {
            if (player == null || player != Player.m_localPlayer || hit == null || _bloodFrenzyRemaining <= 0f || !IsEnabledAndActive())
            {
                return;
            }

            hit.m_pushForce = 0f;
            hit.m_staggerMultiplier = 0f;
        }

        internal static void OnPlayerHit(Character target, HitData hit)
        {
            if (target == null || hit == null || !IsEnabledAndActive())
            {
                return;
            }

            Character attacker = null;
            try
            {
                attacker = hit.GetAttacker();
            }
            catch
            {
            }

            Player player = attacker as Player;
            if (player == null || player != Player.m_localPlayer || target == player || !IsEnemyTarget(player, target))
            {
                return;
            }

            if (hit.m_ranged)
            {
                return;
            }

            float damage = TotalDamage(hit.m_damage);
            if (damage <= 0.01f)
            {
                return;
            }

            AddFuryStack(player);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ApplyLifeSteal(player, damage);
            ApplyPeriodicHeal(player);
        }

        private static void ToggleDecayAura(Player player)
        {
            _decayAuraActive = !_decayAuraActive;
            _decayTickTimer = 0f;
            if (_decayAuraActive)
            {
                EnsureDecayAuraVisual(player);
                RefreshDecayBuff(player);
                ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
                ShowMessage(player, "Decay Aura: activa.");
                return;
            }

            RemoveDecayBuff(player);
            DestroyVisual(ref _decayAuraVisual);
            ShowMessage(player, "Decay Aura: desactivada.");
        }

        private static void UpdateDecayAura(Player player, float dt)
        {
            if (!_decayAuraActive)
            {
                return;
            }

            float staminaCost = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarDecayAuraStaminaPerSecond.Value) * dt;
            if (!SpendStamina(player, staminaCost))
            {
                _decayAuraActive = false;
                RemoveDecayBuff(player);
                DestroyVisual(ref _decayAuraVisual);
                ShowMessage(player, "Decay Aura: sin vigor.");
                return;
            }

            RefreshDecayBuff(player);
            EnsureDecayAuraVisual(player);
            _decayTickTimer -= dt;
            if (_decayTickTimer > 0f)
            {
                return;
            }

            _decayTickTimer = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.RagnarDecayAuraTickInterval.Value);
            float amount = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarDecayAuraBaseDamage.Value + ClassSkillManager.GetSkillLevel(player, "Ragnar") * EpicLootRaritySetsPlugin.RagnarDecayAuraDamagePerAxesLevel.Value);
            HitData.DamageTypes damages = new HitData.DamageTypes { m_poison = amount, m_spirit = amount };
            DamageArea(player, player.GetCenterPoint(), EpicLootRaritySetsPlugin.RagnarDecayAuraRadius.Value, damages, ClassSkillManager.Ragnar);
        }

        private static void RefreshDecayBuff(Player player)
        {
            if (player == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateDecayBuff();
            buff.m_ttl = 1.2f;
            StatusEffectIconHelper.Apply(buff, player, RequiredSet);
            buff.m_tooltip = string.Format(
                "Aura de decadencia Ragnar activa.\n\nRadio: {0:0.#}m.\nConsume vigor/s: {1:0.#}.\nDano veneno+espiritu: {2:0.#}+{3:0.##}/nivel de Ragnar.",
                EpicLootRaritySetsPlugin.RagnarDecayAuraRadius.Value,
                EpicLootRaritySetsPlugin.RagnarDecayAuraStaminaPerSecond.Value,
                EpicLootRaritySetsPlugin.RagnarDecayAuraBaseDamage.Value,
                EpicLootRaritySetsPlugin.RagnarDecayAuraDamagePerAxesLevel.Value);
            player.GetSEMan().RemoveStatusEffect(buff.NameHash(), true);
            player.GetSEMan().AddStatusEffect(buff, true, 0, 0f, 0);
        }

        private static StatusEffect GetOrCreateDecayBuff()
        {
            if (_decayBuff == null)
            {
                _decayBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _decayBuff.name = DecayBuffName;
                _decayBuff.m_name = LocalizedText.AbilityName("Decay Aura");
                _decayBuff.m_category = DecayBuffCategory;
                _decayBuff.m_flashIcon = false;
                _decayBuff.m_cooldownIcon = false;
                _decayBuff.m_hidden = false;
            }

            return _decayBuff;
        }

        private static void RemoveDecayBuff(Player player)
        {
            if (player != null && _decayBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_decayBuff.NameHash(), true);
            }
        }

        private static void EnsureDecayAuraVisual(Player player)
        {
            if (player == null || !_decayAuraActive || _decayAuraVisual != null)
            {
                return;
            }

            _decayAuraVisual = NorseVisualEffectBridge.SpawnAttached(
                player,
                Vector3.up * 1.0f,
                Quaternion.identity,
                1.4f,
                "FxDecayAura",
                "FxDarkAura",
                "DecayAura",
                "DarkAura",
                "PoisonCloud",
                "Spirit");
        }

        private static void DestroyVisual(ref GameObject visual)
        {
            if (visual != null)
            {
                UnityEngine.Object.Destroy(visual);
                visual = null;
            }
        }

        private static void DamageArea(Player player, Vector3 center, float radius, HitData.DamageTypes damages, Skills.SkillType skill)
        {
            radius = Mathf.Max(0.1f, radius);
            bool hitAny = false;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character.IsDead() || !IsEnemyTarget(player, character))
                {
                    continue;
                }

                if ((character.GetCenterPoint() - center).sqrMagnitude <= radius * radius)
                {
                    character.Damage(CreateHit(player, damages, character.GetCenterPoint(), character.GetCenterPoint() - center, skill));
                    hitAny = true;
                }
            }

            if (hitAny)
            {
                ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            }
        }

        private static void UpdateFuryBuff(Player player, float dt)
        {
            if (_furyStacks <= 0)
            {
                return;
            }

            _furyTimer -= dt;
            if (_furyTimer > 0f && IsEnabledAndActive())
            {
                RefreshFuryBuff(player);
                return;
            }

            _furyTimer = 0f;
            _furyStacks = 0;
            RemoveFuryBuff(player);
        }

        private static void UpdateBloodFrenzy(Player player, float dt)
        {
            if (_bloodFrenzyRemaining <= 0f)
            {
                return;
            }

            _bloodFrenzyRemaining -= dt;
            if (_bloodFrenzyRemaining > 0f && IsEnabledAndActive())
            {
                RefreshBloodFrenzyBuff(player);
                return;
            }

            _bloodFrenzyRemaining = 0f;
            RemoveBloodFrenzyBuff(player);
            StartBloodFrenzyCooldown(player);
        }

        private static void UpdateCrush(Player player, float dt)
        {
            UpdateQueuedCrush(player, dt);

            if (!_crushArmed)
            {
                return;
            }

            _crushTimer += Mathf.Max(0f, dt);
            if (player == null || player.IsDead() || player.IsSwimming())
            {
                StopCrush();
                return;
            }

            float verticalVelocity = GetVerticalVelocity(player);
            if (!_crushLeftGround)
            {
                if (_crushTimer > 0.12f || verticalVelocity > 0.35f || GetGroundDistance(player) > 0.35f)
                {
                    _crushLeftGround = true;
                    _crushAirTimer = 0f;
                }

                return;
            }

            _crushAirTimer += Mathf.Max(0f, dt);
            if ((_crushAirTimer >= 0.2f && IsOnGround(player)) || _crushAirTimer >= 3f)
            {
                TriggerCrushImpact(player);
                StopCrush();
            }
        }

        private static void UpdateQueuedCrush(Player player, float dt)
        {
            if (_crushQueuedTimer <= 0f)
            {
                return;
            }

            _crushQueuedTimer = Mathf.Max(0f, _crushQueuedTimer - Mathf.Max(0f, dt));
            if (TryStartCrush(player, false))
            {
                _crushQueuedTimer = 0f;
                _crushQueuedFailureReason = null;
                return;
            }

            if (_crushQueuedTimer <= 0f && !string.IsNullOrEmpty(_crushQueuedFailureReason))
            {
                ShowMessage(player, _crushQueuedFailureReason);
                _crushQueuedFailureReason = null;
            }
        }

        private static void StopCrush()
        {
            _crushArmed = false;
            _crushLeftGround = false;
            _crushTimer = 0f;
            _crushAirTimer = 0f;
            DestroyVisual(ref _crushFlameVisual);
        }

        private static void UpdateCooldowns(float dt)
        {
            if (_bloodFrenzyCooldown > 0f)
            {
                _bloodFrenzyCooldown = Mathf.Max(0f, _bloodFrenzyCooldown - dt);
            }

            if (_crushCooldown > 0f)
            {
                _crushCooldown = Mathf.Max(0f, _crushCooldown - dt);
            }
        }

        private static void TryActivateBloodFrenzy(Player player)
        {
            if (_bloodFrenzyRemaining > 0f)
            {
                ShowMessage(player, LocalizedText.Select("Blood Frenzy ya esta activo.", "Blood Frenzy is already active."));
                return;
            }

            if (_bloodFrenzyCooldown > 0f)
            {
                ShowMessage(player, "Blood Frenzy: " + _bloodFrenzyCooldown.ToString("0") + "s cooldown.");
                return;
            }

            float cost = Mathf.Max(0f, GetMaxStamina(player) * Mathf.Clamp01(EpicLootRaritySetsPlugin.RagnarBloodFrenzyStaminaCostFraction.Value));
            if (!SpendStamina(player, cost))
            {
                if (Hud.instance != null)
                {
                    Hud.instance.StaminaBarEmptyFlash();
                }

                ShowMessage(player, LocalizedText.Select("Blood Frenzy: vigor insuficiente.", "Blood Frenzy: not enough stamina."));
                return;
            }

            _bloodFrenzyRemaining = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.RagnarBloodFrenzyDuration.Value);
            RefreshBloodFrenzyBuff(player);
            NorseVisualEffectBridge.SpawnAttached(player, Vector3.up * 1.1f, Quaternion.identity, 1.2f, "vfx_perfectblock", "fx_DvergerMage_Fire_hit", "vfx_Burning");
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, LocalizedText.AbilityName("Blood Frenzy") + ".");
        }

        private static void StartBloodFrenzyCooldown(Player player)
        {
            _bloodFrenzyCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarBloodFrenzyCooldown.Value);
            if (_bloodFrenzyCooldown > 0f)
            {
                AbilityCooldownBuffController.Start(player, "RagnarBloodFrenzy", "Blood Frenzy", _bloodFrenzyCooldown, StatusEffectIconHelper.GetIcon(player, RequiredSet));
            }
        }

        private static bool TryStartCrush(Player player, bool showMessage)
        {
            if (_crushArmed)
            {
                return false;
            }

            if (player == null || !IsEnabledAndActive())
            {
                return false;
            }

            if (!HasJumpedForCrush(player))
            {
                return FailCrush(player, showMessage, "Crush: salta primero.");
            }

            if (!CanStartCrush(player))
            {
                return FailCrush(player, showMessage, "Crush: ocupado.");
            }

            if (_crushCooldown > 0f)
            {
                return FailCrush(player, showMessage, "Ragnar Crush: " + _crushCooldown.ToString("0") + "s cooldown.");
            }

            float stamina = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarCrushStaminaUse.Value);
            if (!SpendStamina(player, stamina))
            {
                if (Hud.instance != null)
                {
                    Hud.instance.StaminaBarEmptyFlash();
                }

                return FailCrush(player, showMessage, LocalizedText.Select("Ragnar Crush: sin vigor.", "Ragnar Crush: not enough stamina."));
            }

            TriggerCrushAnimation(player);
            RemoveSlowFallEffects(player);
            StartSurtImpulse(player);
            DestroyVisual(ref _crushFlameVisual);
            _crushFlameVisual = NorseVisualEffectBridge.SpawnAttached(player, Vector3.up * 0.9f, Quaternion.identity, 3f, "FxFlameWithSoundOnline", "FxFlame", "Flame", "Fire");
            _crushArmed = true;
            _crushLeftGround = false;
            _crushTimer = 0f;
            _crushAirTimer = 0f;
            _crushCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarCrushCooldown.Value);
            AbilityCooldownBuffController.Start(player, "RagnarCrush", "Ragnar Crush", _crushCooldown, StatusEffectIconHelper.GetIcon(player, RequiredSet));
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, LocalizedText.AbilityName("Ragnar Crush") + ".");
            return Physics.Raycast(player.transform.position + Vector3.up * 0.25f, Vector3.down, 0.65f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
        }

        private static void TriggerCrushImpact(Player player)
        {
            float skill = ClassSkillManager.GetSkillLevel(player, RequiredSet);
            float amount = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarCrushBaseDamage.Value + skill * EpicLootRaritySetsPlugin.RagnarCrushDamagePerRagnarLevel.Value);
            HitData.DamageTypes damages = new HitData.DamageTypes { m_blunt = amount, m_fire = amount };
            Vector3 center = player != null ? player.transform.position : Vector3.zero;
            TryProjectGround(center, out center);
            DamageArea(player, center, EpicLootRaritySetsPlugin.RagnarCrushRadius.Value, damages, ClassSkillManager.Ragnar);
            NorseVisualEffectBridge.Spawn(center, Quaternion.identity, "FxFireExplosion2", "FxFireExpansion", "Crush", "Surt", "FxFire", "Fire");

            string reason;
            if (!NorseSurtAbilityBridge.TryBurningGround(player, out reason) && EpicLootRaritySetsPlugin.Log != null)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning("Could not trigger Surt Burning Ground after Ragnar Crush. " + (reason ?? string.Empty));
            }
        }

        private static bool FailCrush(Player player, bool showMessage, string reason)
        {
            _crushQueuedFailureReason = reason;
            if (showMessage)
            {
                ShowMessage(player, reason);
            }

            return false;
        }

        private static void QueueCrush(Player player)
        {
            _crushQueuedTimer = 0.45f;
            _crushQueuedFailureReason = null;
            TryStartCrush(player, false);
        }

        private static bool ShouldQueueCrush(Player player)
        {
            if (player == null || IsOnGround(player))
            {
                return false;
            }

            return GetGroundDistance(player) > 0.2f || GetVerticalVelocity(player) > 0.1f || GetMaxAirAltitude(player) > 0.2f;
        }

        private static bool CanStartCrush(Player player)
        {
            if (player == null || player.IsDead() || player.IsTeleporting() || player.IsSitting() || player.IsSwimming())
            {
                return false;
            }

            if (PlayerInAttackMethod != null)
            {
                try
                {
                    object value = PlayerInAttackMethod.Invoke(player, null);
                    if (value is bool)
                    {
                        return !(bool)value;
                    }
                }
                catch
                {
                }
            }

            return true;
        }

        private static bool HasJumpedForCrush(Player player)
        {
            if (player == null || IsOnGround(player))
            {
                return false;
            }

            return GetMaxAirAltitude(player) >= 2f || GetGroundDistance(player) >= 0.75f || GetVerticalVelocity(player) > 0.35f;
        }

        private static float GetMaxAirAltitude(Player player)
        {
            try
            {
                object value = MaxAirAltitudeField != null ? MaxAirAltitudeField.GetValue(player) : null;
                if (value is float)
                {
                    return (float)value;
                }
            }
            catch
            {
            }

            return 0f;
        }

        private static float GetGroundDistance(Player player)
        {
            if (player == null)
            {
                return float.MaxValue;
            }

            RaycastHit hit;
            Vector3 origin = player.transform.position + Vector3.up * 0.5f;
            if (Physics.Raycast(origin, Vector3.down, out hit, 8f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
            {
                return Mathf.Max(0f, hit.distance - 0.5f);
            }

            return float.MaxValue;
        }

        private static float GetVerticalVelocity(Player player)
        {
            if (player == null)
            {
                return 0f;
            }

            try
            {
                return player.GetVelocity().y;
            }
            catch
            {
            }

            Rigidbody body = player.GetComponent<Rigidbody>();
            return body != null ? body.velocity.y : 0f;
        }

        private static void TriggerCrushAnimation(Player player)
        {
            TriggerSecondaryAttackIfNeeded(player, "knife_secondary", 0f);
        }

        private static void TriggerSecondaryAttackIfNeeded(Player player, string animationOverride, float staminaOverride)
        {
            if (player == null || PlayerStartAttackMethod == null)
            {
                return;
            }

            ItemDrop.ItemData weapon = player.GetCurrentWeapon();
            ItemDrop.ItemData.SharedData shared = weapon != null ? weapon.m_shared : null;
            Attack secondaryAttack = shared != null ? shared.m_secondaryAttack : null;
            string originalAnimation = null;
            float originalStamina = 0f;
            bool overrideShared = secondaryAttack != null && !string.IsNullOrEmpty(animationOverride);

            try
            {
                if (overrideShared)
                {
                    originalAnimation = secondaryAttack.m_attackAnimation;
                    originalStamina = secondaryAttack.m_attackStamina;
                    secondaryAttack.m_attackAnimation = animationOverride;
                    secondaryAttack.m_attackStamina = staminaOverride;
                }

                ParameterInfo[] parameters = PlayerStartAttackMethod.GetParameters();
                object[] args = new object[parameters.Length];
                for (int i = 0; i < parameters.Length; i++)
                {
                    Type type = parameters[i].ParameterType;
                    if (type == typeof(bool))
                    {
                        args[i] = true;
                    }
                    else if (typeof(Character).IsAssignableFrom(type))
                    {
                        args[i] = null;
                    }
                    else
                    {
                        args[i] = type.IsValueType ? Activator.CreateInstance(type) : null;
                    }
                }

                PlayerStartAttackMethod.Invoke(player, args);
            }
            catch
            {
            }
            finally
            {
                if (overrideShared)
                {
                    secondaryAttack.m_attackAnimation = originalAnimation;
                    secondaryAttack.m_attackStamina = originalStamina;
                }
            }
        }

        private static void StartSurtImpulse(Player player)
        {
            if (player == null)
            {
                return;
            }

            LoadCrushForces();
            Rigidbody body = player.GetComponent<Rigidbody>();
            if (body == null)
            {
                return;
            }

            Vector3 velocity = body.velocity;
            velocity += player.transform.forward * _crushForceForward + Vector3.up * _crushForceUpwards + Vector3.up * (0f - velocity.y);
            body.velocity = velocity;
            body.WakeUp();
        }

        private static void LoadCrushForces()
        {
            if (_crushForcesLoaded)
            {
                return;
            }

            _crushForcesLoaded = true;
            _crushForceForward = ReadNorseCrushFloat("Force Forward", 5f);
            _crushForceUpwards = ReadNorseCrushFloat("Force Upwards", 7f);
        }

        private static float ReadNorseCrushFloat(string key, float fallback)
        {
            try
            {
                string path = Path.Combine(Paths.ConfigPath, "NorseDemigods.cfg");
                if (!File.Exists(path))
                {
                    return fallback;
                }

                bool inSection = false;
                foreach (string rawLine in File.ReadAllLines(path))
                {
                    string line = rawLine.Trim();
                    if (line.Length == 0 || line.StartsWith("#"))
                    {
                        continue;
                    }

                    if (line.StartsWith("[") && line.EndsWith("]"))
                    {
                        inSection = string.Equals(line, "[Ability Crush]", StringComparison.OrdinalIgnoreCase);
                        continue;
                    }

                    if (!inSection || !line.StartsWith(key + " =", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    string value = line.Substring(line.IndexOf('=') + 1).Trim();
                    float result;
                    if (float.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out result) ||
                        float.TryParse(value, NumberStyles.Float, CultureInfo.CurrentCulture, out result) ||
                        float.TryParse(value.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out result))
                    {
                        return result;
                    }
                }
            }
            catch
            {
            }

            return fallback;
        }

        private static void RemoveSlowFallEffects(Player player)
        {
            RemoveNorseStatus(player, "s_statusEffectSlowFall");
            RemoveNorseStatus(player, "s_statusEffectJCGliding");
            RemoveNorseStatus(player, "s_statusEffectDarkWings");
        }

        private static void RemoveNorseStatus(Player player, string fieldName)
        {
            if (player == null)
            {
                return;
            }

            try
            {
                Type cacheType = AccessTools.TypeByName("NorseDemigods.Cache");
                FieldInfo field = AccessTools.Field(cacheType, fieldName);
                if (field == null)
                {
                    return;
                }

                object rawValue = field.GetValue(null);
                if (!(rawValue is int))
                {
                    return;
                }

                int statusHash = (int)rawValue;
                SEMan seMan = player.GetSEMan();
                if (seMan != null && seMan.HaveStatusEffect(statusHash))
                {
                    seMan.RemoveStatusEffect(statusHash, false);
                }
            }
            catch
            {
            }
        }

        private static bool TryProjectGround(Vector3 probe, out Vector3 point)
        {
            RaycastHit[] hits = Physics.RaycastAll(probe + Vector3.up * 8f, Vector3.down, 20f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            Array.Sort(hits, (left, right) => left.distance.CompareTo(right.distance));
            foreach (RaycastHit hit in hits)
            {
                if (hit.collider == null || hit.collider.GetComponentInParent<Character>() != null)
                {
                    continue;
                }

                point = hit.point + Vector3.up * 0.05f;
                return true;
            }

            point = probe;
            return false;
        }

        private static void AddFuryStack(Player player)
        {
            int maxStacks = Mathf.Max(1, EpicLootRaritySetsPlugin.RagnarFuryMaxStacks.Value);
            _furyStacks = Mathf.Clamp(_furyStacks + 1, 1, maxStacks);
            _furyTimer = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.RagnarFuryDuration.Value);
            RefreshFuryBuff(player);
        }

        private static void ApplyLifeSteal(Player player, float damage)
        {
            float lifeSteal = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarFuryLifeStealPerStack.Value) * _furyStacks;
            float healing = Mathf.Max(0f, damage * lifeSteal);
            if (healing > 0.01f)
            {
                player.Heal(healing, true);
            }
        }

        private static void ApplyPeriodicHeal(Player player)
        {
            int every = Mathf.Max(1, EpicLootRaritySetsPlugin.RagnarFuryHealEveryAttacks.Value);
            _furyHitCounter++;
            if (_furyHitCounter < every)
            {
                return;
            }

            _furyHitCounter = 0;
            float healing = Mathf.Max(0f, player.GetMaxHealth() * EpicLootRaritySetsPlugin.RagnarFuryHealMaxHealthFraction.Value);
            if (healing > 0.01f)
            {
                player.Heal(healing, true);
                ShowMessage(player, string.Format(LocalizedText.Select("{0}: +{1:0.#} salud.", "{0}: +{1:0.#} health."), LocalizedText.AbilityName("Blood Surge"), healing));
            }
        }

        private static void RefreshFuryBuff(Player player)
        {
            if (player == null || _furyStacks <= 0)
            {
                return;
            }

            StatusEffect buff = GetOrCreateFuryBuff();
            int maxStacks = Mathf.Max(1, EpicLootRaritySetsPlugin.RagnarFuryMaxStacks.Value);
            float attackSpeed = EpicLootRaritySetsPlugin.RagnarFuryAttackSpeedPerStack.Value * _furyStacks * 100f;
            float lifeSteal = EpicLootRaritySetsPlugin.RagnarFuryLifeStealPerStack.Value * _furyStacks * 100f;
            buff.m_name = string.Format("{0} {1}/{2}", LocalizedText.AbilityName("Ragnar Fury"), _furyStacks, maxStacks);
            buff.m_ttl = Mathf.Max(0.1f, _furyTimer + 0.1f);
            StatusEffectIconHelper.Apply(buff, player, RequiredSet);
            buff.m_tooltip = string.Format(
                "Pasiva de Ragnar activa.\n\nCargas: {0}/{1}.\nVelocidad de ataque: +{2:0.#}%.\nRobo de vida: {3:0.##}% del dano de golpe.\nOleada de sangre: cada {4} golpes cuerpo a cuerpo cura {5:0.#}% de salud maxima.\nTiempo restante: {6:0.#}s.",
                _furyStacks,
                maxStacks,
                attackSpeed,
                lifeSteal,
                Mathf.Max(1, EpicLootRaritySetsPlugin.RagnarFuryHealEveryAttacks.Value),
                EpicLootRaritySetsPlugin.RagnarFuryHealMaxHealthFraction.Value * 100f,
                Mathf.Max(0f, _furyTimer));
            SEMan seMan = player.GetSEMan();
            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, _furyStacks, 0f, 0);
        }

        private static StatusEffect GetOrCreateFuryBuff()
        {
            if (_furyBuff == null)
            {
                _furyBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _furyBuff.name = FuryBuffName;
                _furyBuff.m_category = FuryBuffCategory;
                _furyBuff.m_flashIcon = false;
                _furyBuff.m_cooldownIcon = true;
                _furyBuff.m_hidden = false;
            }

            return _furyBuff;
        }

        private static void RefreshBloodFrenzyBuff(Player player)
        {
            if (player == null || _bloodFrenzyRemaining <= 0f)
            {
                return;
            }

            StatusEffect buff = GetOrCreateBloodFrenzyBuff();
            float attack = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarBloodFrenzyAttackSpeedBonus.Value) * 100f;
            float speed = Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarBloodFrenzyMoveSpeedBonus.Value) * 100f;
            buff.m_name = LocalizedText.AbilityName("Blood Frenzy");
            buff.m_ttl = Mathf.Max(0.1f, _bloodFrenzyRemaining + 0.1f);
            StatusEffectIconHelper.Apply(buff, player, RequiredSet);
            buff.m_tooltip = string.Format(
                LocalizedText.Select(
                    "Frenesi de sangre de Ragnar.\n\nVelocidad de ataque: +{0:0.#}%.\nVelocidad de movimiento: +{1:0.#}%.\nInmovible: ignora empuje y stagger recibidos.\nTiempo restante: {2:0.#}s.",
                    "Ragnar Blood Frenzy.\n\nAttack speed: +{0:0.#}%.\nMovement speed: +{1:0.#}%.\nImmovable: ignores incoming push and stagger.\nTime remaining: {2:0.#}s."),
                attack,
                speed,
                Mathf.Max(0f, _bloodFrenzyRemaining));

            if (SpeedModifierField != null)
            {
                SpeedModifierField.SetValue(buff, Mathf.Max(0f, EpicLootRaritySetsPlugin.RagnarBloodFrenzyMoveSpeedBonus.Value));
            }

            SEMan seMan = player.GetSEMan();
            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, 0, 0f, 0);
        }

        private static StatusEffect GetOrCreateBloodFrenzyBuff()
        {
            if (_bloodFrenzyBuff == null)
            {
                _bloodFrenzyBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _bloodFrenzyBuff.name = BloodFrenzyBuffName;
                _bloodFrenzyBuff.m_category = BloodFrenzyBuffCategory;
                _bloodFrenzyBuff.m_flashIcon = false;
                _bloodFrenzyBuff.m_cooldownIcon = true;
                _bloodFrenzyBuff.m_hidden = false;
            }

            return _bloodFrenzyBuff;
        }

        private static void RemoveFuryBuff(Player player)
        {
            if (player != null && _furyBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_furyBuff.NameHash(), true);
            }
        }

        private static void RemoveBloodFrenzyBuff(Player player)
        {
            if (player != null && _bloodFrenzyBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_bloodFrenzyBuff.NameHash(), true);
            }
        }

        private static float TotalDamage(HitData.DamageTypes damages)
        {
            return damages.m_blunt + damages.m_slash + damages.m_pierce + damages.m_chop + damages.m_pickaxe + damages.m_fire + damages.m_frost + damages.m_lightning + damages.m_poison + damages.m_spirit;
        }

        private static Player GetAttackPlayer(Attack attack)
        {
            if (attack == null || AttackCharacterField == null)
            {
                return null;
            }

            try
            {
                return AttackCharacterField.GetValue(attack) as Player;
            }
            catch
            {
                return null;
            }
        }

        private static HitData CreateHit(Player player, HitData.DamageTypes damages, Vector3 point, Vector3 direction, Skills.SkillType skill)
        {
            HitData hit = new HitData
            {
                m_damage = damages,
                m_skill = skill,
                m_skillLevel = player != null ? player.GetSkillLevel(skill) : 0f,
                m_ranged = true,
                m_dodgeable = true,
                m_blockable = true,
                m_backstabBonus = 1f,
                m_staggerMultiplier = 1f,
                m_point = point,
                m_dir = direction.sqrMagnitude > 0.001f ? direction.normalized : Vector3.forward
            };

            if (player != null)
            {
                hit.SetAttacker(player);
            }

            return hit;
        }

        private static bool SpendStamina(Player player, float amount)
        {
            if (player == null || amount <= 0f)
            {
                return true;
            }

            float current = GetStamina(player);
            if (current >= 0f && current < amount)
            {
                return false;
            }

            try
            {
                if (UseStaminaMethod != null)
                {
                    UseStaminaMethod.Invoke(player, new object[] { amount });
                    return true;
                }
            }
            catch
            {
            }

            return true;
        }

        private static float GetStamina(Player player)
        {
            try
            {
                if (GetStaminaMethod != null)
                {
                    return Convert.ToSingle(GetStaminaMethod.Invoke(player, null));
                }
            }
            catch
            {
            }

            return -1f;
        }

        private static float GetMaxStamina(Player player)
        {
            try
            {
                if (GetMaxStaminaMethod != null)
                {
                    return Mathf.Max(0f, Convert.ToSingle(GetMaxStaminaMethod.Invoke(player, null)));
                }
            }
            catch
            {
            }

            float current = GetStamina(player);
            return current >= 0f ? current : 100f;
        }

        private static bool IsEnabledAndActive()
        {
            return EpicLootRaritySetsPlugin.EnableRagnarAbilities != null &&
                   EpicLootRaritySetsPlugin.EnableRagnarAbilities.Value &&
                   SetActivationBuffController.HasActiveSet(RequiredSet);
        }

        private static bool CanReadInput(Player player)
        {
            return !player.IsDead() && !player.IsTeleporting() && !IsAnyMenuOpen();
        }

        private static bool IsOnGround(Player player)
        {
            if (player == null)
            {
                return false;
            }

            if (PlayerIsOnGroundMethod != null)
            {
                try
                {
                    object value = PlayerIsOnGroundMethod.Invoke(player, null);
                    if (value is bool)
                    {
                        return (bool)value;
                    }
                }
                catch
                {
                }
            }

            return true;
        }

        private static bool IsShortcutDown(ConfigEntry<KeyboardShortcut> entry)
        {
            if (entry == null)
            {
                return false;
            }

            KeyboardShortcut shortcut = entry.Value;
            if (shortcut.IsDown())
            {
                return true;
            }

            KeyCode mainKey = shortcut.MainKey;
            if (mainKey == KeyCode.None || !Input.GetKeyDown(mainKey))
            {
                return false;
            }

            foreach (KeyCode modifier in shortcut.Modifiers)
            {
                if (!Input.GetKey(modifier))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool IsAnyMenuOpen()
        {
            return (InventoryGui.instance != null && InventoryGui.IsVisible()) ||
                   (Menu.instance != null && Menu.IsVisible()) ||
                   (TextInput.instance != null && TextInput.IsVisible()) ||
                   (Chat.instance != null && Chat.instance.HasFocus()) ||
                   (Minimap.instance != null && Minimap.IsOpen());
        }

        private static bool IsEnemyTarget(Player player, Character target)
        {
            if (player == null || target == null || target == player)
            {
                return false;
            }

            if (CharacterTargeting.IsPlayerPvPEnemy(player, target))
            {
                return true;
            }

            if (target is Player)
            {
                return false;
            }

            if (BaseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = BaseAIIsEnemyMethod.Invoke(null, new object[] { player, target });
                    if (value is bool)
                    {
                        return (bool)value;
                    }
                }
                catch
                {
                }
            }

            return true;
        }

        private static void ShowMessage(Player player, string message)
        {
            if (player != null)
            {
                player.Message(MessageHud.MessageType.Center, message, 0, null, false);
            }
        }
    }

    internal static class HeimdallAbilityController
    {
        private const string RequiredSet = "Heimdall";
        private const string ArmorBuffName = "FranHeimdallBlockArmor";
        private const string ArmorBuffCategory = "FranHeimdallBlockArmor";
        private const string LightningStormBuffName = "FranHeimdallLightningStorm";
        private const string LightningStormBuffCategory = "FranHeimdallLightningStorm";
        private const string LightningStormSlowBuffName = "FranHeimdallLightningStormSlow";
        private const string LightningStormSlowBuffCategory = "FranHeimdallLightningStormSlow";
        private const string StoneShieldBuffName = "FranHeimdallStoneShield";
        private const string StoneShieldBuffCategory = "FranHeimdallStoneShield";

        private static readonly MethodInfo BaseAIIsEnemyMethod = AccessTools.Method(typeof(BaseAI), "IsEnemy", new[] { typeof(Character), typeof(Character) });
        private static readonly MethodInfo GetStaminaMethod = AccessTools.Method(typeof(Player), "GetStamina", Type.EmptyTypes) ?? AccessTools.Method(typeof(Character), "GetStamina", Type.EmptyTypes);
        private static readonly MethodInfo UseStaminaMethod = AccessTools.Method(typeof(Player), "UseStamina", new[] { typeof(float) }) ?? AccessTools.Method(typeof(Character), "UseStamina", new[] { typeof(float) });
        private static readonly MethodInfo IsBlockingMethod = AccessTools.Method(typeof(Character), "IsBlocking", Type.EmptyTypes) ?? AccessTools.Method(typeof(Player), "IsBlocking", Type.EmptyTypes);
        private static readonly MethodInfo MonsterAISetTargetMethod = AccessTools.Method(typeof(MonsterAI), "SetTarget", new[] { typeof(Character) });
        private static readonly MethodInfo BaseAISetAlertedMethod = AccessTools.Method(typeof(BaseAI), "SetAlerted", new[] { typeof(bool) });
        private static readonly MethodInfo BaseAIAlertMethod = AccessTools.Method(typeof(BaseAI), "Alert", Type.EmptyTypes);
        private static readonly MethodInfo GetCurrentBlockerMethod =
            AccessTools.Method(typeof(Humanoid), "GetCurrentBlocker", Type.EmptyTypes) ??
            AccessTools.Method(typeof(Player), "GetCurrentBlocker", Type.EmptyTypes);
        private static readonly FieldInfo HitBlockedField = AccessTools.Field(typeof(HitData), "m_blocked");
        private static readonly FieldInfo StatusEffectTimeField = AccessTools.Field(typeof(StatusEffect), "m_time");
        private static readonly FieldInfo SpeedModifierField = AccessTools.Field(typeof(SE_Stats), "m_speedModifier");

        private static readonly Dictionary<HitData, float> PendingBlockDamage = new Dictionary<HitData, float>();
        private static StatusEffect _armorBuff;
        private static StatusEffect _lightningStormBuff;
        private static StatusEffect _lightningStormSlowBuff;
        private static StatusEffect _stoneShieldBuff;
        private static GameObject _lightningStormVisual;
        private static GameObject _stoneShieldVisual;
        private static GameObject _harpoonRopeVisual;
        private static int _armorStacks;
        private static float _armorTimer;
        private static float _waterSphereCooldown;
        private static float _lightningStormCooldown;
        private static float _lightningStormRemaining;
        private static float _lightningStormTickTimer;
        private static Vector3 _lightningStormCenter;
        private static float _stoneShieldCooldown;
        private static float _stoneShieldRemaining;
        private static float _harpoonCooldown;
        private static bool _reflecting;
        private static int _lastSuccessfulBlockFrame = -1;
        private static float _lastSuccessfulBlockTime = -999f;
        private static float _lastObservedStamina = -1f;
        private static float _blockStaminaDropLockout;
        private static float _recentBlockableDamageTimer;
        private static bool _loggedHarpoonProjectileFailure;
        private static bool _loggedHarpoonRopeFailure;
        private static bool _wasActive;

        internal static void Update(Player player, float dt)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            _lightningStormCooldown = Mathf.Max(0f, _lightningStormCooldown - dt);
            _waterSphereCooldown = Mathf.Max(0f, _waterSphereCooldown - dt);
            _stoneShieldCooldown = Mathf.Max(0f, _stoneShieldCooldown - dt);
            _harpoonCooldown = Mathf.Max(0f, _harpoonCooldown - dt);
            _blockStaminaDropLockout = Mathf.Max(0f, _blockStaminaDropLockout - dt);
            _recentBlockableDamageTimer = Mathf.Max(0f, _recentBlockableDamageTimer - dt);
            float currentStamina = GetStamina(player);
            UpdateArmorBuff(player, dt);
            NorseWaterSphereBridge.Update(dt);

            if (!IsEnabledAndActive())
            {
                if (_wasActive || _armorStacks > 0 || _lightningStormRemaining > 0f || _stoneShieldRemaining > 0f ||
                    _lightningStormVisual != null || _stoneShieldVisual != null || _harpoonRopeVisual != null)
                {
                    Clear(player);
                }
                _lastObservedStamina = currentStamina;
                return;
            }

            _wasActive = true;
            UpdateLightningStorm(player, dt);
            UpdateStoneShield(player, dt);

            if (!CanReadInput(player))
            {
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.HeimdallHarpoonHotkey) &&
                IsHarpoonCastModifierHeld(player))
            {
                TryAbyssalHarpoon(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.HeimdallWaterSphereHotkey) &&
                SetAbilityInput.IsBlockHeld())
            {
                TryWaterSphere(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.HeimdallLightningStormHotkey))
            {
                TryLightningStorm(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.HeimdallStoneShieldHotkey))
            {
                TryStoneShield(player);
            }
        }

        internal static void Clear(Player player)
        {
            _armorStacks = 0;
            _armorTimer = 0f;
            _waterSphereCooldown = 0f;
            _lightningStormRemaining = 0f;
            _lightningStormTickTimer = 0f;
            _lightningStormCenter = Vector3.zero;
            _stoneShieldRemaining = 0f;
            _lastObservedStamina = -1f;
            _blockStaminaDropLockout = 0f;
            _recentBlockableDamageTimer = 0f;
            _lastSuccessfulBlockTime = -999f;
            if (player != null)
            {
                if (_armorBuff != null) player.GetSEMan().RemoveStatusEffect(_armorBuff.NameHash(), true);
                if (_lightningStormBuff != null) player.GetSEMan().RemoveStatusEffect(_lightningStormBuff.NameHash(), true);
                if (_stoneShieldBuff != null) player.GetSEMan().RemoveStatusEffect(_stoneShieldBuff.NameHash(), true);
            }
            DestroyVisual(ref _lightningStormVisual);
            DestroyVisual(ref _stoneShieldVisual);
            DestroyVisual(ref _harpoonRopeVisual);
            _wasActive = false;
        }

        internal static void ModifyIncomingDamage(Player player, HitData hit)
        {
            if (player == null || hit == null || player != Player.m_localPlayer || _reflecting || !IsEnabledAndActive())
            {
                return;
            }

            if (CanAcceptBlockSource(player, hit))
            {
                _recentBlockableDamageTimer = 0.6f;
            }

            ApplyGuardDamageReduction(player, hit);

            if (_stoneShieldRemaining > 0f)
            {
                float before = TotalDamage(hit.m_damage);
                float reduction = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallStoneShieldBaseReduction.Value + ClassSkillManager.GetSkillLevel(player, "Heimdall") * EpicLootRaritySetsPlugin.HeimdallStoneShieldReductionPerBlockingLevel.Value);
                ReduceFlatDamage(ref hit.m_damage, reduction);
                float mitigated = Mathf.Max(0f, before - TotalDamage(hit.m_damage));
                ReflectMitigatedDamage(player, hit, mitigated);
            }
        }

        internal static void OnDamaged(Player player, HitData hit)
        {
            if (player == null || player != Player.m_localPlayer || hit == null || !IsEnabledAndActive())
            {
                return;
            }

            OnDamageTaken(player, hit);
        }

        internal static void TrackIncomingBlockCandidate(Player player, HitData hit)
        {
            if (!CanEvaluateBlock(player, hit))
            {
                return;
            }

            PendingBlockDamage[hit] = TotalDamage(hit.m_damage);
        }

        internal static void DetectApplyDamageBlock(Player player, HitData hit)
        {
            if (!CanEvaluateBlock(player, hit))
            {
                return;
            }

            float before;
            bool hadBefore = PendingBlockDamage.TryGetValue(hit, out before);
            if (hadBefore)
            {
                PendingBlockDamage.Remove(hit);
            }

            float after = TotalDamage(hit.m_damage);
            if (hadBefore && before > 0.01f && after <= before * 0.98f)
            {
                OnSuccessfulBlock(player);
                return;
            }

            if (!hadBefore && IsBlocked(player, hit))
            {
                OnSuccessfulBlock(player);
            }
        }

        internal static void OnBlockAttackResult(Player player, HitData hit, bool success)
        {
            if (success && CanAcceptBlockSource(player, hit))
            {
                OnSuccessfulBlock(player);
            }
        }

        internal static void OnSuccessfulBlock(Player player)
        {
            if (player == null || player != Player.m_localPlayer || !IsEnabledAndActive())
            {
                return;
            }

            if (_lastSuccessfulBlockFrame == Time.frameCount)
            {
                return;
            }

            if (Time.time - _lastSuccessfulBlockTime < 0.35f)
            {
                return;
            }

            _lastSuccessfulBlockFrame = Time.frameCount;
            _lastSuccessfulBlockTime = Time.time;
            _blockStaminaDropLockout = Mathf.Max(_blockStaminaDropLockout, 0.35f);
        }

        internal static void ModifyOutgoingDamage(HitData hit)
        {
        }

        internal static void ApplyBlockPower(ItemDrop.ItemData item, ref float result)
        {
            Player player = Player.m_localPlayer;
            if (player == null || item == null || _armorStacks <= 0 || !IsEnabledAndActive())
            {
                return;
            }

            ItemDrop.ItemData blocker = GetCurrentBlockerItem(player);
            if (blocker != item)
            {
                return;
            }

            result *= 1f + Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallBlockPowerBonusPerStack.Value) * Mathf.Clamp(_armorStacks, 0, GetArmorMaxStacks());
        }

        private static void OnDamageTaken(Player player, HitData hit)
        {
            if (player == null || hit == null || player != Player.m_localPlayer || !IsEnabledAndActive())
            {
                return;
            }

            if (!CanAcceptGuardSource(player, hit) || TotalDamage(hit.m_damage) <= 0.01f)
            {
                return;
            }

            _armorStacks = Mathf.Clamp(_armorStacks + 1, 1, GetArmorMaxStacks());
            _armorTimer = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HeimdallBlockArmorDuration.Value);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            NorseVisualEffectBridge.SpawnAtPlayer(player, "FxStoneHit", "Block");
            RefreshArmorBuff(player, true);
        }

        private static void ApplyGuardDamageReduction(Player player, HitData hit)
        {
            if (player == null || hit == null || _armorStacks <= 0 || !IsEnabledAndActive())
            {
                return;
            }

            if (!CanAcceptGuardSource(player, hit))
            {
                return;
            }

            float reduction = Mathf.Clamp01(EpicLootRaritySetsPlugin.HeimdallBlockArmorBonusPerStack.Value * Mathf.Clamp(_armorStacks, 0, GetArmorMaxStacks()));
            if (reduction <= 0f)
            {
                return;
            }

            ScaleAllDamage(ref hit.m_damage, Mathf.Max(0f, 1f - reduction));
        }

        private static void UpdateArmorBuff(Player player, float dt)
        {
            if (_armorStacks <= 0)
            {
                return;
            }

            _armorTimer -= dt;
            if (_armorTimer <= 0f || !IsEnabledAndActive())
            {
                _armorStacks = 0;
                _armorTimer = 0f;
                if (player != null && _armorBuff != null)
                {
                    player.GetSEMan().RemoveStatusEffect(_armorBuff.NameHash(), true);
                }
                return;
            }

            RefreshArmorBuff(player, false);
        }

        private static void UpdateStoneShield(Player player, float dt)
        {
            if (_stoneShieldRemaining <= 0f)
            {
                return;
            }

            _stoneShieldRemaining -= dt;
            if (_stoneShieldRemaining <= 0f)
            {
                RemoveStoneShieldBuff(player);
                return;
            }

            EnsureStoneShieldVisual(player);
            RefreshStoneShieldBuff(player);
        }

        private static void TryWaterSphere(Player player)
        {
            if (_waterSphereCooldown > 0f)
            {
                ShowMessage(player, string.Format("Water Sphere: {0:0}s cooldown.", _waterSphereCooldown));
                return;
            }

            float staminaUse = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallWaterSphereStaminaUse.Value);
            float currentStamina = GetStamina(player);
            if (currentStamina >= 0f && currentStamina < staminaUse)
            {
                if (Hud.instance != null)
                {
                    Hud.instance.StaminaBarEmptyFlash();
                }

                ShowMessage(player, LocalizedText.Select("Water Sphere: no tienes vigor suficiente.", "Water Sphere: not enough stamina."));
                return;
            }

            string failureReason;
            if (!NorseWaterSphereBridge.TryWaterSphere(
                    player,
                    ClassSkillManager.Heimdall,
                    RequiredSet,
                    RequiredSet,
                    EpicLootRaritySetsPlugin.HeimdallWaterSphereMaxDuration.Value,
                    EpicLootRaritySetsPlugin.HeimdallWaterSpherePullRadius.Value,
                    EpicLootRaritySetsPlugin.HeimdallWaterSpherePullForce.Value,
                    out failureReason))
            {
                ShowMessage(player, failureReason);
                return;
            }

            SpendStamina(player, staminaUse);
            _waterSphereCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallWaterSphereCooldown.Value);
            AbilityCooldownBuffController.Start(player, "HeimdallWaterSphere", "Water Sphere", _waterSphereCooldown, null);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, LocalizedText.AbilityName("Water Sphere") + ".");
        }

        private static void TryLightningStorm(Player player)
        {
            if (_lightningStormRemaining > 0f)
            {
                ShowMessage(player, "Lightning Storm: activa.");
                return;
            }

            if (_lightningStormCooldown > 0f)
            {
                ShowMessage(player, string.Format("Lightning Storm: {0:0}s cooldown.", _lightningStormCooldown));
                return;
            }

            Vector3 center;
            if (!TryFindLightningStormPoint(player, out center))
            {
                ShowMessage(player, "Lightning Storm: sin punto.");
                return;
            }

            _lightningStormCenter = center;
            _lightningStormRemaining = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HeimdallLightningStormDuration.Value);
            _lightningStormTickTimer = 0f;
            _lightningStormCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallLightningStormCooldown.Value);
            EnsureLightningStormVisual(player);
            SpawnLightningStormPulse(_lightningStormCenter, Mathf.Max(0.5f, _lightningStormRemaining));
            RefreshLightningStormBuff(player);
            AbilityCooldownBuffController.Start(player, "HeimdallLightningStorm", "Lightning Storm", _lightningStormCooldown, null);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, "Lightning Storm.");
        }

        private static void UpdateLightningStorm(Player player, float dt)
        {
            if (_lightningStormRemaining <= 0f)
            {
                return;
            }

            _lightningStormRemaining -= dt;
            if (_lightningStormRemaining <= 0f)
            {
                RemoveLightningStormBuff(player);
                DestroyVisual(ref _lightningStormVisual);
                _lightningStormCenter = Vector3.zero;
                return;
            }

            EnsureLightningStormVisual(player);
            RefreshLightningStormBuff(player);
            _lightningStormTickTimer -= dt;
            if (_lightningStormTickTimer > 0f)
            {
                return;
            }

            _lightningStormTickTimer = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HeimdallLightningStormTickInterval.Value);
            TickLightningStorm(player);
        }

        private static void TickLightningStorm(Player player)
        {
            if (player == null)
            {
                return;
            }

            float radius = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HeimdallLightningStormRadius.Value);
            float amount = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallLightningStormBaseDamage.Value + ClassSkillManager.GetSkillLevel(player, "Heimdall") * EpicLootRaritySetsPlugin.HeimdallLightningStormDamagePerBlockingLevel.Value);
            HitData.DamageTypes damages = new HitData.DamageTypes { m_lightning = amount };
            Vector3 center = _lightningStormCenter;
            if (center == Vector3.zero)
            {
                center = player.GetCenterPoint();
            }

            SpawnLightningStormPulse(center, 1.35f);
            bool hitAny = false;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character.IsDead() || !IsEnemyTarget(player, character))
                {
                    continue;
                }

                if ((character.GetCenterPoint() - center).sqrMagnitude > radius * radius)
                {
                    continue;
                }

                RedirectThreatToPlayer(character, player);
                character.Damage(CreateHit(player, damages, character.GetCenterPoint(), character.GetCenterPoint() - center, ClassSkillManager.Heimdall));
                ApplyLightningStormSlow(character);
                NorseVisualEffectBridge.Spawn(character.GetCenterPoint(), Quaternion.identity, 1.25f, "FxLightning", "Lightning", "Thunder", "Thor");
                hitAny = true;
            }

            if (hitAny)
            {
                ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            }
        }

        private static void ApplyLightningStormSlow(Character target)
        {
            if (target == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateLightningStormSlowBuff();
            SEMan seMan = target.GetSEMan();
            if (seMan == null)
            {
                return;
            }

            seMan.RemoveStatusEffect(buff.NameHash(), true);
            seMan.AddStatusEffect(buff, true, 0, 0f, 0);
        }

        private static StatusEffect GetOrCreateLightningStormSlowBuff()
        {
            if (_lightningStormSlowBuff == null)
            {
                _lightningStormSlowBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _lightningStormSlowBuff.name = LightningStormSlowBuffName;
                _lightningStormSlowBuff.m_name = LocalizedText.Select("Ralentizacion de tormenta", "Storm Slow");
                _lightningStormSlowBuff.m_category = LightningStormSlowBuffCategory;
                _lightningStormSlowBuff.m_flashIcon = false;
                _lightningStormSlowBuff.m_cooldownIcon = true;
                _lightningStormSlowBuff.m_hidden = false;
            }

            float slow = Mathf.Clamp01(EpicLootRaritySetsPlugin.HeimdallLightningStormSlow != null ? EpicLootRaritySetsPlugin.HeimdallLightningStormSlow.Value : 0.3f);
            float duration = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HeimdallLightningStormSlowDuration != null ? EpicLootRaritySetsPlugin.HeimdallLightningStormSlowDuration.Value : 6f);
            _lightningStormSlowBuff.m_ttl = duration;
            _lightningStormSlowBuff.m_tooltip = string.Format(
                LocalizedText.Select(
                    "Ralentizado por Tormenta de rayos.\n\nVelocidad: -{0:0.#}%.\nDuracion: {1:0.#}s.",
                    "Slowed by Lightning Storm.\n\nMovement speed: -{0:0.#}%.\nDuration: {1:0.#}s."),
                slow * 100f,
                duration);
            StatusEffectIconHelper.Apply(_lightningStormSlowBuff, Player.m_localPlayer, RequiredSet);
            if (SpeedModifierField != null)
            {
                try
                {
                    SpeedModifierField.SetValue(_lightningStormSlowBuff, -slow);
                }
                catch
                {
                }
            }

            return _lightningStormSlowBuff;
        }

        private static bool TryFindLightningStormPoint(Player player, out Vector3 point)
        {
            point = player != null ? player.transform.position : Vector3.zero;
            if (player == null)
            {
                return false;
            }

            float range = Mathf.Max(18f, EpicLootRaritySetsPlugin.HeimdallLightningStormRadius.Value * 3f);
            Transform originTransform = GameCamera.instance != null ? GameCamera.instance.transform : player.transform;
            RaycastHit hit;
            if (Physics.Raycast(originTransform.position, originTransform.forward, out hit, range, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
            {
                point = hit.point;
                return TryProjectGround(point, out point);
            }

            point = player.transform.position + Vector3.ProjectOnPlane(player.transform.forward, Vector3.up).normalized * Mathf.Min(range, 18f);
            return TryProjectGround(point, out point);
        }

        private static bool TryProjectGround(Vector3 probe, out Vector3 point)
        {
            RaycastHit[] hits = Physics.RaycastAll(probe + Vector3.up * 12f, Vector3.down, 30f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            Array.Sort(hits, (left, right) => left.distance.CompareTo(right.distance));
            foreach (RaycastHit hit in hits)
            {
                if (hit.collider == null || hit.collider.GetComponentInParent<Character>() != null)
                {
                    continue;
                }

                point = hit.point + Vector3.up * 0.08f;
                return true;
            }

            point = probe;
            return true;
        }

        private static void SpawnLightningStormPulse(Vector3 center, float lifetime)
        {
            NorseVisualEffectBridge.Spawn(
                center + Vector3.up * 0.15f,
                Quaternion.identity,
                Mathf.Max(0.2f, lifetime),
                "FxLightningExpansion",
                "FxLightningExplosion2",
                "FxLightningExplosion1",
                "FxLightningMist",
                "FxLightningWithSoundOnline",
                "FxLightningWithoutSoundOnline",
                "Storm",
                "Thunder",
                "Lightning");
        }

        private static void RedirectThreatToPlayer(Character target, Player player)
        {
            if (target == null || player == null)
            {
                return;
            }

            MonsterAI monsterAI = target.GetComponent<MonsterAI>();
            if (monsterAI != null)
            {
                try
                {
                    if (MonsterAISetTargetMethod != null)
                    {
                        MonsterAISetTargetMethod.Invoke(monsterAI, new object[] { player });
                    }
                }
                catch
                {
                }
            }

            BaseAI baseAI = target.GetComponent<BaseAI>();
            if (baseAI != null)
            {
                try
                {
                    if (BaseAISetAlertedMethod != null)
                    {
                        BaseAISetAlertedMethod.Invoke(baseAI, new object[] { true });
                    }

                    if (BaseAIAlertMethod != null)
                    {
                        BaseAIAlertMethod.Invoke(baseAI, null);
                    }
                }
                catch
                {
                }
            }
        }

        private static void TryAbyssalHarpoon(Player player)
        {
            if (_harpoonCooldown > 0f)
            {
                ShowMessage(player, string.Format("Abyssal Harpoon: {0:0}s cooldown.", _harpoonCooldown));
                return;
            }

            Character target;
            if (!TryFindHarpoonTarget(player, out target))
            {
                ShowMessage(player, "Abyssal Harpoon: sin objetivo.");
                return;
            }

            Vector3 spawnPoint;
            Vector3 direction;
            GetHarpoonProjectileSpawn(player, target, out spawnPoint, out direction);
            if (direction.sqrMagnitude <= 0.001f)
            {
                ShowMessage(player, "Abyssal Harpoon: objetivo invalido.");
                return;
            }

            TryLaunchNativeHarpoonProjectile(player, target, spawnPoint, direction);
            StartHarpoonRope(player, target, spawnPoint);
            RedirectThreatToPlayer(target, player);
            NorseVisualEffectBridge.SpawnAtPlayer(player, "fx_sledge_demolisher_hit", "sfx_harpoon_hit", "Harpoon", "Rope", "Spear");
            _harpoonCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallHarpoonCooldown.Value);
            AbilityCooldownBuffController.Start(player, "HeimdallAbyssalHarpoon", "Abyssal Harpoon", _harpoonCooldown, null);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, "Abyssal Harpoon.");
        }

        private static void TryLaunchNativeHarpoonProjectile(Player player, Character target, Vector3 spawnPoint, Vector3 direction)
        {
            GameObject projectileObject = null;
            try
            {
                GameObject projectilePrefab = GetHarpoonProjectilePrefab();
                if (projectilePrefab == null)
                {
                    LogHarpoonProjectileFailureOnce("Heimdall Abyssal Harpoon could not resolve SpearChitin/projectile_chitinharpoon; using custom rope fallback.");
                    return;
                }

                projectileObject = UnityEngine.Object.Instantiate(projectilePrefab, spawnPoint, Quaternion.LookRotation(direction));
                IProjectile projectile = projectileObject.GetComponent<IProjectile>() ?? projectileObject.GetComponentInChildren<IProjectile>();
                if (projectile == null)
                {
                    ZNetSceneSafety.Destroy(projectileObject);
                    LogHarpoonProjectileFailureOnce("Heimdall Abyssal Harpoon prefab has no IProjectile component: " + projectilePrefab.name);
                    return;
                }

                HitData hit = CreateHit(player, new HitData.DamageTypes(), target.GetCenterPoint(), direction, ClassSkillManager.Heimdall);
                hit.m_pushForce = 0f;
                ItemDrop.ItemData harpoonItem = GetHarpoonItemData() ?? player.GetCurrentWeapon();
                projectile.Setup(player, direction * Mathf.Max(5f, EpicLootRaritySetsPlugin.HeimdallHarpoonProjectileVelocity.Value), 0f, hit, harpoonItem, null);
            }
            catch (Exception ex)
            {
                if (projectileObject != null)
                {
                    ZNetSceneSafety.Destroy(projectileObject);
                }

                LogHarpoonProjectileFailureOnce("Heimdall Abyssal Harpoon native projectile failed; using custom rope fallback. " + ex.GetBaseException().Message);
            }
        }

        private static void StartHarpoonRope(Player player, Character target, Vector3 launchPoint)
        {
            try
            {
                DestroyVisual(ref _harpoonRopeVisual);
                _harpoonRopeVisual = new GameObject("HeimdallAbyssalHarpoonRope");
                HeimdallHarpoonRope rope = _harpoonRopeVisual.AddComponent<HeimdallHarpoonRope>();
                rope.Initialize(
                    player,
                    target,
                    launchPoint,
                    Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HeimdallHarpoonPullDuration.Value),
                    Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallHarpoonPullForce.Value),
                    Mathf.Max(5f, EpicLootRaritySetsPlugin.HeimdallHarpoonProjectileVelocity.Value));
            }
            catch (Exception ex)
            {
                DestroyVisual(ref _harpoonRopeVisual);
                LogHarpoonRopeFailureOnce("Heimdall Abyssal Harpoon rope visual failed. " + ex.GetBaseException().Message);
            }
        }

        private static bool IsHarpoonCastModifierHeld(Player player)
        {
            return SetAbilityInput.IsBlockHeld() || IsBlocking(player);
        }

        private static bool TryFindHarpoonTarget(Player player, out Character target)
        {
            target = null;
            if (player == null)
            {
                return false;
            }

            float range = Mathf.Max(1f, EpicLootRaritySetsPlugin.HeimdallHarpoonRange.Value);
            if (TryFindHarpoonCrosshairTarget(player, range, out target))
            {
                return true;
            }

            return TryFindHarpoonConeTarget(player, range, out target);
        }

        private static bool TryFindHarpoonCrosshairTarget(Player player, float range, out Character target)
        {
            target = null;
            Vector3 origin = GetAimOrigin(player);
            Vector3 forward = GetAimForward(player);
            RaycastHit[] hits = Physics.RaycastAll(origin, forward, range, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            Array.Sort(hits, (left, right) => left.distance.CompareTo(right.distance));

            foreach (RaycastHit hit in hits)
            {
                if (hit.collider == null)
                {
                    continue;
                }

                Character character = GetCharacterFromCollider(hit.collider);
                if (character != null)
                {
                    if (IsEnemyTarget(player, character))
                    {
                        target = character;
                        return true;
                    }

                    continue;
                }

                return false;
            }

            return false;
        }

        private static bool TryFindHarpoonConeTarget(Player player, float range, out Character target)
        {
            target = null;
            Vector3 origin = GetAimOrigin(player);
            Vector3 forward = GetAimForward(player);
            float bestScore = float.MaxValue;
            float maxAngleDot = Mathf.Cos(22.5f * Mathf.Deg2Rad);
            float rangeSqr = range * range;

            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character.IsDead() || !IsEnemyTarget(player, character))
                {
                    continue;
                }

                Vector3 toTarget = character.GetCenterPoint() - origin;
                float distanceSqr = toTarget.sqrMagnitude;
                if (distanceSqr <= 0.001f || distanceSqr > rangeSqr)
                {
                    continue;
                }

                Vector3 direction = toTarget.normalized;
                float dot = Vector3.Dot(forward, direction);
                if (dot < maxAngleDot || !HasLineOfSightToTarget(player, character, origin, direction, Mathf.Sqrt(distanceSqr)))
                {
                    continue;
                }

                float score = (1f - dot) * range + Mathf.Sqrt(distanceSqr) * 0.05f;
                if (score < bestScore)
                {
                    bestScore = score;
                    target = character;
                }
            }

            return target != null;
        }

        private static bool HasLineOfSightToTarget(Player player, Character target, Vector3 origin, Vector3 direction, float distance)
        {
            RaycastHit hit;
            if (!Physics.Raycast(origin, direction, out hit, distance, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
            {
                return true;
            }

            Character hitCharacter = hit.collider != null ? GetCharacterFromCollider(hit.collider) : null;
            return hitCharacter == target || hitCharacter == player;
        }

        private static Character GetCharacterFromCollider(Collider collider)
        {
            if (collider == null)
            {
                return null;
            }

            try
            {
                GameObject hitObject = Projectile.FindHitObject(collider);
                if (hitObject != null)
                {
                    Character character = hitObject.GetComponent<Character>();
                    if (character != null)
                    {
                        return character;
                    }
                }
            }
            catch
            {
            }

            return collider.GetComponentInParent<Character>();
        }

        private static Vector3 GetAimOrigin(Player player)
        {
            if (GameCamera.instance != null)
            {
                return GameCamera.instance.transform.position;
            }

            return player != null ? player.GetCenterPoint() + Vector3.up * 0.35f : Vector3.zero;
        }

        private static Vector3 GetAimForward(Player player)
        {
            Vector3 forward = GameCamera.instance != null ? GameCamera.instance.transform.forward : player.transform.forward;
            return forward.sqrMagnitude > 0.001f ? forward.normalized : Vector3.forward;
        }

        private static void GetHarpoonProjectileSpawn(Player player, Character target, out Vector3 spawnPoint, out Vector3 direction)
        {
            Vector3 forward = GetAimForward(player);
            Vector3 flatForward = Vector3.ProjectOnPlane(forward, Vector3.up);
            if (flatForward.sqrMagnitude <= 0.001f && player != null)
            {
                flatForward = Vector3.ProjectOnPlane(player.transform.forward, Vector3.up);
            }

            spawnPoint = player.GetCenterPoint() + Vector3.up * 0.25f + flatForward.normalized * 0.7f;
            Vector3 aimPoint = target != null ? target.GetCenterPoint() : spawnPoint + forward;
            direction = aimPoint - spawnPoint;
            direction = direction.sqrMagnitude > 0.001f ? direction.normalized : forward;
        }

        private static GameObject GetHarpoonProjectilePrefab()
        {
            GameObject projectile = GetAttackProjectileFromItem("SpearChitin");
            if (projectile != null)
            {
                return projectile;
            }

            return GetProjectilePrefab("projectile_chitinharpoon", "projectile_chitin_harpoon", "ChitinHarpoonProjectile", "HarpoonProjectile");
        }

        private static ItemDrop.ItemData GetHarpoonItemData()
        {
            GameObject prefab = GetItemPrefab("SpearChitin");
            ItemDrop itemDrop = prefab != null ? prefab.GetComponent<ItemDrop>() : null;
            return itemDrop != null ? itemDrop.m_itemData : null;
        }

        private static GameObject GetAttackProjectileFromItem(string itemPrefabName)
        {
            GameObject itemPrefab = GetItemPrefab(itemPrefabName);
            ItemDrop itemDrop = itemPrefab != null ? itemPrefab.GetComponent<ItemDrop>() : null;
            if (itemDrop == null || itemDrop.m_itemData == null || itemDrop.m_itemData.m_shared == null)
            {
                return null;
            }

            return itemDrop.m_itemData.m_shared.m_attack.m_attackProjectile;
        }

        private static GameObject GetItemPrefab(string itemPrefabName)
        {
            if (string.IsNullOrEmpty(itemPrefabName))
            {
                return null;
            }

            GameObject itemPrefab = ObjectDB.instance != null ? ObjectDB.instance.GetItemPrefab(itemPrefabName) : null;
            if (itemPrefab != null)
            {
                return itemPrefab;
            }

            return ZNetScene.instance != null ? ZNetScene.instance.GetPrefab(itemPrefabName) : null;
        }

        private static GameObject GetProjectilePrefab(params string[] prefabNames)
        {
            if (prefabNames == null || ZNetScene.instance == null)
            {
                return null;
            }

            foreach (string prefabName in prefabNames)
            {
                if (string.IsNullOrEmpty(prefabName))
                {
                    continue;
                }

                GameObject prefab = ZNetScene.instance.GetPrefab(prefabName);
                if (prefab != null && (prefab.GetComponent<IProjectile>() != null || prefab.GetComponentInChildren<IProjectile>() != null))
                {
                    return prefab;
                }
            }

            return null;
        }

        private static void LogHarpoonProjectileFailureOnce(string message)
        {
            if (_loggedHarpoonProjectileFailure)
            {
                return;
            }

            _loggedHarpoonProjectileFailure = true;
            if (EpicLootRaritySetsPlugin.Log != null)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning(message);
            }
        }

        private static void LogHarpoonRopeFailureOnce(string message)
        {
            if (_loggedHarpoonRopeFailure)
            {
                return;
            }

            _loggedHarpoonRopeFailure = true;
            if (EpicLootRaritySetsPlugin.Log != null)
            {
                EpicLootRaritySetsPlugin.Log.LogWarning(message);
            }
        }

        private sealed class HeimdallHarpoonRope : MonoBehaviour
        {
            private const float StopDistance = 2.35f;
            private Player _owner;
            private Character _target;
            private LineRenderer _line;
            private LineRenderer _auraLine;
            private Material _material;
            private Material _auraMaterial;
            private Vector3 _launchPoint;
            private float _age;
            private float _flightDuration;
            private float _pullDuration;
            private float _pullForce;

            internal void Initialize(Player owner, Character target, Vector3 launchPoint, float pullDuration, float pullForce, float projectileVelocity)
            {
                _owner = owner;
                _target = target;
                _launchPoint = launchPoint;
                _pullDuration = Mathf.Max(0.1f, pullDuration);
                _pullForce = Mathf.Max(0f, pullForce);

                float distance = target != null ? Vector3.Distance(launchPoint, target.GetCenterPoint()) : 0f;
                _flightDuration = Mathf.Clamp(distance / Mathf.Max(5f, projectileVelocity), 0.08f, 0.32f);
                SetupLine();
                UpdateLine(GetOwnerRopePoint(), _launchPoint);
            }

            private void Update()
            {
                try
                {
                    UpdateRope();
                }
                catch (Exception ex)
                {
                    LogHarpoonRopeFailureOnce("Heimdall Abyssal Harpoon rope update failed. " + ex.GetBaseException().Message);
                    UnityEngine.Object.Destroy(gameObject);
                }
            }

            private void UpdateRope()
            {
                if (_owner == null || _target == null || _owner.IsDead() || _target.IsDead())
                {
                    UnityEngine.Object.Destroy(gameObject);
                    return;
                }

                _age += Time.deltaTime;
                float totalDuration = _flightDuration + _pullDuration;
                if (_age >= totalDuration)
                {
                    UnityEngine.Object.Destroy(gameObject);
                    return;
                }

                Vector3 start = GetOwnerRopePoint();
                Vector3 targetPoint = _target.GetCenterPoint();
                bool caught = _age >= _flightDuration;
                Vector3 end = caught ? targetPoint : Vector3.Lerp(_launchPoint, targetPoint, Mathf.Clamp01(_age / Mathf.Max(0.01f, _flightDuration)));
                UpdateLine(start, end);

                if (caught)
                {
                    PullTarget(Time.deltaTime);
                }
            }

            private void SetupLine()
            {
                _auraLine = CreateLineRenderer("HeimdallAbyssalHarpoonAura");
                _auraLine.useWorldSpace = true;
                _auraLine.positionCount = 4;
                _auraLine.startWidth = 0.24f;
                _auraLine.endWidth = 0.17f;
                _auraLine.numCapVertices = 8;
                _auraLine.numCornerVertices = 5;
                _auraLine.startColor = new Color(0.40f, 0.82f, 1f, 0.42f);
                _auraLine.endColor = new Color(1f, 0.82f, 0.36f, 0.34f);

                _line = CreateLineRenderer("HeimdallAbyssalHarpoonCord");
                _line.useWorldSpace = true;
                _line.positionCount = 4;
                _line.startWidth = 0.07f;
                _line.endWidth = 0.045f;
                _line.numCapVertices = 3;
                _line.numCornerVertices = 2;
                _line.startColor = new Color(0.76f, 0.62f, 0.40f, 1f);
                _line.endColor = new Color(0.52f, 0.40f, 0.24f, 1f);

                Shader shader = Shader.Find("Sprites/Default");
                if (shader == null)
                {
                    shader = Shader.Find("Unlit/Color");
                }
                if (shader == null)
                {
                    shader = Shader.Find("Standard");
                }

                if (shader != null)
                {
                    _material = new Material(shader);
                    if (_material.HasProperty("_Color"))
                    {
                        _material.color = new Color(0.72f, 0.58f, 0.36f, 1f);
                    }
                    _line.material = _material;

                    _auraMaterial = new Material(shader);
                    if (_auraMaterial.HasProperty("_Color"))
                    {
                        _auraMaterial.color = new Color(0.55f, 0.88f, 1f, 0.38f);
                    }
                    _auraLine.material = _auraMaterial;
                }
            }

            private LineRenderer CreateLineRenderer(string objectName)
            {
                GameObject lineObject = new GameObject(objectName);
                lineObject.transform.SetParent(transform, false);
                return lineObject.AddComponent<LineRenderer>();
            }

            private void UpdateLine(Vector3 start, Vector3 end)
            {
                if (_line == null)
                {
                    return;
                }

                Vector3 sag = Vector3.down * Mathf.Min(0.35f, Vector3.Distance(start, end) * 0.025f);
                _line.SetPosition(0, start);
                _line.SetPosition(1, Vector3.Lerp(start, end, 0.33f) + sag * 0.45f);
                _line.SetPosition(2, Vector3.Lerp(start, end, 0.66f) + sag);
                _line.SetPosition(3, end);

                if (_auraLine == null)
                {
                    return;
                }

                float pulse = 0.5f + 0.5f * Mathf.Sin(Time.time * 9f);
                _auraLine.startWidth = Mathf.Lerp(0.20f, 0.32f, pulse);
                _auraLine.endWidth = Mathf.Lerp(0.14f, 0.24f, pulse);
                _auraLine.startColor = Color.Lerp(new Color(0.32f, 0.78f, 1f, 0.30f), new Color(0.75f, 0.95f, 1f, 0.56f), pulse);
                _auraLine.endColor = Color.Lerp(new Color(1f, 0.72f, 0.26f, 0.24f), new Color(1f, 0.90f, 0.44f, 0.48f), pulse);
                _auraLine.SetPosition(0, start);
                _auraLine.SetPosition(1, Vector3.Lerp(start, end, 0.33f) + sag * 0.45f);
                _auraLine.SetPosition(2, Vector3.Lerp(start, end, 0.66f) + sag);
                _auraLine.SetPosition(3, end);
            }

            private Vector3 GetOwnerRopePoint()
            {
                if (_owner == null)
                {
                    return _launchPoint;
                }

                Vector3 forward = Vector3.ProjectOnPlane(_owner.transform.forward, Vector3.up);
                if (forward.sqrMagnitude <= 0.001f)
                {
                    forward = _owner.transform.forward;
                }

                return _owner.GetCenterPoint() + forward.normalized * 0.7f + _owner.transform.right * 0.25f;
            }

            private void PullTarget(float dt)
            {
                if (_owner == null || _target == null || _pullForce <= 0f)
                {
                    return;
                }

                Vector3 pullPoint = _owner.transform.position + Vector3.ProjectOnPlane(_owner.transform.forward, Vector3.up).normalized * 1.4f;
                Vector3 targetPosition = _target.transform.position;
                Vector3 delta = pullPoint - targetPosition;
                float distance = delta.magnitude;
                if (distance <= StopDistance)
                {
                    return;
                }

                Vector3 direction = delta / Mathf.Max(0.001f, distance);
                direction.y = Mathf.Clamp(direction.y, -0.1f, 0.35f);
                if (direction.sqrMagnitude <= 0.001f)
                {
                    return;
                }

                direction.Normalize();
                float distanceFactor = Mathf.Lerp(0.75f, 1.65f, Mathf.InverseLerp(StopDistance, 18f, distance));
                float pullSpeed = Mathf.Max(8f, _pullForce * distanceFactor);
                Vector3 pullStep = direction * Mathf.Min(distance - StopDistance, pullSpeed * dt);
                Rigidbody body = _target.GetComponent<Rigidbody>() ?? _target.GetComponentInChildren<Rigidbody>();
                if (body != null && !body.isKinematic)
                {
                    body.WakeUp();
#pragma warning disable 0618
                    Vector3 existingVelocity = body.velocity;
                    Vector3 dampedVelocity = Vector3.ProjectOnPlane(existingVelocity, Vector3.up) * 0.25f + Vector3.up * Mathf.Min(existingVelocity.y, 0.5f);
                    body.velocity = Vector3.ClampMagnitude(dampedVelocity + direction * pullSpeed, 30f);
#pragma warning restore 0618
                    body.MovePosition(body.position + pullStep);
                }
                else
                {
                    _target.transform.position += pullStep;
                }

                Vector3 afterDelta = pullPoint - _target.transform.position;
                if (afterDelta.magnitude > StopDistance)
                {
                    _target.transform.position += direction * Mathf.Min(afterDelta.magnitude - StopDistance, pullStep.magnitude * 0.35f);
                }
            }

            private void OnDestroy()
            {
                if (_material != null)
                {
                    UnityEngine.Object.Destroy(_material);
                    _material = null;
                }

                if (_auraMaterial != null)
                {
                    UnityEngine.Object.Destroy(_auraMaterial);
                    _auraMaterial = null;
                }
            }
        }

        private static void TryStoneShield(Player player)
        {
            if (_stoneShieldRemaining > 0f)
            {
                ShowMessage(player, "Stone Shield: activo.");
                return;
            }

            if (_stoneShieldCooldown > 0f)
            {
                ShowMessage(player, string.Format("Stone Shield: {0:0}s cooldown.", _stoneShieldCooldown));
                return;
            }

            float stamina = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallStoneShieldStaminaUse.Value);
            if (!SpendStamina(player, stamina))
            {
                ShowMessage(player, "Stone Shield: no tienes vigor suficiente.");
                return;
            }

            _stoneShieldRemaining = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.HeimdallStoneShieldDuration.Value);
            _stoneShieldCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallStoneShieldCooldown.Value);
            EnsureStoneShieldVisual(player);
            RefreshStoneShieldBuff(player);
            AbilityCooldownBuffController.Start(player, "HeimdallStoneShield", "Stone Shield", _stoneShieldCooldown, null);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, "Stone Shield.");
        }

        private static void ReflectMitigatedDamage(Player player, HitData incoming, float mitigated)
        {
            if (mitigated <= 0f)
            {
                return;
            }

            Character attacker = null;
            try { attacker = incoming.GetAttacker(); } catch { }
            if (attacker == null || attacker == player || attacker.IsDead() || !IsEnemyTarget(player, attacker))
            {
                return;
            }

            float reflect = Mathf.Min(
                Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallStoneShieldReflectBase.Value + ClassSkillManager.GetSkillLevel(player, "Heimdall") * EpicLootRaritySetsPlugin.HeimdallStoneShieldReflectPerBlockingLevel.Value),
                Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallStoneShieldReflectMax.Value));
            HitData hit = CreateHit(player, new HitData.DamageTypes { m_blunt = mitigated * reflect }, attacker.GetCenterPoint(), attacker.GetCenterPoint() - player.GetCenterPoint(), ClassSkillManager.Heimdall);
            _reflecting = true;
            try { attacker.Damage(hit); }
            finally { _reflecting = false; }
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
        }

        private static bool IsBlocked(Player player, HitData hit)
        {
            if (HitBlockedField != null)
            {
                try
                {
                    object blocked = HitBlockedField.GetValue(hit);
                    if (blocked is bool && (bool)blocked)
                    {
                        return true;
                    }
                }
                catch { }
            }

            if (IsBlockingMethod != null)
            {
                try
                {
                    object value = IsBlockingMethod.Invoke(player, null);
                    return value is bool && (bool)value;
                }
                catch { }
            }

            return SetAbilityInput.IsBlockHeld() && HasCurrentBlocker(player);
        }

        private static bool HasCurrentBlocker(Player player)
        {
            if (player == null)
            {
                return false;
            }

            if (GetCurrentBlockerMethod != null)
            {
                try
                {
                    return GetCurrentBlockerMethod.Invoke(player, null) != null;
                }
                catch
                {
                }
            }

            return SetAbilityInput.IsBlockHeld();
        }

        private static ItemDrop.ItemData GetCurrentBlockerItem(Player player)
        {
            if (player == null || GetCurrentBlockerMethod == null)
            {
                return null;
            }

            try
            {
                return GetCurrentBlockerMethod.Invoke(player, null) as ItemDrop.ItemData;
            }
            catch
            {
                return null;
            }
        }

        private static Sprite GetBlockerIcon(Player player)
        {
            ItemDrop.ItemData item = GetCurrentBlockerItem(player);
            if (item == null && player != null)
            {
                item = player.GetCurrentWeapon();
            }

            if (item == null || item.m_shared == null || item.m_shared.m_icons == null || item.m_shared.m_icons.Length == 0)
            {
                return null;
            }

            return item.m_shared.m_icons[0];
        }

        private static void RefreshArmorBuff(Player player, bool forceLevelUpdate)
        {
            if (player == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateArmorBuff();
            int maxStacks = GetArmorMaxStacks();
            float damageReduction = GetArmorBonusFraction();
            float blockPower = GetBlockPowerBonusFraction();
            ApplyArmorStats(buff);
            buff.m_ttl = Mathf.Max(0.1f, _armorTimer + 0.1f);
            buff.m_name = string.Format("{0} {1}/{2}", LocalizedText.AbilityName("Heimdall Guard"), _armorStacks, maxStacks);
            buff.m_tooltip = string.Format("Recibir dano fortalece Heimdall.\n\nCargas: {0}/{1}.\nReduccion de todo el dano: {2:0.#}%.\nPoder de bloqueo: +{3:0.#}%.\nTiempo restante: {4:0.#}s.", _armorStacks, maxStacks, damageReduction * 100f, blockPower * 100f, Mathf.Max(0f, _armorTimer));
            buff.m_icon = GetBlockerIcon(player);
            SEMan seMan = player.GetSEMan();
            StatusEffect active = seMan.GetStatusEffect(buff.NameHash());
            if (active == null || forceLevelUpdate)
            {
                seMan.RemoveStatusEffect(buff.NameHash(), true);
                seMan.AddStatusEffect(buff, true, Mathf.Max(1, _armorStacks), 0f, 0);
                return;
            }

            active.m_name = buff.m_name;
            active.m_tooltip = buff.m_tooltip;
            active.m_ttl = buff.m_ttl;
            active.m_icon = buff.m_icon;
            active.m_flashIcon = buff.m_flashIcon;
            active.m_cooldownIcon = buff.m_cooldownIcon;
            active.m_hidden = buff.m_hidden;
            active.m_category = buff.m_category;
            ApplyArmorStats(active);
            if (StatusEffectTimeField != null)
            {
                try
                {
                    StatusEffectTimeField.SetValue(active, 0f);
                }
                catch
                {
                }
            }
        }

        private static StatusEffect GetOrCreateArmorBuff()
        {
            if (_armorBuff == null)
            {
                _armorBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _armorBuff.name = ArmorBuffName;
                _armorBuff.m_name = LocalizedText.AbilityName("Heimdall Guard");
                _armorBuff.m_category = ArmorBuffCategory;
                _armorBuff.m_flashIcon = false;
                _armorBuff.m_cooldownIcon = true;
                _armorBuff.m_hidden = false;
            }

            return _armorBuff;
        }

        private static int GetArmorMaxStacks()
        {
            return Mathf.Clamp(EpicLootRaritySetsPlugin.HeimdallBlockArmorMaxStacks.Value, 1, 3);
        }

        private static float GetArmorBonusFraction()
        {
            return Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallBlockArmorBonusPerStack.Value) * Mathf.Clamp(_armorStacks, 0, GetArmorMaxStacks());
        }

        private static float GetBlockPowerBonusFraction()
        {
            return Mathf.Max(0f, EpicLootRaritySetsPlugin.HeimdallBlockPowerBonusPerStack.Value) * Mathf.Clamp(_armorStacks, 0, GetArmorMaxStacks());
        }

        private static void ApplyArmorStats(StatusEffect effect)
        {
            SE_Stats stats = effect as SE_Stats;
            if (stats == null)
            {
                return;
            }

            stats.m_addArmor = 0f;
            stats.m_armorMultiplier = 0f;
        }

        private static bool CanEvaluateBlock(Player player, HitData hit)
        {
            if (!CanAcceptBlockSource(player, hit))
            {
                return false;
            }

            return HasCurrentBlocker(player) || SetAbilityInput.IsBlockHeld() || IsBlocked(player, hit);
        }

        private static bool CanAcceptBlockSource(Player player, HitData hit)
        {
            return CanAcceptGuardSource(player, hit);
        }

        private static bool CanAcceptGuardSource(Player player, HitData hit)
        {
            if (player == null || player != Player.m_localPlayer || hit == null || !IsEnabledAndActive())
            {
                return false;
            }

            Character attacker = null;
            try
            {
                attacker = hit.GetAttacker();
            }
            catch
            {
            }

            if (attacker != null && (attacker == player || !IsEnemyTarget(player, attacker)))
            {
                return false;
            }

            return attacker != null || hit.m_blockable;
        }

        private static void TryDetectGuardingBlock(Player player, HitData hit)
        {
            if (!CanAcceptBlockSource(player, hit))
            {
                return;
            }

            if (!IsActivelyGuarding(player) && !IsBlocked(player, hit))
            {
                return;
            }

            if (!IsHitInBlockArc(player, hit))
            {
                return;
            }

            OnSuccessfulBlock(player);
        }

        private static void DetectBlockByStaminaDrop(Player player, float currentStamina)
        {
            try
            {
                if (player == null || currentStamina < 0f || _lastObservedStamina < 0f || _blockStaminaDropLockout > 0f)
                {
                    return;
                }

                float staminaDrop = _lastObservedStamina - currentStamina;
                if (staminaDrop < 0.2f)
                {
                    return;
                }

                if (!IsActivelyGuarding(player))
                {
                    return;
                }

                if (_recentBlockableDamageTimer <= 0f && !HasEnemyNear(player, 6f))
                {
                    return;
                }

                _blockStaminaDropLockout = 0.45f;
                OnSuccessfulBlock(player);
            }
            finally
            {
                _lastObservedStamina = currentStamina;
            }
        }

        private static bool IsActivelyGuarding(Player player)
        {
            return player != null && (SetAbilityInput.IsBlockHeld() || HasCurrentBlocker(player) || IsBlocking(player));
        }

        private static bool IsBlocking(Player player)
        {
            if (player == null || IsBlockingMethod == null)
            {
                return false;
            }

            try
            {
                object value = IsBlockingMethod.Invoke(player, null);
                return value is bool && (bool)value;
            }
            catch
            {
                return false;
            }
        }

        private static bool HasEnemyNear(Player player, float radius)
        {
            if (player == null)
            {
                return false;
            }

            float clampedRadius = Mathf.Max(0.1f, radius);
            float radiusSqr = clampedRadius * clampedRadius;
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character.IsDead() || !IsEnemyTarget(player, character))
                {
                    continue;
                }

                if ((character.GetCenterPoint() - player.GetCenterPoint()).sqrMagnitude <= radiusSqr)
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsHitInBlockArc(Player player, HitData hit)
        {
            Character attacker = null;
            try { attacker = hit != null ? hit.GetAttacker() : null; } catch { }
            if (player == null || attacker == null)
            {
                return true;
            }

            Vector3 toAttacker = attacker.GetCenterPoint() - player.GetCenterPoint();
            toAttacker.y = 0f;
            Vector3 forward = player.transform.forward;
            forward.y = 0f;
            if (toAttacker.sqrMagnitude <= 0.001f || forward.sqrMagnitude <= 0.001f)
            {
                return true;
            }

            return Vector3.Dot(forward.normalized, toAttacker.normalized) >= -0.35f;
        }

        private static void RefreshLightningStormBuff(Player player)
        {
            if (player == null)
            {
                return;
            }

            StatusEffect buff = GetOrCreateLightningStormBuff();
            buff.m_ttl = Mathf.Max(0.1f, _lightningStormRemaining + 0.1f);
            StatusEffectIconHelper.Apply(buff, player, RequiredSet);
            buff.m_tooltip = string.Format(
                "Tormenta de rayos de Thor activa.\n\nZona fija invocada en el punto apuntado.\nRadio: {0:0.#}m.\nPulso: cada {1:0.#}s.\nDano de rayo: {2:0.#}+{3:0.##}/nivel de Heimdall.\nCada golpe redirige la amenaza de los enemigos afectados hacia Heimdall y los ralentiza {5:0.#}% durante {6:0.#}s.\nTiempo restante: {4:0.#}s.",
                EpicLootRaritySetsPlugin.HeimdallLightningStormRadius.Value,
                EpicLootRaritySetsPlugin.HeimdallLightningStormTickInterval.Value,
                EpicLootRaritySetsPlugin.HeimdallLightningStormBaseDamage.Value,
                EpicLootRaritySetsPlugin.HeimdallLightningStormDamagePerBlockingLevel.Value,
                Mathf.Max(0f, _lightningStormRemaining),
                Mathf.Clamp01(EpicLootRaritySetsPlugin.HeimdallLightningStormSlow.Value) * 100f,
                EpicLootRaritySetsPlugin.HeimdallLightningStormSlowDuration.Value);
            player.GetSEMan().RemoveStatusEffect(buff.NameHash(), true);
            player.GetSEMan().AddStatusEffect(buff, true, 0, 0f, 0);
        }

        private static StatusEffect GetOrCreateLightningStormBuff()
        {
            if (_lightningStormBuff == null)
            {
                _lightningStormBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _lightningStormBuff.name = LightningStormBuffName;
                _lightningStormBuff.m_name = LocalizedText.AbilityName("Lightning Storm");
                _lightningStormBuff.m_category = LightningStormBuffCategory;
                _lightningStormBuff.m_flashIcon = false;
                _lightningStormBuff.m_cooldownIcon = true;
                _lightningStormBuff.m_hidden = false;
            }

            return _lightningStormBuff;
        }

        private static void RemoveLightningStormBuff(Player player)
        {
            _lightningStormRemaining = 0f;
            _lightningStormTickTimer = 0f;
            _lightningStormCenter = Vector3.zero;
            if (player != null && _lightningStormBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_lightningStormBuff.NameHash(), true);
            }
        }

        private static void RefreshStoneShieldBuff(Player player)
        {
            StatusEffect buff = GetOrCreateStoneShieldBuff();
            buff.m_ttl = Mathf.Max(0.1f, _stoneShieldRemaining + 0.1f);
            StatusEffectIconHelper.Apply(buff, player, RequiredSet);
            buff.m_tooltip = string.Format("Escudo de piedra activo.\n\nReduce dano plano y refleja parte del dano mitigado.\nTiempo restante: {0:0.#}s.", Mathf.Max(0f, _stoneShieldRemaining));
            player.GetSEMan().RemoveStatusEffect(buff.NameHash(), true);
            player.GetSEMan().AddStatusEffect(buff, true, 0, 0f, 0);
        }

        private static StatusEffect GetOrCreateStoneShieldBuff()
        {
            if (_stoneShieldBuff == null)
            {
                _stoneShieldBuff = ScriptableObject.CreateInstance<SE_Stats>();
                _stoneShieldBuff.name = StoneShieldBuffName;
                _stoneShieldBuff.m_name = LocalizedText.AbilityName("Stone Shield");
                _stoneShieldBuff.m_category = StoneShieldBuffCategory;
                _stoneShieldBuff.m_flashIcon = false;
                _stoneShieldBuff.m_cooldownIcon = true;
                _stoneShieldBuff.m_hidden = false;
            }

            return _stoneShieldBuff;
        }

        private static void RemoveStoneShieldBuff(Player player)
        {
            _stoneShieldRemaining = 0f;
            if (player != null && _stoneShieldBuff != null)
            {
                player.GetSEMan().RemoveStatusEffect(_stoneShieldBuff.NameHash(), true);
            }
            DestroyVisual(ref _stoneShieldVisual);
        }

        private static void EnsureLightningStormVisual(Player player)
        {
            if (player == null || _lightningStormRemaining <= 0f || _lightningStormVisual != null)
            {
                return;
            }

            Vector3 center = _lightningStormCenter != Vector3.zero ? _lightningStormCenter : player.GetCenterPoint();
            _lightningStormVisual = NorseVisualEffectBridge.Spawn(
                center + Vector3.up * 0.2f,
                Quaternion.identity,
                Mathf.Max(0.2f, _lightningStormRemaining + 0.25f),
                "FxLightningExpansion",
                "FxLightningExplosion2",
                "FxLightningExplosion1",
                "FxLightningMist",
                "LightningStorm",
                "ThunderStorm",
                "ThorStorm",
                "Thunder",
                "Lightning",
                "Thor");
        }

        private static void EnsureStoneShieldVisual(Player player)
        {
            if (player == null || _stoneShieldRemaining <= 0f || _stoneShieldVisual != null)
            {
                return;
            }

            _stoneShieldVisual = NorseVisualEffectBridge.SpawnAttached(
                player,
                Vector3.up * 1.0f,
                Quaternion.identity,
                Mathf.Max(0.2f, _stoneShieldRemaining + 0.25f),
                "FxStoneShield",
                "StoneShield",
                "Stone",
                "Shield");
        }

        private static void DestroyVisual(ref GameObject visual)
        {
            if (visual != null)
            {
                UnityEngine.Object.Destroy(visual);
                visual = null;
            }
        }

        private static void DamageArea(Player player, Vector3 center, float radius, HitData.DamageTypes damages, Skills.SkillType skill)
        {
            radius = Mathf.Max(0.1f, radius);
            foreach (Character character in Character.GetAllCharacters())
            {
                if (character == null || character.IsDead() || !IsEnemyTarget(player, character))
                {
                    continue;
                }

                if ((character.GetCenterPoint() - center).sqrMagnitude <= radius * radius)
                {
                    character.Damage(CreateHit(player, damages, character.GetCenterPoint(), character.GetCenterPoint() - center, skill));
                }
            }
        }

        private static HitData CreateHit(Player player, HitData.DamageTypes damages, Vector3 point, Vector3 direction, Skills.SkillType skill)
        {
            HitData hit = new HitData
            {
                m_damage = damages,
                m_skill = skill,
                m_skillLevel = player != null ? player.GetSkillLevel(skill) : 0f,
                m_ranged = true,
                m_dodgeable = true,
                m_blockable = true,
                m_backstabBonus = 1f,
                m_staggerMultiplier = 1f,
                m_point = point,
                m_dir = direction.sqrMagnitude > 0.001f ? direction.normalized : Vector3.forward
            };
            if (player != null) hit.SetAttacker(player);
            return hit;
        }

        private static bool SpendStamina(Player player, float amount)
        {
            if (player == null || amount <= 0f)
            {
                return true;
            }

            float current = GetStamina(player);
            if (current >= 0f && current < amount)
            {
                return false;
            }

            try
            {
                if (UseStaminaMethod != null)
                {
                    UseStaminaMethod.Invoke(player, new object[] { amount });
                    return true;
                }
            }
            catch { }

            return true;
        }

        private static float GetStamina(Player player)
        {
            try
            {
                if (GetStaminaMethod != null)
                {
                    return Convert.ToSingle(GetStaminaMethod.Invoke(player, null));
                }
            }
            catch { }
            return -1f;
        }

        private static void ReduceFlatDamage(ref HitData.DamageTypes damages, float reduction)
        {
            float total = TotalDamage(damages);
            if (total <= 0.001f)
            {
                return;
            }

            ScaleAllDamage(ref damages, Mathf.Clamp01((total - Mathf.Max(0f, reduction)) / total));
        }

        private static void ScaleAllDamage(ref HitData.DamageTypes damages, float multiplier)
        {
            damages.m_blunt *= multiplier;
            damages.m_slash *= multiplier;
            damages.m_pierce *= multiplier;
            damages.m_chop *= multiplier;
            damages.m_pickaxe *= multiplier;
            damages.m_fire *= multiplier;
            damages.m_frost *= multiplier;
            damages.m_lightning *= multiplier;
            damages.m_poison *= multiplier;
            damages.m_spirit *= multiplier;
        }

        private static float TotalDamage(HitData.DamageTypes damages)
        {
            return damages.m_blunt + damages.m_slash + damages.m_pierce + damages.m_chop + damages.m_pickaxe + damages.m_fire + damages.m_frost + damages.m_lightning + damages.m_poison + damages.m_spirit;
        }

        private static bool IsEnabledAndActive()
        {
            return EpicLootRaritySetsPlugin.EnableHeimdallAbilities != null &&
                   EpicLootRaritySetsPlugin.EnableHeimdallAbilities.Value &&
                   SetActivationBuffController.HasActiveSet(RequiredSet);
        }

        private static bool CanReadInput(Player player)
        {
            return !player.IsDead() && !player.IsTeleporting() && !IsAnyMenuOpen();
        }

        private static bool IsShortcutDown(ConfigEntry<KeyboardShortcut> entry)
        {
            if (entry == null) return false;
            KeyboardShortcut shortcut = entry.Value;
            if (shortcut.IsDown()) return true;
            KeyCode mainKey = shortcut.MainKey;
            if (mainKey == KeyCode.None || !Input.GetKeyDown(mainKey)) return false;
            foreach (KeyCode modifier in shortcut.Modifiers)
            {
                if (!Input.GetKey(modifier)) return false;
            }
            return true;
        }

        private static bool IsAnyMenuOpen()
        {
            return (InventoryGui.instance != null && InventoryGui.IsVisible()) ||
                   (Menu.instance != null && Menu.IsVisible()) ||
                   (TextInput.instance != null && TextInput.IsVisible()) ||
                   (Chat.instance != null && Chat.instance.HasFocus()) ||
                   (Minimap.instance != null && Minimap.IsOpen());
        }

        private static bool IsEnemyTarget(Player player, Character target)
        {
            if (player == null || target == null || target == player)
            {
                return false;
            }

            if (CharacterTargeting.IsPlayerPvPEnemy(player, target))
            {
                return true;
            }

            if (target is Player)
            {
                return false;
            }

            if (BaseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = BaseAIIsEnemyMethod.Invoke(null, new object[] { player, target });
                    if (value is bool) return (bool)value;
                }
                catch { }
            }

            return true;
        }

        private static void ShowMessage(Player player, string message)
        {
            if (player != null) player.Message(MessageHud.MessageType.Center, message, 0, null, false);
        }
    }

    internal static class SeidrAbilityController
    {
        private const string RequiredSet = "Seidr";
        private const string NanoBuffName = "FranSeidrNanocube";
        private const string NanoBuffCategory = "FranSeidrNanocube";
        private const string NanoDamageBuffName = "FranSeidrNanocubeDamage";
        private const string NanoDamageBuffCategory = "FranSeidrNanocubeDamage";
        private const string ShieldBuffName = "FranSeidrElementalShield";
        private const string ShieldBuffCategory = "FranSeidrElementalShield";
        private const string StoneGolemBuffName = "FranSeidrStoneGolem";
        private const string StoneGolemBuffCategory = "FranSeidrStoneGolem";
        private const string FrostNovaSlowBuffName = "FranSeidrFrostNovaSlow";
        private const string FrostNovaSlowBuffCategory = "FranSeidrFrostNovaSlow";

        private static readonly MethodInfo BaseAIIsEnemyMethod = AccessTools.Method(typeof(BaseAI), "IsEnemy", new[] { typeof(Character), typeof(Character) });
        private static readonly MethodInfo GetMaxEitrMethod = AccessTools.Method(typeof(Player), "GetMaxEitr", Type.EmptyTypes) ?? AccessTools.Method(typeof(Character), "GetMaxEitr", Type.EmptyTypes);
        private static readonly FieldInfo SpeedModifierField = AccessTools.Field(typeof(SE_Stats), "m_speedModifier");
        private static readonly FieldInfo StatusEffectTimeField = AccessTools.Field(typeof(StatusEffect), "m_time");
        private static readonly MethodInfo TameMethod = AccessTools.Method(typeof(Tameable), "Tame");

        private static StatusEffect _nanoBuff;
        private static StatusEffect _nanoDamageBuff;
        private static StatusEffect _shieldBuff;
        private static StatusEffect _stoneGolemBuff;
        private static StatusEffect _frostNovaSlowBuff;
        private static GameObject _stoneGolem;
        private static GameObject _shieldVisual;
        private static Vector3 _nanoCenter;
        private static readonly List<GameObject> NanoVisuals = new List<GameObject>();
        private static float _nanoRemaining;
        private static float _nanoVisualRefreshTimer;
        private static bool _nanoAreaActive;
        private static bool _nanoPlayerInside;
        private static bool _wasActive;
        private static float _nanoCooldown;
        private static float _shieldCooldown;
        private static bool _shieldActive;
        private static float _stoneGolemCooldown;
        private static float _stoneGolemRemaining;
        private static float _frostNovaCooldown;

        internal static void Update(Player player, float dt)
        {
            if (player == null || player != Player.m_localPlayer)
            {
                return;
            }

            _nanoCooldown = Mathf.Max(0f, _nanoCooldown - dt);
            _shieldCooldown = Mathf.Max(0f, _shieldCooldown - dt);
            _stoneGolemCooldown = Mathf.Max(0f, _stoneGolemCooldown - dt);
            _frostNovaCooldown = Mathf.Max(0f, _frostNovaCooldown - dt);

            if (!IsEnabledAndActive())
            {
                if (_wasActive || _nanoRemaining > 0f || _shieldActive || _stoneGolem != null)
                {
                    Clear(player);
                }
                return;
            }

            _wasActive = true;
            UpdateNanoCube(player, dt);
            UpdateElementalShield(player, dt);
            UpdateStoneGolem(player, dt);

            if (!CanReadInput(player))
            {
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.SeidrNanoCubeHotkey))
            {
                TryNanoCube(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.SeidrFrostNovaHotkey) &&
                SetAbilityInput.IsBlockHeld())
            {
                TryFrostNova(player);
                return;
            }

            if (IsShortcutDown(EpicLootRaritySetsPlugin.SeidrElementalShieldHotkey))
            {
                ToggleElementalShield(player);
                return;
            }

            if (SetAbilityInput.IsSecondaryAttackDown() ||
                IsShortcutDown(EpicLootRaritySetsPlugin.SeidrStoneGolemHotkey))
            {
                TryStoneGolem(player);
            }
        }

        internal static void Clear(Player player)
        {
            _nanoRemaining = 0f;
            _nanoVisualRefreshTimer = 0f;
            _nanoAreaActive = false;
            _nanoPlayerInside = false;
            _shieldActive = false;
            if (player != null)
            {
                if (_nanoBuff != null) player.GetSEMan().RemoveStatusEffect(_nanoBuff.NameHash(), true);
                if (_nanoDamageBuff != null) player.GetSEMan().RemoveStatusEffect(_nanoDamageBuff.NameHash(), true);
                if (_shieldBuff != null) player.GetSEMan().RemoveStatusEffect(_shieldBuff.NameHash(), true);
                if (_stoneGolemBuff != null) player.GetSEMan().RemoveStatusEffect(_stoneGolemBuff.NameHash(), true);
            }
            DestroyNanoVisuals();
            DestroyVisual(ref _shieldVisual);
            DestroyStoneGolem();
            _wasActive = false;
        }

        internal static void ModifyIncomingDamage(Player player, HitData hit)
        {
            if (player == null || hit == null || player != Player.m_localPlayer || !_shieldActive || !IsEnabledAndActive() || !HasShieldBuff(player))
            {
                return;
            }

            hit.m_damage = new HitData.DamageTypes();
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
        }

        internal static void ModifyOutgoingDamage(HitData hit)
        {
            if (hit == null || _nanoRemaining <= 0f)
            {
                return;
            }

            Character attacker = null;
            try { attacker = hit.GetAttacker(); } catch { }
            Player player = attacker as Player;
            if (player == null || player != Player.m_localPlayer || !IsEnabledAndActive())
            {
                return;
            }

            if (!IsNanoDamageActiveFor(player))
            {
                return;
            }

            float magicBefore = hit.m_damage.m_fire + hit.m_damage.m_frost + hit.m_damage.m_lightning + hit.m_damage.m_poison + hit.m_damage.m_spirit;
            if (magicBefore <= 0.01f)
            {
                return;
            }

            float multiplier = 1f + Mathf.Max(0f, EpicLootRaritySetsPlugin.SeidrNanoCubeMagicDamageBonus.Value);
            hit.m_damage.m_fire *= multiplier;
            hit.m_damage.m_frost *= multiplier;
            hit.m_damage.m_lightning *= multiplier;
            hit.m_damage.m_poison *= multiplier;
            hit.m_damage.m_spirit *= multiplier;
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
        }

        private static void TryNanoCube(Player player)
        {
            if (_nanoCooldown > 0f)
            {
                ShowMessage(player, string.Format("Nanocube: {0:0}s cooldown.", _nanoCooldown));
                return;
            }

            float eitr = Mathf.Max(0f, EpicLootRaritySetsPlugin.SeidrNanoCubeEitrUse.Value);
            if (eitr > 0f && !player.HaveEitr(eitr))
            {
                if (Hud.instance != null)
                {
                    Hud.instance.EitrBarEmptyFlash();
                }
                ShowMessage(player, "Nanocube: no tienes eitr suficiente.");
                return;
            }

            player.UseEitr(eitr);
            _nanoCenter = player.transform.position;
            _nanoRemaining = Mathf.Max(0.1f, EpicLootRaritySetsPlugin.SeidrNanoCubeDuration.Value);
            _nanoVisualRefreshTimer = 0f;
            _nanoAreaActive = true;
            _nanoPlayerInside = IsPlayerInsideNano(player);
            _nanoCooldown = Mathf.Max(0f, EpicLootRaritySetsPlugin.SeidrNanoCubeCooldown.Value);
            RefreshNanoVisual();
            RefreshNanoBuff(player);
            if (_nanoPlayerInside)
            {
                RefreshNanoDamageBuff(player);
            }
            else
            {
                RemoveNanoDamageBuff(player);
            }
            AbilityCooldownBuffController.Start(player, "SeidrNanocube", "Nanocube", _nanoCooldown, null);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, "Nanocube.");
        }

        private static void ToggleElementalShield(Player player)
        {
            if (_shieldActive)
            {
                _shieldActive = false;
                _shieldCooldown = 0f;
                RemoveShieldBuff(player);
                DestroyVisual(ref _shieldVisual);
                AbilityCooldownBuffController.Clear(player, "SeidrElementalShield");
                ShowMessage(player, "Elemental Shield: desactivado.");
                return;
            }

            _shieldCooldown = 0f;

            float eitr = Mathf.Max(0f, EpicLootRaritySetsPlugin.SeidrElementalShieldEitrUse.Value);
            if (eitr > 0f && !player.HaveEitr(eitr))
            {
                if (Hud.instance != null)
                {
                    Hud.instance.EitrBarEmptyFlash();
                }
                ShowMessage(player, "Elemental Shield: no tienes eitr suficiente.");
                return;
            }

            player.UseEitr(eitr);
            _shieldActive = true;
            EnsureShieldVisual(player);
            RefreshShieldBuff(player);
            ClassSkillManager.RaiseSkill(player, RequiredSet, 1f);
            ShowMessage(player, "Elemental Shield: activo.");
        }

        private static void TryStoneGolem(Player player)
        {
            if (_stoneGolemCooldown > 0f)
            {
                ShowMessage(player, string.Format("Stone Golem: {0:0}s cooldown.", _stoneGolemCooldown));
                return;
            }

            float eitr = Mathf.Max(0f, EpicLootRaritySetsPlugin.SeidrStoneGolemEitrUse.Value);
