        private static void DestroyVisual(ref GameObject visual)
        {
            if (visual != null)
            {
                UnityEngine.Object.Destroy(visual);
                visual = null;
            }
        }

        private static void SetupSummon(Player player, GameObject summon)
        {
            if (summon == null) return;
            Character character = summon.GetComponent<Character>();
            if (character != null) character.SetTamed(true);
            Tameable tameable = summon.GetComponent<Tameable>() ?? summon.AddComponent<Tameable>();
            if (tameable != null)
            {
                tameable.m_commandable = true;
                tameable.m_fedDuration = Mathf.Max(tameable.m_fedDuration, 3600f);
                if (TameMethod != null)
                {
                    try { TameMethod.Invoke(tameable, null); } catch { }
                }
            }
            MonsterAI monsterAI = summon.GetComponent<MonsterAI>();
            if (monsterAI != null)
            {
                monsterAI.MakeTame();
                monsterAI.SetFollowTarget(player.gameObject);
            }
            ZNetView view = summon.GetComponent<ZNetView>();
            if (view != null && view.GetZDO() != null) view.GetZDO().Persistent = false;
            ApplyGhostVisual(summon);
            NorseVisualEffectBridge.SpawnAttached(summon, Vector3.up * 1.2f, Quaternion.identity, Mathf.Max(1f, EpicLootRaritySetsPlugin.SeidrStoneGolemDuration.Value), "ElementalGolem", "StoneGolem", "Golem", "Spirit", "Ghost");
        }

        private static void ApplyStoneGolemScaling(Player player, GameObject summon)
        {
            float skill = ClassSkillManager.GetSkillLevel(player, RequiredSet);
            ClassPetScalingController.Register(
                summon,
                GetStoneGolemMaxHealth(skill),
                GetStoneGolemDamageMultiplier(skill),
                GetStoneGolemDamageTakenReduction(skill));
        }

        private static float GetStoneGolemMaxHealth(float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            return 220f + skill * 2.2f;
        }

        private static float GetStoneGolemDamageMultiplier(float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            return 0.35f + skill * 0.0035f;
        }

        private static float GetStoneGolemDamageTakenReduction(float skill)
        {
            skill = Mathf.Clamp(skill, 0f, 100f);
            return Mathf.Min(0.25f, skill * 0.002f);
        }

        private static void ApplyGhostVisual(GameObject target)
        {
            if (target == null)
            {
                return;
            }

            Renderer[] renderers = target.GetComponentsInChildren<Renderer>(true);
            foreach (Renderer renderer in renderers)
            {
                if (renderer == null)
                {
                    continue;
                }

                Material[] materials = renderer.materials;
                foreach (Material material in materials)
                {
                    if (material == null)
                    {
                        continue;
                    }

                    Color color = material.HasProperty("_Color") ? material.color : Color.white;
                    color.a = Mathf.Min(color.a <= 0.05f ? 0.55f : color.a, 0.55f);
                    if (material.HasProperty("_Color"))
                    {
                        material.color = color;
                    }

                    Color tintColor = material.HasProperty("_TintColor") ? material.GetColor("_TintColor") : color;
                    tintColor.a = Mathf.Min(tintColor.a <= 0.05f ? 0.55f : tintColor.a, 0.55f);
                    if (material.HasProperty("_TintColor"))
                    {
                        material.SetColor("_TintColor", tintColor);
                    }

                    if (material.HasProperty("_EmissionColor"))
                    {
                        material.SetColor("_EmissionColor", new Color(0.45f, 0.75f, 1f, 0.55f));
                    }

                    if (material.HasProperty("_EmissionColor"))
                    {
                        material.EnableKeyword("_EMISSION");
                    }

                    material.SetOverrideTag("RenderType", "Transparent");
                    if (material.HasProperty("_Mode"))
                    {
                        material.SetFloat("_Mode", 3f);
                    }

                    if (material.HasProperty("_SrcBlend"))
                    {
                        material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                    }

                    if (material.HasProperty("_DstBlend"))
                    {
                        material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                    }

                    if (material.HasProperty("_ZWrite"))
                    {
                        material.SetInt("_ZWrite", 1);
                    }

                    material.renderQueue = 3000;
                }
            }
        }

        private static void DestroyStoneGolem()
        {
            if (_stoneGolem != null)
            {
                ClassPetScalingController.Unregister(_stoneGolem);
                if (ZNetScene.instance != null) ZNetScene.instance.Destroy(_stoneGolem);
                else UnityEngine.Object.Destroy(_stoneGolem);
            }
            _stoneGolem = null;
            _stoneGolemRemaining = 0f;
            RemoveStoneGolemBuff(Player.m_localPlayer);
        }

        internal static bool IsStoneGolemForPetCommand(Character character)
        {
            if (character == null || _stoneGolem == null)
            {
                return false;
            }

            Character golemCharacter = _stoneGolem.GetComponent<Character>() ?? _stoneGolem.GetComponentInChildren<Character>();
            return golemCharacter == character || character.transform.IsChildOf(_stoneGolem.transform);
        }

        internal static int GetActivePetCount()
        {
            Character character = _stoneGolem != null ? _stoneGolem.GetComponent<Character>() ?? _stoneGolem.GetComponentInChildren<Character>() : null;
            return character != null && !character.IsDead() ? 1 : 0;
        }

        internal static void ReleasePetFollow(Player owner)
        {
            PetCommandController.ReleasePetFollow(_stoneGolem);
        }

        private static GameObject GetPrefab(params string[] names)
        {
            if (ZNetScene.instance == null || names == null) return null;
            foreach (string name in names)
            {
                GameObject prefab = ZNetScene.instance.GetPrefab(name);
                if (prefab != null && (prefab.GetComponent<Character>() != null || prefab.GetComponentInChildren<Character>() != null)) return prefab;
            }
            return null;
        }

        private static float GetMaxEitr(Player player)
        {
            try
            {
                if (GetMaxEitrMethod != null) return Mathf.Max(0f, Convert.ToSingle(GetMaxEitrMethod.Invoke(player, null)));
            }
            catch { }
            return 100f;
        }

        private static bool IsEnabledAndActive()
        {
            return EpicLootRaritySetsPlugin.EnableSeidrAbilities != null &&
                   EpicLootRaritySetsPlugin.EnableSeidrAbilities.Value &&
                   SetActivationBuffController.HasActiveSet(RequiredSet);
        }

        private static bool CanReadInput(Player player)
        {
            return !player.IsDead() && !player.IsTeleporting() && !IsAnyMenuOpen();
        }

        private static bool IsShortcutDown(ConfigEntry<KeyboardShortcut> entry)
        {
            if (entry == null) return false;
            KeyboardShortcut shortcut = entry.Value;
            if (shortcut.IsDown()) return true;
            KeyCode mainKey = shortcut.MainKey;
            if (mainKey == KeyCode.None || !Input.GetKeyDown(mainKey)) return false;
            foreach (KeyCode modifier in shortcut.Modifiers)
            {
                if (!Input.GetKey(modifier)) return false;
            }
            return true;
        }

        private static bool IsAnyMenuOpen()
        {
            return (InventoryGui.instance != null && InventoryGui.IsVisible()) ||
                   (Menu.instance != null && Menu.IsVisible()) ||
                   (TextInput.instance != null && TextInput.IsVisible()) ||
                   (Chat.instance != null && Chat.instance.HasFocus()) ||
                   (Minimap.instance != null && Minimap.IsOpen());
        }

        private static bool IsEnemyTarget(Player player, Character target)
        {
            if (player == null || target == null || target == player) return false;
            if (CharacterTargeting.IsPlayerPvPEnemy(player, target)) return true;
            if (target is Player) return false;
            if (BaseAIIsEnemyMethod != null)
            {
                try
                {
                    object value = BaseAIIsEnemyMethod.Invoke(null, new object[] { player, target });
                    if (value is bool) return (bool)value;
                }
                catch { }
            }
            return true;
        }

        private static Sprite FindSeidrIcon(Player player)
        {
            ItemDrop.ItemData weapon = player != null ? player.GetCurrentWeapon() : null;
            Sprite weaponIcon = GetItemIcon(weapon);
            if (weaponIcon != null)
            {
                return weaponIcon;
            }

            Inventory inventory = player != null ? player.GetInventory() : null;
            if (inventory == null)
            {
                return null;
            }

            foreach (ItemDrop.ItemData item in inventory.GetEquippedItems())
            {
                Sprite icon = GetItemIcon(item);
                if (icon == null)
                {
                    continue;
                }

                MagicItem magicItem = ItemDataExtensions.GetMagicItem(item);
                if (magicItem != null && (IsSeidrId(magicItem.SetID) || IsSeidrId(magicItem.LegendaryID)))
                {
                    return icon;
                }
            }

            return null;
        }

        private static Sprite GetItemIcon(ItemDrop.ItemData item)
        {
            if (item == null || item.m_shared == null || item.m_shared.m_icons == null || item.m_shared.m_icons.Length == 0)
            {
                return null;
            }

            return item.m_shared.m_icons[0];
        }

        private static bool IsSeidrId(string id)
        {
            return !string.IsNullOrEmpty(id) && id.IndexOf("Seidr", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static void ShowMessage(Player player, string message)
        {
            if (player != null) player.Message(MessageHud.MessageType.Center, message, 0, null, false);
        }
    }

    internal static class BossSetDropController
    {
        private static readonly Dictionary<string, BossSetDropRule> RulesByObject = new Dictionary<string, BossSetDropRule>(StringComparer.OrdinalIgnoreCase);

        [ThreadStatic]
        private static BossLootContext _context;

        [ThreadStatic]
        private static Stack<string> _lootDropItems;

        [ThreadStatic]
        private static Stack<string> _resolveLootDropItems;

        internal static void Load()
        {
            RulesByObject.Clear();

            if (EpicLootRaritySetsPlugin.ReadBossSetDropRules != null && !EpicLootRaritySetsPlugin.ReadBossSetDropRules.Value)
            {
                return;
            }

            string path = Path.Combine(Paths.ConfigPath, "EpicLoot", "bosssetdrops.json");
            if (!File.Exists(path))
            {
                return;
            }

            try
            {
                BossSetDropConfig config = JsonConvert.DeserializeObject<BossSetDropConfig>(File.ReadAllText(path));
                if (config == null || !config.Enabled || config.Bosses == null)
                {
                    return;
                }

                foreach (BossSetDropRule rule in config.Bosses)
                {
                    if (rule == null || string.IsNullOrEmpty(rule.Object) || !rule.Enabled)
                    {
                        continue;
                    }

                    rule.GuaranteedSetDrops = Math.Max(0, rule.GuaranteedSetDrops);
                    rule.ExtraSetDropChance = Mathf.Clamp01(rule.ExtraSetDropChance);
                    if (rule.ForceSetDropItems == null)
                    {
                        rule.ForceSetDropItems = new List<string>();
                    }
                    if (rule.ForceSetItemIds == null)
                    {
                        rule.ForceSetItemIds = new List<string>();
                    }

                    RulesByObject[rule.Object] = rule;
                }

                EpicLootRaritySetsPlugin.Log.LogInfo(string.Format("Loaded boss set drop rules: {0}", RulesByObject.Count));
            }
            catch (Exception ex)
            {
                EpicLootRaritySetsPlugin.Log.LogError("Failed to load boss set drop rules from " + path + ": " + ex);
            }
        }

        internal static void EnterLootTable(string objectName, int level)
        {
            if (_context != null)
            {
                _context.Depth++;
                return;
            }

            BossSetDropRule rule;
            if (string.IsNullOrEmpty(objectName) || !RulesByObject.TryGetValue(objectName, out rule))
            {
                return;
            }

            _context = new BossLootContext(rule, objectName, level);
        }

        internal static void ExitLootTable()
        {
            if (_context == null)
            {
                return;
            }

            _context.Depth--;
            if (_context.Depth <= 0)
            {
                _context = null;
            }
        }

        internal static void PushLootDrop(LootDrop lootDrop)
        {
            if (_lootDropItems == null)
            {
                _lootDropItems = new Stack<string>();
            }

            _lootDropItems.Push(lootDrop != null ? lootDrop.Item : null);
        }

        internal static void PopLootDrop()
        {
            if (_lootDropItems == null || _lootDropItems.Count == 0)
            {
                return;
            }

            _lootDropItems.Pop();
        }

        internal static void PushResolveLootDrop(LootDrop lootDrop)
        {
            if (_resolveLootDropItems == null)
            {
                _resolveLootDropItems = new Stack<string>();
            }

            _resolveLootDropItems.Push(lootDrop != null ? lootDrop.Item : null);
        }

        internal static void PopResolveLootDrop()
        {
            if (_resolveLootDropItems == null || _resolveLootDropItems.Count == 0)
            {
                return;
            }

            _resolveLootDropItems.Pop();
        }

        internal static bool HasActiveBossRule()
        {
            return _context != null && _context.Rule != null;
        }

        internal static void ForceResolvedBossLootDrop(LootDrop lootDrop)
        {
            if (!HasActiveBossRule() || lootDrop == null || IsBossUtilityDrop(lootDrop))
            {
                return;
            }

            ItemRarity targetRarity;
            if (!TryGetRuleRarity(_context.Rule, out targetRarity))
            {
                return;
            }

            string sourceItem = GetCurrentResolveLootDropItem();
            string resolvedItem = lootDrop.Item;
            bool hasRarityRoll = lootDrop.Rarity != null && lootDrop.Rarity.Length > 0;
            bool shouldForce = hasRarityRoll || IsForcedSetDropItem(sourceItem) || IsForcedSetDropItem(resolvedItem);
            if (!shouldForce)
            {
                return;
            }

            string baseItemName;
            if (!RaritySetRegistry.TrySelectSetBaseItemFromIds(targetRarity, _context.Rule.ForceSetItemIds, resolvedItem, out baseItemName))
            {
                return;
            }

            lootDrop.Item = baseItemName;
            lootDrop.Rarity = BuildForcedRarityArray(targetRarity);
            lootDrop.RarityItems = null;
        }

        internal static bool TryGetBossSetDropChance(ItemDrop.ItemData baseItem, out float chance)
        {
            chance = 0f;

            if (!HasActiveBossRule())
            {
                return false;
            }

            string lootDropItem = GetCurrentLootDropItem();
            string baseItemName = GetBaseItemName(baseItem);
            if (_context.Rule.ForceSetDropItems.Count > 0)
            {
                if (!IsForcedSetDropItem(lootDropItem) && !IsForcedSetDropItem(baseItemName))
                {
                    chance = 0f;
                    return true;
                }
            }

            if (IsForcedSetDropItem(lootDropItem) || IsForcedSetDropItem(baseItemName))
            {
                chance = 1f;
                return true;
            }

            chance = _context.SetDropsMade < _context.Rule.GuaranteedSetDrops ? 1f : _context.Rule.ExtraSetDropChance;
            return true;
        }

        internal static bool TryRollBossSetItem(ItemDrop.ItemData baseItem, MagicItem originalMagicItem, ItemRarity rolledRarity, float powerLevelMod, out MagicItem magicItem)
        {
            magicItem = null;
            if (!HasActiveBossRule())
            {
                return false;
            }

            ItemRarity targetRarity;
            if (!TryGetRuleRarity(_context.Rule, out targetRarity))
            {
                targetRarity = rolledRarity;
            }

            return RaritySetRegistry.TryRollSetItemFromIds(targetRarity, _context.Rule.ForceSetItemIds, baseItem, originalMagicItem, powerLevelMod, out magicItem);
        }

        internal static bool IsAllowedBossSetDrop(MagicItem magicItem)
        {
            if (!HasActiveBossRule() || magicItem == null || string.IsNullOrEmpty(magicItem.SetID))
            {
                return false;
            }

            ItemRarity targetRarity;
            if (TryGetRuleRarity(_context.Rule, out targetRarity) && magicItem.Rarity != targetRarity)
            {
                return false;
            }

            return _context.Rule.ForceSetItemIds.Count == 0 ||
                   (!string.IsNullOrEmpty(magicItem.LegendaryID) &&
                    _context.Rule.ForceSetItemIds.Contains(magicItem.LegendaryID, StringComparer.OrdinalIgnoreCase));
        }

        internal static void RecordSetDrop()
        {
            if (HasActiveBossRule())
            {
                _context.SetDropsMade++;
            }
        }

        internal static void EnsureGuaranteedSetDrops(ref List<GameObject> drops, Vector3 dropPoint, bool initializeObject)
        {
            if (!HasActiveBossRule() || _context.Depth != 1)
            {
                return;
            }

            ConvertExistingBossMagicDrops(drops, dropPoint, initializeObject);
            int guaranteedDrops = Math.Max(0, _context.Rule.GuaranteedSetDrops);
            int guard = 0;
            while (_context.SetDropsMade < guaranteedDrops && guard < guaranteedDrops + 8)
            {
                guard++;

                GameObject dropObject;
                if (!TrySpawnBossSetDrop(dropPoint, initializeObject, out dropObject))
                {
                    EpicLootRaritySetsPlugin.Log.LogWarning(string.Format(
                        "Could not create guaranteed boss set drop {0}/{1} for {2}.",
                        _context.SetDropsMade + 1,
                        guaranteedDrops,
                        _context.ObjectName));
                    break;
                }

                if (drops == null)
                {
                    drops = new List<GameObject>();
                }

                drops.Add(dropObject);
                RecordSetDrop();
            }
        }

        private static void ConvertExistingBossMagicDrops(List<GameObject> drops, Vector3 dropPoint, bool initializeObject)
        {
            if (drops == null || drops.Count == 0)
            {
                return;
            }

            ItemRarity targetRarity;
            if (!TryGetRuleRarity(_context.Rule, out targetRarity))
            {
                return;
            }

            int allowedCount = CountAllowedBossSetDrops(drops);
            if (allowedCount > _context.SetDropsMade)
            {
                _context.SetDropsMade = allowedCount;
            }

            for (int i = 0; i < drops.Count; i++)
            {
                GameObject dropObject = drops[i];
                ItemDrop itemDrop = dropObject != null ? dropObject.GetComponent<ItemDrop>() : null;
                if (itemDrop == null || itemDrop.m_itemData == null || IsBossUtilityDropItem(GetDropObjectName(dropObject, itemDrop)))
                {
                    continue;
                }

                MagicItem currentMagicItem = ItemDataExtensions.GetMagicItem(itemDrop.m_itemData);
                if (currentMagicItem == null)
                {
                    continue;
                }

                if (IsAllowedBossSetDrop(currentMagicItem))
                {
                    continue;
                }

                MagicItem bossSetItem;
                if (TryRollBossSetItem(itemDrop.m_itemData, currentMagicItem, targetRarity, 1f, out bossSetItem))
                {
                    ItemDataExtensions.SaveMagicItem(itemDrop.m_itemData, bossSetItem);
                    RecordSetDrop();
                    continue;
                }

                GameObject replacement;
                Vector3 replacementPoint = dropObject != null ? dropObject.transform.position : dropPoint;
                if (TrySpawnBossSetDrop(replacementPoint, initializeObject, out replacement))
                {
                    DestroyDropObject(dropObject);
                    drops[i] = replacement;
                    RecordSetDrop();
                }
            }
        }

        private static int CountAllowedBossSetDrops(List<GameObject> drops)
        {
            int count = 0;
            if (drops == null)
            {
                return count;
            }

            foreach (GameObject dropObject in drops)
            {
                ItemDrop itemDrop = dropObject != null ? dropObject.GetComponent<ItemDrop>() : null;
                MagicItem magicItem = itemDrop != null && itemDrop.m_itemData != null
                    ? ItemDataExtensions.GetMagicItem(itemDrop.m_itemData)
                    : null;
                if (IsAllowedBossSetDrop(magicItem))
                {
                    count++;
                }
            }

            return count;
        }

        private static bool TrySpawnBossSetDrop(Vector3 dropPoint, bool initializeObject, out GameObject dropObject)
        {
            dropObject = null;

            ItemRarity targetRarity;
            if (!TryGetRuleRarity(_context.Rule, out targetRarity))
            {
                return false;
            }

            return RaritySetRegistry.TrySpawnSetItemDropFromIds(targetRarity, _context.Rule.ForceSetItemIds, dropPoint, initializeObject, out dropObject);
        }

        private static string GetDropObjectName(GameObject dropObject, ItemDrop itemDrop)
        {
            if (itemDrop != null && itemDrop.m_itemData != null && itemDrop.m_itemData.m_dropPrefab != null)
            {
                return itemDrop.m_itemData.m_dropPrefab.name;
            }

            if (dropObject != null)
            {
                return dropObject.name;
            }

            return null;
        }

        private static void DestroyDropObject(GameObject dropObject)
        {
            if (dropObject == null)
            {
                return;
            }

            if (ZNetScene.instance != null)
            {
                ZNetScene.instance.Destroy(dropObject);
            }
            else
            {
                UnityEngine.Object.Destroy(dropObject);
            }
        }

        private static string GetCurrentLootDropItem()
        {
            if (_lootDropItems == null || _lootDropItems.Count == 0)
            {
                return null;
            }

            return _lootDropItems.Peek();
        }

        private static string GetCurrentResolveLootDropItem()
        {
            if (_resolveLootDropItems == null || _resolveLootDropItems.Count == 0)
            {
                return null;
            }

            return _resolveLootDropItems.Peek();
        }

        private static string GetBaseItemName(ItemDrop.ItemData baseItem)
        {
            if (baseItem == null)
            {
                return null;
            }

            if (baseItem.m_dropPrefab != null)
            {
                return baseItem.m_dropPrefab.name;
            }

            return baseItem.m_shared != null ? baseItem.m_shared.m_name : null;
        }

        private static bool IsForcedSetDropItem(string item)
        {
            return HasActiveBossRule() &&
                   !string.IsNullOrEmpty(item) &&
                   _context.Rule.ForceSetDropItems != null &&
                   _context.Rule.ForceSetDropItems.Contains(item, StringComparer.OrdinalIgnoreCase);
        }

        private static float[] BuildForcedRarityArray(ItemRarity rarity)
        {
            int size = Math.Max(Enum.GetValues(typeof(ItemRarity)).Length, (int)rarity + 1);
            float[] values = new float[size];
            int index = (int)rarity;
            if (index >= 0 && index < values.Length)
            {
                values[index] = 100f;
            }

            return values;
        }

        private static bool IsBossUtilityDrop(LootDrop lootDrop)
        {
            if (lootDrop == null)
            {
                return false;
            }

            if (IsBossUtilityDropItem(lootDrop.Item))
            {
                return true;
            }

            if (lootDrop.RarityItems == null)
            {
                return false;
            }

            foreach (string item in lootDrop.RarityItems.Values)
            {
                if (IsBossUtilityDropItem(item))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsBossUtilityDropItem(string item)
        {
            return !string.IsNullOrEmpty(item) &&
                   (item.IndexOf("Runestone", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    item.IndexOf("ShardStone", StringComparison.OrdinalIgnoreCase) >= 0);
        }

        private static bool TryGetRuleRarity(BossSetDropRule rule, out ItemRarity rarity)
        {
            rarity = ItemRarity.Magic;
            return rule != null &&
                   !string.IsNullOrEmpty(rule.Rarity) &&
                   Enum.TryParse(rule.Rarity, true, out rarity);
        }

        private class BossLootContext
        {
            public readonly BossSetDropRule Rule;
            public readonly string ObjectName;
            public int Depth;
            public int SetDropsMade;

            public BossLootContext(BossSetDropRule rule, string objectName, int level)
            {
                Rule = rule;
                ObjectName = objectName;
                Depth = 1;
                SetDropsMade = 0;
            }
        }

        #pragma warning disable 0649
        private class BossSetDropConfig
        {
            public bool Enabled = true;
            public List<BossSetDropRule> Bosses;
        }

        private class BossSetDropRule
        {
            public string Object;
            public bool Enabled = true;
            public string Rarity;
            public int GuaranteedSetDrops = 1;
            public float ExtraSetDropChance = 0.4f;
            public List<string> ForceSetDropItems;
            public List<string> ForceSetItemIds;
        }
        #pragma warning restore 0649
    }

    internal static class MoonveinBowEitrUse
    {
        internal static float GetCost(Character character, ItemDrop.ItemData weapon)
        {
            MagicItem magicItem;
            if (!IsMoonveinBow(weapon, out magicItem))
            {
                return 0f;
            }

            float baseCost = GetBaseCost(magicItem.Rarity);
            if (baseCost <= 0f)
            {
                return 0f;
            }

            Player player = character as Player;
            if (player == null)
            {
                return baseCost;
            }

            float costMultiplier = ModifyAttackCosts.GetModifyAttackValue(player, weapon, MagicEffectType.ModifyAttackEitrUse);
            if (float.IsNaN(costMultiplier) || float.IsInfinity(costMultiplier))
            {
                return baseCost;
            }

            return Mathf.Max(0f, baseCost * costMultiplier);
        }

        internal static bool IsMoonveinBow(ItemDrop.ItemData weapon, out MagicItem magicItem)
        {
            magicItem = null;
            if (weapon == null || weapon.m_shared == null || weapon.m_shared.m_itemType != ItemDrop.ItemData.ItemType.Bow)
            {
                return false;
            }

            magicItem = ItemDataExtensions.GetMagicItem(weapon);
            if (magicItem == null)
            {
                return false;
            }

            return IsMoonveinId(magicItem.SetID) || IsMoonveinId(magicItem.LegendaryID);
        }

        private static bool IsMoonveinId(string id)
        {
            return !string.IsNullOrEmpty(id) && id.IndexOf("Moonvein", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static float GetBaseCost(ItemRarity rarity)
        {
            if (rarity == ItemRarity.Magic)
            {
                return EpicLootRaritySetsPlugin.MoonveinMagicBowEitrUse.Value;
            }

            if (rarity == ItemRarity.Rare)
            {
                return EpicLootRaritySetsPlugin.MoonveinRareBowEitrUse.Value;
            }

            if (rarity == ItemRarity.Epic)
            {
                return EpicLootRaritySetsPlugin.MoonveinEpicBowEitrUse.Value;
            }

            if (rarity == ItemRarity.Legendary)
            {
                return EpicLootRaritySetsPlugin.MoonveinLegendaryBowEitrUse.Value;
            }

            if (rarity == ItemRarity.Mythic)
            {
